# ========== FUNCIONES AUXILIARES PARA MOVIMIENTOS ==========

def registrar_movimiento_producto(producto_talla, concepto, cantidad, responsable,
                                dte=None, ticket=None, sucursal_origen=None,
                                sucursal_destino=None, observaciones=None,
                                referencia_externa=None, crear_lote_fifo=True,
                                consumir_lotes=True):
    """
    Función centralizada para registrar movimientos de productos
    Ahora incluye soporte para FIFO automático.

    consumir_lotes=False es para llamadores que ya gestionaron los lotes por
    su cuenta (aplicar_salida_stock_producto, ajustar_lote, consumir_stock_fifo
    de views_modulo_productos) — si no, un egreso consumiría lotes dos veces.
    """
    from .models import Movimientos_Producto
    
    # Determinar sucursales si no se proporcionan
    if not sucursal_origen:
        sucursal_origen = producto_talla.producto.sucursal
    if not sucursal_destino:
        sucursal_destino = producto_talla.producto.sucursal
    
    # Si no hay movimientos previos, crear saldo inicial con el stock legacy.
    #
    # `Movimientos_Producto.fecha` tiene default=django_date_today, así que este
    # saldo —que es histórico— entraba al kardex con fecha de HOY: cualquier
    # cálculo de stock a una fecha pasada (kardex, tomas retroactivas, reportes)
    # lo veía en el lugar equivocado. Se fecha con la creación del producto, que
    # es el mejor proxy disponible del origen del saldo (Producto_Talla no tiene
    # ningún campo de fecha propio y fecha_creacion está poblada en el 100% de
    # los 137.947 productos).
    if not producto_talla.movimientos_productos_talla.exists() and producto_talla.stock > 0:
        fecha_creacion_prod = getattr(producto_talla.producto, 'fecha_creacion', None)
        fecha_saldo_inicial = (
            timezone.localtime(fecha_creacion_prod).date()
            if fecha_creacion_prod else timezone.localdate()
        )
        Movimientos_Producto.objects.create(
            ProductoTalla=producto_talla,
            dte=None,
            ticket=None,
            sucursal_origen=sucursal_origen,
            sucursal_destino=sucursal_destino,
            cantidad=producto_talla.stock,
            costo=producto_talla.producto.costo,
            sobreprecio=producto_talla.producto.sobreprecio,
            precio=producto_talla.producto.precioventa,
            concepto='INGRESO_INICIAL',
            responsable='Sistema',
            observaciones='Saldo inicial legacy',
            referencia_externa='SALDO_INICIAL',
            fecha=fecha_saldo_inicial,
        )

    # Crear el movimiento
    movimiento = Movimientos_Producto.objects.create(
        ProductoTalla=producto_talla,
        dte=dte,
        ticket=ticket,
        sucursal_origen=sucursal_origen,
        sucursal_destino=sucursal_destino,
        cantidad=cantidad,
        costo=producto_talla.producto.costo,
        sobreprecio=producto_talla.producto.sobreprecio,
        precio=producto_talla.producto.precioventa,
        concepto=concepto,
        responsable=responsable,
        observaciones=observaciones,
        referencia_externa=referencia_externa
    )
    
    # Actualizar stock del producto
    producto_talla.stock += cantidad
    producto_talla.save()

    # Consumir lotes FIFO en egresos (best-effort): sin esto, traspasos vía
    # modelo Traspaso y ajustes negativos bajaban el stock plano dejando los
    # lotes inflados (drift crónico detectado en la auditoría jul-2026).
    if consumir_lotes and cantidad < 0:
        try:
            from app.services.inventario_service import consumir_lotes_fifo
            consumir_lotes_fifo(producto_talla, -cantidad, usar_lock=False)
        except Exception as e_lotes:
            import logging
            logging.getLogger('app').warning(
                'registrar_movimiento_producto: lotes FIFO no consumidos sku=%s cantidad=%s: %s',
                producto_talla.sku, cantidad, e_lotes,
            )

    # Crear lote FIFO para ingresos (solo si es positivo y se solicita)
    # Lista de conceptos que generan lotes FIFO automáticamente
    if crear_lote_fifo and cantidad > 0 and concepto in [
        'INGRESO_INICIAL', 'INGRESO_MANUAL', 'RECEPCION_COMPRA', 'REPOSICION_STOCK',
        'DEVOLUCION_CLIENTE', 'TRASPASO_ENTRADA', 'AJUSTE_POSITIVO', 'DONACION_RECIBIDA',
        'CAMBIO_PRODUCTO_ENTRADA'
    ]:
        try:
            crear_lote_producto(
                producto_talla=producto_talla,
                cantidad=cantidad,
                costo_unitario=producto_talla.producto.costo,
                sobreprecio_unitario=producto_talla.producto.sobreprecio,
                precio_venta_unitario=producto_talla.producto.precioventa,
                dte=dte,
                movimiento=movimiento,
                observaciones=f"Lote automático - {concepto} - {observaciones or ''}"
            )
        except Exception as e:
            import logging
            logging.getLogger('app').warning("Error creando lote FIFO: %s", e)
    
    return movimiento

def obtener_siguiente_correlativo(sucursal, tipo):
    """
    Obtiene el siguiente número de correlativo para tickets, traspasos, etc.
    """
    from .models import Correlativo

    if _es_tipo_empresa(tipo):
        correlativo = Correlativo.objects.filter(
            sucursal__empresa_id=sucursal.empresa_id,
            tipo_dte=tipo
        ).first()

        if not correlativo:
            correlativo = Correlativo.objects.create(
                tipo_dte=tipo,
                sucursal=sucursal,
                inicio=1,
                termino=999999,
                alias=f'{tipo}_{sucursal.alias}',
                responsable='Sistema'
            )
    else:
        correlativo, created = Correlativo.objects.get_or_create(
            tipo_dte=tipo,
            sucursal=sucursal,
            defaults={
                'inicio': 1,
                'termino': 999999,
                'alias': f'{tipo}_{sucursal.alias}',
                'responsable': 'Sistema'
            }
        )
    
    try:
        return correlativo.obtener_siguiente_numero()
    except ValueError as e:
        # Si el correlativo está agotado, crear uno nuevo automáticamente
        correlativo.inicio = correlativo.termino + 1
        correlativo.termino = correlativo.termino + 100000
        correlativo.fecha_actualizacion = timezone.localdate()
        correlativo.save()
        
        return correlativo.obtener_siguiente_numero()


def obtener_correlativo_existente(sucursal, tipo):
    from .models import Correlativo
    if _es_tipo_empresa(tipo):
        return Correlativo.objects.filter(
            sucursal__empresa_id=sucursal.empresa_id,
            tipo_dte=tipo
        ).first()
    return Correlativo.objects.filter(
        sucursal=sucursal,
        tipo_dte=tipo
    ).first()
# ========== VISTAS PARA VENTAS AL PÚBLICO ==========
@require_POST
@transaction.atomic
def crear_ticket_venta(request):
    """
    Crea un ticket de venta al público y registra los movimientos correspondientes
    """
    try:
        data = json.loads(request.body)
        
        # Datos de sesión
        sucursal_id = request.session.get('idSucursalActual')
        responsable = request.session.get('nombreUsuario', 'Sistema')
        
        if not sucursal_id:
            return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)
        
        sucursal = get_object_or_404(Sucursal, id=sucursal_id)
        vendedor = get_object_or_404(Vendedor, id=data.get('vendedor_id'))
        
        # Datos del ticket
        productos = data.get('productos', [])
        cliente_nombre = data.get('cliente_nombre', '')
        cliente_rut = data.get('cliente_rut', '')
        cliente_email = data.get('cliente_email', '')
        cliente_telefono = data.get('cliente_telefono', '')
        metodo_pago = data.get('metodo_pago', 'EFECTIVO')
        observaciones = data.get('observaciones', '')
        
        if not productos:
            return JsonResponse({'success': False, 'error': 'No hay productos en la venta'}, status=400)
        
        # Calcular totales
        subtotal = 0
        descuento_total = 0
        
        for producto in productos:
            # Validar cantidad
            try:
                cantidad = int(producto['cantidad'])
            except (ValueError, TypeError):
                return JsonResponse({
                    'success': False, 
                    'error': f'Cantidad inválida: debe ser un número entero'
                }, status=400)
            
            if cantidad < 1:
                return JsonResponse({
                    'success': False, 
                    'error': f'Cantidad inválida: debe ser mayor a 0'
                }, status=400)
            
            precio = int(producto['precio'])
            descuento = int(producto.get('descuento', 0))
            
            subtotal += cantidad * precio
            descuento_total += descuento
        
        total = subtotal - descuento_total
        
        # Crear ticket
        correlativo = obtener_siguiente_correlativo(sucursal, 'TICKET')
        
        ticket = Ticket.objects.create(
            vendedor=vendedor,
            sucursal=sucursal,
            correlativo=correlativo,
            estado='PAGADO',
            subTotal=subtotal,
            descuento=descuento_total,
            total=total,
            responsable=responsable,
            cliente_nombre=cliente_nombre,
            cliente_rut=cliente_rut,
            cliente_email=cliente_email,
            cliente_telefono=cliente_telefono,
            metodo_pago=metodo_pago,
            observaciones=observaciones
        )
        
        # Crear detalles y registrar movimientos
        for producto in productos:
            producto_talla = get_object_or_404(Producto_Talla, id=producto['producto_talla_id'])
            
            # Validar cantidad nuevamente antes de procesar
            try:
                cantidad = int(producto['cantidad'])
            except (ValueError, TypeError):
                raise Exception(f'Cantidad inválida para {producto_talla.producto.articulo} - Talla {producto_talla.talla}')
            
            if cantidad < 1:
                raise Exception(f'Cantidad debe ser mayor a 0 para {producto_talla.producto.articulo} - Talla {producto_talla.talla}')
            
            precio = int(producto['precio'])
            descuento = int(producto.get('descuento', 0))
            
            # Verificar stock disponible
            if producto_talla.stock < cantidad:
                raise Exception(
                    f'Stock insuficiente para {producto_talla.producto.articulo} - Talla {producto_talla.talla}. '
                    f'Solicitado: {cantidad}, Disponible: {producto_talla.stock}'
                )
            
            # Crear detalle del ticket
            Ticket_Productos.objects.create(
                ProductoTalla=producto_talla,
                idTicket=ticket,
                stock=cantidad,
                precio=precio,
                descuento_unitario=descuento,
                subtotal=cantidad * precio - descuento,
                precio_original=precio,
                porcentaje_descuento=(descuento / (cantidad * precio)) * 100 if cantidad * precio > 0 else 0
            )
            
            # Consumir stock usando FIFO
            try:
                costo_total_consumido, lotes_utilizados = consumir_stock_fifo(
                    producto_talla=producto_talla,
                    cantidad_requerida=cantidad,
                    responsable=responsable,
                    ticket=ticket,
                    observaciones=f'Ticket #{correlativo} - Cliente: {cliente_nombre}',
                    referencia_externa=str(correlativo)
                )
                
                # Registrar movimiento de egreso (sin crear lote FIFO)
                registrar_movimiento_producto(
                    producto_talla=producto_talla,
                    concepto='VENTA_PUBLICO',
                    cantidad=-cantidad,  # Negativo para egreso
                    responsable=responsable,
                    ticket=ticket,
                    observaciones=f'Ticket #{correlativo} - Cliente: {cliente_nombre} - Costo FIFO: ${costo_total_consumido:,}',
                    referencia_externa=str(correlativo),
                    crear_lote_fifo=False  # No crear lote para egresos
                )
                
                # Guardar información FIFO en el ticket
                ticket_producto = Ticket_Productos.objects.get(
                    ProductoTalla=producto_talla,
                    idTicket=ticket
                )
                # costo_fifo se guarda UNITARIO (los reportes calculan stock * costo_fifo)
                # y los lotes como JSON valido, via el helper compartido.
                from .utils_ventas import persistir_costeo_fifo
                persistir_costeo_fifo(ticket_producto, costo_total_consumido, lotes_utilizados)
                
            except Exception as e:
                raise Exception(f'Error en FIFO para {producto_talla.producto.articulo} - Talla {producto_talla.talla}: {str(e)}')
        
        return JsonResponse({
            'success': True,
            'ticket_id': ticket.id,
            'correlativo': correlativo,
            'total': total
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)

@require_GET
@login_required
def obtener_tickets_venta(request):
    """
    Obtiene tickets de venta con filtros
    """
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)
    
    # Filtros
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    estado = request.GET.get('estado')
    vendedor_id = request.GET.get('vendedor_id')
    cliente = request.GET.get('cliente')
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 50)), 100)
    
    tickets = Ticket.objects.filter(sucursal_id=sucursal_id)
    
    if fecha_inicio:
        tickets = tickets.filter(fecha__gte=parse_date(fecha_inicio))
    if fecha_fin:
        tickets = tickets.filter(fecha__lte=parse_date(fecha_fin))
    if estado:
        tickets = tickets.filter(estado=estado)
    if vendedor_id:
        tickets = tickets.filter(vendedor_id=vendedor_id)
    if cliente:
        tickets = tickets.filter(
            Q(cliente_nombre__icontains=cliente) |
            Q(cliente_rut__icontains=cliente)
        )
    
    total_count = tickets.count()
    offset = (page - 1) * page_size
    tickets = tickets.select_related('vendedor')[offset:offset+page_size]
    
    data = []
    for ticket in tickets:
        data.append({
            'id': ticket.id,
            'correlativo': ticket.correlativo,
            'fecha': ticket.fecha.strftime('%Y-%m-%d'),
            'hora': ticket.hora.strftime('%H:%M'),
            'vendedor': ticket.vendedor.nombre,
            'cliente': ticket.cliente_nombre or 'Sin cliente',
            'subtotal': ticket.subTotal,
            'descuento': ticket.descuento or 0,
            'total': ticket.total,
            'estado': ticket.estado,
            'metodo_pago': ticket.metodo_pago,
            'responsable': ticket.responsable
        })
    
    return JsonResponse({
        'success': True,
        'items': data,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size
        }
    })

# ========== VISTAS PARA TRASPASOS ==========
#
# crear_traspaso / aprobar_traspaso / recibir_traspaso fueron ELIMINADAS el
# 2026-07-28. Motivos:
#   1. Ningún template ni archivo JS las invocaba (flujo muerto).
#   2. Las tres colgaban solo de @require_POST + @transaction.atomic, sin
#      @login_required. PermisosMenuMiddleware devuelve None para usuarios no
#      autenticados (middleware_permisos.py), así que un POST anónimo con un
#      csrftoken obtenido sin sesión movía stock firmado como 'Sistema'.
#   3. aprobar_traspaso descontaba stock de los Traspaso en estado PENDIENTE,
#      pero esos los crea api_crear_despacho_masivo
#      (views_modulo_existencias_nuevo.py) que YA descontó el stock: aprobarlos
#      lo descontaba por segunda vez y reconsumía lotes FIFO.
#
# El circuito real de traspasos entre sucursales es por DTE: emitir_dte genera
# el TRASPASO_SALIDA y confirmar_recepcion_api el TRASPASO_ENTRADA.
# Los modelos Traspaso / Traspaso_Detalle se conservan: los usa el despacho
# masivo y hay datos históricos.


# ========== VISTAS PARA AJUSTES DE INVENTARIO ==========

@require_POST
@transaction.atomic
def crear_ajuste_inventario(request):
    """
    Crea un ajuste de inventario
    """
    try:
        data = json.loads(request.body)
        
        # Datos de sesión
        sucursal_id = request.session.get('idSucursalActual')
        responsable = request.session.get('nombreUsuario', 'Sistema')
        
        if not sucursal_id:
            return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)
        
        sucursal = get_object_or_404(Sucursal, id=sucursal_id)
        
        productos = data.get('productos', [])
        tipo_ajuste = data.get('tipo_ajuste')
        motivo = data.get('motivo', '')
        observaciones = data.get('observaciones', '')
        
        if not productos:
            return JsonResponse({'success': False, 'error': 'No hay productos en el ajuste'}, status=400)
        
        # Crear ajuste
        numero_ajuste = obtener_siguiente_correlativo(sucursal, 'AJUSTE')
        
        ajuste = AjusteInventario.objects.create(
            sucursal=sucursal,
            numero_ajuste=numero_ajuste,
            tipo_ajuste=tipo_ajuste,
            motivo=motivo,
            observaciones=observaciones,
            solicitante=responsable
        )
        
        # Crear detalles y registrar movimientos
        for producto in productos:
            producto_talla = get_object_or_404(Producto_Talla, id=producto['producto_talla_id'])
            stock_sistema = producto_talla.stock
            stock_fisico = int(producto['stock_fisico'])
            diferencia = stock_fisico - stock_sistema
            
            # Crear detalle
            AjusteInventario_Detalle.objects.create(
                ajuste=ajuste,
                producto_talla=producto_talla,
                stock_sistema=stock_sistema,
                stock_fisico=stock_fisico,
                diferencia=diferencia,
                costo=producto_talla.producto.costo,
                precio_venta=producto_talla.producto.precioventa,
                observaciones=producto.get('observaciones', '')
            )
            
            # Registrar movimiento
            if diferencia != 0:
                concepto = 'AJUSTE_POSITIVO' if diferencia > 0 else 'AJUSTE_NEGATIVO'
                registrar_movimiento_producto(
                    producto_talla=producto_talla,
                    concepto=concepto,
                    cantidad=diferencia,
                    responsable=responsable,
                    observaciones=f'Ajuste #{numero_ajuste} - {motivo}',
                    referencia_externa=str(numero_ajuste)
                )
        
        return JsonResponse({
            'success': True,
            'ajuste_id': ajuste.id,
            'numero_ajuste': numero_ajuste
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


CONCEPTOS_AJUSTE_RAPIDO_INGRESO = [
    'INGRESO_INICIAL',
    'DEVOLUCION_CLIENTE',
    'REGULARIZACION_TRASPASO',
    'AJUSTE_POSITIVO',
    'DONACION_RECIBIDA',
    'CAMBIO_PRODUCTO_ENTRADA',
]

CONCEPTOS_AJUSTE_RAPIDO_EGRESO = [
    'AJUSTE_NEGATIVO',
    'PERDIDA_ROBO',
    'PERDIDA_DETERIORO',
    'DONACION_ENTREGADA',
    'DEVOLUCION_PROVEEDOR',
    'CAMBIO_PRODUCTO_SALIDA',
]


def _lookup_producto_talla_ajuste(sku, sucursal_id):
    """
    Busca un Producto_Talla por SKU en la sucursal indicada y devuelve:
      (producto_en_sucursal, productos_otras_sucursales)
    donde el primer elemento puede ser None si no existe en la sucursal actual.
    """
    from .models import Producto_Talla

    qs = Producto_Talla.objects.select_related('producto', 'producto__sucursal').filter(sku=sku)
    en_sucursal = None
    otras = []
    for pt in qs:
        if sucursal_id and pt.producto and pt.producto.sucursal_id == int(sucursal_id):
            en_sucursal = pt
        else:
            otras.append(pt)
    return en_sucursal, otras


def _serializar_producto_talla_ajuste(producto_talla, sucursal_id):
    producto = producto_talla.producto
    sucursal_producto = getattr(producto, 'sucursal', None)
    return {
        'id': producto_talla.id,
        'sku': producto_talla.sku,
        'articulo': producto.articulo,
        'descripcion': producto.descripcion or '',
        'talla': producto_talla.talla or 'Sin talla',
        'stock_actual': producto_talla.stock_sucursal(sucursal_id) if sucursal_id else (producto_talla.stock or 0),
        'stock_total': producto_talla.stock_total(),
        'sucursal_id': sucursal_producto.id if sucursal_producto else None,
        'sucursal_alias': sucursal_producto.alias if sucursal_producto else '',
    }


@login_required
@require_http_methods(["GET", "POST"])
def ajuste_stock_rapido(request):
    """
    Ajuste rápido de stock por SKU y concepto.
    Útil para corregir stock cuando hay stock físico pero no en sistema.

    GET sin parámetros → renderiza el formulario.
    GET ?sku=XXX       → devuelve JSON con la información del producto y su stock
                         en la sucursal activa (y en cuáles otras existe si no está
                         en la actual).
    POST               → registra el movimiento de ajuste.
    """
    from .models import Producto_Talla, CONCEPTO_MOVIMIENTO_CHOICES

    conceptos_permitidos = CONCEPTOS_AJUSTE_RAPIDO_INGRESO + CONCEPTOS_AJUSTE_RAPIDO_EGRESO
    conceptos_egreso = set(CONCEPTOS_AJUSTE_RAPIDO_EGRESO)

    if request.method == "GET":
        sku_param = (request.GET.get('sku') or '').strip()
        sucursal_id = request.session.get('idSucursalActual')

        if sku_param:
            try:
                sku = int(sku_param)
            except ValueError:
                return JsonResponse({'success': False, 'error': 'SKU inválido'}, status=400)

            en_sucursal, otras = _lookup_producto_talla_ajuste(sku, sucursal_id)

            if en_sucursal:
                return JsonResponse({
                    'success': True,
                    'en_sucursal_actual': True,
                    'producto': _serializar_producto_talla_ajuste(en_sucursal, sucursal_id),
                })

            if otras:
                return JsonResponse({
                    'success': True,
                    'en_sucursal_actual': False,
                    'mensaje': 'El SKU existe pero no en la sucursal activa',
                    'producto': _serializar_producto_talla_ajuste(otras[0], sucursal_id),
                    'otras_sucursales': [
                        {
                            'sucursal_id': pt.producto.sucursal_id,
                            'sucursal_alias': pt.producto.sucursal.alias if pt.producto.sucursal else '',
                            'stock': pt.stock or 0,
                        } for pt in otras
                    ],
                }, status=200)

            return JsonResponse({
                'success': False,
                'error': f'No se encontró ningún producto con SKU {sku}',
            }, status=404)

        ingreso_conceptos = [c for c in CONCEPTO_MOVIMIENTO_CHOICES if c[0] in CONCEPTOS_AJUSTE_RAPIDO_INGRESO]
        egreso_conceptos = [c for c in CONCEPTO_MOVIMIENTO_CHOICES if c[0] in CONCEPTOS_AJUSTE_RAPIDO_EGRESO]
        return render(request, 'vistas/modulo_existencias/ajuste_stock_rapido.html', {
            'conceptos_ingreso': ingreso_conceptos,
            'conceptos_egreso': egreso_conceptos,
        })

    try:
        data = json.loads(request.body)
    except json.JSONDecodeError:
        data = request.POST

    sku_raw = str(data.get('sku', '')).strip()
    concepto = str(data.get('concepto', '')).strip()
    observaciones = str(data.get('observaciones', '')).strip()

    try:
        cantidad = int(data.get('cantidad', 0))
    except (TypeError, ValueError):
        cantidad = 0
    cantidad = abs(cantidad)

    if not sku_raw:
        return JsonResponse({'success': False, 'error': 'Debe ingresar un SKU'}, status=400)
    if not concepto or concepto not in conceptos_permitidos:
        return JsonResponse({'success': False, 'error': 'Seleccione un concepto válido'}, status=400)
    if cantidad <= 0:
        return JsonResponse({'success': False, 'error': 'La cantidad debe ser mayor a 0'}, status=400)

    try:
        sku = int(sku_raw)
    except ValueError:
        return JsonResponse({'success': False, 'error': 'SKU inválido'}, status=400)

    sucursal_id = request.session.get('idSucursalActual')
    if sucursal_id:
        en_sucursal, otras = _lookup_producto_talla_ajuste(sku, sucursal_id)
        if en_sucursal:
            producto_talla = en_sucursal
            sucursal = get_object_or_404(Sucursal, id=sucursal_id)
        else:
            if otras:
                alias_otras = ', '.join(
                    pt.producto.sucursal.alias for pt in otras if pt.producto and pt.producto.sucursal
                ) or 'otras sucursales'
                return JsonResponse({
                    'success': False,
                    'error': (
                        f'El SKU {sku} no pertenece a la sucursal activa. '
                        f'Se encuentra en: {alias_otras}. '
                        'Debes crear el producto en esta sucursal antes de ajustar stock.'
                    ),
                    'en_sucursal_actual': False,
                    'otras_sucursales': [
                        {
                            'sucursal_id': pt.producto.sucursal_id,
                            'sucursal_alias': pt.producto.sucursal.alias if pt.producto.sucursal else '',
                            'stock': pt.stock or 0,
                        } for pt in otras
                    ],
                }, status=400)
            return JsonResponse({'success': False, 'error': f'No se encontró SKU {sku}'}, status=404)
    else:
        producto_talla = Producto_Talla.objects.select_related('producto', 'producto__sucursal').filter(sku=sku).first()
        if not producto_talla:
            return JsonResponse({'success': False, 'error': f'No se encontró SKU {sku}'}, status=404)
        sucursal = producto_talla.producto.sucursal

    es_egreso = concepto in conceptos_egreso
    cantidad_mov = -cantidad if es_egreso else cantidad

    if es_egreso:
        stock_disponible = producto_talla.stock_sucursal(sucursal.id)
        if stock_disponible < cantidad:
            return JsonResponse({
                'success': False,
                'error': f'Stock insuficiente. Disponible: {stock_disponible}, intentaste restar {cantidad}.'
            }, status=400)

    responsable = request.user.get_full_name() or request.user.username
    movimiento = registrar_movimiento_producto(
        producto_talla=producto_talla,
        concepto=concepto,
        cantidad=cantidad_mov,
        responsable=responsable,
        sucursal_origen=sucursal,
        sucursal_destino=sucursal,
        observaciones=observaciones,
        referencia_externa='AJUSTE_STOCK_RAPIDO'
    )

    return JsonResponse({
        'success': True,
        'message': 'Ajuste registrado correctamente',
        'movimiento_id': movimiento.id,
        'sku': producto_talla.sku,
        'producto': producto_talla.producto.articulo,
        'talla': producto_talla.talla or 'Sin talla',
        'tipo': 'EGRESO' if es_egreso else 'INGRESO',
        'cantidad': cantidad,
        'nuevo_stock': producto_talla.stock_sucursal(sucursal.id)
    })

