@login_required
@require_GET
def api_detalle_dte_completo(request, dte_id):
    """API que retorna el detalle completo de un DTE (compras o ventas)"""
    try:
        dte = get_object_or_404(Dte, id=dte_id)

        # Autorización a nivel de objeto: el DTE debe pertenecer a la empresa
        # activa, ya sea como emisor (ventas/traspasos) o receptor (compras).
        # Sin esto cualquier usuario autenticado podía leer costos, montos y
        # pagos de DTEs de otras empresas iterando el id (IDOR de lectura).
        empresa_actual_id = request.session.get('idEmpresaActual')
        if empresa_actual_id and dte.emisor_id != empresa_actual_id and dte.receptor_id != empresa_actual_id:
            return JsonResponse(
                {'success': False, 'error': 'No tiene acceso a este documento.'},
                status=403,
            )

        # Para traspasos, identificar la sucursal destino para cotejar stock.
        sucursal_destino_traspaso_id = None
        if dte.tipo_transaccion == 'TRASPASO':
            mov_destino = (
                Movimientos_Producto.objects
                .filter(dte=dte, concepto='TRASPASO_SALIDA', sucursal_destino__isnull=False)
                .only('sucursal_destino_id')
                .first()
            )
            if mov_destino:
                sucursal_destino_traspaso_id = mov_destino.sucursal_destino_id

        # Obtener productos del DTE
        productos = []
        dte_productos_qs = Dte_Productos.objects.filter(dte=dte).select_related('productoTalla__producto')

        # Pre-cargar stock por SKU en origen y destino (si aplica).
        skus = [
            dp.productoTalla.sku for dp in dte_productos_qs
            if dp.productoTalla
        ]
        stock_por_sku = {}
        if skus:
            qs_stocks = Producto_Talla.objects.filter(sku__in=skus).select_related('producto')
            if sucursal_destino_traspaso_id:
                qs_stocks = qs_stocks.filter(
                    producto__sucursal_id__in=[dte.sucursal_id, sucursal_destino_traspaso_id]
                )
            else:
                qs_stocks = qs_stocks.filter(producto__sucursal_id=dte.sucursal_id)
            for t in qs_stocks:
                stock_por_sku.setdefault(t.sku, {})[t.producto.sucursal_id] = int(t.stock or 0)

        if dte_productos_qs.exists():
            for detalle in dte_productos_qs:
                producto = detalle.productoTalla.producto if detalle.productoTalla else None
                subtotal = (detalle.precio or 0) * (detalle.stock or 0)
                sku = detalle.productoTalla.sku if detalle.productoTalla else None
                stock_origen = stock_por_sku.get(sku, {}).get(dte.sucursal_id) if sku else None
                stock_destino = (
                    stock_por_sku.get(sku, {}).get(sucursal_destino_traspaso_id)
                    if (sku and sucursal_destino_traspaso_id) else None
                )
                productos.append({
                    'id': detalle.id,
                    'producto': producto.articulo if producto else detalle.descripcion,
                    'sku': sku,
                    'talla': detalle.productoTalla.talla if detalle.productoTalla else None,
                    'descripcion': detalle.descripcion,
                    'cantidad': detalle.stock,
                    'precio_unitario': detalle.precio,
                    'subtotal': subtotal,
                    'costo': detalle.costo,
                    'activo': detalle.activo,
                    'stock_origen': stock_origen,
                    'stock_destino': stock_destino,
                })
        else:
            # Para compras: los productos vienen de Productos_Recepcionados
            recepciones = Productos_Recepcionados.objects.filter(
                dte=dte
            ).select_related(
                'producto_talla__producto',
                'compra_producto_talla__compra_producto'
            )
            for rec in recepciones:
                cp = rec.compra_producto_talla.compra_producto if rec.compra_producto_talla else None
                pt = rec.producto_talla
                nombre = ''
                if pt and pt.producto:
                    nombre = pt.producto.articulo
                elif cp:
                    nombre = cp.nombre
                
                costo = cp.costo if cp else 0
                subtotal = costo * (rec.stockArribado or 0)
                
                productos.append({
                    'id': rec.id,
                    'producto': nombre,
                    'sku': pt.sku if pt else None,
                    'talla': (rec.compra_producto_talla.talla if rec.compra_producto_talla else (pt.talla if pt else None)),
                    'descripcion': nombre,
                    'cantidad': rec.stockArribado,
                    'precio_unitario': costo,
                    'subtotal': subtotal,
                    'costo': costo,
                    'estado_recepcion': rec.estado,
                })
        
        # Obtener pagos del DTE
        pagos = []
        total_pagado = 0
        for pago in Dte_Detalle_Pago.objects.filter(dte=dte):
            pagos.append({
                'id': pago.id,
                'metodo_pago': pago.metodo_pago,
                'voucher': pago.voucher,
                'monto': pago.monto,
                'tipo_tarjeta': pago.tipo_tarjeta,
            })
            if pago.metodo_pago != 'Nota de Crédito':
                total_pagado += pago.monto or 0
        
        saldo = float(dte.monto_con_iva or 0) - float(total_pagado)
        
        return JsonResponse({
            'success': True,
            'dte': {
                'id': dte.id,
                'numero_documento': dte.numero_documento,
                'tipo_documento': dte.tipo_documento,
                'estado_dte': dte.estado_dte,
                'estado_pago': dte.estado_pago,
                'fecha_emision': dte.fecha_emision.strftime('%d/%m/%Y') if dte.fecha_emision else None,
                'fecha_vencimiento': dte.fecha_vencimiento.strftime('%d/%m/%Y') if dte.fecha_vencimiento else None,
                'fecha_recepcion': dte.fecha_recepcion.strftime('%d/%m/%Y') if dte.fecha_recepcion else None,
                'responsable': dte.responsable,
                'dias_credito': dte.diasCredito,
                'bultos': dte.bultos,
                'unidades_productos': dte.unidades_productos,
                'monto_neto': float(dte.monto_neto or 0),
                'monto_con_iva': float(dte.monto_con_iva or 0),
                'saldo': saldo,
                'observaciones': dte.referencias or '',
                # Receptor
                'receptor_nombre': dte.receptor.nombre if dte.receptor else None,
                'receptor_rut': dte.receptor.rut if dte.receptor else None,
                # Emisor
                'emisor_nombre': dte.emisor.nombre if dte.emisor else None,
                'emisor_rut': dte.emisor.rut if dte.emisor else None,
                # Sucursal
                'sucursal_nombre': dte.sucursal.alias if dte.sucursal else None,
                # Vendedor
                'vendedor_nombre': dte.vendedor.nombre if dte.vendedor else None,
            },
            'productos': productos,
            'pagos': pagos
        })
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': str(e)
        }, status=500)


@login_required
@require_GET
def api_dte_trazabilidad(request, dte_id):
    """
    Devuelve el árbol de trazabilidad completo de un DTE.

    Estructura:
        {
          "success": true,
          "dte": { ... },
          "padre": {  # solo para TRASPASO: la(s) compra(s) origen de los productos
            "compras": [
              {"id": 1, "correlativo": 123, "nombre": "...",
               "fecha": "2025-11-02", "empresa": "...",
               "skus_aportados": [1234, 5678]},
              ...
            ]
          },
          "hijos": [
            {"id": 2, "tipo_documento": "NOTA DE CREDITO",
             "numero_documento": 10, "es_nota_credito": true,
             "motivo_nc": "...", "monto_con_iva": 1000,
             "unidades": 2, "fecha_emision": "2025-12-01"},
            ...
          ],
          "movimientos": {
             "por_sucursal": [
               {"sucursal_id": 1, "sucursal_alias": "Casa Matriz",
                "items": [ ... ]},
               ...
             ]
          }
        }
    """
    from .models import Compras_Producto_Talla

    try:
        dte = (
            Dte.objects
            .select_related('emisor', 'receptor', 'sucursal', 'documento_afectado')
            .get(id=dte_id)
        )
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado'}, status=404)

    # --- Datos del DTE ---
    dte_info = {
        'id': dte.id,
        'numero_documento': dte.numero_documento,
        'tipo_documento': dte.tipo_documento,
        'estado_dte': dte.estado_dte,
        'tipo_transaccion': dte.tipo_transaccion,
        'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d') if dte.fecha_emision else None,
        'fecha_recepcion': dte.fecha_recepcion.strftime('%Y-%m-%d') if dte.fecha_recepcion else None,
        'monto_con_iva': float(dte.monto_con_iva or 0),
        'monto_neto': float(dte.monto_neto or 0),
        'unidades_productos': dte.unidades_productos or 0,
        'es_nota_credito': bool(dte.es_nota_credito),
        'emisor': dte.emisor.nombre if dte.emisor else None,
        'receptor': dte.receptor.nombre if dte.receptor else None,
        'sucursal': dte.sucursal.alias if dte.sucursal else None,
        'sucursal_id': dte.sucursal_id,
        'documento_afectado': None,
    }
    if dte.documento_afectado:
        dte_info['documento_afectado'] = {
            'id': dte.documento_afectado.id,
            'numero_documento': dte.documento_afectado.numero_documento,
            'tipo_documento': dte.documento_afectado.tipo_documento,
        }

    # --- Padre: compras que aportaron los Producto_Talla del DTE ---
    padre_compras = []
    if dte.tipo_transaccion == 'TRASPASO':
        producto_talla_ids = list(
            dte.dte_productos.exclude(productoTalla__isnull=True)
            .values_list('productoTalla_id', flat=True).distinct()
        )
        if producto_talla_ids:
            compras_items = (
                Compras_Producto_Talla.objects
                .filter(producto_talla_id__in=producto_talla_ids)
                .select_related(
                    'compra_producto__compras__empresa',
                    'producto_talla',
                )
            )
            compras_agg = {}
            for cpt in compras_items:
                compra = cpt.compra_producto.compras if cpt.compra_producto else None
                if not compra:
                    continue
                skus_aportados = compras_agg.setdefault(compra.id, {
                    'id': compra.id,
                    'correlativo': compra.correlativo,
                    'nombre': compra.nombre,
                    'empresa': compra.empresa.nombre if compra.empresa else None,
                    'fecha': compra.fecha.strftime('%Y-%m-%d') if compra.fecha else None,
                    'estado': compra.estado,
                    'temporada': compra.temporada,
                    'skus_aportados': [],
                })['skus_aportados']
                if cpt.producto_talla and cpt.producto_talla.sku not in skus_aportados:
                    skus_aportados.append(cpt.producto_talla.sku)
            padre_compras = list(compras_agg.values())

    # --- Hijos: todos los DTEs que referencian a este como documento_afectado ---
    hijos_qs = (
        Dte.objects
        .filter(documento_afectado_id=dte.id)
        .order_by('-fecha_emision', '-id')
    )
    hijos = []
    hijos_lineas_por_dte = {}
    for h in hijos_qs:
        # Flag stock_pendiente: True si la NC/AJUSTE no generó los
        # movimientos de reversa esperados (bug histórico). Se computa con
        # el mismo servicio que `api_ncs_sin_stock`, pero tolera errores
        # silenciosamente para no romper la respuesta de trazabilidad si
        # el diagnóstico falla en un caso borde.
        stock_pendiente = False
        faltantes_totales = 0
        try:
            diag = _diagnostico_nc(h)
            if diag and not diag.get('ya_reparado'):
                stock_pendiente = True
                faltantes_totales = diag.get('total_faltantes') or 0
        except Exception:
            logger.exception("Fallo calculando diagnostico NC hijo %s", h.id)
        hijos.append({
            'id': h.id,
            'tipo_documento': h.tipo_documento,
            'tipo_transaccion': h.tipo_transaccion,
            'numero_documento': h.numero_documento,
            'es_nota_credito': bool(h.es_nota_credito),
            'motivo_nc': (h.motivo_nc or '').strip()[:200],
            'monto_con_iva': float(h.monto_con_iva or 0),
            'monto_neto': float(h.monto_neto or 0),
            'unidades': h.unidades_productos or 0,
            'estado_dte': h.estado_dte,
            'fecha_emision': h.fecha_emision.strftime('%Y-%m-%d') if h.fecha_emision else None,
            'stock_pendiente': stock_pendiente,
            'faltantes_totales': faltantes_totales,
        })
        hijos_lineas_por_dte[h.id] = [
            {
                'sku': dp.productoTalla.sku if dp.productoTalla else None,
                'articulo': dp.productoTalla.producto.articulo if dp.productoTalla and dp.productoTalla.producto else dp.descripcion,
                'descripcion': dp.descripcion,
                'talla': dp.productoTalla.talla if dp.productoTalla else None,
                'cantidad': int(dp.stock or 0),
                'monto': int(dp.monto_item or ((dp.precio or 0) * (dp.stock or 0))),
            }
            for dp in h.dte_productos.select_related('productoTalla__producto').all()
        ]
        hijos[-1]['lineas'] = hijos_lineas_por_dte[h.id]

    # --- Movimientos asociados (del DTE y de sus hijos), agrupados por sucursal ---
    dte_ids_mov = [dte.id] + [h['id'] for h in hijos]
    movs_qs = (
        Movimientos_Producto.objects
        .filter(dte_id__in=dte_ids_mov)
        .select_related('ProductoTalla__producto', 'dte', 'sucursal_origen', 'sucursal_destino')
        .order_by('fecha', 'hora', 'id')
    )

    por_sucursal = {}
    for m in movs_qs:
        # Clasificar el movimiento por la sucursal que "se ve afectada":
        # EGRESO -> sucursal_origen (o ProductoTalla.producto.sucursal si falta)
        # INGRESO -> sucursal_destino
        if m.tipo_movimiento == 'INGRESO':
            sucursal = m.sucursal_destino
        else:
            sucursal = m.sucursal_origen
        if sucursal is None and m.ProductoTalla and m.ProductoTalla.producto_id:
            # Intentamos caer al producto -> sucursal si está vacío el mov.
            try:
                sucursal_id = m.ProductoTalla.producto.sucursal_id
                sucursal = None
                key = ('sin_sucursal_def', sucursal_id)
            except Exception:
                sucursal_id = None
                key = ('sin_sucursal', 0)
        else:
            sucursal_id = sucursal.id if sucursal else None
            key = ('sucursal', sucursal_id)

        grupo = por_sucursal.setdefault(key, {
            'sucursal_id': sucursal_id,
            'sucursal_alias': sucursal.alias if sucursal else 'Sin sucursal',
            'items': [],
            'totales': {
                'ingreso': 0,
                'egreso': 0,
                'nc': 0,
                'neto': 0,
            },
        })
        cantidad_abs = abs(int(m.cantidad or 0))
        if m.tipo_movimiento == 'INGRESO':
            grupo['totales']['ingreso'] += cantidad_abs
            grupo['totales']['neto'] += cantidad_abs
        elif m.tipo_movimiento == 'EGRESO':
            grupo['totales']['egreso'] += cantidad_abs
            grupo['totales']['neto'] -= cantidad_abs

        es_nc = bool(m.dte and (m.dte.es_nota_credito or m.dte.tipo_documento in ('NOTA DE CREDITO', 'NOTA_CREDITO')))
        if es_nc:
            grupo['totales']['nc'] += cantidad_abs

        producto = m.ProductoTalla.producto if m.ProductoTalla else None
        grupo['items'].append({
            'id': m.id,
            'dte_id': m.dte_id,
            'dte_numero': m.dte.numero_documento if m.dte else None,
            'dte_tipo': m.dte.tipo_documento if m.dte else None,
            'es_nc': es_nc,
            'es_hijo': m.dte_id != dte.id,
            'fecha': m.fecha.strftime('%Y-%m-%d') if m.fecha else None,
            'hora': m.hora.strftime('%H:%M') if m.hora else None,
            'concepto': m.concepto,
            'tipo_movimiento': m.tipo_movimiento,
            'cantidad': m.cantidad,
            'sku': m.ProductoTalla.sku if m.ProductoTalla else None,
            'articulo': producto.articulo if producto else None,
            'descripcion': producto.descripcion if producto else None,
            'talla': m.ProductoTalla.talla if m.ProductoTalla else None,
            'sucursal_origen': m.sucursal_origen.alias if m.sucursal_origen else None,
            'sucursal_destino': m.sucursal_destino.alias if m.sucursal_destino else None,
            'observaciones': (m.observaciones or '')[:200],
        })

    # --- Historial de cambios de folio ---
    from .models.dte import HistorialCambioFolioDte
    cambios_folio = []
    historial_qs = HistorialCambioFolioDte.objects.filter(
        dte_id__in=dte_ids_mov
    ).order_by('-fecha_cambio')[:20]
    for h in historial_qs:
        cambios_folio.append({
            'dte_id': h.dte_id,
            'folio_anterior': h.folio_anterior,
            'folio_nuevo': h.folio_nuevo,
            'motivo': h.motivo,
            'usuario': h.usuario_nombre or '',
            'fecha': h.fecha_cambio.strftime('%Y-%m-%d %H:%M') if h.fecha_cambio else None,
            'refs_actualizadas': len(h.referencias_actualizadas or []),
        })

    return JsonResponse({
        'success': True,
        'dte': dte_info,
        'padre': {'compras': padre_compras},
        'hijos': hijos,
        'movimientos': {'por_sucursal': list(por_sucursal.values())},
        'cambios_folio': cambios_folio,
    })


# =========================================================================
# REPARACIÓN RETROACTIVA DE NCs HISTÓRICAS SIN MOVIMIENTOS DE STOCK
# =========================================================================

# Conceptos que cuentan como "reversa" válida sobre el stock cuando
# se intenta determinar si una NC devolvió stock. Si una NC tiene al
# menos un INGRESO con alguno de estos conceptos y cantidad suficiente
# en los Producto_Talla afectados, se considera ya reparada.
_CONCEPTOS_REVERSA_STOCK = (
    'ANULACION', 'DEVOLUCION_NC', 'DEVOLUCION_NC_POST_RECEPCION',
    'REPARACION_STOCK_HISTORICO', 'REGULARIZACION_TRASPASO',
    'CAMBIO_PRODUCTO_ENTRADA',
)

# Estados del DTE padre que indican que el destino ya recepcionó
# (determina el flujo post-recepción vs pre-recepción en la reparación).
_ESTADOS_POST_RECEPCION = {
    'RECEPCIONADO_COMPLETO', 'RECEPCIONADO_PARCIAL',
    'RECEPCIONADO_SOBRANTE', 'EN_REGULARIZACION',
}


def _dte_es_post_recepcion(dte):
    """Regla unificada: detecta si el DTE padre ya fue recepcionado."""
    if getattr(dte, 'fecha_recepcion', None) is not None:
        return True
    return getattr(dte, 'estado_dte', None) in _ESTADOS_POST_RECEPCION


def _sucursal_destino_traspaso(dte):
    """
    Retorna la Sucursal destino del traspaso asociado al DTE, mirando
    el primer Movimientos_Producto TRASPASO_SALIDA con sucursal_destino.
    """
    mov = (
        Movimientos_Producto.objects
        .filter(dte=dte, concepto='TRASPASO_SALIDA', sucursal_destino__isnull=False)
        .select_related('sucursal_destino')
        .first()
    )
    return mov.sucursal_destino if mov else None


def _diagnostico_nc(nc):
    """
    Calcula por cada línea de la NC cuántas unidades ya fueron reversadas
    en Producto_Talla (vía movimientos de reversa) y cuántas faltan.

    Retorna dict:
        {
          'nc_id': ..., 'nc_numero': ..., 'dte_padre_id': ...,
          'dte_padre_numero': ..., 'dte_padre_tipo': ...,
          'sucursal_origen_id': ..., 'sucursal_origen': ...,
          'sucursal_destino_id': ..., 'sucursal_destino': ...,
          'recepcionado': bool,
          'ya_reparado': bool,  # hay al menos un REPARACION_STOCK_HISTORICO sobre la NC
          'lineas': [
            {'sku': ..., 'talla': ..., 'descripcion': ...,
             'dte_producto_id': ..., 'productoTalla_id': ...,
             'cantidad_nc': N,
             'movimientos_existentes': M,
             'esperados': N,
             'faltantes': N - M,
             'stock_origen_actual': X,
             'stock_destino_actual': Y or None,
             'reparable': bool}, ...]
        }

    `None` si la NC no aplica (p.ej. no apunta a un traspaso).
    """
    padre = nc.documento_afectado
    if padre is None or padre.tipo_transaccion != 'TRASPASO':
        return None

    sucursal_origen = nc.sucursal or padre.sucursal
    sucursal_destino = _sucursal_destino_traspaso(padre)
    es_post = _dte_es_post_recepcion(padre)

    # Idempotencia: ya reparada si hay al menos un movimiento con ese concepto.
    ya_reparado = Movimientos_Producto.objects.filter(
        dte=nc, concepto='REPARACION_STOCK_HISTORICO',
    ).exists()

    # Determinar las líneas relevantes. Preferimos las líneas de la NC
    # (copia de lo devuelto); si la NC no tiene líneas con productoTalla
    # (caso legacy de NC parcial con línea genérica), caemos al padre.
    lineas_nc = list(
        nc.dte_productos.exclude(productoTalla__isnull=True)
        .select_related('productoTalla__producto')
    )
    usar_padre = False
    if not lineas_nc:
        usar_padre = True
        lineas_nc = list(
            padre.dte_productos.filter(activo=True)
            .exclude(productoTalla__isnull=True)
            .select_related('productoTalla__producto')
        )

    if not lineas_nc:
        return None

    # Pre-cargar stock actual por Producto_Talla relevante.
    skus = {dp.productoTalla.sku for dp in lineas_nc}
    sucursales_objetivo = [sucursal_origen.id] if sucursal_origen else []
    if sucursal_destino:
        sucursales_objetivo.append(sucursal_destino.id)
    stock_por_sku = {}
    if skus and sucursales_objetivo:
        for pt in (
            Producto_Talla.objects
            .filter(sku__in=skus, producto__sucursal_id__in=sucursales_objetivo)
            .select_related('producto')
        ):
            stock_por_sku.setdefault(pt.sku, {})[pt.producto.sucursal_id] = int(pt.stock or 0)

    # Movimientos de reversa existentes asociados al DTE padre o a la NC
    # (el bug histórico es que no existen, pero consideramos por si alguna
    # reparación parcial ya fue hecha).
    movs_reversa = (
        Movimientos_Producto.objects
        .filter(
            dte__in=[padre.id, nc.id],
            concepto__in=_CONCEPTOS_REVERSA_STOCK,
            tipo_movimiento='INGRESO',
        )
        .values('ProductoTalla__sku')
        .annotate(total=Sum('cantidad'))
    )
    movs_por_sku = {row['ProductoTalla__sku']: int(row['total'] or 0) for row in movs_reversa}

    lineas_out = []
    total_faltantes = 0
    for dp in lineas_nc:
        sku = dp.productoTalla.sku
        cantidad_nc = int(dp.stock or 0)
        movs_existentes = movs_por_sku.get(sku, 0)
        faltantes = max(0, cantidad_nc - movs_existentes)
        if faltantes <= 0:
            # Esta línea ya fue reparada (o nunca tuvo bug).
            continue
        stock_origen = stock_por_sku.get(sku, {}).get(sucursal_origen.id if sucursal_origen else None)
        stock_destino = (
            stock_por_sku.get(sku, {}).get(sucursal_destino.id)
            if sucursal_destino else None
        )
        # Reparable si hay stock suficiente en destino (post-rec) o siempre (pre-rec).
        if es_post:
            reparable = stock_destino is not None and stock_destino >= faltantes
        else:
            reparable = True

        lineas_out.append({
            'sku': sku,
            'talla': dp.productoTalla.talla,
            'descripcion': dp.descripcion,
            'dte_producto_id': dp.id,
            'productoTalla_id': dp.productoTalla_id,
            'cantidad_nc': cantidad_nc,
            'movimientos_existentes': movs_existentes,
            'esperados': cantidad_nc,
            'faltantes': faltantes,
            'stock_origen_actual': stock_origen,
            'stock_destino_actual': stock_destino,
            'reparable': reparable,
        })
        total_faltantes += faltantes

    if not lineas_out:
        return None

    return {
        'nc_id': nc.id,
        'nc_numero': nc.numero_documento,
        'nc_tipo': nc.tipo_documento,
        'nc_fecha': nc.fecha_emision.strftime('%Y-%m-%d') if nc.fecha_emision else None,
        'nc_monto': float(nc.monto_con_iva or 0),
        'dte_padre_id': padre.id,
        'dte_padre_numero': padre.numero_documento,
        'dte_padre_tipo': padre.tipo_documento,
        'dte_padre_estado': padre.estado_dte,
        'sucursal_origen_id': sucursal_origen.id if sucursal_origen else None,
        'sucursal_origen': sucursal_origen.alias if sucursal_origen else None,
        'sucursal_destino_id': sucursal_destino.id if sucursal_destino else None,
        'sucursal_destino': sucursal_destino.alias if sucursal_destino else None,
        'recepcionado': es_post,
        'usar_lineas_padre': usar_padre,
        'ya_reparado': ya_reparado,
        'total_faltantes': total_faltantes,
        'lineas': lineas_out,
    }


def detectar_ncs_sin_stock(empresa_id=None, sucursal_id=None,
                           fecha_inicio=None, fecha_fin=None,
                           tipo_documento_padre=None, limit=None):
    """
    Recorre las NC/AJUSTE que afectan a un DTE de traspaso y retorna la
    lista de diagnósticos por cada una que tenga líneas faltantes.

    Parámetros:
        empresa_id: acota por emisor del DTE padre.
        sucursal_id: acota por sucursal emisora (nc.sucursal).
        fecha_inicio/fecha_fin: sobre fecha_emision de la NC.
        tipo_documento_padre: p.ej. 'GUIA', 'FACTURA ELECTRONICA'.
        limit: tope de resultados (para paginación simple).
    """
    qs = (
        Dte.objects
        .filter(documento_afectado__isnull=False)
        .filter(
            Q(es_nota_credito=True)
            | Q(tipo_documento__in=[
                'NOTA DE CREDITO', 'AJUSTE TRASPASO', 'AJUSTE TRASPASO POST',
            ])
        )
        .filter(documento_afectado__tipo_transaccion='TRASPASO')
        .exclude(estado_dte__in=['CANCELADO', 'ANULADO'])
        .select_related('documento_afectado', 'sucursal')
        .order_by('-fecha_emision', '-id')
    )
    if empresa_id:
        qs = qs.filter(documento_afectado__emisor_id=empresa_id)
    if sucursal_id:
        qs = qs.filter(sucursal_id=sucursal_id)
    if fecha_inicio:
        qs = qs.filter(fecha_emision__gte=fecha_inicio)
    if fecha_fin:
        qs = qs.filter(fecha_emision__lte=fecha_fin)
    if tipo_documento_padre:
        qs = qs.filter(documento_afectado__tipo_documento=tipo_documento_padre)

    resultados = []
    for nc in qs.iterator(chunk_size=200):
        diag = _diagnostico_nc(nc)
        if diag and not diag['ya_reparado']:
            resultados.append(diag)
            if limit and len(resultados) >= limit:
                break
    return resultados


@login_required
@require_GET
def api_ncs_sin_stock(request):
    """
    Lista NCs / AJUSTEs sobre traspasos que no generaron los movimientos
    de reversa esperados (stock nunca volvió).

    Query params:
        empresa_id (opcional) — por defecto toma la de la sesión.
        sucursal_id (opcional) — por defecto toma la de la sesión.
        fecha_inicio / fecha_fin (opcional, YYYY-MM-DD).
        tipo_documento_padre (opcional).
        pagina (opcional, default 1), page_size (default 20).
    """
    try:
        empresa_id = (
            request.GET.get('empresa_id')
            or request.session.get('idEmpresaActual')
        )
        sucursal_id = request.GET.get('sucursal_id')
        if sucursal_id == '':
            sucursal_id = None
        # Si no se pidió sucursal explícita, por default NO filtramos por
        # sucursal (el administrador quiere ver todas). El usuario puede
        # acotar desde el UI.
        fecha_inicio = request.GET.get('fecha_inicio') or None
        fecha_fin = request.GET.get('fecha_fin') or None
        tipo_doc_padre = request.GET.get('tipo_documento_padre') or None
        pagina = max(int(request.GET.get('pagina', 1) or 1), 1)
        page_size = min(max(int(request.GET.get('page_size', 20) or 20), 1), 100)

        detectados = detectar_ncs_sin_stock(
            empresa_id=empresa_id,
            sucursal_id=sucursal_id,
            fecha_inicio=fecha_inicio,
            fecha_fin=fecha_fin,
            tipo_documento_padre=tipo_doc_padre,
            # No ponemos limit aquí — queremos conteo real para paginar.
        )
        total = len(detectados)
        inicio = (pagina - 1) * page_size
        items = detectados[inicio:inicio + page_size]

        return JsonResponse({
            'success': True,
            'items': items,
            'total': total,
            'pagina': pagina,
            'page_size': page_size,
            'total_paginas': (total + page_size - 1) // page_size if page_size else 1,
        })
    except Exception as e:
        logger.exception("Error al detectar NC sin stock")
        return JsonResponse({'success': False, 'error': f'Error: {e}'}, status=500)


def reparar_nc_stock(nc, lineas_solicitadas, usuario, motivo=''):
    """
    Aplica la reparación retroactiva a una NC histórica: crea los
    `Movimientos_Producto` faltantes para que el stock vuelva a quedar
    consistente con la NC ya emitida.

    Parámetros:
        nc: instancia Dte con es_nota_credito=True (o AJUSTE TRASPASO).
        lineas_solicitadas: list[{'sku': int, 'cantidad': int}].
        usuario: str (username).
        motivo: str opcional.

    Retorna:
        (status_code, dict_resultado)
        status_code: 200 OK, 400 validación, 409 conflicto (idempotencia
            o stock insuficiente).

    Comportamiento:
    - Idempotencia: si ya existen movimientos REPARACION_STOCK_HISTORICO
      para esta NC, retorna 409 con ya_reparado=True (no duplica).
    - Si el traspaso padre fue recepcionado: EGRESO en destino + INGRESO
      en origen. Valida stock destino.
    - Si aún no fue recepcionado: sólo INGRESO en origen.
    - Todas las operaciones van dentro de una transacción atómica.
    """
    from decimal import Decimal as _D
    from django.db import transaction as _tx

    padre = nc.documento_afectado
    if padre is None or padre.tipo_transaccion != 'TRASPASO':
        return 400, {'success': False, 'error': 'La NC no apunta a un traspaso válido.'}

    # Idempotencia fuerte: movimientos con concepto REPARACION_STOCK_HISTORICO
    # vinculados a esta NC indican que ya fue reparada (al menos parcialmente).
    if Movimientos_Producto.objects.filter(
        dte=nc, concepto='REPARACION_STOCK_HISTORICO'
    ).exists():
        return 409, {
            'success': False,
            'ya_reparado': True,
            'error': (
                f'La NC #{nc.numero_documento} ya fue reparada previamente. '
                f'Si detectas stock faltante, revisá los movimientos '
                f'REPARACION_STOCK_HISTORICO asociados.'
            ),
        }

    if not lineas_solicitadas:
        return 400, {'success': False, 'error': 'Debe indicar al menos una línea a reparar.'}

    sucursal_origen = nc.sucursal or padre.sucursal
    if sucursal_origen is None:
        return 400, {
            'success': False,
            'error': 'La NC no tiene sucursal emisora. Imposible determinar origen.',
        }

    es_post = _dte_es_post_recepcion(padre)
    sucursal_destino = _sucursal_destino_traspaso(padre) if es_post else None
    if es_post and sucursal_destino is None:
        return 400, {
            'success': False,
            'error': (
                'El padre está en estado recepcionado pero no hay movimiento '
                'TRASPASO_SALIDA que revele la sucursal destino. Revisar manualmente.'
            ),
        }

    # Validación: cada línea solicitada debe tener cantidad > 0 y no
    # exceder los faltantes según el diagnóstico actual.
    diag = _diagnostico_nc(nc)
    if diag is None:
        return 400, {
            'success': False,
            'error': 'Esta NC no tiene líneas aptas para reparación.',
        }
    faltantes_por_sku = {l['sku']: l['faltantes'] for l in diag['lineas']}

    lineas_normalizadas = []
    for l in lineas_solicitadas:
        try:
            sku = int(l.get('sku'))
            cant = int(l.get('cantidad'))
        except (TypeError, ValueError):
            return 400, {
                'success': False,
                'error': 'Línea con formato inválido. Esperado {sku, cantidad}.',
            }
        if cant <= 0:
            return 400, {
                'success': False,
                'error': f'La cantidad para SKU {sku} debe ser mayor a 0.',
            }
        if sku not in faltantes_por_sku:
            return 400, {
                'success': False,
                'error': (
                    f'El SKU {sku} no está entre las líneas pendientes de reparación de '
                    f'la NC #{nc.numero_documento}.'
                ),
            }
        if cant > faltantes_por_sku[sku]:
            return 400, {
                'success': False,
                'error': (
                    f'El SKU {sku} tiene {faltantes_por_sku[sku]} uds pendientes, '
                    f'no se pueden reparar {cant}.'
                ),
            }
        lineas_normalizadas.append((sku, cant))

    hoy = timezone.now()
    skus_set = {s for s, _ in lineas_normalizadas}

    try:
        with _tx.atomic():
            # Buscar Producto_Talla en origen y destino (con lock).
            tallas_origen_qs = (
                Producto_Talla.objects
                .select_for_update(of=('self',))
                .filter(sku__in=skus_set, producto__sucursal_id=sucursal_origen.id)
                .select_related('producto')
            )
            tallas_origen = {t.sku: t for t in tallas_origen_qs}

            tallas_destino = {}
            if es_post:
                tallas_destino_qs = (
                    Producto_Talla.objects
                    .select_for_update(of=('self',))
                    .filter(sku__in=skus_set, producto__sucursal_id=sucursal_destino.id)
                    .select_related('producto')
                )
                tallas_destino = {t.sku: t for t in tallas_destino_qs}

            # Validaciones previas.
            for sku, cant in lineas_normalizadas:
                if sku not in tallas_origen:
                    raise ValueError(
                        f'No se encontró Producto_Talla en origen ({sucursal_origen.alias}) '
                        f'para SKU {sku}.'
                    )
                if es_post:
                    if sku not in tallas_destino:
                        raise ValueError(
                            f'No se encontró Producto_Talla en destino '
                            f'({sucursal_destino.alias}) para SKU {sku}.'
                        )
                    # Releer stock con lock.
                    stock_dest = int(tallas_destino[sku].stock or 0)
                    if stock_dest < cant:
                        return 409, {
                            'success': False,
                            'stock_insuficiente': True,
                            'sku': sku,
                            'disponible_destino': stock_dest,
                            'solicitado': cant,
                            'sugerencia': 'regularizar_con_receptor',
                            'error': (
                                f'Stock insuficiente en destino ({sucursal_destino.alias}) '
                                f'para SKU {sku}: disponible {stock_dest}, '
                                f'solicitado {cant}. Si parte ya se vendió, coordine '
                                f'regularización con el receptor.'
                            ),
                        }

            # Aplicar movimientos por línea.
            stock_delta = []
            total_repuesto = 0
            for sku, cant in lineas_normalizadas:
                talla_origen = tallas_origen[sku]
                precio_ref = 0
                # Precio de referencia: el del Dte_Productos de la NC o del padre.
                dp_nc = nc.dte_productos.filter(productoTalla__sku=sku).first()
                if dp_nc is None:
                    dp_nc = padre.dte_productos.filter(productoTalla__sku=sku).first()
                if dp_nc is not None:
                    precio_ref = int(dp_nc.precio or 0)

                obs_base = (
                    f'Reparación retroactiva NC #{nc.numero_documento} '
                    f'sobre DTE #{padre.numero_documento} ({padre.tipo_documento}).'
                )
                if motivo:
                    obs_base += f' Motivo: {motivo}'

                if es_post:
                    talla_destino = tallas_destino[sku]
                    # EGRESO en destino.
                    Producto_Talla.objects.filter(id=talla_destino.id).update(
                        stock=F('stock') - cant
                    )
                    Movimientos_Producto.objects.create(
                        dte=nc,
                        ProductoTalla=talla_destino,
                        sucursal_origen=sucursal_destino,
                        sucursal_destino=None,
                        cantidad=-cant,
                        costo=dp_nc.costo if dp_nc else 0,
                        sobreprecio=dp_nc.sobreprecio if dp_nc else 0,
                        precio=precio_ref,
                        concepto='REPARACION_STOCK_HISTORICO',
                        tipo_movimiento='EGRESO',
                        estado='COMPLETADO',
                        responsable=usuario,
                        observaciones=f'{obs_base} EGRESO reparación en destino.'[:500],
                    )
                # INGRESO en origen (ambos flujos).
                Producto_Talla.objects.filter(id=talla_origen.id).update(
                    stock=F('stock') + cant
                )
                Movimientos_Producto.objects.create(
                    dte=nc,
                    ProductoTalla=talla_origen,
                    sucursal_origen=None,
                    sucursal_destino=sucursal_origen,
                    cantidad=cant,
                    costo=dp_nc.costo if dp_nc else 0,
                    sobreprecio=dp_nc.sobreprecio if dp_nc else 0,
                    precio=precio_ref,
                    concepto='REPARACION_STOCK_HISTORICO',
                    tipo_movimiento='INGRESO',
                    estado='COMPLETADO',
                    responsable=usuario,
                    observaciones=f'{obs_base} INGRESO reparación en origen.'[:500],
                )
                total_repuesto += cant

            # Tag en referencias para idempotencia visual y auditoría.
            tag = (
                f"\n[REPARACION_STOCK_HISTORICO {hoy.strftime('%Y-%m-%d %H:%M')} "
                f"{usuario}: +{total_repuesto} uds origen"
                f"{', -' + str(total_repuesto) + ' uds destino' if es_post else ''}"
                f"{'. Motivo: ' + motivo if motivo else ''}]"
            )
            nc.referencias = ((nc.referencias or '') + tag).strip()
            nc.save(update_fields=['referencias'])

            # Calcular stock actual para la respuesta.
            sucursales_resp = [sucursal_origen.id]
            if es_post:
                sucursales_resp.append(sucursal_destino.id)
            for t in (
                Producto_Talla.objects
                .filter(sku__in=skus_set, producto__sucursal_id__in=sucursales_resp)
                .select_related('producto', 'producto__sucursal')
            ):
                stock_delta.append({
                    'sku': t.sku,
                    'talla': t.talla,
                    'sucursal_id': t.producto.sucursal_id,
                    'sucursal_alias': t.producto.sucursal.alias if t.producto.sucursal else None,
                    'stock': int(t.stock or 0),
                })

            logger.info(
                "Reparación NC histórica: nc=%s padre=%s post=%s total_repuesto=%s usuario=%s",
                nc.id, padre.id, es_post, total_repuesto, usuario,
            )
            return 200, {
                'success': True,
                'message': (
                    f'Reparación aplicada sobre NC #{nc.numero_documento}: '
                    f'{total_repuesto} uds reingresadas al origen'
                    f'{" y descontadas del destino" if es_post else ""}.'
                ),
                'nc_id': nc.id,
                'es_post_recepcion': es_post,
                'total_repuesto': total_repuesto,
                'stock_delta': stock_delta,
            }
    except ValueError as ve:
        return 400, {'success': False, 'error': str(ve)}
    except Exception as e:
        logger.exception("Error al aplicar reparacion de NC historica")
        return 500, {'success': False, 'error': f'Error al aplicar reparación: {e}'}


@login_required
@requiere_permiso('recepcion_dte', 'puede_aprobar')
@require_http_methods(["POST"])
def api_reparar_stock_nc(request, nc_id):
    """
    Aplica la reparación retroactiva sobre una NC histórica. Body JSON:

        {
          "lineas": [{"sku": 1234, "cantidad": 3}],
          "motivo": "Reparación retroactiva: NC original no generó movimientos."
        }

    Respuestas:
        200 OK con stock_delta y total_repuesto.
        400 validación (línea faltante, cantidad inválida, sin stock origen).
        409 conflicto (ya_reparado o stock_insuficiente en destino).
    """
    try:
        body = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'JSON inválido.'}, status=400)

    lineas = body.get('lineas') or []
    motivo = (body.get('motivo') or '').strip()

    try:
        nc = Dte.objects.select_related('documento_afectado', 'sucursal').get(id=nc_id)
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'NC no encontrada.'}, status=404)

    # Debe ser una NC / AJUSTE sobre traspaso.
    es_nc_valida = (
        bool(nc.es_nota_credito)
        or nc.tipo_documento in ('NOTA DE CREDITO', 'AJUSTE TRASPASO', 'AJUSTE TRASPASO POST')
    )
    if not es_nc_valida:
        return JsonResponse({
            'success': False,
            'error': 'El DTE indicado no es una NC ni un AJUSTE sobre traspaso.',
        }, status=400)

    # Verificar permiso a nivel sucursal del emisor.
    empresa_actual_id = request.session.get('idEmpresaActual')
    if empresa_actual_id and nc.emisor_id and nc.emisor_id != empresa_actual_id:
        return JsonResponse({
            'success': False,
            'error': 'Sin permiso sobre esta NC (empresa distinta).',
        }, status=403)

    status, payload = reparar_nc_stock(
        nc=nc,
        lineas_solicitadas=lineas,
        usuario=request.user.username,
        motivo=motivo,
    )
    return JsonResponse(payload, status=status)


@login_required
@requiere_permiso('recepcion_dte', 'puede_aprobar')
@require_http_methods(["POST"])
def api_crear_skus_destino(request, dte_id):
    """
    Replica en la sucursal destino del traspaso los `Producto`/`Producto_Talla`
    de los SKUs indicados, cuando aún no existen allí. Sirve para habilitar
    NCs/ajustes post-recepción cuando el destino nunca había recibido el
    SKU antes (típico cuando el primer despacho falla y se necesita NC sin
    haber confirmado recepción).

    Body JSON:
        { "skus": [12345, 23456, ...] }

    El stock destino se crea en 0 — la NC posterior generará el descuento
    apropiado o quedará pendiente de regularización por el receptor.

    Respuestas:
        200 OK con `creados`, `existentes`, `errores`.
        400 validación (DTE no es traspaso, sin SKUs, etc).
        404 DTE no encontrado.
    """
    try:
        body = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'JSON inválido.'}, status=400)

    skus_input = body.get('skus') or []
    if not isinstance(skus_input, list) or not skus_input:
        return JsonResponse({
            'success': False,
            'error': 'Debe enviar una lista no vacía de SKUs.',
        }, status=400)

    skus_set = set()
    for s in skus_input:
        try:
            skus_set.add(int(s))
        except (TypeError, ValueError):
            return JsonResponse({
                'success': False,
                'error': f'SKU inválido: {s!r}',
            }, status=400)

    try:
        dte = (
            Dte.objects
            .select_related('sucursal')
            .get(id=dte_id)
        )
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if dte.tipo_transaccion != 'TRASPASO':
        return JsonResponse({
            'success': False,
            'error': 'Sólo aplica a DTE de traspaso.',
        }, status=400)

    sucursal_destino = _sucursal_destino_traspaso(dte)
    if sucursal_destino is None:
        return JsonResponse({
            'success': False,
            'error': 'No se pudo identificar la sucursal destino del traspaso.',
        }, status=400)

    # Sólo el emisor puede solicitar la replicación.
    sucursal_actual_id = request.session.get('idSucursalActual')
    if sucursal_actual_id and dte.sucursal_id != int(sucursal_actual_id):
        return JsonResponse({
            'success': False,
            'error': 'Sólo la sucursal emisora puede replicar SKUs en destino.',
        }, status=403)

    # Buscar tallas de origen para los SKUs solicitados.
    tallas_origen = {
        t.sku: t for t in (
            Producto_Talla.objects
            .filter(sku__in=skus_set, producto__sucursal_id=dte.sucursal_id)
            .select_related('producto')
        )
    }
    tallas_destino_existentes = set(
        Producto_Talla.objects
        .filter(sku__in=skus_set, producto__sucursal_id=sucursal_destino.id)
        .values_list('sku', flat=True)
    )

    creados = []
    existentes = []
    errores = []
    usuario = request.user.username

    try:
        with transaction.atomic():
            for sku in skus_set:
                if sku in tallas_destino_existentes:
                    existentes.append(sku)
                    continue
                talla_origen = tallas_origen.get(sku)
                if talla_origen is None:
                    errores.append({
                        'sku': sku,
                        'error': 'No existe en sucursal origen del DTE.',
                    })
                    continue
                producto_origen = talla_origen.producto
                if producto_origen is None:
                    errores.append({
                        'sku': sku,
                        'error': 'Producto_Talla sin Producto asociado.',
                    })
                    continue

                # Reusar Producto existente en destino si hay coincidencia
                # exacta de articulo + atributos (igual criterio que
                # confirmar_recepcion_api). Si no, crear uno nuevo.
                producto_destino_qs = Producto.objects.filter(
                    articulo=producto_origen.articulo,
                    sucursal=sucursal_destino,
                    atributo1=producto_origen.atributo1,
                    atributo2=producto_origen.atributo2,
                    atributo3=producto_origen.atributo3,
                    atributo4=producto_origen.atributo4,
                ).order_by('id')
                producto_destino = producto_destino_qs.first()
                if producto_destino is None:
                    producto_destino = Producto.objects.create(
                        articulo=producto_origen.articulo,
                        sucursal=sucursal_destino,
                        atributo1=producto_origen.atributo1,
                        atributo2=producto_origen.atributo2,
                        atributo3=producto_origen.atributo3,
                        atributo4=producto_origen.atributo4,
                        descripcion=producto_origen.descripcion,
                        categoria=producto_origen.categoria,
                        costo=producto_origen.costo,
                        sobreprecio=producto_origen.sobreprecio,
                        precioventa=producto_origen.precioventa,
                        precioSugerido=producto_origen.precioSugerido,
                        tipo_talla=producto_origen.tipo_talla,
                        guia_talla=producto_origen.guia_talla,
                    )

                Producto_Talla.objects.create(
                    producto=producto_destino,
                    talla=talla_origen.talla,
                    sku=sku,
                    stock=0,
                )
                creados.append({
                    'sku': sku,
                    'talla': talla_origen.talla,
                    'articulo': producto_origen.articulo,
                })
    except Exception as e:
        logger.exception("Error al replicar SKUs en destino")
        return JsonResponse({
            'success': False,
            'error': f'Error al replicar SKUs: {e}',
        }, status=500)

    logger.info(
        "Replicación SKUs en destino: dte=%s destino=%s creados=%s existentes=%s errores=%s usuario=%s",
        dte.id, sucursal_destino.alias, len(creados), len(existentes), len(errores), usuario,
    )

    return JsonResponse({
        'success': True,
        'sucursal_destino': {
            'id': sucursal_destino.id,
            'alias': sucursal_destino.alias,
        },
        'creados': creados,
        'existentes': existentes,
        'errores': errores,
        'message': (
            f'{len(creados)} SKU(s) replicados en {sucursal_destino.alias}. '
            f'{len(existentes)} ya existían'
            f'{f", {len(errores)} con error" if errores else ""}.'
        ),
    })


@login_required
@requiere_permiso('recepcion_dte', 'puede_aprobar')
@require_http_methods(["POST"])
def api_crear_stock_destino_manual(request, dte_id):
    """
    Permite al emisor "forzar" la creación de stock en la sucursal destino
    de un DTE de TRASPASO sin pasar por el flujo normal de
    `confirmar_recepcion_api`. Útil cuando el receptor no puede recepcionar
    (problemas de acceso, recepción retroactiva, etc.) pero la mercadería
    ya está físicamente en destino.

    Body JSON:
        {
            "items": [
                {"sku": 12345, "stock_final": 5},
                {"sku": 12346, "stock_final": 3}
            ],
            "motivo": "Recepción manual: usuario X en bodega"
        }

    Validaciones:
        - DTE debe ser TRASPASO con sucursal_destino identificable.
        - DTE NO debe tener NC/Ajuste asociado (si tiene, usar el flujo
          normal de NC en su lugar).
        - Sólo el emisor puede invocar la acción.
        - Motivo obligatorio.

    Comportamiento (transacción atómica):
        1. Por cada item:
           - Crea `Producto_Talla` en destino si no existe (stock=0).
           - Calcula delta = stock_final - stock_actual.
           - Aplica delta a `Producto_Talla.stock` del destino.
           - Crea `Movimientos_Producto` con concepto
             `AJUSTE_STOCK_MANUAL_DESTINO`, INGRESO si delta>0,
             EGRESO si delta<0. Si delta=0 no crea movimiento.
        2. Marca el DTE como `RECEPCIONADO_COMPLETO` con
           `fecha_recepcion=hoy` y registra el motivo en `referencias`.

    Respuesta:
        200 OK con `creados`, `stock_delta`, `dte_estado`.
        400 / 404 / 409 según el error.
    """
    try:
        body = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'JSON inválido.'}, status=400)

    items_input = body.get('items') or []
    motivo = (body.get('motivo') or '').strip()

    if not isinstance(items_input, list) or not items_input:
        return JsonResponse({
            'success': False,
            'error': 'Debe enviar al menos un item con sku y stock_final.',
        }, status=400)
    if not motivo:
        return JsonResponse({
            'success': False,
            'error': 'El motivo es obligatorio para auditoría.',
        }, status=400)

    items_normalizados = []
    skus_set = set()
    for it in items_input:
        try:
            sku = int(it.get('sku'))
            stock_final = int(it.get('stock_final'))
        except (TypeError, ValueError):
            return JsonResponse({
                'success': False,
                'error': 'Item con formato inválido. Esperado {sku, stock_final}.',
            }, status=400)
        if stock_final < 0:
            return JsonResponse({
                'success': False,
                'error': f'stock_final no puede ser negativo (sku {sku}).',
            }, status=400)
        if sku in skus_set:
            return JsonResponse({
                'success': False,
                'error': f'SKU {sku} duplicado en items.',
            }, status=400)
        skus_set.add(sku)
        items_normalizados.append((sku, stock_final))

    try:
        dte = (
            Dte.objects
            .select_related('sucursal')
            .get(id=dte_id)
        )
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if dte.tipo_transaccion != 'TRASPASO':
        return JsonResponse({
            'success': False,
            'error': 'Sólo aplica a DTE de traspaso.',
        }, status=400)

    sucursal_actual_id = request.session.get('idSucursalActual')
    if sucursal_actual_id and dte.sucursal_id != int(sucursal_actual_id):
        return JsonResponse({
            'success': False,
            'error': 'Sólo la sucursal emisora puede crear stock en destino.',
        }, status=403)

    sucursal_destino = _sucursal_destino_traspaso(dte)
    if sucursal_destino is None:
        return JsonResponse({
            'success': False,
            'error': 'No se pudo identificar la sucursal destino del traspaso.',
        }, status=400)

    # Bloqueo: si el DTE ya tiene NC/Ajuste, el emisor debería usar el
    # flujo de NC en lugar de "Crear stock". Mezclarlos lleva a stock
    # inconsistente.
    tiene_hijos = (
        Dte.objects
        .filter(documento_afectado=dte)
        .exclude(estado_dte__in=['CANCELADO', 'ANULADO'])
        .exists()
    )
    if tiene_hijos:
        return JsonResponse({
            'success': False,
            'error': (
                'Este DTE ya tiene NC/Ajuste asociado. Usa el flujo de NC '
                'para corregir cantidades, no la creación manual de stock.'
            ),
        }, status=409)

    if dte.estado_dte in ('CANCELADO', 'ANULADO'):
        return JsonResponse({
            'success': False,
            'error': f'El DTE está {dte.estado_dte}. No se puede crear stock.',
        }, status=409)

    usuario = request.user.username
    hoy_dt = timezone.now()
    creados = []
    actualizados = []
    movimientos_resumen = []
    delta_total = 0

    try:
        with transaction.atomic():
            # Pre-cargar tallas existentes en destino con lock.
            tallas_destino = {
                t.sku: t for t in (
                    Producto_Talla.objects
                    .select_for_update(of=('self',))
                    .filter(
                        sku__in=skus_set,
                        producto__sucursal_id=sucursal_destino.id,
                    )
                    .select_related('producto')
                )
            }
            # Pre-cargar tallas en origen (necesitamos referencia para
            # crear el Producto en destino si falta).
            tallas_origen = {
                t.sku: t for t in (
                    Producto_Talla.objects
                    .filter(
                        sku__in=skus_set,
                        producto__sucursal_id=dte.sucursal_id,
                    )
                    .select_related('producto')
                )
            }

            for sku, stock_final in items_normalizados:
                talla_destino = tallas_destino.get(sku)
                creada_ahora = False

                if talla_destino is None:
                    # Crear Producto_Talla en destino reusando atributos
                    # del origen (igual a confirmar_recepcion_api).
                    talla_origen = tallas_origen.get(sku)
                    if talla_origen is None:
                        transaction.set_rollback(True)
                        return JsonResponse({
                            'success': False,
                            'error': (
                                f'SKU {sku} no existe en sucursal origen del '
                                f'DTE. No se puede replicar.'
                            ),
                        }, status=400)
                    producto_origen = talla_origen.producto

                    producto_destino = (
                        Producto.objects.filter(
                            articulo=producto_origen.articulo,
                            sucursal=sucursal_destino,
                            atributo1=producto_origen.atributo1,
                            atributo2=producto_origen.atributo2,
                            atributo3=producto_origen.atributo3,
                            atributo4=producto_origen.atributo4,
                        ).order_by('id').first()
                    )
                    if producto_destino is None:
                        producto_destino = Producto.objects.create(
                            articulo=producto_origen.articulo,
                            sucursal=sucursal_destino,
                            atributo1=producto_origen.atributo1,
                            atributo2=producto_origen.atributo2,
                            atributo3=producto_origen.atributo3,
                            atributo4=producto_origen.atributo4,
                            descripcion=producto_origen.descripcion,
                            categoria=producto_origen.categoria,
                            costo=producto_origen.costo,
                            sobreprecio=producto_origen.sobreprecio,
                            precioventa=producto_origen.precioventa,
                            precioSugerido=producto_origen.precioSugerido,
                            tipo_talla=producto_origen.tipo_talla,
                            guia_talla=producto_origen.guia_talla,
                        )
                    talla_destino = Producto_Talla.objects.create(
                        producto=producto_destino,
                        talla=talla_origen.talla,
                        sku=sku,
                        stock=0,
                    )
                    creada_ahora = True

                stock_actual = int(talla_destino.stock or 0)
                delta = stock_final - stock_actual

                if delta != 0:
                    Producto_Talla.objects.filter(id=talla_destino.id).update(
                        stock=F('stock') + delta
                    )
                    Movimientos_Producto.objects.create(
                        dte=dte,
                        ProductoTalla=talla_destino,
                        sucursal_origen=dte.sucursal if delta > 0 else sucursal_destino,
                        sucursal_destino=sucursal_destino if delta > 0 else None,
                        cantidad=delta,
                        costo=talla_destino.producto.costo if talla_destino.producto else 0,
                        sobreprecio=(
                            talla_destino.producto.sobreprecio
                            if talla_destino.producto else 0
                        ),
                        precio=(
                            talla_destino.producto.precioventa
                            if talla_destino.producto else 0
                        ),
                        concepto='AJUSTE_STOCK_MANUAL_DESTINO',
                        tipo_movimiento='INGRESO' if delta > 0 else 'EGRESO',
                        estado='COMPLETADO',
                        responsable=usuario,
                        observaciones=(
                            f'Creación manual stock destino DTE '
                            f'#{dte.numero_documento} (sku {sku}): '
                            f'{stock_actual}→{stock_final}. Motivo: {motivo}'
                        )[:500],
                    )

                movimientos_resumen.append({
                    'sku': sku,
                    'talla': talla_destino.talla,
                    'stock_anterior': stock_actual,
                    'stock_final': stock_final,
                    'delta': delta,
                    'creada_ahora': creada_ahora,
                })
                if creada_ahora:
                    creados.append(sku)
                else:
                    actualizados.append(sku)
                delta_total += delta

            # Marcar el DTE como recepcionado (manualmente).
            dte.estado_dte = 'RECEPCIONADO_COMPLETO'
            dte.fecha_recepcion = timezone.localdate()
            registro = (
                f"\n[STOCK MANUAL DESTINO] {hoy_dt.strftime('%Y-%m-%d %H:%M')} "
                f"{usuario} → {sucursal_destino.alias}: "
                f"{len(items_normalizados)} item(s), delta total {delta_total:+d}. "
                f"Motivo: {motivo}"
            )
            dte.referencias = ((dte.referencias or '') + registro).strip()
            dte.save(update_fields=['estado_dte', 'fecha_recepcion', 'referencias'])
    except Exception as e:
        logger.exception("Error al crear stock manual en destino")
        return JsonResponse({
            'success': False,
            'error': f'Error al crear stock: {e}',
        }, status=500)

    # Stock final por SKU para refresco de UI.
    stock_delta = []
    for t in (
        Producto_Talla.objects
        .filter(sku__in=skus_set, producto__sucursal_id=sucursal_destino.id)
        .select_related('producto', 'producto__sucursal')
    ):
        stock_delta.append({
            'sku': t.sku,
            'talla': t.talla,
            'sucursal_id': t.producto.sucursal_id,
            'sucursal_alias': t.producto.sucursal.alias if t.producto.sucursal else None,
            'stock': int(t.stock or 0),
        })

    logger.info(
        "Crear stock manual destino: dte=%s destino=%s items=%s delta_total=%s usuario=%s motivo=%r",
        dte.id, sucursal_destino.alias,
        len(items_normalizados), delta_total, usuario, motivo,
    )

    return JsonResponse({
        'success': True,
        'message': (
            f'{len(items_normalizados)} item(s) procesados en '
            f'{sucursal_destino.alias} (delta {delta_total:+d}). '
            f'DTE marcado RECEPCIONADO_COMPLETO.'
        ),
        'dte_id': dte.id,
        'dte_estado': dte.estado_dte,
        'fecha_recepcion': dte.fecha_recepcion.strftime('%Y-%m-%d'),
        'sucursal_destino': {
            'id': sucursal_destino.id,
            'alias': sucursal_destino.alias,
        },
        'creados': creados,
        'actualizados': actualizados,
        'movimientos': movimientos_resumen,
        'stock_delta': stock_delta,
    })


def _parse_dte_producto_descripcion(descripcion):
    """Extrae articulo/talla desde descripciones tipo 'ART-COLOR - Talla 37.0'."""
    texto = (descripcion or '').strip()
    match = re.match(r'^(?P<articulo>.+?)\s+-\s*Talla\s+(?P<talla>.+?)\s*$', texto, re.IGNORECASE)
    if not match:
        return None, None
    return match.group('articulo').strip(), match.group('talla').strip()


def _variantes_talla(talla):
    valores = {(talla or '').strip()}
    if talla:
        texto = str(talla).strip()
        if texto.endswith('.0'):
            valores.add(texto[:-2])
        else:
            valores.add(f'{texto}.0')
    valores.discard('')
    return list(valores)


def _producto_payload(producto):
    if not producto:
        return {}
    return {
        'id': producto.id,
        'articulo': producto.articulo,
        'descripcion': producto.descripcion,
        'sucursal': producto.sucursal.alias if producto.sucursal else None,
    }


def _talla_payload(talla, sucursal_origen_id=None, sucursal_destino_id=None):
    producto = talla.producto if talla else None
    sucursal_id = producto.sucursal_id if producto else None
    roles = []
    if sucursal_origen_id and sucursal_id == sucursal_origen_id:
        roles.append('origen')
    if sucursal_destino_id and sucursal_id == sucursal_destino_id:
        roles.append('destino')
    return {
        'producto_talla_id': talla.id,
        'sku': talla.sku,
        'talla': talla.talla,
        'stock': int(talla.stock or 0),
        'sucursal_id': sucursal_id,
        'sucursal': producto.sucursal.alias if producto and producto.sucursal else None,
        'producto': _producto_payload(producto),
        'roles': roles,
    }


def _clonar_producto_talla_a_sucursal(talla_referencia, sucursal):
    """Crea/reusa Producto y Producto_Talla en una sucursal, con stock inicial 0."""
    producto_ref = talla_referencia.producto
    if producto_ref is None:
        raise ValueError('La talla de referencia no tiene producto asociado.')

    producto_destino = (
        Producto.objects
        .filter(
            articulo=producto_ref.articulo,
            sucursal=sucursal,
            atributo1=producto_ref.atributo1,
            atributo2=producto_ref.atributo2,
            atributo3=producto_ref.atributo3,
            atributo4=producto_ref.atributo4,
        )
        .order_by('id')
        .first()
    )
    if producto_destino is None:
        producto_destino = Producto.objects.create(
            articulo=producto_ref.articulo,
            sucursal=sucursal,
            atributo1=producto_ref.atributo1,
            atributo2=producto_ref.atributo2,
            atributo3=producto_ref.atributo3,
            atributo4=producto_ref.atributo4,
            descripcion=producto_ref.descripcion,
            categoria=producto_ref.categoria,
            costo=producto_ref.costo,
            sobreprecio=producto_ref.sobreprecio,
            precioventa=producto_ref.precioventa,
            precioSugerido=producto_ref.precioSugerido,
            tipo_talla=producto_ref.tipo_talla,
            guia_talla=producto_ref.guia_talla,
        )

    talla_obj = (
        Producto_Talla.objects
        .filter(producto=producto_destino, sku=talla_referencia.sku)
        .order_by('id')
        .first()
    )
    creada = False
    if talla_obj is None:
        talla_obj = Producto_Talla.objects.create(
            producto=producto_destino,
            talla=talla_referencia.talla,
            sku=talla_referencia.sku,
            stock=0,
        )
        creada = True
    return talla_obj, creada


def _diagnostico_reparacion_traspaso(dte, sucursal_destino=None):
    sucursal_destino = sucursal_destino or _sucursal_destino_traspaso(dte)
    hijos = list(
        Dte.objects
        .filter(documento_afectado=dte)
        .exclude(estado_dte__in=['CANCELADO', 'ANULADO'])
        .order_by('-fecha_emision', '-id')
    )

    productos_activos = list(
        dte.dte_productos
        .filter(activo=True)
        .select_related('productoTalla__producto__sucursal')
        .order_by('id')
    )
    recepciones = {
        r.dte_producto_id: r for r in (
            Productos_Recepcionados.objects
            .filter(dte=dte, dte_producto_id__isnull=False)
            .select_related('producto_talla')
        )
    }

    movimientos_salida_total = (
        Movimientos_Producto.objects
        .filter(dte=dte, concepto='TRASPASO_SALIDA')
        .aggregate(total=Sum('cantidad'))['total'] or 0
    )
    movimientos_entrada_total = (
        Movimientos_Producto.objects
        .filter(dte=dte, concepto='TRASPASO_ENTRADA')
        .aggregate(total=Sum('cantidad'))['total'] or 0
    )
    movimientos_entrada_por_sku = {
        row['ProductoTalla__sku']: int(row['total'] or 0)
        for row in (
            Movimientos_Producto.objects
            .filter(dte=dte, concepto='TRASPASO_ENTRADA')
            .exclude(ProductoTalla__isnull=True)
            .values('ProductoTalla__sku')
            .annotate(total=Sum('cantidad'))
        )
    }
    movimientos_salida_por_sku = {
        row['ProductoTalla__sku']: abs(int(row['total'] or 0))
        for row in (
            Movimientos_Producto.objects
            .filter(dte=dte, concepto='TRASPASO_SALIDA')
            .exclude(ProductoTalla__isnull=True)
            .values('ProductoTalla__sku')
            .annotate(total=Sum('cantidad'))
        )
    }

    lineas = []
    lineas_factura = []
    total_documento = 0
    total_recepcionado = 0
    total_lineas_rotas = 0
    total_sin_recepcion = 0
    total_sin_producto_destino = 0
    total_sin_movimiento_entrada = 0

    for dp in productos_activos:
        esperado = int(dp.stock or 0)
        total_documento += esperado
        rec = recepciones.get(dp.id)
        recibido = int(rec.stockArribado or 0) if rec else 0
        total_recepcionado += recibido
        sin_producto_talla = dp.productoTalla_id is None
        sin_recepcion = rec is None
        if sin_producto_talla:
            total_lineas_rotas += 1
        if sin_recepcion:
            total_sin_recepcion += 1

        articulo, talla_desc = _parse_dte_producto_descripcion(dp.descripcion)
        candidatos = []
        if dp.productoTalla:
            candidatos = [
                _talla_payload(dp.productoTalla, dte.sucursal_id, sucursal_destino.id if sucursal_destino else None)
            ]
        elif sin_producto_talla and articulo and talla_desc:
            candidatos_qs = (
                Producto_Talla.objects
                .filter(
                    producto__articulo=articulo,
                    talla__in=_variantes_talla(talla_desc),
                )
                .select_related('producto', 'producto__sucursal')
                .order_by(
                    Case(
                        When(producto__sucursal_id=dte.sucursal_id, then=Value(0)),
                        When(producto__sucursal_id=sucursal_destino.id if sucursal_destino else None, then=Value(1)),
                        default=Value(2),
                        output_field=IntegerField(),
                    ),
                    'producto__sucursal__alias',
                    'id',
                )
            )
            candidatos = [
                _talla_payload(c, dte.sucursal_id, sucursal_destino.id if sucursal_destino else None)
                for c in candidatos_qs[:12]
            ]

        stock_destino = None
        existe_destino = False
        sku = dp.productoTalla.sku if dp.productoTalla else (candidatos[0]['sku'] if candidatos else None)
        if sku and sucursal_destino:
            talla_destino = (
                Producto_Talla.objects
                .filter(sku=sku, producto__sucursal_id=sucursal_destino.id)
                .select_related('producto')
                .first()
            )
            if talla_destino:
                existe_destino = True
                stock_destino = int(talla_destino.stock or 0)

        movimiento_entrada = movimientos_entrada_por_sku.get(sku, 0) if sku else 0
        movimiento_salida = movimientos_salida_por_sku.get(sku, 0) if sku else 0
        if not existe_destino:
            total_sin_producto_destino += 1
        if movimiento_entrada < esperado:
            total_sin_movimiento_entrada += 1

        necesita_reparacion = (
            sin_producto_talla or
            sin_recepcion or
            recibido < esperado or
            not existe_destino or
            movimiento_entrada < esperado
        )
        linea_payload = {
            'dte_producto_id': dp.id,
            'sku_detectado': sku,
            'descripcion': dp.descripcion,
            'articulo_detectado': articulo or (dp.productoTalla.producto.articulo if dp.productoTalla and dp.productoTalla.producto else ''),
            'talla_detectada': talla_desc or (dp.productoTalla.talla if dp.productoTalla else ''),
            'cantidad_documento': esperado,
            'cantidad_recepcionada': recibido,
            'cantidad_sugerida': max(0, esperado - recibido) if rec else esperado,
            'sin_producto_talla': sin_producto_talla,
            'sin_recepcion': sin_recepcion,
            'producto_talla_actual': _talla_payload(dp.productoTalla, dte.sucursal_id, sucursal_destino.id if sucursal_destino else None) if dp.productoTalla else None,
            'candidatos': candidatos,
            'existe_stock_destino': existe_destino,
            'stock_destino_actual': stock_destino,
            'movimiento_entrada': movimiento_entrada,
            'movimiento_salida': movimiento_salida,
            'entrada_completa': movimiento_entrada >= esperado,
            'salida_completa': movimiento_salida >= esperado,
            'necesita_reparacion': necesita_reparacion,
            'puede_reparar': bool(candidatos) if sin_producto_talla else True,
        }
        lineas_factura.append(linea_payload)
        if necesita_reparacion:
            lineas.append(linea_payload)

    advertencias = []
    bloqueos = []
    if hijos:
        advertencias.append({
            'tipo': 'DTE_CON_NC_AJUSTES',
            'mensaje': 'El DTE tiene NC/Ajustes asociados. Revísalos antes de ajustar stock.',
            'cantidad': len(hijos),
            'documentos': [
                {
                    'id': h.id,
                    'tipo_documento': h.tipo_documento,
                    'numero_documento': h.numero_documento,
                    'estado_dte': h.estado_dte,
                    'unidades': h.unidades_productos,
                }
                for h in hijos[:10]
            ],
        })
        for hijo in hijos:
            diag_nc = _diagnostico_nc(hijo)
            if diag_nc and diag_nc.get('total_faltantes', 0) > 0:
                advertencias.append({
                    'tipo': 'NC_STOCK_PENDIENTE',
                    'mensaje': f'El documento hijo #{hijo.numero_documento} tiene stock de NC/Ajuste pendiente de aplicar.',
                    'dte_id': hijo.id,
                    'unidades_pendientes': diag_nc.get('total_faltantes', 0),
                })

    if sucursal_destino is None:
        bloqueos.append({
            'tipo': 'SIN_SUCURSAL_DESTINO',
            'mensaje': 'No se pudo identificar la sucursal destino desde los movimientos del DTE.',
        })

    if total_lineas_rotas or total_sin_recepcion:
        advertencias.append({
            'tipo': 'LINEAS_NO_ACTUALIZADAS',
            'mensaje': (
                f'{total_lineas_rotas} línea(s) perdieron Producto_Talla y '
                f'{total_sin_recepcion} línea(s) no tienen recepción registrada.'
            ),
        })

    return {
        'dte': {
            'id': dte.id,
            'numero_documento': dte.numero_documento,
            'tipo_documento': dte.tipo_documento,
            'estado_dte': dte.estado_dte,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d') if dte.fecha_emision else None,
            'fecha_recepcion': dte.fecha_recepcion.strftime('%Y-%m-%d') if dte.fecha_recepcion else None,
            'sucursal_origen': dte.sucursal.alias if dte.sucursal else None,
            'sucursal_destino': (
                {'id': sucursal_destino.id, 'alias': sucursal_destino.alias}
                if sucursal_destino else None
            ),
        },
        'resumen': {
            'lineas_documento': len(productos_activos),
            'lineas_con_problema': len(lineas),
            'lineas_sin_producto_talla': total_lineas_rotas,
            'lineas_sin_recepcion': total_sin_recepcion,
            'lineas_sin_producto_destino': total_sin_producto_destino,
            'lineas_sin_movimiento_entrada': total_sin_movimiento_entrada,
            'unidades_documento': total_documento,
            'unidades_recepcionadas': total_recepcionado,
            'unidades_sin_recepcion': max(0, total_documento - total_recepcionado),
            'movimientos_salida_unidades': abs(int(movimientos_salida_total or 0)),
            'movimientos_entrada_unidades': int(movimientos_entrada_total or 0),
        },
        'advertencias': advertencias,
        'bloqueos': bloqueos,
        'requiere_confirmar_nc': bool(hijos),
        'lineas': lineas,
        'lineas_factura': lineas_factura,
    }


@login_required
@requiere_permiso('recepcion_dte', 'puede_aprobar')
@require_GET
def api_diagnostico_reparacion_traspaso(request, dte_id):
    try:
        dte = Dte.objects.select_related('sucursal').get(id=dte_id)
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if dte.tipo_transaccion != 'TRASPASO':
        return JsonResponse({'success': False, 'error': 'Sólo aplica a DTE de traspaso.'}, status=400)

    sucursal_actual_id = request.session.get('idSucursalActual')
    if sucursal_actual_id and dte.sucursal_id != int(sucursal_actual_id):
        return JsonResponse({'success': False, 'error': 'Sólo la sucursal emisora puede diagnosticar/reparar este DTE.'}, status=403)

    sucursal_destino = None
    sucursal_destino_id = request.GET.get('sucursal_destino_id')
    if sucursal_destino_id:
        try:
            sucursal_destino = Sucursal.objects.get(id=int(sucursal_destino_id))
        except (Sucursal.DoesNotExist, TypeError, ValueError):
            return JsonResponse({'success': False, 'error': 'Sucursal destino manual inválida.'}, status=400)

    diagnostico = _diagnostico_reparacion_traspaso(dte, sucursal_destino=sucursal_destino)
    return JsonResponse({'success': True, **diagnostico})


@login_required
@requiere_permiso('recepcion_dte', 'puede_aprobar')
@require_POST
def api_reparar_traspaso_manual(request, dte_id):
    try:
        body = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'JSON inválido.'}, status=400)

    items = body.get('items') or []
    motivo = (body.get('motivo') or '').strip()
    confirmar_nc = bool(body.get('confirmar_nc'))
    sucursal_destino_id = body.get('sucursal_destino_id')

    if not isinstance(items, list) or not items:
        return JsonResponse({'success': False, 'error': 'Debe enviar al menos una línea para reparar.'}, status=400)
    if not motivo:
        return JsonResponse({'success': False, 'error': 'El motivo es obligatorio.'}, status=400)

    try:
        with transaction.atomic():
            # Evita que un lock histórico deje el modal girando indefinidamente.
            with connection.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '5s'")
                cur.execute("SET LOCAL statement_timeout = '30s'")

            dte = (
                Dte.objects
                .select_for_update(of=('self',))
                .select_related('sucursal')
                .get(id=dte_id)
            )
            if dte.tipo_transaccion != 'TRASPASO':
                return JsonResponse({'success': False, 'error': 'Sólo aplica a DTE de traspaso.'}, status=400)

            sucursal_actual_id = request.session.get('idSucursalActual')
            if sucursal_actual_id and dte.sucursal_id != int(sucursal_actual_id):
                return JsonResponse({'success': False, 'error': 'Sólo la sucursal emisora puede reparar este DTE.'}, status=403)

            if dte.estado_dte in ('CANCELADO', 'ANULADO'):
                return JsonResponse({'success': False, 'error': f'El DTE está {dte.estado_dte}.'}, status=409)

            hijos_activos = Dte.objects.filter(documento_afectado=dte).exclude(estado_dte__in=['CANCELADO', 'ANULADO'])
            if hijos_activos.exists() and not confirmar_nc:
                return JsonResponse({
                    'success': False,
                    'error': 'Este DTE tiene NC/Ajustes asociados. Confirma explícitamente que los revisaste antes de reparar.',
                    'requiere_confirmar_nc': True,
                }, status=409)

            sucursal_destino = None
            if sucursal_destino_id:
                try:
                    sucursal_destino = Sucursal.objects.get(id=int(sucursal_destino_id))
                except (Sucursal.DoesNotExist, TypeError, ValueError):
                    return JsonResponse({'success': False, 'error': 'Sucursal destino manual inválida.'}, status=400)
            sucursal_destino = sucursal_destino or _sucursal_destino_traspaso(dte)
            if sucursal_destino is None:
                return JsonResponse({
                    'success': False,
                    'error': 'No se pudo identificar la sucursal destino. Selecciónala manualmente en el diagnóstico.',
                    'requiere_sucursal_destino': True,
                }, status=400)

            usuario = request.user.username
            ahora = timezone.now()
            reparados = []
            creados = []
            total_delta_destino = 0

            for raw in items:
                try:
                    dte_producto_id = int(raw.get('dte_producto_id'))
                    candidato_id = int(raw.get('producto_talla_id'))
                    cantidad = int(raw.get('cantidad_recepcionada'))
                except (TypeError, ValueError):
                    transaction.set_rollback(True)
                    return JsonResponse({'success': False, 'error': 'Cada item debe incluir dte_producto_id, producto_talla_id y cantidad_recepcionada.'}, status=400)

                crear_entrada = bool(raw.get('crear_entrada', True))
                actualizar_stock_destino = bool(raw.get('actualizar_stock_destino', crear_entrada))
                crear_movimiento_entrada = bool(raw.get('crear_movimiento_entrada', crear_entrada))
                reconstruir_salida = bool(raw.get('reconstruir_salida', False))

                dp = (
                    Dte_Productos.objects
                    .select_for_update(of=('self',))
                    .select_related('productoTalla')
                    .get(id=dte_producto_id, dte=dte, activo=True)
                )
                if cantidad < 0 or cantidad > int(dp.stock or 0):
                    transaction.set_rollback(True)
                    return JsonResponse({
                        'success': False,
                        'error': f'Cantidad inválida para línea {dp.id}. Debe estar entre 0 y {dp.stock or 0}.',
                    }, status=400)

                candidato = (
                    Producto_Talla.objects
                    .select_related('producto', 'producto__sucursal')
                    .get(id=candidato_id)
                )

                if candidato.producto and candidato.producto.sucursal_id == dte.sucursal_id:
                    talla_origen = candidato
                    origen_creado = False
                else:
                    talla_origen, origen_creado = _clonar_producto_talla_a_sucursal(candidato, dte.sucursal)
                    if origen_creado:
                        creados.append({'tipo': 'origen', 'sku': talla_origen.sku, 'producto_talla_id': talla_origen.id})

                talla_destino, destino_creado = _clonar_producto_talla_a_sucursal(talla_origen, sucursal_destino)
                if destino_creado:
                    creados.append({'tipo': 'destino', 'sku': talla_destino.sku, 'producto_talla_id': talla_destino.id})

                if dp.productoTalla_id != talla_origen.id:
                    dp.productoTalla = talla_origen
                    dp.save(update_fields=['productoTalla'])

                recepcion, rec_creada = Productos_Recepcionados.objects.get_or_create(
                    dte=dte,
                    dte_producto=dp,
                    defaults={
                        'producto_talla': talla_origen,
                        'stockArribado': cantidad,
                        'cantidad_esperada': int(dp.stock or 0),
                        'cantidad_danada': 0,
                        'cantidad_faltante': max(0, int(dp.stock or 0) - cantidad),
                        'cantidad_sobrante': 0,
                        'estado': 'RECEPCIONADO_OK' if cantidad >= int(dp.stock or 0) else 'RECEPCIONADO_PARCIAL',
                        'observaciones': f'Reparación manual trazabilidad DTE: {motivo}',
                        'fecha_recepcion': ahora,
                        'recepcionado_por': usuario,
                    }
                )
                if not rec_creada:
                    delta_rec = cantidad - int(recepcion.stockArribado or 0)
                    if delta_rec < 0:
                        transaction.set_rollback(True)
                        return JsonResponse({
                            'success': False,
                            'error': f'La línea {dp.id} ya tiene más unidades recepcionadas que la cantidad indicada.',
                        }, status=400)
                    recepcion.producto_talla = talla_origen
                    recepcion.stockArribado = cantidad
                    recepcion.cantidad_esperada = int(dp.stock or 0)
                    recepcion.cantidad_faltante = max(0, int(dp.stock or 0) - cantidad)
                    recepcion.estado = 'RECEPCIONADO_OK' if cantidad >= int(dp.stock or 0) else 'RECEPCIONADO_PARCIAL'
                    recepcion.observaciones = f"{recepcion.observaciones or ''}\nReparación manual trazabilidad DTE: {motivo}".strip()
                    recepcion.fecha_recepcion = recepcion.fecha_recepcion or ahora
                    recepcion.recepcionado_por = recepcion.recepcionado_por or usuario
                    recepcion.save(update_fields=[
                        'producto_talla', 'stockArribado', 'cantidad_esperada',
                        'cantidad_faltante', 'estado', 'observaciones',
                        'fecha_recepcion', 'recepcionado_por',
                    ])
                    cantidad_para_stock = delta_rec
                else:
                    cantidad_para_stock = cantidad

                if actualizar_stock_destino and cantidad_para_stock > 0:
                    Producto_Talla.objects.filter(id=talla_destino.id).update(stock=F('stock') + cantidad_para_stock)

                if crear_movimiento_entrada and cantidad_para_stock > 0:
                    Movimientos_Producto.objects.create(
                        dte=dte,
                        ProductoTalla=talla_destino,
                        sucursal_origen=dte.sucursal,
                        sucursal_destino=sucursal_destino,
                        cantidad=cantidad_para_stock,
                        costo=dp.costo,
                        sobreprecio=dp.sobreprecio,
                        precio=dp.precio,
                        concepto='TRASPASO_ENTRADA',
                        tipo_movimiento='INGRESO',
                        estado='COMPLETADO',
                        responsable=usuario,
                        fecha=timezone.localdate(),
                        hora=timezone.localtime().time(),
                        observaciones=f'Reparación manual DTE #{dte.numero_documento} línea {dp.id}. Motivo: {motivo}'[:500],
                    )

                if (actualizar_stock_destino or crear_movimiento_entrada) and cantidad_para_stock > 0:
                    total_delta_destino += cantidad_para_stock

                if reconstruir_salida and cantidad > 0:
                    Movimientos_Producto.objects.create(
                        dte=dte,
                        ProductoTalla=talla_origen,
                        sucursal_origen=dte.sucursal,
                        sucursal_destino=sucursal_destino,
                        cantidad=-cantidad,
                        costo=dp.costo,
                        sobreprecio=dp.sobreprecio,
                        precio=dp.precio,
                        concepto='TRASPASO_SALIDA',
                        tipo_movimiento='EGRESO',
                        estado='COMPLETADO',
                        responsable=usuario,
                        fecha=timezone.localdate(),
                        hora=timezone.localtime().time(),
                        observaciones=(
                            f'Reconstrucción manual de trazabilidad DTE #{dte.numero_documento} '
                            f'línea {dp.id}; no descuenta stock origen. Motivo: {motivo}'
                        )[:500],
                    )

                reparados.append({
                    'dte_producto_id': dp.id,
                    'sku': talla_origen.sku,
                    'cantidad': cantidad,
                    'entrada_stock': cantidad_para_stock if actualizar_stock_destino else 0,
                    'movimiento_entrada': cantidad_para_stock if crear_movimiento_entrada else 0,
                    'reconstruyo_salida': reconstruir_salida,
                })

            recepciones_invalidas = Productos_Recepcionados.objects.filter(dte=dte).exclude(estado='RECEPCIONADO_OK').exists()
            lineas_activas = set(dte.dte_productos.filter(activo=True).values_list('id', flat=True))
            lineas_rec = set(Productos_Recepcionados.objects.filter(dte=dte, dte_producto_id__in=lineas_activas).values_list('dte_producto_id', flat=True))
            dte.estado_dte = 'RECEPCIONADO_COMPLETO' if lineas_activas and lineas_activas.issubset(lineas_rec) and not recepciones_invalidas else 'RECEPCIONADO_PARCIAL'
            if dte.fecha_recepcion is None:
                dte.fecha_recepcion = timezone.localdate()
            registro = (
                f"\n[REPARACION TRAZABILIDAD TRASPASO] {ahora.strftime('%Y-%m-%d %H:%M')} "
                f"{usuario}: {len(reparados)} línea(s), stock destino {total_delta_destino:+d}. "
                f"Motivo: {motivo}"
            )
            dte.referencias = ((dte.referencias or '') + registro).strip()
            dte.save(update_fields=['estado_dte', 'fecha_recepcion', 'referencias'])

    except Dte_Productos.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Alguna línea no pertenece al DTE o está inactiva.'}, status=404)
    except Producto_Talla.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Producto_Talla candidato no encontrado.'}, status=404)
    except Exception as e:
        logger.exception("Error al reparar trazabilidad de DTE")
        return JsonResponse({'success': False, 'error': f'Error al reparar DTE: {e}'}, status=500)

    return JsonResponse({
        'success': True,
        'message': f'Reparación aplicada: {len(reparados)} línea(s), stock destino {total_delta_destino:+d}.',
        'dte_estado': dte.estado_dte,
        'reparados': reparados,
        'creados': creados,
    })


@login_required
@require_GET
def api_stock_productos(request):
    """
    Devuelve el stock actual de Producto_Talla para una lista de SKUs,
    opcionalmente filtrados por sucursal. Usado por el frontend para
    refrescar UI después de operaciones que mueven stock (NC, ajustes).

    Query params:
        skus: lista de SKU separados por coma (requerido)
        sucursales: lista de ids de Sucursal separados por coma (opcional;
            si se omite, retorna stock por cada sucursal donde exista el SKU).

    Respuesta:
        {
            "success": true,
            "items": [
                {"sku": 123, "talla": "M",
                 "sucursal_id": 1, "sucursal_alias": "Casa Matriz",
                 "stock": 42},
                ...
            ]
        }
    """
    skus_raw = (request.GET.get('skus') or '').strip()
    if not skus_raw:
        return JsonResponse({'success': False, 'error': 'Parámetro skus requerido.'}, status=400)

    skus = []
    for s in skus_raw.split(','):
        s = s.strip()
        if not s:
            continue
        try:
            skus.append(int(s))
        except ValueError:
            return JsonResponse({'success': False, 'error': f'SKU inválido: {s}'}, status=400)

    qs = Producto_Talla.objects.filter(sku__in=skus).select_related('producto', 'producto__sucursal')

    sucursales_raw = (request.GET.get('sucursales') or '').strip()
    if sucursales_raw:
        try:
            sucursales_ids = [int(x) for x in sucursales_raw.split(',') if x.strip()]
        except ValueError:
            return JsonResponse({'success': False, 'error': 'Parámetro sucursales inválido.'}, status=400)
        if sucursales_ids:
            qs = qs.filter(producto__sucursal_id__in=sucursales_ids)

    items = []
    for t in qs:
        sucursal = t.producto.sucursal if t.producto else None
        items.append({
            'sku': t.sku,
            'talla': t.talla,
            'producto_talla_id': t.id,
            'sucursal_id': sucursal.id if sucursal else None,
            'sucursal_alias': sucursal.alias if sucursal else None,
            'stock': int(t.stock or 0),
        })

    return JsonResponse({'success': True, 'items': items})


@require_GET
def obtener_recepciones_compra(request, compra_id):
    """
    Obtiene las recepciones detalladas de una compra completa,
    agrupadas por producto y talla para permitir su edición.
    """
    try:
        compra = get_object_or_404(Compras, id=compra_id)
        
        # Obtener todas las recepciones de esta compra
        recepciones = Productos_Recepcionados.objects.filter(
            compra_producto_talla__compra_producto__compras=compra
        ).select_related(
            'compra_producto_talla__compra_producto',
            'dte'
        ).order_by(
            'compra_producto_talla__compra_producto__nombre',
            'compra_producto_talla__talla'
        )
        
        resultado = []
        for rec in recepciones:
            cp = rec.compra_producto_talla.compra_producto
            resultado.append({
                'id': rec.id,
                'dte_id': rec.dte_id,
                'dte_numero': str(rec.dte.numero_documento) if rec.dte else None,
                'producto_id': cp.id,
                'producto_nombre': cp.nombre,
                'producto_marca': cp.atributo1,
                'producto_color': cp.atributo2,
                'talla': rec.compra_producto_talla.talla,
                'cantidad': rec.stockArribado,
                'costo': float(cp.costo) if cp.costo else 0,
                'producto_talla_id': rec.producto_talla_id,
                'creado': rec.producto_talla_id is not None,
            })
        
        return JsonResponse({
            'success': True,
            'recepciones': resultado,
            'compra_nombre': compra.nombre if hasattr(compra, 'nombre') else f'Compra #{compra.id}'
        })
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': str(e)
        }, status=500)


@login_required
def obtener_pendientes_compra(request, compra_id):
    """
    Returns Compras_Producto_Talla items that still have units pending to be received
    (stock > unidades_recibidas), excluding the synthetic __TOTAL__ row.
    """
    try:
        compra = get_object_or_404(Compras, id=compra_id)

        qs = Compras_Producto_Talla.objects.filter(
            compra_producto__compras=compra
        ).exclude(
            talla=Compras_Producto_Talla.TALLA_SIN_DESGLOSAR
        ).select_related('compra_producto').order_by(
            'compra_producto__nombre', 'talla'
        )

        resultado = []
        for pt in qs:
            pendiente_qty = max(0, pt.stock - pt.unidades_recibidas)
            if pendiente_qty <= 0:
                continue
            cp = pt.compra_producto
            tiene_recepcion = Productos_Recepcionados.objects.filter(
                compra_producto_talla=pt
            ).exists()
            resultado.append({
                'id': pt.id,
                'compra_producto_id': cp.id,
                'producto_nombre': cp.nombre,
                'producto_marca': cp.atributo1 or '',
                'producto_color': cp.atributo2 or '',
                'talla': pt.talla,
                'stock_pedido': pt.stock,
                'unidades_recibidas': pt.unidades_recibidas,
                'pendiente': pendiente_qty,
                'estado_item': pt.estado_item,
                'costo': float(cp.costo) if cp.costo else 0,
                'puede_eliminar': not tiene_recepcion and pt.unidades_recibidas == 0,
            })

        return JsonResponse({
            'success': True,
            'pendientes': resultado,
            'total_pedido': sum(p['stock_pedido'] for p in resultado),
            'total_pendiente': sum(p['pendiente'] for p in resultado),
        })

    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@login_required
@require_POST
@transaction.atomic
def eliminar_pendientes_compra_masivo(request):
    """
    Bulk-deletes Compras_Producto_Talla items that have never been received
    (unidades_recibidas == 0 and no linked Productos_Recepcionados).
    """
    try:
        data = json.loads(request.body)
        ids = data.get('ids', [])
        if not ids:
            return JsonResponse({'success': False, 'error': 'No se proporcionaron IDs'}, status=400)

        eliminados = 0
        errores = []

        for pt_id in ids:
            try:
                pt = Compras_Producto_Talla.objects.get(id=pt_id)
                if pt.unidades_recibidas > 0:
                    errores.append(
                        f'Talla {pt.talla} de "{pt.compra_producto.nombre}" tiene recepciones parciales.'
                    )
                    continue
                if Productos_Recepcionados.objects.filter(compra_producto_talla=pt).exists():
                    errores.append(
                        f'Talla {pt.talla} de "{pt.compra_producto.nombre}" ya tiene recepciones registradas.'
                    )
                    continue
                pt.delete()
                eliminados += 1
            except Compras_Producto_Talla.DoesNotExist:
                errores.append(f'Item ID {pt_id} no encontrado.')

        mensaje = f'{eliminados} item(s) eliminado(s) correctamente.'
        if errores:
            mensaje += ' Omitidos: ' + '; '.join(errores[:5])

        return JsonResponse({
            'success': True,
            'eliminados': eliminados,
            'errores': errores,
            'message': mensaje,
        })

    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@require_POST
@transaction.atomic
def actualizar_recepciones_compra(request):
    """
    Actualiza las cantidades de recepciones de una compra.
    Permite modificar cantidades o eliminar recepciones.
    También ajusta el inventario y registra movimientos si el producto ya existe.
    """
    try:
        data = json.loads(request.body)
        compra_id = data.get('compra_id')
        cambios = data.get('cambios', [])
        
        if not compra_id or not cambios:
            return JsonResponse({
                'success': False,
                'error': 'Datos incompletos'
            }, status=400)
        
        compra = get_object_or_404(Compras, id=compra_id)
        usuario = request.user.username if request.user.is_authenticated else 'Sistema'
        
        actualizados = 0
        eliminados = 0
        movimientos_creados = 0
        
        for cambio in cambios:
            recepcion_id = cambio.get('recepcion_id')
            cantidad_nueva = cambio.get('cantidad', 0)
            eliminar = cambio.get('eliminar', False)
            
            try:
                recepcion = Productos_Recepcionados.objects.get(
                    id=recepcion_id,
                    compra_producto_talla__compra_producto__compras=compra
                )
                
                cantidad_anterior = recepcion.stockArribado
                diferencia = cantidad_nueva - cantidad_anterior
                
                # Verificar si el producto ya fue creado en inventario
                producto_talla = recepcion.producto_talla
                
                if eliminar or cantidad_nueva == 0:
                    # Si hay producto en inventario, crear movimiento de ajuste negativo
                    if producto_talla:
                        # Registrar movimiento de egreso por eliminación
                        Movimientos_Producto.objects.create(
                            ProductoTalla=producto_talla,
                            dte=recepcion.dte,
                            cantidad=-cantidad_anterior,  # Negativo porque es egreso
                            costo=producto_talla.producto.costo or 0,
                            precio=producto_talla.producto.precio or 0,
                            concepto='AJUSTE_NEGATIVO',
                            tipo_movimiento='AJUSTE',
                            estado='COMPLETADO',
                            responsable=usuario,
                            observaciones=f'Eliminación de recepción desde Gestión de Compras. Compra #{compra_id}'
                        )
                        movimientos_creados += 1
                    
                    # Eliminar la recepción
                    recepcion.delete()
                    eliminados += 1
                    
                elif diferencia != 0:
                    # Si cambió la cantidad y hay producto en inventario
                    if producto_talla:
                        # Crear movimiento de ajuste
                        if diferencia > 0:
                            concepto = 'AJUSTE_POSITIVO'
                            tipo = 'AJUSTE'
                        else:
                            concepto = 'AJUSTE_NEGATIVO'
                            tipo = 'AJUSTE'
                        
                        Movimientos_Producto.objects.create(
                            ProductoTalla=producto_talla,
                            dte=recepcion.dte,
                            cantidad=diferencia,  # Positivo o negativo según el ajuste
                            costo=producto_talla.producto.costo or 0,
                            precio=producto_talla.producto.precio or 0,
                            concepto=concepto,
                            tipo_movimiento=tipo,
                            estado='COMPLETADO',
                            responsable=usuario,
                            observaciones=f'Ajuste de recepción: {cantidad_anterior} → {cantidad_nueva}. Compra #{compra_id}'
                        )
                        movimientos_creados += 1
                    
                    # Actualizar cantidad en la recepción
                    recepcion.stockArribado = cantidad_nueva
                    recepcion.save()
                    actualizados += 1
                    
            except Productos_Recepcionados.DoesNotExist:
                continue
        
        mensaje = f'Se actualizaron {actualizados} recepciones y se eliminaron {eliminados}'
        if movimientos_creados > 0:
            mensaje += f'. Se registraron {movimientos_creados} movimientos de inventario.'
        
        return JsonResponse({
            'success': True,
            'message': mensaje,
            'actualizados': actualizados,
            'eliminados': eliminados,
            'movimientos_creados': movimientos_creados
        })
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': str(e)
        }, status=500)

 
@require_GET
@login_required
def margenes_usuario(request):
    """Obtiene los márgenes del usuario para la sucursal actual"""
    user = request.user
    empresa_id = request.session.get('idEmpresaActual')
    sucursal_id = request.session.get('idSucursalActual')

    try:
        # Primero intentar obtener márgenes específicos de la sucursal
        eu = EmpresaUser.objects.filter(
            user=user, 
            empresa_id=empresa_id, 
            sucursal_id=sucursal_id, 
            status=True
        ).first()
        
        if eu:
            sucursal_nombre = eu.sucursal.alias if eu.sucursal else 'Sin sucursal'
            return JsonResponse({
                'success': True,
                'margenSobreprecio': eu.margenSobreprecio or 0,
                'margenPrecioVenta': eu.margenPrecioVenta or 0,
                'sucursal_id': sucursal_id,
                'sucursal_nombre': sucursal_nombre
            })
        
        # Si no existe para esta sucursal, buscar el activo del usuario
        eu_activo = EmpresaUser.objects.filter(
            user=user, 
            empresa_id=empresa_id,
            active=True
        ).first()
        
        if eu_activo:
            return JsonResponse({
                'success': True,
                'margenSobreprecio': eu_activo.margenSobreprecio or 0,
                'margenPrecioVenta': eu_activo.margenPrecioVenta or 0,
                'sucursal_id': sucursal_id,
                'sucursal_nombre': eu_activo.sucursal.alias if eu_activo.sucursal else 'Sin sucursal',
                'nota': 'Usando márgenes del perfil activo'
            })
        
        # Si no hay ninguno, devolver valores por defecto
        return JsonResponse({
            'success': True,
            'margenSobreprecio': 0,
            'margenPrecioVenta': 0,
            'sucursal_id': sucursal_id,
            'nota': 'Sin configuración previa'
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})


@require_POST
@login_required
def guardar_margenes_usuario(request):
    """Guarda los márgenes del usuario para la sucursal actual"""
    empresa_id = request.session.get('idEmpresaActual')
    sucursal_id = request.session.get('idSucursalActual')
    
    try:
        margenSobreprecio = int(request.POST.get('margenSobreprecio', 0))
        margenPrecioVenta = int(request.POST.get('margenPrecioVenta', 0))
        
        # Buscar o crear registro para esta sucursal específica
        eu, created = EmpresaUser.objects.get_or_create(
            user=request.user,
            empresa_id=empresa_id,
            sucursal_id=sucursal_id,
            defaults={
                'status': True,
                'active': False,
                'margenSobreprecio': margenSobreprecio,
                'margenPrecioVenta': margenPrecioVenta
            }
        )
        
        if not created:
            # Si ya existía, actualizar los márgenes
            eu.margenSobreprecio = margenSobreprecio
            eu.margenPrecioVenta = margenPrecioVenta
            eu.save()
        
        sucursal_nombre = eu.sucursal.alias if eu.sucursal else 'Sin sucursal'
        
        return JsonResponse({
            'success': True,
            'message': f'Márgenes guardados para {sucursal_nombre}',
            'sucursal_id': sucursal_id,
            'sucursal_nombre': sucursal_nombre,
            'created': created
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})

  
def ajustar_margenes(request):
    if request.method == 'POST':
        user = request.user
        margen_sobreprecio = request.POST.get('margenSobreprecio')
        margen_precio_venta = request.POST.get('margenPrecioVenta')

        empresa_user = EmpresaUser.objects.get(user=user)
        empresa_user.margenSobreprecio = margen_sobreprecio
        empresa_user.margenPrecioVenta = margen_precio_venta
        empresa_user.save()

        return JsonResponse({'success': True})
    return JsonResponse({'success': False}, status=400)
 
@require_GET
def categorias_existentes(request):
    tree_mode = request.GET.get('tree', '0') == '1'

    # Antes: N+1 grave — 1 subquery + 2 COUNT por categoría (≈336 queries / 63s
    # contra la BD remota, con 112 categorías). Ahora: 2 queries totales
    # (todas las categorías + un agregado de productos por categoría) y el árbol
    # se arma en memoria. Beneficia a los ~15 llamadores del endpoint.
    # Excluir las categorías deprecadas (_ZZ_ = viejas vacías ya limpiadas).
    todas = list(Categoria.objects.exclude(nombre__startswith='_ZZ_')
                 .order_by('nombre').values('id', 'nombre', 'padre_id'))
    hijos_por_padre = {}
    for c in todas:
        hijos_por_padre.setdefault(c['padre_id'], []).append(c)

    prod_count = {}
    if tree_mode:
        prod_count = dict(
            Producto.objects.values_list('categoria_id').annotate(n=Count('id'))
        )

    def recorrer(padre_id, prefijo='', nivel=0):
        resultado = []
        for c in hijos_por_padre.get(padre_id, []):
            hijos = hijos_por_padre.get(c['id'], [])
            resultado.append({
                'id': c['id'],
                'nombre': f"{prefijo}{c['nombre']}" if not tree_mode else c['nombre'],
                'padre_id': c['padre_id'],
                'nivel': nivel,
                'hijos_count': len(hijos),
                'productos_count': prod_count.get(c['id'], 0),
            })
            resultado += recorrer(c['id'], prefijo + '› ', nivel + 1)
        return resultado

    data = recorrer(None)
    return JsonResponse(data, safe=False)


@require_POST
def categoria_guardar(request):
    from django.shortcuts import get_object_or_404
    id = request.POST.get('id')
    eliminar = request.POST.get('eliminar')

    if eliminar == '1' and id:
        try:
            categoria = get_object_or_404(Categoria, pk=id)
            if categoria.categoria_productos.exists():
                return JsonResponse({'success': False, 'error': 'No se puede eliminar: tiene productos asociados'})
            categoria.delete()
            return JsonResponse({'success': True})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})

    nombre = request.POST.get('nombre')
    padre_id = request.POST.get('padre')

    if not nombre:
        return JsonResponse({'success': False, 'error': 'Nombre obligatorio'})

    padre = Categoria.objects.filter(id=padre_id).first() if padre_id else None

    if id:
        categoria = get_object_or_404(Categoria, pk=id)
        categoria.nombre = nombre
        categoria.padre = padre
        categoria.save()
    else:
        Categoria.objects.create(nombre=nombre, padre=padre)

    return JsonResponse({'success': True})
 
# Las vistas de Guías de Talla no tenían ningún decorador: respondían 200 a un
# anónimo (verificado). Se usa @login_required a secas y NO un permiso granular
# porque estos endpoints los consumen también los modales de guía dentro de
# verGestionProductos.html y modulo_compras/gestionCompras.html; atarlos a
