@login_required
def eliminar_guia_talla(request):
    if request.method == 'POST':
        try:
            id = request.POST.get('id')
            if not id:
                return JsonResponse({'success': False, 'error': 'ID no proporcionado'})

            guia = GuiaTalla.objects.get(pk=id)

            # Borrar la guía no es inocuo: el CASCADE se lleva sus GuiaTallaItem
            # y el SET_NULL deja en NULL el `guia_talla` de todos los productos
            # que la usaban (683 productos vinculados en el sistema; la guía #33
            # sola tiene 63). Antes se borraba a ciegas y sin dejar rastro.
            #
            # NO se bloquea con un 409 pidiendo `confirmar`: ninguno de los tres
            # llamadores (gestion_guias_talla.html y dos puntos de
            # verGestionProductos.html) envía hoy esa bandera, así que exigirla
            # dejaría la eliminación imposible desde toda la UI. El aviso previo
            # ya existe en el front (gestion_guias_talla.html muestra el conteo
            # de productos antes de confirmar). Aquí se registra el impacto y se
            # devuelve al cliente para que pueda mostrarlo.
            productos_afectados = guia.productos_principales.count()
            items_afectados = guia.items.count()

            nombre_guia = guia.nombre
            guia.delete()
            logger.info(
                '[GUIA-TALLA] Usuario %s eliminó la guía #%s (%s): %s producto(s) '
                'quedaron sin guía, %s items borrados.',
                request.user.username, id, nombre_guia,
                productos_afectados, items_afectados,
            )
            return JsonResponse({
                'success': True,
                'productos_afectados': productos_afectados,
                'items_afectados': items_afectados,
            })
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
 
 
@transaction.atomic
def crear_producto(data, responsable, fecha_creacion=None):
    """
    Crea un producto nuevo o reutiliza el existente (mismo articulo + sucursal).

    - Si el producto YA existe → mantiene su fecha_creacion original, solo
      agrega/suma tallas y registra el movimiento de ingreso.
    - Si es nuevo → fecha_creacion = parámetro o now() como fallback.
    - El movimiento de ingreso se crea SIEMPRE con fecha_creacion (no today())
      para que recepciones históricas queden con su fecha real.

    Args:
        data: dict con datos del producto.
        responsable: usuario responsable.
        fecha_creacion: datetime/date histórico (ej. fecha del DTE/recepción).
                        Si None, usa timezone.now().
    """
    from datetime import datetime, time

    # Normalizar fecha_creacion a datetime aware
    if fecha_creacion is None:
        fecha_creacion = timezone.now()
    elif not isinstance(fecha_creacion, datetime):
        fecha_creacion = timezone.make_aware(datetime.combine(fecha_creacion, time.min))
    elif timezone.is_naive(fecha_creacion):
        fecha_creacion = timezone.make_aware(fecha_creacion)

    # get_or_create por (articulo, sucursal): evita crear duplicados si ya existe
    producto, created = Producto.objects.get_or_create(
        articulo=data['articulo'],
        sucursal=data['sucursal'],
        defaults={
            'descripcion': data['descripcion'],
            'atributo1': data['atributo1'],
            'atributo2': data['atributo2'],
            'atributo3': data['atributo3'],
            'atributo4': data['atributo4'],
            'categoria': data.get('categoria'),
            'costo': data['costo'],
            'sobreprecio': data['sobreprecio'],
            'precioventa': data['precioventa'],
            'precioSugerido': data.get('precioSugerido'),
        }
    )

    # Solo si es NUEVO: forzar fecha_creacion (auto_now_add ignora valores en .create)
    if created:
        Producto.objects.filter(pk=producto.pk).update(fecha_creacion=fecha_creacion)

    # Crear / actualizar tallas y registrar movimiento por cada una
    for talla_data in data['tallas']:
        producto_talla, talla_created = Producto_Talla.objects.get_or_create(
            producto=producto,
            talla=talla_data['talla'],
            defaults={
                'sku': obtener_siguiente_sku(),
                'stock': talla_data['stock'],
            }
        )
        # Si la talla ya existía → sumar el nuevo stock al existente
        if not talla_created and talla_data.get('stock'):
            producto_talla.stock = (producto_talla.stock or 0) + int(talla_data['stock'])
            producto_talla.save(update_fields=['stock'])

        # Movimiento de ingreso con la fecha correcta (DTE/recepción)
        Movimientos_Producto.objects.create(
            ProductoTalla=producto_talla,
            costo=producto.costo,
            sobreprecio=producto.sobreprecio,
            precio=producto.precioventa,
            fecha=fecha_creacion.date(),
            hora=fecha_creacion.time(),
            concepto='INGRESO_INICIAL' if (created and talla_created) else 'RECEPCION_COMPRA',
            tipo_movimiento='INGRESO',
            responsable=responsable,
            sucursal_origen=data['sucursal'],
        )

    return producto
 
@login_required
def guias_talla_por_marca(request):
    marca_id = request.GET.get('marca')
    if not marca_id:
        return JsonResponse([], safe=False)
    
    guias = GuiaTalla.objects.filter(marca_id=marca_id).order_by('nombre')
    data = [{'id': g.id, 'nombre': g.nombre} for g in guias]
    return JsonResponse(data, safe=False)
 
def verificar_existencia_producto(request):
    articulo = request.GET.get('articulo')
    if not articulo:
        return JsonResponse({'existe': False})

    # iexact: los códigos históricos quedaron con mayúsculas/minúsculas mezcladas
    existe = Producto.objects.filter(articulo__iexact=articulo.strip()).exists()
    return JsonResponse({'existe': existe})
 
@transaction.atomic
def obtener_siguiente_sku():
    """
    Obtiene el siguiente SKU disponible verificando que no exista en la BD.
    Usa select_for_update para evitar condiciones de carrera.
    """
    parametro, creado = ParametroGlobal.objects.select_for_update().get_or_create(
        nombre='sku',
        defaults={'valor_entero': 100000}
    )

    siguiente = parametro.valor_entero + 1
    
    # Verificar que el SKU no exista ya en la base de datos
    while Producto_Talla.objects.filter(sku=siguiente).exists():
        siguiente += 1
    
    parametro.valor_entero = siguiente
    parametro.save()

    return siguiente
@require_GET
def obtener_siguiente_sku_view(request):
    try:
        sku = obtener_siguiente_sku()
        return JsonResponse({'success': True, 'sku': sku})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


@require_GET
@transaction.atomic
def obtener_multiples_skus_view(request):
    """
    Genera múltiples SKUs verificados de una vez.
    Uso: /app/obtener_multiples_skus/?cantidad=5
    """
    try:
        cantidad = int(request.GET.get('cantidad', 1))
        if cantidad < 1 or cantidad > 100:
            return JsonResponse({'success': False, 'error': 'Cantidad debe ser entre 1 y 100'}, status=400)
        
        skus = []
        for _ in range(cantidad):
            sku = obtener_siguiente_sku()
            skus.append(sku)
        
        return JsonResponse({'success': True, 'skus': skus})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


# ========== CONFIGURACIÓN DE SKU ==========

@login_required
@require_GET
def obtener_configuracion_sku(request):
    """
    Obtiene la configuración actual del SKU secuencial
    NOTA: Solo considera SKUs secuenciales (< 10 millones)
          Los SKUs mayores son códigos de barras/EAN y no se cuentan
    """
    try:
        # Umbral para diferenciar SKUs secuenciales de códigos de barras
        UMBRAL_SKU_SECUENCIAL = 10000000  # 10 millones
        
        parametro, created = ParametroGlobal.objects.get_or_create(
            nombre='sku',
            defaults={'valor_entero': 100000}
        )
        
        # Obtener el SKU máximo SECUENCIAL (ignorar códigos de barras)
        max_sku_db = Producto_Talla.objects.filter(
            sku__lt=UMBRAL_SKU_SECUENCIAL
        ).aggregate(m=Max('sku'))['m'] or 0
        
        return JsonResponse({
            'success': True,
            'configuracion': {
                'valor_actual': parametro.valor_entero,
                'max_sku_en_db': max_sku_db,
                'siguiente_sku': max(parametro.valor_entero, max_sku_db) + 1,
                'fecha_actualizacion': parametro.fecha_actualizacion.strftime('%d/%m/%Y %H:%M') if parametro.fecha_actualizacion else None
            }
        })
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': str(e)
        }, status=500)


@login_required
@require_http_methods(["POST"])
def actualizar_configuracion_sku(request):
    """
    Actualiza el valor inicial del SKU secuencial
    Permite valores menores al máximo si hay al menos 4 millones de espacio
    """
    try:
        # Umbral para diferenciar SKUs secuenciales de códigos de barras
        UMBRAL_SKU_SECUENCIAL = 10000000  # 10 millones
        MARGEN_SEGURIDAD = 4000000  # 4 millones de SKUs de margen
        
        data = json.loads(request.body)
        nuevo_valor = int(data.get('valor', 0))
        
        if nuevo_valor <= 0:
            return JsonResponse({
                'success': False,
                'error': 'El valor debe ser mayor a 0'
            }, status=400)
        
        # Obtener el SKU máximo SECUENCIAL (ignorar códigos de barras)
        max_sku_db = Producto_Talla.objects.filter(
            sku__lt=UMBRAL_SKU_SECUENCIAL
        ).aggregate(m=Max('sku'))['m'] or 0
        
        # Validación: Si el nuevo valor es menor al máximo, debe haber 4M de margen
        if nuevo_valor < max_sku_db:
            espacio_disponible = max_sku_db - nuevo_valor
            if espacio_disponible < MARGEN_SEGURIDAD:
                return JsonResponse({
                    'success': False,
                    'error': f'Valor muy cercano al máximo existente ({max_sku_db}). Necesita al menos {MARGEN_SEGURIDAD:,} de margen. Disponible: {espacio_disponible:,}'
                }, status=400)
        
        # Actualizar parámetro
        parametro, created = ParametroGlobal.objects.get_or_create(
            nombre='sku',
            defaults={'valor_entero': nuevo_valor}
        )
        
        valor_anterior = parametro.valor_entero
        parametro.valor_entero = nuevo_valor
        parametro.save()
        
        return JsonResponse({
            'success': True,
            'mensaje': f'SKU actualizado de {valor_anterior} a {nuevo_valor}',
            'configuracion': {
                'valor_anterior': valor_anterior,
                'valor_nuevo': nuevo_valor,
                'siguiente_sku': nuevo_valor + 1
            }
        })
        
    except json.JSONDecodeError:
        return JsonResponse({
            'success': False,
            'error': 'Datos JSON inválidos'
        }, status=400)
    except ValueError:
        return JsonResponse({
            'success': False,
            'error': 'El valor debe ser un número entero válido'
        }, status=400)
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': str(e)
        }, status=500)

@login_required
@require_GET
def buscar_articulo_autocomplete(request):
    """
    Búsqueda parcial rápida de productos por artículo (para autocomplete).
    Busca por coincidencia parcial (icontains) y devuelve info compacta.
    """
    q = request.GET.get('q', '').strip()
    # Mismo fallback dual que el resto de las vistas: leyendo SOLO
    # 'idSucursalActual', una sesión que traía 'sucursalActual' buscaba en
    # TODAS las bodegas y el dropdown repetía cada código una vez por bodega.
    sucursal_id = request.session.get('idSucursalActual') or request.session.get('sucursalActual')

    if len(q) < 2:
        return JsonResponse({'resultados': []})

    filtros = Q(articulo__icontains=q)
    if sucursal_id:
        filtros &= Q(sucursal_id=sucursal_id)

    # Más recientes primero (id como proxy de recencia: fecha_creacion legacy
    # tiene nulls). Margen de 40 para que el dedupe por identidad no deje el
    # dropdown corto.
    productos = (
        Producto.objects
        .filter(filtros)
        .select_related('atributo1', 'atributo2', 'atributo3', 'categoria', 'guia_talla')
        .prefetch_related('producto_talla')
        .order_by('-id')[:40]
    )

    # Agrupar por IDENTIDAD (articulo normalizado + marca + color + género +
    # categoría + bodega): las fichas duplicadas exactas se muestran UNA vez.
    # Variantes reales (otro color) siguen siendo filas separadas — el caso
    # típico de error es el mismo código creado 2 veces con otro color y años
    # de diferencia; por eso cada fila lleva su fecha de creación.
    from .utils_producto_match import normalizar_articulo as _normart
    grupos = {}
    orden_grupos = []
    for p in productos:
        key = (_normart(p.articulo), p.atributo1_id, p.atributo2_id,
               p.atributo3_id, p.categoria_id, p.sucursal_id)
        if key not in grupos:
            grupos[key] = []
            orden_grupos.append(key)
        grupos[key].append(p)

    # Variantes por código (grupos distintos que comparten articulo)
    variantes_por_articulo = {}
    for key in orden_grupos:
        variantes_por_articulo[key[0]] = variantes_por_articulo.get(key[0], 0) + 1

    resultados = []
    for key in orden_grupos[:15]:
        fichas = grupos[key]
        # La ficha de MENOR id es la que el matching de identidad usa para
        # sumar stock: esa es la que debe copiarse al formulario. El stock
        # mostrado sí es el TOTAL entre las fichas duplicadas.
        p = min(fichas, key=lambda f: f.id)
        marca = p.atributo1.valor if p.atributo1 else '-'
        color = p.atributo2.valor if p.atributo2 else '-'
        genero = p.atributo3.valor if p.atributo3 else '-'
        categoria = p.categoria.nombre if p.categoria else '-'
        tallas_qs = p.producto_talla.all()
        tallas_list = [t.talla for t in tallas_qs]
        stock_total = sum(
            t.stock for f in fichas for t in f.producto_talla.all())
        tallas_detail = [{'talla': t.talla, 'sku': t.sku, 'stock': t.stock} for t in tallas_qs]

        resultados.append({
            'id': p.id,
            'articulo': p.articulo,
            'descripcion': p.descripcion or '',
            'marca': marca,
            'marca_id': p.atributo1_id,
            'color': color,
            'color_id': p.atributo2_id,
            'genero': genero,
            'genero_id': p.atributo3_id,
            'categoria': categoria,
            'categoria_id': p.categoria_id,
            'precio': int(p.precioventa or 0),
            'costo': int(p.costo or 0),
            'sobreprecio': int(p.sobreprecio or 0),
            'stock': stock_total,
            'tallas': ', '.join(tallas_list[:6]) + ('...' if len(tallas_list) > 6 else ''),
            'tallas_detail': tallas_detail,
            'variantes': variantes_por_articulo.get(key[0], 1),
            'fichas_duplicadas': len(fichas) - 1,
            'creado': (p.fecha_creacion.strftime('%d-%m-%Y')
                       if getattr(p, 'fecha_creacion', None) else ''),
            'tipo_talla': p.tipo_talla or 'CL',
            'guia_talla_id': p.guia_talla_id,
            'guia_talla_nombre': str(p.guia_talla) if p.guia_talla else None,
        })

    total_global = Producto.objects.filter(filtros).count() if resultados else 0

    return JsonResponse({
        'resultados': resultados,
        'total': total_global,
        'query': q,
    })

def _especialidades_por_producto(producto_ids):
    """{producto_id: [{'id', 'valor'}]} del atributo "Especialidad" (v1.2), en UNA query.

    Todo endpoint que alimente el picker del modal Crear Manual debe devolver
    esta lista: `NexoManualPicker.setEsp(p.especialidades || [])` interpreta la
    ausencia de la clave como "sin especialidades" y LIMPIA lo que hubiera,
    así que un endpoint que la omita borra la especialidad en pantalla.
    """
    out = {}
    if not producto_ids:
        return out
    try:
        from .models import ProductoAtributoValor
        for pav in (ProductoAtributoValor.objects
                    .filter(producto_id__in=producto_ids,
                            atributo__nombre__iexact='Especialidad')
                    .select_related('opcion')):
            out.setdefault(pav.producto_id, []).append(
                {'id': pav.opcion_id, 'valor': pav.opcion.valor})
    except Exception as e:
        logger.warning("No se pudieron leer las especialidades: %s", e)
    return out


@require_GET
def buscar_productos_por_articulo(request):
    """
    Busca TODOS los productos que coincidan con un artículo (diferentes colores, marcas, etc.)
    Útil para mostrar variantes disponibles al usuario
    """
    articulo = request.GET.get('articulo', '').strip()
    sucursal_id = request.session.get('idSucursalActual')
    
    if not articulo:
        return JsonResponse({'productos': []})
    
    # Buscar todos los productos con este artículo en la sucursal
    filtros = {'articulo__iexact': articulo}
    if sucursal_id:
        filtros['sucursal_id'] = sucursal_id
    
    productos = Producto.objects.filter(**filtros).select_related(
        'atributo1', 'atributo2', 'atributo3', 'categoria'
    ).prefetch_related('producto_talla')[:20]
    
    # Especialidades v1.2 de todos los resultados en UNA query: sin esto el
    # autocomplete del artículo dejaba el picker en blanco al elegir un producto
    # existente (setEsp([]) borra lo que hubiera seleccionado).
    esp_map = _especialidades_por_producto([p.id for p in productos])

    resultado = []
    for p in productos:
        tallas = list(p.producto_talla.values('talla', 'sku', 'stock'))
        stock_total = sum(t.get('stock', 0) for t in tallas)

        resultado.append({
            'id': p.id,
            'especialidades': esp_map.get(p.id, []),
            'articulo': p.articulo,
            'descripcion': p.descripcion,
            'marca': p.atributo1.valor if p.atributo1 else '-',
            'marca_id': p.atributo1_id,
            'color': p.atributo2.valor if p.atributo2 else '-',
            'color_id': p.atributo2_id,
            'genero': p.atributo3.valor if p.atributo3 else '-',
            'genero_id': p.atributo3_id,
            'categoria': p.categoria.nombre if p.categoria else '-',
            'categoria_id': p.categoria_id,
            'costo': int(p.costo or 0),
            'sobreprecio': int(p.sobreprecio or 0),
            'precioventa': int(p.precioventa or 0),
            'stock_total': stock_total,
            'tallas': tallas,
            'tallas_str': ', '.join([t['talla'] for t in tallas]),
            'tipo_talla': p.tipo_talla or 'CL',
            'guia_talla_id': p.guia_talla_id,
            'guia_talla_nombre': str(p.guia_talla) if p.guia_talla else None,
        })
    
    return JsonResponse({'productos': resultado, 'total': len(resultado)})

 
def verificar_producto_existente(request):
    articulo = request.GET.get('articulo')
    marca = request.GET.get('marca')
    color = request.GET.get('color')
    genero = request.GET.get('genero')
    categoria = request.GET.get('categoria')
    sku_base = request.GET.get('sku_base')  # SKU base del producto de compra

    # ✅ OBTENER SUCURSAL ACTIVA DEL USUARIO
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        # Intentar obtener de EmpresaUser
        try:
            empresa_user = EmpresaUser.objects.filter(user=request.user, active=True).first()
            if empresa_user and empresa_user.sucursal:
                sucursal_id = empresa_user.sucursal.id
        except:
            pass

    # Normalizar el código: el aviso "producto ya existe" debe dispararse aunque
    # el usuario tipee el articulo con otras mayúsculas/espacios que el existente.
    articulo = (articulo or '').strip()

    # Convertir a enteros si son números, o buscar por valor si son texto
    filtros = {'articulo__iexact': articulo}

    # ✅ FILTRAR POR SUCURSAL ACTIVA
    if sucursal_id:
        filtros['sucursal_id'] = sucursal_id
    
    # ========== FUNCIÓN PARA BUSCAR ATRIBUTO CASE-INSENSITIVE ==========
    def buscar_atributo_flexible(valor, tipo_atributo=None):
        """Busca atributo por valor ignorando mayúsculas/minúsculas"""
        if not valor:
            return None
        try:
            # Primero intentar como ID
            attr_id = int(valor)
            return attr_id
        except (ValueError, TypeError):
            # Buscar por valor case-insensitive
            try:
                # Buscar el atributo que más se usa con ese valor (para evitar duplicados)
                attr_obj = AtributoOpcion.objects.filter(valor__iexact=valor).first()
                if attr_obj:
                    return attr_obj.id
            except AtributoOpcion.DoesNotExist:
                pass
        return None
    
    if marca:
        marca_id = buscar_atributo_flexible(marca)
        if marca_id:
            filtros['atributo1_id'] = marca_id
    
    if color:
        color_id = buscar_atributo_flexible(color)
        if color_id:
            filtros['atributo2_id'] = color_id
    
    if genero:
        genero_id = buscar_atributo_flexible(genero)
        if genero_id:
            filtros['atributo3_id'] = genero_id
    
    if categoria:
        try:
            categoria_id = int(categoria)
            filtros['categoria_id'] = categoria_id
        except (ValueError, TypeError):
            try:
                from .models import Categoria
                categoria_obj = Categoria.objects.get(nombre=categoria)
                filtros['categoria_id'] = categoria_obj.id
            except Categoria.DoesNotExist:
                pass

    # Buscar producto con los filtros exactos (en la sucursal activa).
    # ordenar_por_reciente es OBLIGATORIO: sin ORDER BY el motor devolvía una
    # ficha distinta según el orden físico de la tabla, así que el panel podía
    # mostrar los SKUs de una ficha mientras la creación escribía en la otra.
    from .utils_producto_match import ordenar_por_reciente
    _qs_identidad = ordenar_por_reciente(
        Producto.objects.filter(**filtros)
        .select_related('sucursal', 'atributo1', 'atributo2', 'atributo3', 'categoria'))
    _fichas_identidad = list(_qs_identidad)
    producto = _fichas_identidad[0] if _fichas_identidad else None

    # Detectar duplicados en la sucursal activa (mismo artículo + atributos)
    hay_duplicados = False
    total_duplicados = 0
    fichas_duplicadas = []
    if producto and articulo:
        total_duplicados = len(_fichas_identidad)
        hay_duplicados = total_duplicados > 1
        if hay_duplicados:
            # Detalle de CADA ficha (tallas, SKUs y stock) para que el modal
            # pueda avisar de forma bloqueante en cuál va a caer el stock.
            _aggs_dup = {r['producto_id']: r for r in
                         Producto_Talla.objects.filter(producto_id__in=[f.id for f in _fichas_identidad])
                         .values('producto_id').annotate(s=Sum('stock'), n=Count('id'))}
            _skus_dup = {}
            for _pt in Producto_Talla.objects.filter(
                    producto_id__in=[f.id for f in _fichas_identidad]).order_by('talla'):
                _skus_dup.setdefault(_pt.producto_id, []).append(str(_pt.sku))
            for _i, _f in enumerate(_fichas_identidad):
                _a = _aggs_dup.get(_f.id, {})
                fichas_duplicadas.append({
                    'producto_id': _f.id,
                    'es_destino': _i == 0,  # la más reciente: ahí caerá el stock
                    'descripcion': _f.descripcion or '',
                    'categoria': _f.categoria.nombre if _f.categoria else '-',
                    'precioventa': int(_f.precioventa or 0),
                    'n_tallas': (_a.get('n') or 0),
                    'stock_total': (_a.get('s') or 0),
                    'skus': _skus_dup.get(_f.id, [])[:12],
                    'fecha_creacion': _f.fecha_creacion.strftime('%d/%m/%Y') if _f.fecha_creacion else '—',
                })
            logger.warning(
                "Codigo con fichas DUPLICADAS en la sucursal: articulo=%s sucursal_id=%s fichas=%s destino=%s",
                articulo, sucursal_id, [f.id for f in _fichas_identidad], producto.id,
            )

    # ========== BÚSQUEDA FLEXIBLE SI NO ENCUENTRA EXACTO ==========
    if not producto and articulo:
        # Obtener valores de atributos para comparación case-insensitive
        def get_valor_attr(attr_valor):
            if not attr_valor:
                return None
            try:
                attr_id = int(attr_valor)
                attr_obj = AtributoOpcion.objects.filter(id=attr_id).first()
                return attr_obj.valor.upper() if attr_obj else None
            except (ValueError, TypeError):
                return str(attr_valor).upper()
        
        valor_marca = get_valor_attr(marca)
        valor_color = get_valor_attr(color)
        valor_genero = get_valor_attr(genero)
        
        # Obtener categoría ID para comparación
        categoria_id_filtro = None
        if categoria:
            try:
                categoria_id_filtro = int(categoria)
            except (ValueError, TypeError):
                try:
                    from .models import Categoria as CategoriaModel
                    cat_obj = CategoriaModel.objects.filter(nombre=categoria).first()
                    categoria_id_filtro = cat_obj.id if cat_obj else None
                except:
                    pass
        
        # Buscar productos con el mismo artículo en la sucursal (case/space-insensitive)
        filtros_candidatos = {'articulo__iexact': articulo}
        if sucursal_id:
            filtros_candidatos['sucursal_id'] = sucursal_id
        # ✅ INCLUIR CATEGORÍA EN LA BÚSQUEDA FLEXIBLE
        if categoria_id_filtro:
            filtros_candidatos['categoria_id'] = categoria_id_filtro
            
        productos_candidatos = Producto.objects.filter(
            **filtros_candidatos
        ).select_related('atributo1', 'atributo2', 'atributo3', 'sucursal', 'categoria')
        
        for prod in productos_candidatos:
            # Comparar atributos case-insensitive
            match_marca = (not valor_marca) or \
                         (prod.atributo1 and prod.atributo1.valor.upper() == valor_marca)
            match_color = (not valor_color) or \
                         (prod.atributo2 and prod.atributo2.valor.upper() == valor_color)
            match_genero = (not valor_genero) or \
                          (prod.atributo3 and prod.atributo3.valor.upper() == valor_genero)
            
            if match_marca and match_color and match_genero:
                producto = prod
                logger.debug(
                    "Producto encontrado con atributos equivalentes: producto_id=%s articulo=%s",
                    prod.id,
                    prod.articulo,
                )
                break

    # ========== MISMA VARIANTE PERO OTRA CATEGORÍA (guardia anti-duplicado) ==========
    # La categoría es parte de la identidad: si el usuario seleccionó la
    # categoría "correcta" pero la ficha guardada tiene otra, el match exacto
    # falla y el flujo de creación terminaría en un DUPLICADO con SKUs nuevos.
    # Se detecta acá para que la UI ofrezca corregir la categoría del existente.
    producto_categoria_distinta = None
    if (not producto and articulo and filtros.get('categoria_id')
            and filtros.get('atributo1_id') and filtros.get('atributo2_id')
            and filtros.get('atributo3_id')):
        try:
            _f = {k: v for k, v in filtros.items() if k != 'categoria_id'}
            _p = (Producto.objects.filter(**_f)
                  .exclude(categoria_id=filtros['categoria_id'])
                  .select_related('categoria', 'atributo1', 'atributo2', 'atributo3')
                  .first())
            if _p:
                _agg = Producto_Talla.objects.filter(producto=_p).aggregate(s=Sum('stock'), n=Count('id'))
                _cat_form = Categoria.objects.filter(id=filtros['categoria_id']).first()
                producto_categoria_distinta = {
                    'id': _p.id,
                    'articulo': _p.articulo,
                    'marca': _p.atributo1.valor if _p.atributo1 else '-',
                    'color': _p.atributo2.valor if _p.atributo2 else '-',
                    'genero': _p.atributo3.valor if _p.atributo3 else '-',
                    'categoria': _p.categoria.nombre if _p.categoria else '-',
                    'categoria_id': _p.categoria_id,
                    'categoria_form_id': filtros['categoria_id'],
                    'categoria_form_nombre': _cat_form.nombre if _cat_form else '-',
                    'n_tallas': _agg.get('n') or 0,
                    'stock_total': _agg.get('s') or 0,
                }
        except Exception as e:
            logger.warning("Error detectando producto con otra categoría: %s", e)

    # 🔍 BUSCAR PRODUCTOS SIMILARES POR SKU (solo en sucursal activa)
    productos_similares_sku = []
    if sku_base and sku_base.strip():
        filtro_sku = {'sku__icontains': sku_base.strip()}
        if sucursal_id:
            filtro_sku['producto__sucursal_id'] = sucursal_id
            
        tallas_similares = Producto_Talla.objects.filter(
            **filtro_sku
        ).select_related(
            'producto', 'producto__atributo1', 'producto__atributo2', 
            'producto__atributo3', 'producto__categoria'
        ).distinct()[:20]
        
        productos_ids_vistos = set()
        for talla in tallas_similares:
            if talla.producto_id not in productos_ids_vistos:
                productos_ids_vistos.add(talla.producto_id)
                p = talla.producto
                # Obtener tallas del producto
                tallas_producto = list(Producto_Talla.objects.filter(producto=p).values_list('talla', flat=True))
                productos_similares_sku.append({
                    'id': p.id,
                    'articulo': p.articulo,
                    'marca': p.atributo1.valor if p.atributo1 else '-',
                    'marca_id': p.atributo1_id,
                    'color': p.atributo2.valor if p.atributo2 else '-',
                    'color_id': p.atributo2_id,
                    'genero': p.atributo3.valor if p.atributo3 else '-',
                    'genero_id': p.atributo3_id,
                    'categoria': p.categoria.nombre if p.categoria else '-',
                    'categoria_id': p.categoria_id,
                    'precioventa': float(p.precioventa) if p.precioventa else None,
                    'costo': float(p.costo) if p.costo else None,
                    'tallas': ', '.join(tallas_producto) if tallas_producto else '-',
                    'sku_ejemplo': talla.sku
                })
    
    # 🔍 BUSCAR PRODUCTOS SIMILARES POR NOMBRE (solo en sucursal activa)
    productos_similares_nombre = []
    if articulo and articulo.strip():
        filtro_nombre = {'articulo__icontains': articulo.strip()}
        if sucursal_id:
            filtro_nombre['sucursal_id'] = sucursal_id
            
        productos_nombre = Producto.objects.filter(
            **filtro_nombre
        ).select_related(
            'atributo1', 'atributo2', 'atributo3', 'categoria'
        ).exclude(id=producto.id if producto else 0)[:10]
        
        for p in productos_nombre:
            primera_talla = Producto_Talla.objects.filter(producto=p).first()
            tallas_producto = list(Producto_Talla.objects.filter(producto=p).values_list('talla', flat=True))
            productos_similares_nombre.append({
                'id': p.id,
                'articulo': p.articulo,
                'marca': p.atributo1.valor if p.atributo1 else '-',
                'marca_id': p.atributo1_id,
                'color': p.atributo2.valor if p.atributo2 else '-',
                'color_id': p.atributo2_id,
                'genero': p.atributo3.valor if p.atributo3 else '-',
                'genero_id': p.atributo3_id,
                'categoria': p.categoria.nombre if p.categoria else '-',
                'categoria_id': p.categoria_id,
                'precioventa': float(p.precioventa) if p.precioventa else None,
                'costo': float(p.costo) if p.costo else None,
                'tallas': ', '.join(tallas_producto) if tallas_producto else '-',
                'sku_ejemplo': primera_talla.sku if primera_talla else '-'
            })
    

    # ========== BODEGAS DEL CÓDIGO (todas las sucursales del usuario) ==========
    # Muestra en qué bodegas existe el código y sus variantes (colores/géneros
    # distintos) diferenciadas, para elegir bien y no duplicar.
    bodegas_codigo = []
    try:
        if articulo:
            _emp = EmpresaUser.objects.filter(user=request.user, status=True).values_list('empresa_id', flat=True)
            _suc_ids = list(Sucursal.objects.filter(empresa_id__in=_emp).values_list('id', flat=True))
            from .utils_producto_match import productos_por_codigo_sucursales

            def _cid(v):
                try:
                    return int(v)
                except (ValueError, TypeError):
                    return None
            _combo_actual = (_cid(marca), _cid(color), _cid(genero), _cid(categoria))
            _combo_completo = all(c is not None for c in _combo_actual)
            _prods = productos_por_codigo_sucursales(articulo, _suc_ids)
            # Stock y nº de tallas de TODOS los productos en UNA sola query (evita N+1)
            _aggs = {r['producto_id']: r for r in
                     Producto_Talla.objects.filter(producto_id__in=[p.id for p in _prods])
                     .values('producto_id').annotate(s=Sum('stock'), n=Count('id'))}
            for p in _prods:
                _combo_p = (p.atributo1_id, p.atributo2_id, p.atributo3_id, p.categoria_id)
                _a = _aggs.get(p.id, {})
                bodegas_codigo.append({
                    'producto_id': p.id,
                    'sucursal': p.sucursal.alias if p.sucursal else '-',
                    'sucursal_id': p.sucursal_id,
                    'es_sucursal_actual': str(p.sucursal_id) == str(sucursal_id),
                    'marca': p.atributo1.valor if p.atributo1 else '-',
                    'color': p.atributo2.valor if p.atributo2 else '-',
                    'genero': p.atributo3.valor if p.atributo3 else '-',
                    'categoria': p.categoria.nombre if p.categoria else '-',
                    'descripcion': p.descripcion or '',
                    'precioventa': int(p.precioventa or 0),
                    'stock_total': (_a.get('s') or 0),
                    'n_tallas': (_a.get('n') or 0),
                    'mismo_combo': (_combo_p == _combo_actual) if _combo_completo else None,
                })
    except Exception as e:
        logger.warning("Error calculando bodegas_codigo: %s", e)

    if producto:
        # Obtener las tallas existentes con sus SKUs
        tallas_existentes = Producto_Talla.objects.filter(producto=producto).values('talla', 'sku', 'stock')
        tallas_lista = list(Producto_Talla.objects.filter(producto=producto).values_list('talla', flat=True))
        
        # ========== NORMALIZACIÓN DE TALLAS PARA COMPARACIÓN FLEXIBLE ==========
        def normalizar_talla_verificacion(talla_str):
            """Normaliza una talla para comparación (7 = 7.0 = 7,0). Preserva '00' como talla única CL."""
            if not talla_str:
                return None
            talla_str = str(talla_str).strip()
            # Preservar tallas con ceros iniciales significativos (ej: "00" = talla única CL)
            if re.match(r'^0\d+$', talla_str):
                return talla_str
            talla_str = talla_str.replace(',', '.')
            try:
                valor = float(talla_str)
                if valor == int(valor):
                    return f"{int(valor)}.0"
                return f"{valor:.1f}"
            except (ValueError, TypeError):
                return talla_str.upper()
        
        # Crear mapa de tallas normalizadas para que el frontend pueda comparar
        tallas_normalizadas_map = {}
        for talla in tallas_lista:
            talla_norm = normalizar_talla_verificacion(talla)
            if talla_norm:
                tallas_normalizadas_map[talla_norm] = talla
                # También agregar variantes comunes
                try:
                    valor = float(talla.replace(',', '.'))
                    if valor == int(valor):
                        # Para enteros, agregar sin decimal
                        tallas_normalizadas_map[str(int(valor))] = talla
                except (ValueError, TypeError):
                    pass
        # ==========================================================================
        
        # ✅ Incluir info del producto encontrado (incluyendo precios para comparación)
        producto_encontrado = {
            'id': producto.id,
            'articulo': producto.articulo,
            'descripcion': producto.descripcion,
            'marca': producto.atributo1.valor if producto.atributo1 else '-',
            'marca_id': producto.atributo1_id,  # ✅ ID para seleccionar en el form
            'color': producto.atributo2.valor if producto.atributo2 else '-',
            'color_id': producto.atributo2_id,  # ✅ ID para seleccionar en el form
            'genero': producto.atributo3.valor if producto.atributo3 else '-',
            'genero_id': producto.atributo3_id,  # ✅ ID para seleccionar en el form
            'categoria': producto.categoria.nombre if producto.categoria else '-',
            'categoria_id': producto.categoria_id,  # ✅ ID para seleccionar en el form
            'tallas': ', '.join(tallas_lista) if tallas_lista else '-',
            'total_tallas': len(tallas_lista),
            # ✅ Agregar precios para comparación en frontend
            'costo': int(producto.costo or 0),
            'sobreprecio': int(producto.sobreprecio or 0),
            'precioventa': int(producto.precioventa or 0),
            'stock_total': sum(t.get('stock', 0) for t in tallas_existentes)
        }

        # Especialidades v1.2 del producto (atributo transversal multi-etiqueta),
        # para que "copiar datos" del modal manual las precargue en el picker.
        try:
            from .models import ProductoAtributoValor
            producto_encontrado['especialidades'] = [
                {'id': pav.opcion_id, 'valor': pav.opcion.valor}
                for pav in ProductoAtributoValor.objects.filter(
                    producto=producto, atributo__nombre__iexact='Especialidad'
                ).select_related('opcion')
            ]
        except Exception:
            producto_encontrado['especialidades'] = []
        
        # ========== BUSCAR PRECIOS EN OTRAS SUCURSALES ==========
        productos_otras_sucursales = []
        try:
            # Incluir la sucursal actual primero (siempre existe porque producto fue encontrado aquí)
            sucursal_actual_obj = producto.sucursal
            productos_otras_sucursales.append({
                'producto_id': producto.id,
                'sucursal_id': producto.sucursal_id,
                'sucursal_nombre': sucursal_actual_obj.alias if sucursal_actual_obj else 'Sucursal actual',
                'precioventa': int(producto.precioventa or 0),
                'costo': int(producto.costo or 0),
                'sobreprecio': int(producto.sobreprecio or 0),
                'precio_diferente': False,
                'marca': producto.atributo1.valor if producto.atributo1 else '-',
                'color': producto.atributo2.valor if producto.atributo2 else '-',
                'es_sucursal_actual': True,
            })

            # Buscar productos con mismo artículo y atributos en OTRAS sucursales
            # (iexact: hay códigos históricos con mayúsculas/minúsculas mezcladas)
            filtros_otras = {
                'articulo__iexact': articulo,
            }
            if producto.atributo1_id:
                filtros_otras['atributo1_id'] = producto.atributo1_id
            if producto.atributo2_id:
                filtros_otras['atributo2_id'] = producto.atributo2_id
            if producto.atributo3_id:
                filtros_otras['atributo3_id'] = producto.atributo3_id
            if producto.categoria_id:
                filtros_otras['categoria_id'] = producto.categoria_id
            
            otros_productos = Producto.objects.filter(
                **filtros_otras
            ).exclude(
                sucursal_id=sucursal_id  # Excluir sucursal actual (ya incluida arriba)
            ).select_related('sucursal', 'atributo1', 'atributo2')
            
            for op in otros_productos:
                productos_otras_sucursales.append({
                    'producto_id': op.id,
                    'sucursal_id': op.sucursal_id,
                    'sucursal_nombre': op.sucursal.alias if op.sucursal else 'Sin sucursal',
                    'precioventa': int(op.precioventa or 0),
                    'costo': int(op.costo or 0),
                    'sobreprecio': int(op.sobreprecio or 0),
                    'precio_diferente': int(op.precioventa or 0) != int(producto.precioventa or 0),
                    'marca': op.atributo1.valor if op.atributo1 else '-',
                    'color': op.atributo2.valor if op.atributo2 else '-',
                    'es_sucursal_actual': False,
                })
            
            if productos_otras_sucursales:
                logger.debug(
                    "Producto encontrado en multiples sucursales: producto_id=%s total=%s",
                    producto.id,
                    len(productos_otras_sucursales),
                )
        except Exception as e:
            logger.warning("Error buscando producto en otras sucursales: %s", e)
        # =========================================================
        
        return JsonResponse({
            'existe': True,
            'producto_id': producto.id,
            'producto_encontrado': producto_encontrado,
            'tallas_existentes': list(tallas_existentes),
            'tallas_normalizadas_map': tallas_normalizadas_map,
            'productos_similares_sku': productos_similares_sku,
            'productos_similares_nombre': productos_similares_nombre,
            'productos_otras_sucursales': productos_otras_sucursales,
            'edel_producto': _build_edel_producto_ref(articulo, producto),
            'hay_duplicados': hay_duplicados,
            'total_duplicados': total_duplicados,
            'fichas_duplicadas': fichas_duplicadas,
            'bodegas_codigo': bodegas_codigo,
        })
    else:
        # ========== BUSCAR PRECIOS EN OTRAS SUCURSALES (para producto nuevo) ==========
        productos_otras_sucursales = []
        try:
            logger.debug(
                "Buscando producto en otras sucursales: articulo=%s marca=%s color=%s genero=%s",
                articulo,
                marca,
                color,
                genero,
            )
            
            # Obtener IDs de atributos para la búsqueda
            marca_id = buscar_atributo_flexible(marca) if marca else None
            color_id = buscar_atributo_flexible(color) if color else None
            genero_id = buscar_atributo_flexible(genero) if genero else None
            
            logger.debug(
                "Atributos resueltos para busqueda en otras sucursales: marca_id=%s color_id=%s genero_id=%s",
                marca_id,
                color_id,
                genero_id,
            )
            
            # ✅ BÚSQUEDA MEJORADA: Primero buscar solo por artículo (más flexible)
            if articulo:
                # Búsqueda 1: Por artículo exacto (ignorando case)
                otros_productos = Producto.objects.filter(
                    articulo__iexact=articulo
                ).select_related('sucursal', 'atributo1', 'atributo2', 'atributo3')
                
                # Si hay sucursal actual, excluirla
                if sucursal_id:
                    otros_productos = otros_productos.exclude(sucursal_id=sucursal_id)
                
                logger.debug("Productos encontrados por articulo en otras sucursales: total=%s", otros_productos.count())
                
                # Si hay muchos, filtrar por atributos
                if otros_productos.count() > 10 and (marca_id or color_id):
                    filtros_extras = Q()
                    if marca_id:
                        filtros_extras &= Q(atributo1_id=marca_id)
                    if color_id:
                        filtros_extras &= Q(atributo2_id=color_id)
                    if genero_id:
                        filtros_extras &= Q(atributo3_id=genero_id)
                    otros_productos = otros_productos.filter(filtros_extras)
                    logger.debug("Productos tras filtrar atributos en otras sucursales: total=%s", otros_productos.count())
                
                for op in otros_productos:
                    productos_otras_sucursales.append({
                        'producto_id': op.id,
                        'sucursal_id': op.sucursal_id,
                        'sucursal_nombre': op.sucursal.alias if op.sucursal else 'Sin sucursal',
                        'precioventa': int(op.precioventa or 0),
                        'costo': int(op.costo or 0),
                        'sobreprecio': int(op.sobreprecio or 0),
                        'precio_diferente': True,  # Siempre diferente porque no existe local
                        'marca': op.atributo1.valor if op.atributo1 else '-',
                        'color': op.atributo2.valor if op.atributo2 else '-'
                    })
                
                if productos_otras_sucursales:
                    logger.debug(
                        "Producto no existe localmente pero fue encontrado en otras sucursales: total=%s",
                        len(productos_otras_sucursales),
                    )
                else:
                    logger.debug("Producto no encontrado en otras sucursales: articulo=%s", articulo)
        except Exception as e:
            logger.exception("Error buscando producto en otras sucursales")
        # =========================================================
        
        return JsonResponse({
            'existe': False,
            'tallas_existentes': [],
            'producto_encontrado': None,
            'producto_categoria_distinta': producto_categoria_distinta,
            'productos_similares_sku': productos_similares_sku,
            'productos_similares_nombre': productos_similares_nombre,
            'productos_otras_sucursales': productos_otras_sucursales,
            'edel_producto': _build_edel_producto_ref(articulo, None),
            'bodegas_codigo': bodegas_codigo,
        })


def _build_edel_producto_ref(articulo, producto_local):
    """Busca el producto en EDEL (alias='EDEL') y devuelve sus datos de referencia.
    Si el producto_local ya es de EDEL se reutiliza su data directamente.
    Retorna None si no hay producto en EDEL."""
    try:
        # Si el producto encontrado ya pertenece a EDEL, no hacer otra query
        if producto_local and producto_local.sucursal and \
                producto_local.sucursal.alias and \
                producto_local.sucursal.alias.upper() == 'EDEL':
            p = producto_local
        else:
            p = Producto.objects.filter(
                articulo__iexact=articulo,
                sucursal__alias__iexact='EDEL'
            ).select_related('atributo1', 'atributo2', 'atributo3', 'categoria', 'sucursal').first()

        if not p:
            return None

        tallas_qs = Producto_Talla.objects.filter(producto=p).values('talla', 'sku', 'stock')
        tallas_lista = [t['talla'] for t in tallas_qs]
        return {
            'id': p.id,
            'articulo': p.articulo,
            'descripcion': p.descripcion,
            'marca': p.atributo1.valor if p.atributo1 else '-',
            'marca_id': p.atributo1_id,
            'color': p.atributo2.valor if p.atributo2 else '-',
            'color_id': p.atributo2_id,
            'genero': p.atributo3.valor if p.atributo3 else '-',
            'genero_id': p.atributo3_id,
            'categoria': p.categoria.nombre if p.categoria else '-',
            'categoria_id': p.categoria_id,
            'precioventa': int(p.precioventa or 0),
            'costo': int(p.costo or 0),
            'sobreprecio': int(p.sobreprecio or 0),
            'total_tallas': len(tallas_lista),
            'tallas': ', '.join(tallas_lista),
            # Detalle por talla (necesario para "reutiliza" en modo distribuir)
            'tallas_detail': [{'talla': t['talla'], 'sku': t['sku'], 'stock': t['stock'] or 0} for t in tallas_qs],
        }
    except Exception as e:
        logger.warning("Error buscando producto en EDEL: %s", e)
        return None


@transaction.atomic
def crear_producto_desde_recepcion(request):
    # 1. Validar sesión y datos básicos
    session_sucursal_id = request.session.get('idSucursalActual')
    usuario = request.session.get('nombreUsuario', 'Sistema')
    if not session_sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)

    data = request.POST

    # Diseño multi-sucursal:
    # • El `Producto` se crea (o se actualiza) SIEMPRE en la sucursal ACTIVA
    #   del usuario — el catálogo es centralizado. La sucursal de la fila
    #   (`sucursal_destino_id`) es SÓLO una referencia para saber a qué
    #   sucursal va a parar físicamente la mercadería.
    # • `sucursal_destino_id` sirve únicamente como filtro para decidir qué
    #   `Productos_Recepcionados` enlazar al `Producto_Talla` creado (los que
    #   corresponden a esa fila) y para qué unidades registrar el ingreso en
    #   los `Movimientos_Producto` de la sucursal activa.
    sucursal = get_object_or_404(Sucursal, pk=session_sucursal_id)
    sucursal_id = sucursal.id

    # Lista de sucursales destino que el frontend quiere procesar en batch.
    # Formato aceptado (en orden de prioridad):
    #   • POST sucursales_destino_ids[]  (lista, flujo multi-sucursal)
    #   • POST sucursales_destino_ids    (CSV "5,6" en un solo campo)
    #   • POST sucursal_destino_id       (singular, flujo legacy)
    # Un valor vacío representa la fila "Sin sucursal" (NULL).
    raw_lista = []
    if hasattr(data, 'getlist'):
        raw_lista = data.getlist('sucursales_destino_ids[]') or data.getlist('sucursales_destino_ids')
    if not raw_lista:
        csv_val = data.get('sucursales_destino_ids')
        if csv_val:
            raw_lista = [s.strip() for s in csv_val.split(',')]
    if not raw_lista:
        singular = data.get('sucursal_destino_id')
        if singular is not None:
            raw_lista = [singular]

    sucursales_destino_ids = []
    incluir_null_destino = False
    for raw in raw_lista:
        s = (raw or '').strip() if isinstance(raw, str) else raw
        if s == '' or s is None:
            incluir_null_destino = True
            continue
        try:
            sucursales_destino_ids.append(int(s))
        except (TypeError, ValueError):
            continue
    # Back-compat: conservar la primera sucursal como "fila" para logs/chips
    sucursal_destino_fila_id = (
        sucursales_destino_ids[0] if sucursales_destino_ids else None
    )

    # Filtro de recepciones por sucursales DESTINO. Cuando llegan explícitas,
    # filtramos estricto por ellas (todas las listadas). Sin lista (flujo
    # legacy), mantenemos el filtro amplio (sucursal activa + NULL).
    if sucursales_destino_ids and incluir_null_destino:
        filtro_sucursal_recepciones = (
            Q(sucursal_destino_id__in=sucursales_destino_ids)
            | Q(sucursal_destino__isnull=True)
        )
    elif sucursales_destino_ids:
        filtro_sucursal_recepciones = Q(sucursal_destino_id__in=sucursales_destino_ids)
    elif incluir_null_destino:
        filtro_sucursal_recepciones = Q(sucursal_destino__isnull=True)
    else:
        filtro_sucursal_recepciones = (
            Q(sucursal_destino=sucursal) | Q(sucursal_destino__isnull=True)
        )
    # Canonizar SIEMPRE el código al guardarlo (mayúsculas, sin espacios dobles
    # ni acentos): es el mismo canon que usa el matching de identidad. Antes se
    # guardaba tal cual se tipeó y quedaban códigos en minúscula en el catálogo.
    from .utils_producto_match import normalizar_articulo as _normart
    articulo = _normart(data.get('articulo'))
    descripcion = data.get('descripcion')
    atributo1 = data.get('atributo1') or None
    atributo2 = data.get('atributo2') or None
    atributo3 = data.get('atributo3') or None
    atributo4 = data.get('atributo4') or None
    categoria = data.get('categoria') or None
    costo = int(data.get('costo') or 0)
    sobreprecio = int(data.get('sobreprecio') or 0)
    precioventa = int(data.get('precioventa') or 0)
    precio_sugerido = int(data.get('precio_sugerido') or 0)
    tipo_talla = data.get('tipo_talla') or 'CL'
    guia_talla = data.get('guia_talla') or None
    # El frontend puede enviar sin_guia=1 cuando el usuario eligió "Sin guía"
    # (talla única 00). En ese caso consolidamos todas las recepciones en una
    # sola Producto_Talla y guia_talla queda en None.
    es_sin_guia = (
        (data.get('sin_guia') in ('1', 'true', 'True'))
        or guia_talla in ('SIN_GUIA',)
    )
    if es_sin_guia:
        guia_talla = None
    # Cuando la compra venía con talla consolidada ("00" o "__TOTAL__") y el
    # usuario distribuye el total en tallas reales de la guía. Debemos:
    # 1) reemplazar la Compras_Producto_Talla consolidada por N reales
    #    proporcionales, 2) clonar Productos_Recepcionados por DTE×talla,
    # 3) seguir el flujo normal para crear Producto_Talla y movimientos.
    redistribuir_desde_consolidado = (
        data.get('redistribuir_desde_consolidado') in ('1', 'true', 'True')
    )
    producto_compra_id = data.get('producto_compra_id') or None
    
    tallas_recibidas = [(k, v) for k, v in data.items() if k.startswith('sku_') or k.startswith('stock_')]
    logger.debug(
        "Crear producto desde recepcion: articulo=%s marca=%s color=%s genero=%s categoria=%s costo=%s sobreprecio=%s precioventa=%s producto_compra_id=%s sucursal_id=%s tallas_recibidas=%s",
        articulo,
        atributo1,
        atributo2,
        atributo3,
        categoria,
        costo,
        sobreprecio,
        precioventa,
        producto_compra_id,
        sucursal_id,
        tallas_recibidas,
    )

    # ========== NORMALIZACIÓN DE ATRIBUTOS (case-insensitive) ==========
    def buscar_atributo_normalizado(atributo_id, tipo_atributo=None):
        """
        Busca un atributo considerando mayúsculas/minúsculas.
        Si el ID dado no existe o hay uno equivalente con diferente capitalización,
        retorna el ID correcto.
        """
        if not atributo_id:
            return None
        
        try:
            # Primero verificar si el ID existe
            atributo = AtributoOpcion.objects.get(id=atributo_id)
            valor_original = atributo.valor
            
            # Buscar si hay un atributo equivalente (case-insensitive)
            # Usar el primero que coincida
            atributo_similar = AtributoOpcion.objects.filter(
                atributo=atributo.atributo,
                valor__iexact=valor_original
            ).first()
            
            if atributo_similar:
                return atributo_similar.id
            
            return atributo_id
        except AtributoOpcion.DoesNotExist:
            return atributo_id
    
    # Normalizar atributos para búsqueda flexible
    atributo1_normalizado = buscar_atributo_normalizado(atributo1)
    atributo2_normalizado = buscar_atributo_normalizado(atributo2)
    atributo3_normalizado = buscar_atributo_normalizado(atributo3)

    # ========== 2. BUSCAR SI PRODUCTO YA EXISTE EN ESTA SUCURSAL ==========
    # Match por IDENTIDAD con articulo NORMALIZADO (sin distinguir mayúsculas,
    # espacios ni acentos) + marca + color + género + categoría + sucursal.
    # Antes comparaba el articulo como texto exacto y un tipeo distinto creaba
    # un producto duplicado con SKUs nuevos (bug reportado en recepción).
    # Desde el fix de determinismo esta función devuelve SIEMPRE la ficha más
    # reciente del grupo, así que dos recepciones seguidas ya no caen en fichas
    # distintas. Este flujo no tiene confirmación bloqueante (sí la tiene el
    # modal Crear Manual), pero deja rastro en el log para poder auditarlo.
    from .utils_producto_match import fichas_por_identidad
    _fichas = fichas_por_identidad(
        articulo, atributo1_normalizado, atributo2_normalizado,
        atributo3_normalizado, categoria, sucursal.id,
    )
    producto_existente = _fichas[0] if _fichas else None
    if len(_fichas) > 1:
        logger.warning(
            "Recepcion sobre codigo con fichas DUPLICADAS: articulo=%s sucursal=%s fichas=%s destino=%s",
            articulo, sucursal.alias, [f.id for f in _fichas], producto_existente.id,
        )

    # Si no encuentra, buscar con atributos case-insensitive por valor
    if not producto_existente:
        # Nota: `Q` ya está importado a nivel de módulo (línea 46). Evitamos
        # un `from ... import Q` local: al estar la función anotada con
        # @transaction.atomic, si reasignamos Q dentro de un bloque, Python
        # lo trata como variable local en TODA la función y truena con
        # UnboundLocalError al primer uso previo (línea 11639).

        # Obtener valores de atributos para búsqueda flexible
        def get_valor_atributo(attr_id):
            if not attr_id:
                return None
            try:
                return AtributoOpcion.objects.get(id=attr_id).valor
            except AtributoOpcion.DoesNotExist:
                return None
        
        valor_attr1 = get_valor_atributo(atributo1)
        valor_attr2 = get_valor_atributo(atributo2)
        valor_attr3 = get_valor_atributo(atributo3)
        
        # Buscar productos con el mismo CÓDIGO NORMALIZADO en la sucursal Y categoría
        # (el fallback flexible ahora también normaliza el articulo, no solo los atributos).
        from .utils_producto_match import normalizar_articulo
        objetivo_art = normalizar_articulo(articulo)
        token_art = objetivo_art.split(' ')[0] if objetivo_art else ''
        filtros_flex = {'sucursal': sucursal}
        if token_art:
            filtros_flex['articulo__icontains'] = token_art
        if categoria:
            filtros_flex['categoria_id'] = categoria

        productos_candidatos = Producto.objects.filter(
            **filtros_flex
        ).select_related('atributo1', 'atributo2', 'atributo3')

        for prod in productos_candidatos:
            # Debe coincidir el código normalizado (mayúsculas/espacios/acentos)
            if normalizar_articulo(prod.articulo) != objetivo_art:
                continue
            # Comparar atributos case-insensitive
            match_attr1 = (not valor_attr1 and not prod.atributo1) or \
                         (valor_attr1 and prod.atributo1 and prod.atributo1.valor.upper() == valor_attr1.upper())
            match_attr2 = (not valor_attr2 and not prod.atributo2) or \
                         (valor_attr2 and prod.atributo2 and prod.atributo2.valor.upper() == valor_attr2.upper())
            match_attr3 = (not valor_attr3 and not prod.atributo3) or \
                         (valor_attr3 and prod.atributo3 and prod.atributo3.valor.upper() == valor_attr3.upper())
            
            if match_attr1 and match_attr2 and match_attr3:
                producto_existente = prod
                logger.debug(
                    "Producto existente encontrado con atributos equivalentes: producto_id=%s articulo=%s",
                    prod.id,
                    prod.articulo,
                )
                break
    
    producto_actualizado = False
    precios_cambiaron = False
    precio_anterior = 0
    costo_anterior = 0
    
    if producto_existente:
        # ✅ PRODUCTO EXISTE - Actualizar precios si cambiaron
        producto = producto_existente
        precio_anterior = producto.precioventa
        costo_anterior = producto.costo
        
        logger.debug(
            "Producto existente encontrado: producto_id=%s articulo=%s precios_bd=(%s,%s,%s) precios_nuevos=(%s,%s,%s)",
            producto.id,
            producto.articulo,
            producto.costo,
            producto.sobreprecio,
            producto.precioventa,
            costo,
            sobreprecio,
            precioventa,
        )
        
        # Verificar si los precios cambiaron (forzar comparación como int)
        costo_db = int(producto.costo or 0)
        sobreprecio_db = int(producto.sobreprecio or 0)
        precioventa_db = int(producto.precioventa or 0)

        # Gate de precios (paridad con el flujo manual): solo se pisan los
        # precios/costos guardados si el usuario lo pidió explícitamente
        # (checkbox del modal). Antes la recepción SIEMPRE sobrescribía precio
        # de venta y costo del producto existente, cambiando precios de vitrina
        # sin control. El flag lo envía el frontend; ausente = no tocar precios.
        actualizar_precios_flag = str(data.get('actualizar_precios', '')).strip().lower() in (
            '1', 'true', 'on', 'yes',
        )
        precios_difieren = (
            costo_db != costo or sobreprecio_db != sobreprecio or precioventa_db != precioventa
        )

        if precios_difieren and actualizar_precios_flag:
            precios_cambiaron = True
            logger.debug("Precios cambiaron; actualizando producto_id=%s", producto.id)
            
            # Actualizar precios del producto
            producto.costo = costo
            producto.sobreprecio = sobreprecio
            producto.precioventa = precioventa
            producto.precioSugerido = precio_sugerido
            producto.descripcion = descripcion  # También actualizar descripción
            producto.save()
            logger.info("Producto guardado con nuevos precios: producto_id=%s", producto.id)
            
            # Actualizar lotes FIFO activos con el nuevo precio
            lotes_repreciados = LoteProducto.objects.filter(
                producto_talla__producto=producto,
                cantidad_disponible__gt=0,
                activo=True
            ).update(
                precio_venta_unitario=precioventa,
                costo_unitario=costo,
                sobreprecio_unitario=sobreprecio
            )

            # Registrar historial de cambio (una fila por campo pisado:
            # costo, sobreprecio y precio de venta)
            from .services.historial_precios import registrar_cambios_precio
            registrar_cambios_precio(
                producto,
                {'costo': costo_db, 'sobreprecio': sobreprecio_db, 'precioventa': precioventa_db},
                usuario=getattr(request, 'user', None),
                motivo=f'Actualización desde recepción de compra en {sucursal.alias}',
                tipo_cambio='ACTUALIZACION_RECEPCION',
                ip_address=request.META.get('REMOTE_ADDR'),
                lotes_afectados=lotes_repreciados,
            )

            producto_actualizado = True
            logger.info(
                "Producto existente actualizado desde recepcion: producto_id=%s articulo=%s precio_anterior=%s precio_nuevo=%s",
                producto.id,
                articulo,
                precio_anterior,
                precioventa,
            )
        elif precios_difieren:
            # Difieren pero el usuario NO marcó "actualizar precios": se
            # conservan los de la BD (solo se agregan tallas/stock).
            logger.info(
                "Recepcion: precios difieren pero actualizar_precios=false; se conservan los de la BD. "
                "producto_id=%s articulo=%s bd=(c=%s,sp=%s,pv=%s) form=(c=%s,sp=%s,pv=%s)",
                producto.id, articulo,
                costo_db, sobreprecio_db, precioventa_db, costo, sobreprecio, precioventa,
            )
        else:
            logger.debug("Producto existente sin cambios de precio: producto_id=%s articulo=%s", producto.id, articulo)
    else:
        # 🆕 PRODUCTO NO EXISTE - Crear nuevo
        producto = Producto.objects.create(
            articulo=articulo,
            descripcion=descripcion,
            atributo1_id=atributo1,
            atributo2_id=atributo2,
            atributo3_id=atributo3,
            atributo4_id=atributo4,
            categoria_id=categoria,
            sucursal=sucursal,
            costo=costo,
            sobreprecio=sobreprecio,
            precioventa=precioventa,
            precioSugerido=precio_sugerido,
            tipo_talla=tipo_talla,
            guia_talla_id=guia_talla,
        )
        logger.info("Producto nuevo creado desde recepcion: producto_id=%s articulo=%s", producto.id, articulo)

    # ===== Propagar descripción a la MISMA variante en todas las bodegas (opt-in) =====
    if data.get('aplicar_todas_bodegas') == 'true' and descripcion:
        try:
            _emp = EmpresaUser.objects.filter(user=request.user, status=True).values_list('empresa_id', flat=True)
            _suc = list(Sucursal.objects.filter(empresa_id__in=_emp).values_list('id', flat=True))
            from .utils_producto_match import productos_por_identidad_sucursales
            _ids = [p.id for p in productos_por_identidad_sucursales(
                articulo, producto.atributo1_id, producto.atributo2_id,
                producto.atributo3_id, producto.categoria_id, _suc)]
            if producto.id not in _ids:
                _ids.append(producto.id)
            Producto.objects.filter(id__in=_ids).update(descripcion=descripcion)
            logger.info("Descripción propagada a %s bodegas (recepción) para código %s", len(_ids), articulo)
        except Exception as e:
            logger.warning("Error propagando descripción multi-bodega (recepción): %s", e)

    # =====================================================================
    # 2b. PRE-PROCESO: Redistribuir Compras_Producto_Talla consolidada
    # =====================================================================
    # Si el usuario eligió distribuir las N unidades que llegaron como una
    # única talla "00"/"__TOTAL__" en las tallas reales de la guía, creamos
    # N nuevas Compras_Producto_Talla proporcionales y clonamos las
    # Productos_Recepcionados por DTE × nueva talla manteniendo trazabilidad
    # al DTE.
    #
    # IMPORTANTE (multi-sucursal): una misma CPT consolidada puede tener
    # recepciones para MÚLTIPLES sucursales (cada sucursal se crea por
    # separado desde la tabla "Pendientes de crear"). Por lo tanto:
    #   • Sólo redistribuimos las recepciones de la sucursal objetivo.
    #   • El "total consolidado" con el que validamos la suma es la suma
    #     de stockArribado de ESAS recepciones, no cpt_consolidada.stock
    #     (que representa el total de la compra).
    #   • Si la CPT de destino (ej. talla "37") ya existe (porque otra
    #     sucursal ya redistribuyó antes), la reutilizamos y acumulamos su
    #     stock en vez de crear duplicados.
    #   • No borramos la CPT consolidada todavía: puede haber recepciones
    #     de otras sucursales pendientes. Sólo la borramos si queda vacía.
    if redistribuir_desde_consolidado and producto_compra_id:
        # Parsear distribución del formulario (stock_<talla>)
        # Nota: '00' puede ser tanto el consolidado ORIGINAL (fuente) como una
        # talla real del guía (destino). El consolidado se identifica por su
        # registro en Compras_Producto_Talla, no por el nombre de talla.
        distribucion_form = {}
        for k, v in data.items():
            if not k.startswith('stock_'):
                continue
            talla_k = k[len('stock_'):].strip()
            if talla_k in ('__TOTAL__', ''):   # solo excluir marcadores internos
                continue
            try:
                stock_k = int(v or 0)
            except (TypeError, ValueError):
                stock_k = 0
            if talla_k and stock_k > 0:
                distribucion_form[talla_k] = stock_k

        total_form = sum(distribucion_form.values())

        # Encontrar la CPT consolidada (talla == '00' o '__TOTAL__')
        cpt_consolidada = Compras_Producto_Talla.objects.filter(
            compra_producto_id=producto_compra_id,
            talla__in=['00', '__TOTAL__']
        ).first()

        if cpt_consolidada and distribucion_form and total_form > 0:
            # Recepciones de la CPT consolidada que pertenecen a ESTA sucursal.
            # El total a redistribuir es la suma de stockArribado de estas
            # (no cpt_consolidada.stock, que es el total de la compra).
            recepciones_previas = list(
                Productos_Recepcionados.objects.filter(
                    compra_producto_talla=cpt_consolidada
                ).filter(filtro_sucursal_recepciones).values(
                    'id', 'dte_id', 'stockArribado', 'sucursal_destino_id'
                )
            )
            stock_consolidado_sucursal = sum(
                int(r['stockArribado'] or 0) for r in recepciones_previas
            )

            if stock_consolidado_sucursal <= 0:
                return JsonResponse({
                    'success': False,
                    'error': (
                        f'No hay stock consolidado recepcionado para la sucursal '
                        f'{sucursal.alias}. No se puede distribuir.'
                    )
                }, status=400)

            if total_form != stock_consolidado_sucursal:
                return JsonResponse({
                    'success': False,
                    'error': (
                        f'La suma distribuida ({total_form}) debe igualar el '
                        f'stock consolidado recepcionado en {sucursal.alias} '
                        f'({stock_consolidado_sucursal}).'
                    )
                }, status=400)

            # Crear o reutilizar CPT reales por talla. Reutilizamos cuando
            # otra sucursal ya distribuyó antes en la misma talla (mismo
            # compra_producto_id), acumulando stock para mantener coherencia
            # con el total comprado.
            mapa_cpt_por_talla = {}
            for talla_nueva, stock_nueva in distribucion_form.items():
                cpt_existente = Compras_Producto_Talla.objects.filter(
                    compra_producto_id=cpt_consolidada.compra_producto_id,
                    talla=talla_nueva,
                ).exclude(pk=cpt_consolidada.pk).first()
                if cpt_existente:
                    cpt_existente.stock = int(cpt_existente.stock or 0) + stock_nueva
                    cpt_existente.pendiente_distribuir = False
                    cpt_existente.save(update_fields=['stock', 'pendiente_distribuir'])
                    mapa_cpt_por_talla[talla_nueva] = cpt_existente
                else:
                    mapa_cpt_por_talla[talla_nueva] = Compras_Producto_Talla.objects.create(
                        compra_producto_id=cpt_consolidada.compra_producto_id,
                        talla=talla_nueva,
                        stock=stock_nueva,
                        pendiente_distribuir=False,
                    )

            # Clonar Productos_Recepcionados por DTE × nueva talla. Para cada
            # DTE se reparte su stockArribado proporcional a distribucion_form
            # (mismas proporciones que la distribución global), compensando
            # residuos en la última talla para conservar suma exacta.
            from collections import defaultdict
            por_dte = defaultdict(lambda: {'total': 0, 'sucursal_id': None, 'ids': []})
            for r in recepciones_previas:
                key = r['dte_id']
                por_dte[key]['total'] += int(r['stockArribado'] or 0)
                por_dte[key]['ids'].append(r['id'])
                if r['sucursal_destino_id'] and not por_dte[key]['sucursal_id']:
                    por_dte[key]['sucursal_id'] = r['sucursal_destino_id']

            # Las recepciones clonadas mantienen como destino la sucursal de
            # la fila (si se envió) — NO la sucursal activa del usuario, ya
            # que el destino físico de la mercadería es un dato de la compra,
            # no del catálogo. Fallback: dejar NULL / el mismo valor previo.
            sucursal_dest_nuevas = sucursal_destino_fila_id

            for dte_id, info in por_dte.items():
                total_dte = info['total']
                if total_dte <= 0:
                    continue
                # Reparto proporcional con ajuste de residuos.
                tallas_orden = list(distribucion_form.keys())
                partes = []
                acumulado = 0
                for i, t_n in enumerate(tallas_orden):
                    if i < len(tallas_orden) - 1:
                        asignado = (distribucion_form[t_n] * total_dte) // stock_consolidado_sucursal
                        acumulado += asignado
                        partes.append(asignado)
                    else:
                        partes.append(total_dte - acumulado)
                for t_n, cantidad in zip(tallas_orden, partes):
                    if cantidad <= 0:
                        continue
                    Productos_Recepcionados.objects.create(
                        compra_producto_talla=mapa_cpt_por_talla[t_n],
                        dte_id=dte_id,
                        stockArribado=cantidad,
                        sucursal_destino_id=info['sucursal_id'] or sucursal_dest_nuevas,
                        producto_talla=None,
                    )

            # Borrar las recepciones de la CPT consolidada que ya fueron
            # redistribuidas (las de esta sucursal). NO borramos la CPT
            # consolidada todavía: otras sucursales podrían tener sus propias
            # recepciones pendientes contra la misma CPT.
            ids_a_borrar = [r['id'] for r in recepciones_previas]
            if ids_a_borrar:
                Productos_Recepcionados.objects.filter(id__in=ids_a_borrar).delete()

            # Reducir el stock de la CPT consolidada por lo que acabamos de
            # trasladar a las CPT reales. Si queda en 0 y sin recepciones,
            # la eliminamos para no dejar basura.
            cpt_consolidada.stock = max(
                0, int(cpt_consolidada.stock or 0) - stock_consolidado_sucursal
            )
            restantes = Productos_Recepcionados.objects.filter(
                compra_producto_talla=cpt_consolidada
            ).count()
            if restantes == 0 and int(cpt_consolidada.stock or 0) <= 0:
                cpt_consolidada.delete()
            else:
                cpt_consolidada.save(update_fields=['stock'])

            logger.info(
                "Stock consolidado redistribuido: sucursal=%s unidades=%s tallas=%s recepciones_restantes=%s",
                sucursal.alias,
                stock_consolidado_sucursal,
                len(distribucion_form),
                restantes,
            )

    # 3. Crear o reutilizar variantes (tallas)
    tallas = []
    tallas_nuevas = 0
    tallas_existentes = 0
    
    # ========== FUNCIÓN DE NORMALIZACIÓN DE TALLAS ==========
    def normalizar_talla(talla_str):
        """
        Normaliza una talla para comparación flexible.
        Convierte diferentes formatos al mismo estándar:
        - '7' → '7.0'
        - '7,0' → '7.0'
        - '7.0' → '7.0'
        - '10' → '10.0'
        - '6,5' → '6.5'
        - '00' → '00' (preservar ceros iniciales: talla única CL)
        Retorna None si no es numérica (ej: 'S', 'M', 'L')
        """
        if not talla_str:
            return None
        talla_str = str(talla_str).strip()
        # Preservar tallas con ceros iniciales significativos (ej: "00" = talla única CL)
        if re.match(r'^0\d+$', talla_str):
            return talla_str
        # Reemplazar coma por punto
        talla_str = talla_str.replace(',', '.')
        try:
            valor = float(talla_str)
            # Formatear: si es entero mostrar con .0, si tiene decimal mantenerlo
            if valor == int(valor):
                return f"{int(valor)}.0"
            else:
                return f"{valor:.1f}"
        except (ValueError, TypeError):
            # No es numérica, retornar tal cual (ej: 'S', 'M', 'L', 'XL')
            return talla_str.upper()
    
    def generar_variantes_talla(talla_str):
        """
        Genera todas las posibles variantes de formato de una talla.
        Por ejemplo: '7' genera ['7', '7.0', '7,0']
        Preserva tallas con ceros iniciales (ej: '00' = talla única CL)
        """
        original = str(talla_str).strip()
        variantes = [original]
        # Preservar tallas con ceros iniciales significativos
        if re.match(r'^0\d+$', original):
            return variantes
        talla_str = original.replace(',', '.')

        try:
            valor = float(talla_str)
            # Agregar variante entera si aplica
            if valor == int(valor):
                variantes.append(str(int(valor)))  # '7'
                variantes.append(f"{int(valor)}.0")  # '7.0'
                variantes.append(f"{int(valor)},0")  # '7,0'
            else:
                # Talla con decimal (ej: 7.5)
                variantes.append(f"{valor:.1f}")  # '7.5'
                variantes.append(f"{valor:.1f}".replace('.', ','))  # '7,5'
        except (ValueError, TypeError):
            pass

        return list(set(variantes))  # Eliminar duplicados
    
    def buscar_talla_existente(producto, talla_buscar):
        """
        Busca una talla existente considerando diferentes formatos.
        Retorna el Producto_Talla si existe, None si no.
        """
        variantes = generar_variantes_talla(talla_buscar)
        
        # Buscar con cualquiera de las variantes
        for variante in variantes:
            pt = Producto_Talla.objects.filter(producto=producto, talla=variante).first()
            if pt:
                return pt
        
        # Si no encontró exacta, buscar por normalización
        talla_normalizada = normalizar_talla(talla_buscar)
        if talla_normalizada:
            for pt in Producto_Talla.objects.filter(producto=producto):
                if normalizar_talla(pt.talla) == talla_normalizada:
                    return pt
        
        return None
    # ========== FIN FUNCIONES DE NORMALIZACIÓN ==========
    
    for key in data:
        if key.startswith('sku_'):
            talla = key.replace('sku_', '')
            sku_raw = data[key].strip() if data[key] else ''
            sku = int(sku_raw) if sku_raw else None
            stock = int(data.get(f'stock_{talla}', 0) or 0)
            
            # Verificar si la talla ya existe para este producto (con normalización)
            pt_existente = buscar_talla_existente(producto, talla)
            
            if pt_existente:
                # ✅ Talla existe - reutilizar (el movimiento sumará stock)
                pt = pt_existente
                tallas_existentes += 1
                logger.debug("Talla existente reutilizada: talla=%s talla_bd=%s sku=%s", talla, pt.talla, pt.sku)
            else:
                # 🆕 Talla nueva - crear con stock=0
                # Normalizar la talla antes de guardar para consistencia
                talla_guardar = talla
                talla_norm = normalizar_talla(talla)
                if talla_norm and talla_norm != talla:
                    # Si es numérica, guardar en formato normalizado
                    talla_guardar = talla_norm
                
                # ✅ VERIFICAR QUE EL SKU NO EXISTA - si existe o viene vacío, generar uno nuevo
                sku_final = sku
                if not sku_final or Producto_Talla.objects.filter(sku=sku_final).exists():
                    sku_anterior = sku_final
                    sku_final = obtener_siguiente_sku()
                    if sku_anterior:
                        logger.warning("SKU ya existia; se genero uno nuevo: sku_anterior=%s sku_nuevo=%s", sku_anterior, sku_final)
                    else:
                        logger.debug("SKU vacio; se genero automatico: sku=%s", sku_final)
                
                pt = Producto_Talla.objects.create(
                    producto=producto,
                    sku=sku_final,
                    stock=0,  # Iniciar en 0, el movimiento sumará el stock
                    talla=talla_guardar,
                )
                tallas_nuevas += 1
                logger.info("Talla nueva creada para producto: producto_id=%s talla=%s sku=%s", producto.id, talla_guardar, sku_final)
            
            tallas.append((pt, stock, talla))

    # 4. Registrar movimiento de ingreso y CREAR LOTES FIFO para cada variante
    # IMPORTANTE: Crear un lote por cada DTE diferente para mantener trazabilidad
    logger.debug("Tallas a procesar desde recepcion: total=%s", len(tallas))
    for pt, stock, talla in tallas:
        logger.debug("Procesando talla desde recepcion: talla=%s stock=%s producto_talla_id=%s stock_actual=%s", talla, stock, pt.id, pt.stock)
        if producto_compra_id:
            # Usa el mismo criterio por sucursal que se definió al inicio:
            # estricto si el frontend envió sucursal_destino_id, amplio (con
            # NULL) en el flujo legacy.
            filtro_sucursal_mov = filtro_sucursal_recepciones
            if es_sin_guia:
                # Consolidar TODAS las recepciones (cualquier talla) de este
                # producto_compra_id para crear lotes por DTE apuntando a la
                # única Producto_Talla "00".
                recepciones = Productos_Recepcionados.objects.filter(
                    compra_producto_talla__compra_producto_id=producto_compra_id,
                    producto_talla__isnull=True
                ).filter(filtro_sucursal_mov).values('dte_id').annotate(
                    cantidad=Sum('stockArribado')
                )
            else:
                # Generar variantes de la talla para búsqueda flexible
                variantes_talla = generar_variantes_talla(talla)
                
                # Obtener TODAS las recepciones de esta talla agrupadas por DTE
                recepciones = Productos_Recepcionados.objects.filter(
                    compra_producto_talla__compra_producto_id=producto_compra_id,
                    compra_producto_talla__talla__in=variantes_talla,
                    producto_talla__isnull=True  # Solo las no procesadas
                ).filter(filtro_sucursal_mov).values('dte_id').annotate(
                    cantidad=Sum('stockArribado')
                )
            
            # Convertir a lista para poder iterar múltiples veces
            recepciones_list = list(recepciones)
            logger.debug(
                "Recepciones encontradas para talla: talla=%s variantes=%s total=%s",
                talla,
                locals().get('variantes_talla', []),
                len(recepciones_list),
            )
            
            if recepciones_list:
                for recepcion_grupo in recepciones_list:
                    dte_id = recepcion_grupo['dte_id']
                    cantidad_dte = recepcion_grupo['cantidad']
                    logger.debug("Recepcion encontrada para movimiento inicial: dte_id=%s cantidad=%s", dte_id, cantidad_dte)
                    
                    dte = None
                    if dte_id:
                        try:
                            dte = Dte.objects.get(id=dte_id)
                        except Dte.DoesNotExist:
                            pass
                    
                    # Registrar movimiento con la cantidad específica de este DTE
                    # ✅ crear_lote_fifo=True (el movimiento crea el lote automáticamente)
                    ref_externa = f'{dte.tipo_documento} #{dte.numero_documento}' if dte else None
                    mov_ing = registrar_movimiento_producto(
                        producto_talla=pt,
                        concepto='INGRESO_INICIAL',
                        cantidad=cantidad_dte,
                        responsable=usuario,
                        dte=dte,
                        sucursal_origen=sucursal,
                        sucursal_destino=sucursal,
                        observaciones=f'Ingreso inicial - {producto.articulo} Talla {talla}' + (f' - DTE: {dte.numero_documento}' if dte else ''),
                        referencia_externa=ref_externa,
                        crear_lote_fifo=True
                    )
                    logger.debug("Movimiento inicial registrado desde recepcion: producto_talla_id=%s cantidad=%s", pt.id, cantidad_dte)
                    # Traza recepción↔kardex: vincular este movimiento a las filas
                    # de recepción de su mismo DTE/talla (aún sin producto_talla).
                    # .update() independiente: si no matchea, el campo queda NULL
                    # (= comportamiento previo) — nunca rompe la creación.
                    if mov_ing is not None and dte_id:
                        _link_filtro = dict(
                            compra_producto_talla__compra_producto_id=producto_compra_id,
                            dte_id=dte_id,
                            producto_talla__isnull=True,
                            movimiento_ingreso__isnull=True,
                        )
                        if not es_sin_guia:
                            _link_filtro['compra_producto_talla__talla__in'] = variantes_talla
                        Productos_Recepcionados.objects.filter(**_link_filtro).filter(
                            filtro_sucursal_mov
                        ).update(movimiento_ingreso=mov_ing)
            else:
                # Si no hay recepciones pendientes, crear movimiento sin DTE
                logger.warning("No hay recepciones pendientes; se usara stock del formulario: producto_talla_id=%s stock=%s", pt.id, stock)
                registrar_movimiento_producto(
                    producto_talla=pt,
                    concepto='INGRESO_INICIAL',
                    cantidad=stock,
                    responsable=usuario,
                    dte=None,
                    sucursal_origen=sucursal,
                    sucursal_destino=sucursal,
                    observaciones=f'Ingreso inicial - {producto.articulo} Talla {talla}',
                    referencia_externa='CREACION_PRODUCTO',
                    crear_lote_fifo=True
                )
        else:
            # Sin producto_compra_id, crear movimiento sin DTE
            registrar_movimiento_producto(
                producto_talla=pt,
                concepto='INGRESO_INICIAL',
                cantidad=stock,
                responsable=usuario,
                dte=None,
                sucursal_origen=sucursal,
                sucursal_destino=sucursal,
                observaciones=f'Ingreso inicial - {producto.articulo} Talla {talla}',
                referencia_externa='CREACION_MANUAL',
                crear_lote_fifo=True
            )

    # 5. Actualizar tabla de recepción de productos
    # ✅ Filtrar por sucursal: solo vinculamos las filas de ESTA sucursal,
    # no las de otras sucursales que puedan tener el mismo compra_producto_id.
    # Reutilizamos el criterio ya definido al inicio (estricto si viene
    # sucursal_destino_id en el POST; amplio + NULL en el flujo legacy).
    if producto_compra_id:
        filtro_sucursal_update = filtro_sucursal_recepciones
        if es_sin_guia and tallas:
            # Modo "Sin guía": TODAS las Productos_Recepcionados de la compra
            # (con cualquier talla original, incluso "__TOTAL__") apuntan al
            # único Producto_Talla "00" recién creado. Mantiene trazabilidad
            # compra ↔ producto aunque la talla del catálogo ya no coincida
            # con la talla que traía la recepción.
            pt_unica = tallas[0][0]
            Productos_Recepcionados.objects.filter(
                compra_producto_talla__compra_producto_id=producto_compra_id,
            ).filter(filtro_sucursal_update).update(producto_talla=pt_unica)
        else:
            for pt, stock, talla in tallas:
                Productos_Recepcionados.objects.filter(
                    compra_producto_talla__compra_producto_id=producto_compra_id,
                    compra_producto_talla__talla=talla
                ).filter(filtro_sucursal_update).update(producto_talla=pt)

    # ========== 5b. ALIMENTAR COLA DE PENDIENTES DE DESPACHO ==========
    # Para cada Producto_Talla recién enlazado cuya recepción original tenía
    # una sucursal_destino DISTINTA a la sucursal activa (donde vive el
    # catálogo central), registramos una entrada en `PendienteDespacho`.
    # Así, cuando el usuario vaya a emitir una Guía de Despacho interna
    # hacia esa sucursal, la UI le ofrece precargar todo lo pendiente de
    # un click.
    try:
        from .models import PendienteDespacho
        pt_ids = [pt.id for pt, _stock, _talla in tallas]
        if pt_ids:
            pendientes_raw = (
                Productos_Recepcionados.objects
                .filter(producto_talla_id__in=pt_ids)
                .exclude(sucursal_destino__isnull=True)
                .exclude(sucursal_destino_id=sucursal.id)
                .values(
                    'producto_talla_id',
                    'sucursal_destino_id',
                    'dte_id',
                    'compra_producto_talla__compra_producto_id',
                )
                .annotate(total=Sum('stockArribado'))
            )
            for row in pendientes_raw:
                total = int(row['total'] or 0)
                if total <= 0:
                    continue
                # Buscar pendiente activo (PENDIENTE/PARCIAL) para acumular;
                # si no existe, crear uno nuevo.
                pendiente = PendienteDespacho.objects.filter(
                    producto_talla_id=row['producto_talla_id'],
                    sucursal_origen_id=sucursal.id,
                    sucursal_destino_id=row['sucursal_destino_id'],
                    estado__in=['PENDIENTE', 'PARCIAL'],
                ).first()
                if pendiente:
                    pendiente.cantidad = (pendiente.cantidad or 0) + total
                    if not pendiente.dte_origen_id and row.get('dte_id'):
                        pendiente.dte_origen_id = row['dte_id']
                    if not pendiente.compra_producto_id and row.get('compra_producto_talla__compra_producto_id'):
                        pendiente.compra_producto_id = row['compra_producto_talla__compra_producto_id']
                    pendiente.recomputar_estado()
                    pendiente.save()
                else:
                    PendienteDespacho.objects.create(
                        producto_talla_id=row['producto_talla_id'],
                        sucursal_origen_id=sucursal.id,
                        sucursal_destino_id=row['sucursal_destino_id'],
                        cantidad=total,
                        cantidad_despachada=0,
                        dte_origen_id=row.get('dte_id'),
                        compra_producto_id=row.get('compra_producto_talla__compra_producto_id'),
                        estado='PENDIENTE',
                    )
    except Exception:
        # No bloqueamos la creación del producto por un error en la cola
        # de despacho; se loggea para revisar y se continúa.
        logger.exception("Error alimentando PendienteDespacho")

    # ========== 6. SINCRONIZAR PRECIOS Y CREAR ALERTAS EN OTRAS SUCURSALES ==========
    # Sincroniza automáticamente Y crea alertas para que las sucursales revisen el cambio
    productos_sincronizados = 0
    sucursales_afectadas = []
    notificaciones_creadas = 0
    
    try:
        from .models import HistorialCambioPrecio, CambioPrecioPendiente, NotificacionCambioPrecio, EmpresaUser
        from datetime import timedelta
        
        # Buscar el MISMO producto en las otras sucursales (identidad completa:
        # código+marca+color+género+categoría). Ver el porqué de género/categoría
        # en `qs_fichas_identidad_otras_sucursales`.
        from .utils_producto_match import (
            qs_fichas_identidad_otras_sucursales, qs_fichas_codigo_otra_identidad,
            resumen_casi_coincidencias,
        )
        productos_similares = qs_fichas_identidad_otras_sucursales(
            articulo, atributo1, atributo2, atributo3, categoria, sucursal.id,
        ).annotate(
            stock_total=Sum('producto_talla__stock')
        ).select_related('sucursal')

        logger.debug(
            "Buscando productos similares en otras sucursales: articulo=%s total=%s",
            articulo,
            productos_similares.count(),
        )

        # Fichas con el mismo código+marca+color pero otro género/categoría: NO
        # se sincronizan (serían otro producto). Se loguea para poder detectar
        # códigos reutilizados o fichas mal categorizadas.
        _casi = qs_fichas_codigo_otra_identidad(
            articulo, atributo1, atributo2, atributo3, categoria, sucursal.id,
        )
        if _casi.exists():
            logger.warning(
                "Sync precios: %s ficha(s) con codigo %s NO sincronizadas por "
                "distinta categoria/genero -> %s",
                _casi.count(), articulo, resumen_casi_coincidencias(_casi),
            )
        
        if productos_similares.exists():
            for prod_similar in productos_similares:
                precio_anterior = int(prod_similar.precioventa or 0)
                stock_sucursal = prod_similar.stock_total or 0
                
                logger.debug(
                    "Producto similar para sincronizacion: sucursal=%s stock=%s precio_actual=%s",
                    prod_similar.sucursal.alias,
                    stock_sucursal,
                    precio_anterior,
                )
                
                # Solo procesar si hay diferencia de precio
                if precio_anterior == precioventa:
                    logger.debug("Producto similar sin cambio de precio: sucursal=%s producto_id=%s", prod_similar.sucursal.alias, prod_similar.id)
                    continue
                
                # === SINCRONIZAR PRECIO ===
                prod_similar.precioventa = precioventa
                prod_similar.costo = costo
                prod_similar.sobreprecio = sobreprecio
                prod_similar.save()
                
                # Actualizar lotes activos
                LoteProducto.objects.filter(
                    producto_talla__producto=prod_similar,
                    cantidad_disponible__gt=0,
                    activo=True
                ).update(precio_venta_unitario=precioventa)
                
                # Calcular diferencia
                diferencia_sync = precioventa - precio_anterior
                porcentaje_sync = round((diferencia_sync / precio_anterior * 100), 2) if precio_anterior else 0
                
                # Registrar en historial
                HistorialCambioPrecio.objects.create(
                    producto=prod_similar,
                    precio_anterior=precio_anterior,
                    precio_nuevo=precioventa,
                    diferencia=diferencia_sync,
                    porcentaje_cambio=porcentaje_sync,
                    tipo_cambio='SINCRONIZACION',
                    motivo=f'Sincronización automática desde creación de producto en {sucursal.alias}',
                    usuario=request.user if hasattr(request, 'user') and request.user.is_authenticated else None,
                    ip_address=request.META.get('REMOTE_ADDR')
                )
                
                # === CREAR ALERTA Y NOTIFICACIONES (solo si tiene stock) ===
                try:
                    stock_actual = prod_similar.stock_total or 0
                    primera_talla = Producto_Talla.objects.filter(
                        producto=prod_similar,
                        stock__gt=0
                    ).first()
                    
                    if not primera_talla:
                        # No hay stock, precio actualizado pero sin alerta
                        logger.info("Precio actualizado sin alerta por stock cero: sucursal=%s producto_id=%s", prod_similar.sucursal.alias, prod_similar.id)
                    
                    if primera_talla:
                        # Determinar prioridad según la diferencia
                        prioridad = 'MEDIA'
                        if abs(porcentaje_sync) > 20:
                            prioridad = 'ALTA'
                        if abs(porcentaje_sync) > 50:
                            prioridad = 'URGENTE'
                        
                        # Crear cambio con estado PENDIENTE para que revisen
                        cambio = CambioPrecioPendiente.objects.create(
                            producto_talla=primera_talla,
                            sucursal=prod_similar.sucursal,
                            precio_anterior=precio_anterior,
                            precio_nuevo=precioventa,
                            diferencia=diferencia_sync,
                            porcentaje_cambio=porcentaje_sync,
                            tipo_cambio='SINCRONIZACION',
                            estado='APLICADO',  # APLICADO porque ya se sincronizó
                            motivo=f'Precio sincronizado automáticamente desde {sucursal.alias}',
                            creado_por=request.user if hasattr(request, 'user') and request.user.is_authenticated else None,
                            prioridad=prioridad,
                            fecha_vencimiento=timezone.now() + timedelta(days=7),
                            notificado=True
                        )
                        
                        # Crear notificaciones para usuarios de esa sucursal
                        usuarios_sucursal = EmpresaUser.objects.filter(
                            sucursal=prod_similar.sucursal,
                            status=True
                        ).select_related('user')
                        
                        mensaje_notif = (
                            f"💰 Precio actualizado en {articulo}: "
                            f"${precio_anterior:,} → ${precioventa:,} "
                            f"(desde {sucursal.alias})"
                        )
                        
                        for empresa_user in usuarios_sucursal:
                            NotificacionCambioPrecio.objects.create(
                                cambio_precio=cambio,
                                usuario=empresa_user.user,
                                tipo='NUEVA',
                                mensaje=mensaje_notif
                            )
                            notificaciones_creadas += 1
                        
                        logger.info(
                            "Alerta de cambio de precio creada: sucursal=%s usuarios_notificados=%s cambio_id=%s",
                            prod_similar.sucursal.alias,
                            usuarios_sucursal.count(),
                            cambio.id,
                        )
                        
                except Exception as alert_error:
                    logger.warning("Error creando alerta de cambio de precio: producto_id=%s error=%s", prod_similar.id, alert_error)
                
                productos_sincronizados += 1
                sucursales_afectadas.append(prod_similar.sucursal.alias)
                logger.info(
                    "Precio sincronizado en sucursal: sucursal=%s producto_id=%s precio_anterior=%s precio_nuevo=%s",
                    prod_similar.sucursal.alias,
                    prod_similar.id,
                    precio_anterior,
                    precioventa,
                )
        
        if productos_sincronizados > 0:
            logger.info(
                "Sincronizacion de precios completada: productos=%s sucursales=%s notificaciones=%s",
                productos_sincronizados,
                len(sucursales_afectadas),
                notificaciones_creadas,
            )
    except Exception:
        logger.exception("Error en sincronizacion de precios")

    # Construir mensaje descriptivo
    if producto_actualizado:
        mensaje = f'Producto actualizado correctamente'
        if precios_cambiaron:
            mensaje += f' (precio: ${precio_anterior:,} → ${precioventa:,})'
    else:
        mensaje = 'Producto creado correctamente'
    
    if tallas_nuevas > 0:
        mensaje += f'. {tallas_nuevas} talla(s) nueva(s) agregada(s)'
    if tallas_existentes > 0:
        mensaje += f'. {tallas_existentes} talla(s) existente(s) actualizada(s)'
    if productos_sincronizados > 0:
        mensaje += f'. Precios sincronizados en {productos_sincronizados} productos de otras sucursales ({", ".join(sucursales_afectadas)})'

    # Resumen de sucursales procesadas (para feedback en UI y fase 2).
    sucursales_procesadas = []
    if sucursales_destino_ids:
        aliases = dict(
            Sucursal.objects.filter(id__in=sucursales_destino_ids).values_list('id', 'alias')
        )
        for sid in sucursales_destino_ids:
            sucursales_procesadas.append({
                'id': sid,
                'alias': aliases.get(sid) or f'ID {sid}',
            })
    if incluir_null_destino:
        sucursales_procesadas.append({'id': None, 'alias': 'Sin sucursal'})

    return JsonResponse({
        'success': True,
        'producto_id': producto.id,
        'mensaje': mensaje,
        'producto_actualizado': producto_actualizado,
        'precios_cambiaron': precios_cambiaron,
        'tallas_nuevas': tallas_nuevas,
        'tallas_existentes': tallas_existentes,
        'productos_sincronizados': productos_sincronizados,
        'sucursales_afectadas': sucursales_afectadas,
        'sucursales_procesadas': sucursales_procesadas,
    })
import re

def obtener_tallas_post(request):
    """
    Convierte los campos 'sku_36', 'stock_36', 'guia_talla_36'… recibidos
    en una lista de dicts:
        [{'nombre': '36', 'sku': '123', 'stock': 8, 'guia_talla': '1'}, …]
    """
    tallas = {}
    for k, v in request.POST.items():
        m = re.match(r'^(sku|stock|guia_talla)_(.+)$', k)
        if not m:
            continue
        campo, talla = m.groups()
        tallas.setdefault(talla, {})[campo] = v

    return [
        {
            'nombre': t,
            'sku': datos.get('sku') or None,
            'stock': int(datos.get('stock', 0) or 0),
            'guia_talla': datos.get('guia_talla') or None
        }
        for t, datos in tallas.items()
    ]

# views.py
 
def _next_sku():
    """
    Genera el siguiente SKU disponible usando la función centralizada.
    """
    return obtener_siguiente_sku()


def _buscar_producto(request, articulo, attr1, attr2, attr3):
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return None
    qs = Producto.objects.filter(
        articulo      = articulo.strip(),
        atributo1_id  = attr1,
        sucursal_id   = sucursal_id
    )
    if attr2:
        qs = qs.filter(atributo2_id = attr2)
    if attr3:
        qs = qs.filter(atributo3_id = attr3)
    return qs.first()


def sku_para_talla(request):
    """
    GET params:
        articulo, atributo1, atributo2?, atributo3?, talla
    Return:
        { sku: 12345, existe: true|false }
    """
    art     = request.GET.get('articulo')
    attr1   = request.GET.get('atributo1')
    attr2   = request.GET.get('atributo2')
    attr3   = request.GET.get('atributo3')
    talla   = request.GET.get('talla')

    if not (art and attr1 and talla):
        return JsonResponse({'error': 'parametros'}, status=400)

    producto = _buscar_producto(request, art, attr1, attr2, attr3)

    # 1 Ya existe producto y talla
    if producto:
        pt = Producto_Talla.objects.filter(producto=producto, talla=talla).first()
        if pt:
            return JsonResponse({'sku': pt.sku, 'existe': True})

    # 2 SKU sugerido no sirve → genera nuevo
    sku = _next_sku()
    return JsonResponse({'sku': sku, 'existe': False})

@require_GET
def facturas_pendientes(request):
    """
    Devuelve facturas de compra (Dte) PENDIENTES para recepcionar productos.
    Solo muestra facturas con estados válidos para recepción (no las ya recepcionadas/anuladas).
    
    Filtros:
    - ?proveedor_id= : Filtrar por proveedor (REQUERIDO para resultados útiles)
    - ?q= : Buscar por número de factura
    - ?meses= : Limitar a últimos N meses (default: 12)
    - ?limit= : Límite de resultados (default: 100)
    """
    from datetime import date, timedelta
    
    proveedor_id = request.GET.get('proveedor_id')
    try:
        proveedor_id = int(proveedor_id) if proveedor_id else None
    except (TypeError, ValueError):
        proveedor_id = None
    
    q = request.GET.get('q', '').strip()
    
    # compra_id (opcional): si viene, ajustamos la ventana de fechas para
    # que siempre abarque la fecha real de la compra. Caso de uso: una
    # compra creada en 2025 que recién llega/se recepciona en 2026; con el
    # filtro por meses los DTE de 2025 quedaban fuera y el select del
    # modal "Agregar Producto Manual" aparecía vacío.
    compra_id = request.GET.get('compra_id')
    try:
        compra_id = int(compra_id) if compra_id else None
    except (TypeError, ValueError):
        compra_id = None
    
    # Parámetros de limitación
    try:
        meses = int(request.GET.get('meses', 1))  # Por defecto MES ACTUAL (1 mes)
    except (TypeError, ValueError):
        meses = 1
    
    try:
        limit = min(int(request.GET.get('limit', 50)), 200)  # Máximo 200, default 50
    except (TypeError, ValueError):
        limit = 50

    # ============================================================
    # FILTRO: Requiere proveedor_id para devolver resultados
    # ============================================================
    if not proveedor_id:
        return JsonResponse([], safe=False)
    
    ESTADOS_EXCLUIDOS = ['ANULADO', 'CANCELADO', 'RECHAZADO']
    fecha_corte = timezone.localdate() - timedelta(days=meses * 30)

    # Si nos pasan compra_id, extender el corte hacia atrás hasta incluir
    # la fecha de la compra (con 30 días de colchón), para soportar compras
    # cuyo DTE es más antiguo que la ventana "meses".
    if compra_id:
        try:
            from .models import Compras
            compra = Compras.objects.only('fecha').get(id=compra_id)
            if compra.fecha:
                fecha_corte = min(fecha_corte, compra.fecha - timedelta(days=30))
        except Exception:
            pass
    
    # Buscar DTEs de COMPRA de TODAS las sucursales/empresas del usuario
    facturas = Dte.objects.filter(
        tipo_transaccion='COMPRA',
        fecha_emision__gte=fecha_corte
    ).exclude(
        estado_dte__in=ESTADOS_EXCLUIDOS
    ).select_related('emisor')
    
    # Filtro por proveedor (emisor del DTE)
    try:
        from .models import Empresa
        prov = Empresa.objects.get(id=proveedor_id)
        if prov.rut:
            facturas = facturas.filter(
                Q(emisor_id=proveedor_id) | Q(emisor__rut=prov.rut)
            )
        else:
            facturas = facturas.filter(emisor_id=proveedor_id)
    except Exception:
        facturas = facturas.filter(emisor_id=proveedor_id)
    
    # Excluir descartados (soft delete)
    if hasattr(Dte, 'descartado'):
        facturas = facturas.filter(descartado=False)
    
    if q:
        facturas = facturas.filter(numero_documento__icontains=q)

    # Ordenar por fecha descendente (más recientes primero) y limitar
    facturas = facturas.order_by('-fecha_emision')[:limit]
    
    # Obtener datos de facturas
    facturas = facturas.values('id', 'numero_documento', 'monto_con_iva', 'emisor__nombre', 'fecha_emision')
    ids = [f['id'] for f in facturas]
    
    from django.db.models import Sum, F
    from .models import Productos_Recepcionados
    usados = (
        Productos_Recepcionados.objects
        .filter(dte_id__in=ids)
        .values('dte_id')
        .annotate(total=Sum(F('stockArribado') * F('compra_producto_talla__compra_producto__costo')))
    )
    usado_map = {u['dte_id']: u['total'] for u in usados}

    disponibles = []
    for f in facturas:
        usado = usado_map.get(f['id'], 0) or 0
        # Formatear fecha para mostrar
        fecha_str = f['fecha_emision'].strftime('%d/%m/%y') if f['fecha_emision'] else ''
        disponibles.append({
            'id': f['id'],
            'text': str(f['numero_documento']),
            'text_con_fecha': f"{f['numero_documento']} ({fecha_str})",
            'monto': float(f['monto_con_iva']),
            'usado': float(usado),
            'proveedor_nombre': f['emisor__nombre'] or '',
            'fecha': fecha_str
        })

    # Formato para select2 con proveedor incluido y fecha
    return JsonResponse([
        {
            'id': f['id'], 
            'text': f['text'],
            'text_con_fecha': f['text_con_fecha'],
            'proveedor_nombre': f['proveedor_nombre'],
            'fecha': f['fecha']
        }
        for f in disponibles
    ], safe=False)

@login_required
def verMovimientosProducto(request):
    """
    Renderiza la página de movimientos de producto por sucursal.
    """
    return render(request, 'vistas/modulo_existencias/gestionMovimientos.html')

@require_GET
@login_required
def obtener_movimientos_producto(request):
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)

    from datetime import datetime, timedelta
    from django.utils.dateparse import parse_date
    from django.utils import timezone
    
    def parse_fecha_ddmmyyyy(fecha_str):
        try:
            if fecha_str and '/' in fecha_str:
                return datetime.strptime(fecha_str, '%d/%m/%Y').date()
            elif fecha_str:
                return parse_date(fecha_str)
        except Exception:
            return None
        return None
    
    def limpiar_prefijo(valor):
        """Limpia prefijos de atributos como 'Marca:', 'Color:', 'Género:'"""
        if not valor:
            return ''
        for prefijo in ['Marca:', 'Color:', 'Género:']:
            if valor.startswith(prefijo):
                return valor[len(prefijo):].strip()
        return valor.strip()

    # Filtros
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    tipo = request.GET.get('tipo')  # INGRESO, EGRESO, etc.
    articulo = request.GET.get('articulo')
    sku_codigo = (
        request.GET.get('sku_codigo')
        or request.GET.get('sku')
        or request.GET.get('codigo_barra')
        or ''
    ).strip()
    responsable = request.GET.get('responsable')
    concepto = request.GET.get('concepto')
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 50)), 100)

    fecha_inicio_dt = parse_fecha_ddmmyyyy(fecha_inicio)
    fecha_fin_dt = parse_fecha_ddmmyyyy(fecha_fin)
    
    # ✅ OPTIMIZACIÓN: Fecha por defecto (últimos 30 días) si no hay filtros de fecha
    # Esto evita cargar todo el historial en la carga inicial
    hoy = timezone.localdate()
    usar_fecha_defecto = not fecha_inicio and not fecha_fin
    if usar_fecha_defecto:
        fecha_inicio_dt = hoy - timedelta(days=30)
        fecha_fin_dt = hoy

    # Mostrar solo movimientos relevantes para esta sucursal:
    # - Egresos donde esta sucursal es el origen (cosas que salieron)
    # - Ingresos donde esta sucursal es el destino (cosas que llegaron)
    # - Movimientos sin sucursal_destino que pertenecen a esta sucursal (ventas, ajustes, etc.)
    movimientos = Movimientos_Producto.objects.select_related(
        'ProductoTalla__producto__atributo1',
        'ProductoTalla__producto__atributo2', 
        'ProductoTalla__producto__atributo3',
        'dte', 
        'ticket', 
        'sucursal_origen', 
        'sucursal_destino'
    ).filter(
        Q(sucursal_origen_id=sucursal_id, tipo_movimiento='EGRESO') |
        Q(sucursal_destino_id=sucursal_id, tipo_movimiento='INGRESO') |
        Q(sucursal_origen_id=sucursal_id, sucursal_destino__isnull=True)
    )
    
    # Aplicar filtro de fecha (incluir movimientos sin fecha para no perder datos)
    if fecha_inicio_dt and fecha_fin_dt:
        movimientos = movimientos.filter(
            Q(fecha__gte=fecha_inicio_dt, fecha__lte=fecha_fin_dt) | Q(fecha__isnull=True)
        )
    elif fecha_inicio_dt:
        movimientos = movimientos.filter(Q(fecha__gte=fecha_inicio_dt) | Q(fecha__isnull=True))
    elif fecha_fin_dt:
        movimientos = movimientos.filter(Q(fecha__lte=fecha_fin_dt) | Q(fecha__isnull=True))
    
    # Aplicar otros filtros
    if tipo:
        movimientos = movimientos.filter(tipo_movimiento__iexact=tipo)
    if articulo:
        movimientos = movimientos.filter(ProductoTalla__producto__articulo__icontains=articulo)
    if sku_codigo:
        movimientos = movimientos.annotate(
            sku_text=Cast('ProductoTalla__sku', CharField())
        ).filter(sku_text__icontains=sku_codigo)
    if responsable:
        movimientos = movimientos.filter(responsable__icontains=responsable)
    if concepto:
        movimientos = movimientos.filter(concepto__icontains=concepto)

    # ✅ OPTIMIZACIÓN: Contar y paginar de forma eficiente
    # Primero ordenamos, luego contamos solo si es necesario para la paginación
    movimientos = movimientos.order_by('-fecha', '-hora')
    total_count = movimientos.count()
    offset = (page - 1) * page_size
    movimientos = movimientos[offset:offset+page_size]

    data = []
    for m in movimientos:
        prod = m.ProductoTalla.producto
        
        # ✅ MEJORA: Construir referencia priorizando referencia_externa para devoluciones
        # Las devoluciones ya guardan el numero_operacion en referencia_externa
        # `tipo_referencia` permite al frontend darle un estilo claro (badge) según el origen
        tipo_referencia = ''
        if m.referencia_externa:
            # Si existe referencia_externa, usarla (devoluciones, cambios, etc.)
            referencia = m.referencia_externa
            # Agregar contexto adicional si aplica
            if m.concepto in ('DEVOLUCION_CLIENTE', 'DEVOLUCION_PROVEEDOR') and m.ticket:
                referencia = f"{m.referencia_externa} (Ticket #{m.ticket.correlativo})"
            tipo_referencia = 'devolucion' if (m.concepto or '').find('DEVOLUCION') != -1 else 'externa'
        elif m.tipo_movimiento == 'TRASPASO' and m.sucursal_destino:
            referencia = f"Destino: {m.sucursal_destino.alias}"
            tipo_referencia = 'traspaso'
        elif m.dte:
            referencia = f"{m.dte.get_tipo_documento_display()} #{m.dte.numero_documento}"
            tipo_referencia = 'dte'
        elif m.ticket:
            referencia = f"Ticket #{m.ticket.correlativo}"
            tipo_referencia = 'ticket'
        else:
            referencia = ''

        # ✅ DTE estructurado para render claro en el frontend (evita parsear strings en JS)
        if m.dte:
            dte_info = {
                'numero': m.dte.numero_documento,
                'tipo': m.dte.tipo_documento,                     # código crudo (ej. 'FACTURA ELECTRONICA')
                'tipo_label': m.dte.get_tipo_documento_display(),  # legible (ej. 'Factura Electrónica')
            }
        else:
            dte_info = None

        # Extraer atributos del producto (ya cargados por select_related)
        marca = limpiar_prefijo(prod.atributo1.valor if prod.atributo1 else '')
        color = limpiar_prefijo(prod.atributo2.valor if prod.atributo2 else '')
        genero = limpiar_prefijo(prod.atributo3.valor if prod.atributo3 else '')
        
        data.append({
            'id': m.id,
            'fecha': m.fecha.strftime('%Y-%m-%d'),
            'hora': m.hora.strftime('%H:%M:%S') if m.hora else '',
            'articulo': prod.articulo,
            'descripcion': prod.descripcion,
            'marca': marca,
            'color': color,
            'genero': genero,
            'talla': m.ProductoTalla.talla,
            'sku': m.ProductoTalla.sku,
            'codigo_barra': m.ProductoTalla.sku,
            'cantidad': m.cantidad,
            'costo': m.costo,
            'precio': m.precio,
            'sobreprecio': m.sobreprecio,
            'tipo_movimiento': m.tipo_movimiento,
            'concepto': m.concepto,
            'responsable': m.responsable,
            'dte': dte_info,
            'referencia_externa': referencia,
            'tipo_referencia': tipo_referencia,
            'sucursal_destino': m.sucursal_destino.alias if m.sucursal_destino else '',
        })
    
    return JsonResponse({
        'success': True,
        'items': data,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size,
            'has_next': page * page_size < total_count,
            'has_previous': page > 1
        },
        # ✅ OPTIMIZACIÓN: Informar al frontend si se usaron fechas por defecto
        'filtros_aplicados': {
            'fecha_inicio': fecha_inicio_dt.strftime('%d/%m/%Y') if fecha_inicio_dt else None,
            'fecha_fin': fecha_fin_dt.strftime('%d/%m/%Y') if fecha_fin_dt else None,
            'fecha_defecto_aplicada': usar_fecha_defecto
        }
    })

@require_GET
@login_required
def obtener_productos(request):
    q = request.GET.get('q', '').strip()
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 20)), 100)
    # Allow explicit sucursal_id override; 'todas' means skip filter
    sucursal_id_param = request.GET.get('sucursal_id', '')
    if sucursal_id_param == 'todas':
        sucursal_id = None
    elif sucursal_id_param:
        sucursal_id = sucursal_id_param
    else:
        sucursal_id = request.session.get('idSucursalActual')
    # El bucle de serialización de más abajo lee prod.atributo1/2/3.valor,
    # prod.sucursal.alias y prod.categoria.nombre. Sin traerlos en el
    # select_related cada fila dispara 4 queries extra (N+1): medido en
    # producción, una página de 50 SKUs costaba 203 queries / 51,9 s.
    productos = Producto_Talla.objects.select_related(
        'producto', 'producto__categoria',
        'producto__atributo1', 'producto__atributo2', 'producto__atributo3',
        'producto__sucursal',
    )
    if sucursal_id:
        productos = productos.filter(producto__sucursal_id=sucursal_id)
    if q:
        productos = productos.filter(
            Q(producto__articulo__icontains=q) |
            Q(producto__descripcion__icontains=q) |
            Q(producto__atributo1__valor__icontains=q) |
            Q(producto__atributo2__valor__icontains=q) |
            Q(producto__atributo3__valor__icontains=q) |
            Q(sku__icontains=q)
        )
    # Filtro por categoría v1.2: un padre (Calzado/Ropa/Accesorios) incluye
    # también sus hijas; una hija filtra exacto.
    categoria_id = request.GET.get('categoria_id', '')
    if categoria_id and str(categoria_id).isdigit():
        cat_ids = [int(categoria_id)]
        cat_ids += list(Categoria.objects.filter(padre_id=categoria_id).values_list('id', flat=True))
        productos = productos.filter(producto__categoria_id__in=cat_ids)
    # Filtro por especialidad v1.2 (AtributoOpcion del atributo "Especialidad",
    # vía ProductoAtributoValor; related_name='atributos' en Producto).
    especialidad_id = request.GET.get('especialidad_id', '')
    if especialidad_id and str(especialidad_id).isdigit():
        productos = productos.filter(producto__atributos__opcion_id=especialidad_id).distinct()
    # Filtro "sin especialidad": productos que NO tienen ninguna etiqueta del
    # atributo Especialidad (para encontrarlos y completarlos en la revisión).
    if request.GET.get('sin_especialidad') == '1':
        productos = productos.exclude(
            producto__atributos__atributo__nombre__iexact='Especialidad')
    # Filtro por talla (revisión): productos que tienen esa talla.
    talla_filtro = request.GET.get('talla', '').strip()
    if talla_filtro:
        productos = productos.filter(talla__iexact=talla_filtro)
    total_count = productos.count()
    offset = (page - 1) * page_size
    # Orden del listado. Por defecto 'reciente': lo último creado arriba, que es
    # lo que se quiere justo después de cargar una recepción. 'alfabetico'
    # mantiene el orden histórico por código.
    # Desempate por 'id' en ambos: (articulo, talla) NO es única (un mismo
    # artículo/talla existe en varias bodegas), así que sin un tercer criterio
    # estable el motor puede devolver el mismo registro en dos páginas u omitirlo.
    # fecha_creacion es nullable en fichas legacy → nulls_last para que no se
    # tomen la primera página.
    orden = request.GET.get('orden', 'reciente')
    if orden == 'alfabetico':
        criterio = ('producto__articulo', 'talla', 'id')
    else:
        criterio = (F('producto__fecha_creacion').desc(nulls_last=True),
                    F('producto_id').desc(), 'talla', 'id')
    productos = list(productos.order_by(*criterio)[offset:offset+page_size])

    # Especialidades v1.2 de los productos de ESTA página en UNA sola query
    # (evita N+1). Map producto_id -> [valores de especialidad].
    esp_por_producto = {}
    _pids_pagina = {pt.producto_id for pt in productos}
    if _pids_pagina:
        from .models import ProductoAtributoValor
        for pav in ProductoAtributoValor.objects.filter(
                producto_id__in=_pids_pagina, atributo__nombre__iexact='Especialidad'
        ).select_related('opcion').values('producto_id', 'opcion__valor'):
            esp_por_producto.setdefault(pav['producto_id'], []).append(pav['opcion__valor'])

    def limpiar_prefijo(valor):
        if not valor:
            return ''
        for prefijo in ['Marca:', 'Color:', 'Género:']:
            if valor.startswith(prefijo):
                return valor[len(prefijo):].strip()
        return valor.strip()
    results = []
    for pt in productos:
        prod = pt.producto
        marca = limpiar_prefijo(prod.atributo1.valor if prod.atributo1 else '')
        color = limpiar_prefijo(prod.atributo2.valor if prod.atributo2 else '')
        genero = limpiar_prefijo(prod.atributo3.valor if prod.atributo3 else '')
        
        # Stock REAL, sin normalizar. stock_total() aplica max(0, stock) y por
        # eso los SKUs con stock negativo (registros corruptos que hay que
        # detectar y corregir) se mostraban como 0 en la pantalla de edición.
        stock = pt.stock if pt.stock is not None else 0

        text = f"{prod.articulo} - {prod.descripcion} | Marca: {marca} | Color: {color} | Género: {genero} | Talla: {pt.talla} | SKU: {pt.sku}"
        results.append({
            'id': pt.id,
            'text': text,
            'sku': pt.sku,
            'marca': marca,
            'color': color,
            'genero': genero,
            'talla': pt.talla,
            'stock': stock,
            'costo': prod.costo,
            'sobreprecio': prod.sobreprecio,
            'precioventa': prod.precioventa,
            'producto_id': prod.id,
            'sucursal_id': prod.sucursal_id,
            'sucursal_nombre': prod.sucursal.alias if prod.sucursal else '',
            'excluir_de_analitica': prod.excluir_de_analitica,
            'categoria': prod.categoria.nombre if prod.categoria else '',
            'categoria_id': prod.categoria_id,
            'especialidades': esp_por_producto.get(prod.id, []),
        })
    return JsonResponse({
        'results': results,
        'pagination': {
            # 'more' se mantiene por compatibilidad con Select2. El resto son
            # metadatos que el front necesitaba para avisar del truncado y
            # poder paginar de verdad (antes solo sabía si "había más").
            'more': offset + page_size < total_count,
            'total_count': total_count,
            'page': page,
            'page_size': page_size,
            'total_pages': (total_count + page_size - 1) // page_size if page_size else 0,
        }
    })

@require_GET
@login_required
def reporte_despachos_por_proveedor(request):
    """
    Reporte que muestra por cada proveedor y DTE:
    - Total de productos ingresados
    - Total de productos despachados (vendidos, transferidos, etc.)
    - Saldo restante
    - Resumen global de KPIs
    
    NOTA: En una COMPRA, el EMISOR es el proveedor (quien nos vende/factura)
    """
    # Filtros
    proveedor_id = request.GET.get('proveedor_id')
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    dte_numero = request.GET.get('dte_numero')
    # Por defecto se excluye la facturación interna (emisor == receptor).
    # El frontend puede pasar excluir_interna=false para incluirlas.
    excluir_interna = request.GET.get('excluir_interna', 'true').lower() != 'false'
    
    # Parámetros de paginación
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 25)), 100)
    
    # Tipos de documento válidos para compras a proveedores
    # Excluimos boletas (son de venta al público) y tickets
    TIPOS_DOCUMENTO_EXCLUIDOS = [
        'BOLETA ELECTRONICA',
        'BOLETA PAPEL',
        'TICKET',
    ]
    
    # Query base: DTEs con tipo_transaccion='COMPRA'
    # En una compra según crearDteCompras:
    #   - emisor = proveedor (quien nos vende/emite la factura)
    #   - receptor = nosotros (quien compra/recibe la factura)
    dtes_query = Dte.objects.filter(
        tipo_transaccion='COMPRA'
    ).exclude(
        tipo_documento__in=TIPOS_DOCUMENTO_EXCLUIDOS
    ).select_related('emisor', 'receptor')

    # Excluir facturación interna: DTEs donde el emisor y receptor son la misma empresa.
    # Estos son auto-facturaciones que distorsionan los KPIs de compras a proveedores.
    if excluir_interna:
        dtes_query = dtes_query.exclude(emisor_id=F('receptor_id'))

    # Aplicar filtros - Buscar por emisor (que es el proveedor en compras)
    if proveedor_id:
        dtes_query = dtes_query.filter(emisor_id=proveedor_id)
    if fecha_inicio:
        dtes_query = dtes_query.filter(fecha_emision__gte=fecha_inicio)
    if fecha_fin:
        dtes_query = dtes_query.filter(fecha_emision__lte=fecha_fin)
    if dte_numero:
        dtes_query = dtes_query.filter(numero_documento__icontains=dte_numero)
    
    # Contar total para paginación
    total_count = dtes_query.count()
    total_pages = (total_count + page_size - 1) // page_size
    
    # ========== RESUMEN GLOBAL (todos los registros filtrados) ==========
    resumen_global = {
        'total_proveedores': dtes_query.values('emisor_id').distinct().count(),
        'total_dtes': total_count,
        'dtes_pagados': dtes_query.filter(estado_pago='PAGADO').count(),
        'dtes_pendientes': dtes_query.filter(estado_pago='PENDIENTE').count(),
        'dtes_aceptados': dtes_query.filter(estado_dte='ACEPTADO').count(),
        'total_unidades_ingresadas': 0,
        'total_unidades_despachadas': 0,
        'total_monto_compras': 0,
        'monto_minimo': 0,
        'monto_maximo': 0,
    }
    
    # Calcular métricas globales de movimientos para todos los DTEs filtrados
    all_dtes_ids = list(dtes_query.values_list('id', flat=True))
    if all_dtes_ids:
        # Ingresos globales
        ingresos_globales = Movimientos_Producto.objects.filter(
            dte_id__in=all_dtes_ids,
            tipo_movimiento='INGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Egresos globales
        egresos_globales = Movimientos_Producto.objects.filter(
            dte_id__in=all_dtes_ids,
            tipo_movimiento='EGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        resumen_global['total_unidades_ingresadas'] = ingresos_globales['total_cantidad'] or 0
        resumen_global['total_unidades_despachadas'] = abs(egresos_globales['total_cantidad'] or 0)
        resumen_global['total_monto_compras'] = float(ingresos_globales['total_costo'] or 0)

        # Unidades totales comprometidas en DTEs y pendientes de ingreso
        total_en_dtes = Dte_Productos.objects.filter(dte_id__in=all_dtes_ids).aggregate(t=Sum('stock'))['t'] or 0
        resumen_global['total_unidades_en_dtes'] = total_en_dtes
        resumen_global['total_unidades_pendientes'] = max(0, total_en_dtes - resumen_global['total_unidades_ingresadas'])

        # Calcular monto mínimo y máximo
        montos_dtes = dtes_query.aggregate(
            monto_min=Min('monto_con_iva'),
            monto_max=Max('monto_con_iva'),
            monto_promedio=Avg('monto_con_iva')
        )
        resumen_global['monto_minimo'] = float(montos_dtes['monto_min'] or 0)
        resumen_global['monto_maximo'] = float(montos_dtes['monto_max'] or 0)
        resumen_global['monto_promedio'] = float(montos_dtes['monto_promedio'] or 0)
    
    # Aplicar paginación para datos de tabla
    offset = (page - 1) * page_size
    dtes = dtes_query.order_by('-fecha_emision')[offset:offset + page_size]
    
    resultado = []
    
    for dte in dtes:
        # Calcular ingresos (movimientos de INGRESO asociados a este DTE)
        ingresos = Movimientos_Producto.objects.filter(
            dte=dte,
            tipo_movimiento='INGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Calcular despachos (movimientos de EGRESO asociados a este DTE)
        despachos = Movimientos_Producto.objects.filter(
            dte=dte,
            tipo_movimiento='EGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Valores por defecto
        total_ingresado = ingresos['total_cantidad'] or 0
        total_despachado = abs(despachos['total_cantidad'] or 0)  # Valor absoluto porque egresos son negativos
        saldo_restante = total_ingresado - total_despachado

        # Unidades comprometidas en el DTE y pendientes de ingreso
        unidades_en_dte = Dte_Productos.objects.filter(dte=dte).aggregate(t=Sum('stock'))['t'] or 0
        unidades_pendientes_ingreso = max(0, unidades_en_dte - total_ingresado)

        # Calcular montos
        monto_ingresado = ingresos['total_costo'] or 0
        monto_despachado = abs(despachos['total_costo'] or 0)
        monto_restante = monto_ingresado - monto_despachado
        
        resultado.append({
            'dte_id': dte.id,
            'dte_numero': dte.numero_documento,
            'dte_tipo': dte.tipo_documento,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d'),
            'proveedor_id': dte.emisor.id if dte.emisor else None,
            'proveedor_nombre': dte.emisor.nombre if dte.emisor else 'Sin proveedor',
            'proveedor_rut': dte.emisor.rut if dte.emisor else '-',
            'unidades_en_dte': unidades_en_dte,
            'unidades_pendientes_ingreso': unidades_pendientes_ingreso,
            'total_ingresado': total_ingresado,
            'total_despachado': total_despachado,
            'saldo_restante': saldo_restante,
            'monto_ingresado': float(monto_ingresado),
            'monto_despachado': float(monto_despachado),
            'monto_restante': float(monto_restante),
            'estado_dte': dte.estado_dte,
            'estado_pago': dte.estado_pago
        })
    
    return JsonResponse({
        'success': True,
        'data': resultado,
        'resumen': resumen_global,
        'excluir_interna': excluir_interna,
        'pagination': {
            'current_page': page,
            'total_pages': total_pages,
            'total_records': total_count,
            'page_size': page_size
        }
    })

