# ========== VISTAS PARA CREACIÓN MANUAL DE PRODUCTOS ==========

@require_GET
@login_required
def obtener_proveedores(request):
    """
    Obtiene lista de proveedores para el modal de creación manual
    """
    try:
        proveedores = Empresa.objects.filter(esProveedor=True).values('id', 'nombre').order_by('nombre')
        result = list(proveedores)
        logger.debug("Proveedores obtenidos para creacion manual: total=%s", len(result))
        return JsonResponse(result, safe=False)
    except Exception as e:
        logger.exception("Error obteniendo proveedores")
        return JsonResponse({'error': str(e)}, status=500)

@require_GET
@login_required
def obtener_dtes_por_proveedor(request, proveedor_id):
    """
    Obtiene DTEs de un proveedor específico para el modal de creación manual.
    En compras, el proveedor es el EMISOR de la factura.
    """
    try:
        logger.debug("Consultando DTEs por proveedor: proveedor_id=%s", proveedor_id)
        
        # Verificar si el proveedor existe
        proveedor = Empresa.objects.filter(id=proveedor_id, esProveedor=True).first()
        if not proveedor:
            logger.warning("Proveedor no encontrado al consultar DTEs: proveedor_id=%s", proveedor_id)
            return JsonResponse({'error': 'Proveedor no encontrado'}, status=404)
        
        logger.debug("Proveedor encontrado para DTEs: proveedor_id=%s nombre=%s", proveedor_id, proveedor.nombre)
        
        # En compras, el proveedor es el EMISOR de la factura
        # Buscar DTEs de tipo COMPRA donde el proveedor sea el emisor
        dtes = Dte.objects.filter(
            Q(emisor_id=proveedor_id) | Q(emisor__rut=proveedor.rut) if proveedor.rut else Q(emisor_id=proveedor_id),
            tipo_transaccion='COMPRA'
        ).values('id', 'numero_documento', 'fecha_emision', 'estado_pago').order_by('-fecha_emision')[:50]
        
        logger.debug("DTEs de compra encontrados para proveedor: proveedor_id=%s total=%s", proveedor_id, len(dtes))
        
        # Si no hay DTEs de compra, buscar cualquier DTE del proveedor
        if len(dtes) == 0:
            logger.debug("Sin DTEs de compra; buscando DTEs alternativos del proveedor: proveedor_id=%s", proveedor_id)
            dtes = Dte.objects.filter(
                Q(emisor_id=proveedor_id) | Q(receptor_id=proveedor_id)
            ).values('id', 'numero_documento', 'fecha_emision', 'estado_pago').order_by('-fecha_emision')[:50]
            logger.debug("DTEs alternativos encontrados para proveedor: proveedor_id=%s total=%s", proveedor_id, len(dtes))
        
        # Formatear fecha para mostrar
        result = []
        for dte in dtes:
            fecha = 'Sin fecha'
            if dte['fecha_emision']:
                fecha = dte['fecha_emision'].strftime('%d/%m/%Y')
            
            result.append({
                'id': dte['id'],
                'numero_documento': dte['numero_documento'],
                'fecha': fecha,
                'estado_pago': dte['estado_pago'] or ''
            })
        
        logger.debug("DTEs por proveedor preparados: proveedor_id=%s total=%s", proveedor_id, len(result))
        return JsonResponse(result, safe=False)
    except Exception as e:
        logger.exception("Error en obtener_dtes_por_proveedor")
        return JsonResponse({'error': str(e)}, status=500)

@require_POST
@login_required
def crear_producto_manual(request):
    """
    Crea un producto manualmente con DTE y proveedor seleccionados.
    Genera registros en Compras, Compras_Producto, Compras_Producto_Talla,
    Dte_Productos y Productos_Recepcionados para que las tallas figuren
    en la compra y queden vinculadas al DTE seleccionado.
    """
    try:
        # Obtener datos del formulario
        es_manual = request.POST.get('es_manual') == 'true'
        # Solo se actualizan precios de un producto existente si el usuario lo
        # marcó explícitamente en el modal (antes se hacía silenciosamente).
        actualizar_precios = request.POST.get('actualizar_precios') == 'true'
        # Propagar la descripción a todas las bodegas del mismo código.
        aplicar_todas_bodegas = request.POST.get('aplicar_todas_bodegas') == 'true'
        # NOTA: `omitir_tallas_sin_stock` ya no se lee. Omitir las tallas nuevas
        # que vienen en 0 es ahora el comportamiento ÚNICO (ver el loop de
        # variantes más abajo), no una opción del formulario: el modal puede
        # llenar la curva completa desde la guía o el generador de rango, y solo
        # deben nacer las tallas que realmente llegaron.
        proveedor_id = request.POST.get('proveedor')
        dte_id = request.POST.get('dte_manual')
        # Canonizar SIEMPRE el código al guardarlo (mayúsculas, sin espacios
        # dobles ni acentos): mismo canon que usa el matching de identidad.
        # Antes se guardaba tal cual se tipeó y quedaban códigos en minúscula.
        from .utils_producto_match import normalizar_articulo as _normart
        articulo = _normart(request.POST.get('articulo'))
        descripcion = request.POST.get('descripcion', '')
        atributo1 = request.POST.get('atributo1')  # Marca
        atributo2 = request.POST.get('atributo2')  # Color
        atributo3 = request.POST.get('atributo3')  # Género
        categoria_id = request.POST.get('categoria')
        # Especialidades v1.2 (multi-etiqueta): lista de ids de AtributoOpcion del
        # atributo "Especialidad". Opcional — el producto puede no tener ninguna.
        especialidad_ids = [e for e in request.POST.getlist('especialidad[]') if e]
        tipo_talla = request.POST.get('tipo_talla')
        guia_talla_id = request.POST.get('guia_talla')
        costo = Decimal(request.POST.get('costo', 0))
        sobreprecio = Decimal(request.POST.get('sobreprecio', 0))
        precioventa = Decimal(request.POST.get('precioventa', 0))
        
        # Obtener tallas del formulario
        tallas = request.POST.getlist('talla[]')
        stocks = request.POST.getlist('stock[]')
        skus = request.POST.getlist('sku[]')
        guias_talla_manual = request.POST.getlist('guia_talla_manual[]')
        
        logger.debug(
            "Crear producto manual: proveedor_id=%s dte_id=%s articulo=%s tallas=%s stocks=%s skus=%s",
            proveedor_id,
            dte_id,
            articulo,
            tallas,
            stocks,
            skus,
        )
        
        # Validaciones básicas con mensajes específicos
        campos_faltantes = []
        if not proveedor_id:
            campos_faltantes.append('Proveedor')
        if not dte_id:
            campos_faltantes.append('DTE (Documento de Compra)')
        if not articulo:
            campos_faltantes.append('Artículo')
        if not atributo1:
            campos_faltantes.append('Marca')
        if not atributo2:
            campos_faltantes.append('Color')
        if not atributo3:
            campos_faltantes.append('Género')
        if not categoria_id:
            campos_faltantes.append('Categoría')
        if not tipo_talla:
            campos_faltantes.append('Tipo de Talla')
        if not costo:
            campos_faltantes.append('Costo')
        if not precioventa:
            campos_faltantes.append('Precio Venta')
        
        if campos_faltantes:
            return JsonResponse({
                'success': False, 
                'error': f'Faltan campos obligatorios: {", ".join(campos_faltantes)}'
            })
        
        if not tallas:
            return JsonResponse({'success': False, 'error': 'Debe agregar al menos una talla'})

        # Guard anti "creado sin stock": si el total de unidades enviado es 0
        # (p.ej. la auto-detección de producto existente reconstruyó la tabla de
        # tallas y dejó el Stock en 0, pisando lo tipeado), no se debe crear nada
        # ni devolver un "creado" engañoso. El movimiento de ingreso ya está
        # gateado por `if stock > 0`, así que con total 0 no entraría stock:
        # abortamos temprano con un mensaje claro para el usuario.
        # Parseo por-item: un valor sucio ('' , ' ', '1.5') no debe anular el
        # total de las demás tallas válidas. La lista limpia se reutiliza en el
        # loop de variantes (mismo criterio que el guard: sucio/faltante = 0,
        # negativos clampeados a 0 — antes un stocks[] corto INVENTABA 1 unidad
        # y un valor sucio reventaba con ValueError a mitad de la creación).
        stocks_limpios = []
        for _s in stocks:
            try:
                stocks_limpios.append(max(int(str(_s).strip() or 0), 0))
            except (TypeError, ValueError):
                stocks_limpios.append(0)
        total_unidades_stock = sum(stocks_limpios)
        if total_unidades_stock <= 0:
            return JsonResponse({
                'success': False,
                'error': 'No ingresaste unidades de stock (todas las tallas quedaron en 0). Escribe la cantidad en la columna Stock antes de crear.'
            })

        # Obtener objetos relacionados
        proveedor = get_object_or_404(Empresa, id=proveedor_id)
        dte = get_object_or_404(Dte, id=dte_id)
        categoria = get_object_or_404(Categoria, id=categoria_id)
        sucursal = get_object_or_404(Sucursal, id=request.session.get('idSucursalActual'))
        responsable = request.session.get('nombreUsuario', 'Sistema')
        
        # Obtener instancias de AtributoOpcion (no strings)
        atributo1_obj = get_object_or_404(AtributoOpcion, id=atributo1)
        atributo2_obj = get_object_or_404(AtributoOpcion, id=atributo2)
        atributo3_obj = get_object_or_404(AtributoOpcion, id=atributo3)
        
        # ========== VERIFICAR SI PRODUCTO EXISTE EN ESTA SUCURSAL ==========
        # Identidad: articulo NORMALIZADO (sin distinguir mayúsculas, espacios
        # ni acentos) + marca + color + género + categoría + sucursal. Antes se
        # comparaba el articulo como texto exacto y un tipeo distinto ("ZAP-001"
        # vs "zap-001 ") creaba un producto duplicado con SKUs nuevos.
        from .utils_producto_match import fichas_por_identidad
        fichas_identidad = fichas_por_identidad(
            articulo, atributo1_obj.id, atributo2_obj.id, atributo3_obj.id,
            categoria.id, sucursal.id,
        )
        # La ficha destino por defecto es la MÁS RECIENTE (primer elemento del
        # orden canónico). Si el modal mandó explícitamente en cuál escribir
        # (`producto_id_destino`, el mismo id que mostró el panel), se respeta
        # siempre que pertenezca a este grupo de identidad: así lo que se ve en
        # pantalla y lo que se escribe en la BD no pueden divergir.
        producto_existente = fichas_identidad[0] if fichas_identidad else None
        producto_id_destino = (request.POST.get('producto_id_destino') or '').strip()
        if producto_id_destino:
            _elegida = next((f for f in fichas_identidad
                             if str(f.id) == producto_id_destino), None)
            if _elegida is not None:
                producto_existente = _elegida
            else:
                logger.warning(
                    "producto_id_destino=%s no pertenece a la identidad %s en sucursal %s; se usa la ficha mas reciente",
                    producto_id_destino, articulo, sucursal.id,
                )

        # ========== ALERTA BLOQUEANTE POR FICHAS DUPLICADAS ==========
        # En producción hay códigos con 2+ fichas idénticas heredadas de la
        # migración Laravel. Escribir stock sin avisar partía el histórico del
        # artículo entre fichas (caso F35542 en EDEL). No se crea NADA hasta que
        # el usuario confirme en cuál ficha quiere el stock.
        if len(fichas_identidad) > 1 and request.POST.get('confirmar_duplicado') != 'true':
            _aggs_dup = {r['producto_id']: r for r in
                         Producto_Talla.objects.filter(producto_id__in=[f.id for f in fichas_identidad])
                         .values('producto_id').annotate(s=Sum('stock'), n=Count('id'))}
            detalle_fichas = []
            for _f in fichas_identidad:
                _a = _aggs_dup.get(_f.id, {})
                detalle_fichas.append({
                    'producto_id': _f.id,
                    'es_destino': _f.id == producto_existente.id,
                    'descripcion': _f.descripcion or '',
                    'n_tallas': (_a.get('n') or 0),
                    'stock_total': (_a.get('s') or 0),
                    'skus': [str(s) for s in Producto_Talla.objects.filter(producto=_f)
                             .order_by('talla').values_list('sku', flat=True)[:12]],
                    'fecha_creacion': _f.fecha_creacion.strftime('%d/%m/%Y') if _f.fecha_creacion else '—',
                })
            logger.warning(
                "Creacion manual BLOQUEADA por fichas duplicadas: articulo=%s sucursal=%s fichas=%s",
                articulo, sucursal.alias, [f.id for f in fichas_identidad],
            )
            return JsonResponse({
                'success': False,
                'requiere_confirmacion_duplicado': True,
                'articulo': articulo,
                'sucursal': sucursal.alias,
                'total_fichas': len(fichas_identidad),
                'producto_id_destino': producto_existente.id,
                'fichas_duplicadas': detalle_fichas,
                'error': (f'El código {articulo} tiene {len(fichas_identidad)} fichas duplicadas '
                          f'en {sucursal.alias}. Confirma en cuál debe entrar el stock.'),
            })

        producto_actualizado = False
        precios_cambiaron = False
        precio_anterior = 0
        costo_anterior = 0
        
        if producto_existente:
            # ✅ PRODUCTO EXISTE - Actualizar precios si cambiaron
            producto = producto_existente
            precio_anterior = float(producto.precioventa)
            costo_anterior = float(producto.costo)
            sobreprecio_anterior = float(producto.sobreprecio)
            
            # Verificar si los precios cambiaron (solo si el usuario autorizó
            # la actualización en el modal; si no, se conservan los del producto).
            if actualizar_precios and (float(producto.costo) != float(costo) or float(producto.sobreprecio) != float(sobreprecio) or float(producto.precioventa) != float(precioventa)):
                precios_cambiaron = True
                
                # Actualizar precios del producto
                producto.costo = costo
                producto.sobreprecio = sobreprecio
                producto.precioventa = precioventa
                producto.precioSugerido = precioventa
                producto.descripcion = descripcion
                producto.save()
                
                # Actualizar lotes FIFO activos con el nuevo precio
                lotes_repreciados = LoteProducto.objects.filter(
                    producto_talla__producto=producto,
                    cantidad_disponible__gt=0,
                    activo=True
                ).update(
                    precio_venta_unitario=precioventa,
                    costo_unitario=costo,
                    sobreprecio_unitario=sobreprecio
                )

                # Registrar historial de cambio (una fila por campo pisado:
                # costo, sobreprecio y precio de venta)
                from .services.historial_precios import registrar_cambios_precio
                registrar_cambios_precio(
                    producto,
                    {
                        'costo': costo_anterior,
                        'sobreprecio': sobreprecio_anterior,
                        'precioventa': precio_anterior,
                    },
                    usuario=getattr(request, 'user', None),
                    motivo=f'Actualización desde creación manual en {sucursal.alias}',
                    tipo_cambio='ACTUALIZACION_MANUAL',
                    ip_address=request.META.get('REMOTE_ADDR'),
                    lotes_afectados=lotes_repreciados,
                )

                producto_actualizado = True
                logger.info(
                    "Producto existente actualizado manualmente: producto_id=%s articulo=%s precio_anterior=%s precio_nuevo=%s",
                    producto.id,
                    articulo,
                    precio_anterior,
                    precioventa,
                )
            else:
                logger.debug("Producto manual existente sin cambios de precio: producto_id=%s articulo=%s", producto.id, articulo)
        else:
            # 🆕 PRODUCTO NO EXISTE - Crear nuevo
            producto = Producto.objects.create(
                articulo=articulo,
                descripcion=descripcion,
                atributo1=atributo1_obj,
                atributo2=atributo2_obj,
                atributo3=atributo3_obj,
                categoria=categoria,
                tipo_talla=tipo_talla,
                guia_talla_id=guia_talla_id if guia_talla_id else None,
                costo=costo,
                sobreprecio=sobreprecio,
                precioventa=precioventa,
                precioSugerido=precioventa,
                sucursal=sucursal
            )
            logger.info("Producto nuevo creado manualmente: producto_id=%s articulo=%s", producto.id, articulo)

        # ========== ESPECIALIDADES v1.2 (multi-etiqueta) ==========
        # Guarda/actualiza las especialidades como ProductoAtributoValor del
        # atributo "Especialidad". Idempotente (get_or_create) y aditivo: quita
        # las que el usuario deseleccionó y agrega las nuevas, sin tocar otros
        # atributos del producto. Silencioso si el atributo no existe todavía.
        # Solo se sincroniza si el usuario SELECCIONÓ especialidades. Con el picker
        # vacío no se toca nada: al agregar tallas a un producto EXISTENTE (flujo
        # típico post-recategorización) un borrado incondicional limpiaría las
        # especialidades que la migración v1.2 ya le asignó.
        especialidades_bodegas = 0
        try:
            if especialidad_ids:
                from .models import ProductoAtributoValor
                attr_esp = Productos_Atributos.objects.filter(nombre__iexact='Especialidad').first()
                if attr_esp is not None:
                    opciones_validas = list(AtributoOpcion.objects.filter(
                        atributo=attr_esp, id__in=especialidad_ids))
                    ids_ok = {o.id for o in opciones_validas}
                    # Destino: la ficha de esta bodega y, si el usuario marcó
                    # "aplicar a todas las bodegas", la MISMA variante en el
                    # resto. La especialidad es propiedad del producto
                    # (deporte/uso), no de la bodega: escribirla solo aquí
                    # dejaba las demás fichas sin etiquetar y por lo tanto
                    # invisibles para los filtros y dashboards por especialidad.
                    destinos = [producto]
                    if aplicar_todas_bodegas:
                        try:
                            _emp_ids = EmpresaUser.objects.filter(
                                user=request.user, status=True).values_list('empresa_id', flat=True)
                            _suc_ids = list(Sucursal.objects.filter(
                                empresa_id__in=_emp_ids).values_list('id', flat=True))
                            from .utils_producto_match import productos_por_identidad_sucursales
                            destinos = productos_por_identidad_sucursales(
                                articulo, producto.atributo1_id, producto.atributo2_id,
                                producto.atributo3_id, producto.categoria_id, _suc_ids) or [producto]
                            if producto.id not in [d.id for d in destinos]:
                                destinos.append(producto)
                        except Exception as e:
                            logger.warning("No se pudo resolver las bodegas para especialidades: %s", e)
                            destinos = [producto]
                    for _dest in destinos:
                        # Quitar las deseleccionadas y agregar las nuevas (no duplica)
                        ProductoAtributoValor.objects.filter(
                            producto=_dest, atributo=attr_esp).exclude(opcion_id__in=ids_ok).delete()
                        for opcion in opciones_validas:
                            ProductoAtributoValor.objects.get_or_create(
                                producto=_dest, atributo=attr_esp, opcion=opcion)
                    especialidades_bodegas = len(destinos)
                    if especialidades_bodegas > 1:
                        logger.info("Especialidades aplicadas a %s fichas del código %s",
                                    especialidades_bodegas, articulo)
        except Exception as e:
            logger.warning("Error guardando especialidades del producto %s: %s", producto.id, e)

        # ========== PROPAGAR DESCRIPCIÓN A TODAS LAS BODEGAS DEL CÓDIGO ==========
        bodegas_actualizadas = 0
        if aplicar_todas_bodegas and descripcion:
            try:
                emp_ids = EmpresaUser.objects.filter(user=request.user, status=True).values_list('empresa_id', flat=True)
                suc_ids = list(Sucursal.objects.filter(empresa_id__in=emp_ids).values_list('id', flat=True))
                # Solo la MISMA variante (identidad) en otras bodegas, para no
                # pisar la descripción de otras variantes (colores) del código.
                from .utils_producto_match import productos_por_identidad_sucursales
                ids_bodegas = [p.id for p in productos_por_identidad_sucursales(
                    articulo, producto.atributo1_id, producto.atributo2_id,
                    producto.atributo3_id, producto.categoria_id, suc_ids)]
                if producto.id not in ids_bodegas:
                    ids_bodegas.append(producto.id)
                bodegas_actualizadas = Producto.objects.filter(id__in=ids_bodegas).update(descripcion=descripcion)
                logger.info("Descripción propagada a %s bodegas para código %s", bodegas_actualizadas, articulo)
            except Exception as e:
                logger.warning("Error propagando descripción multi-bodega: %s", e)

        # ========== CREAR O REUTILIZAR VARIANTES (TALLAS) ==========
        tallas_creadas = {}
        tallas_nuevas = 0
        tallas_existentes_count = 0
        tallas_omitidas = []   # tallas nuevas descartadas por venir en 0

        for i, talla in enumerate(tallas):
            if not talla.strip():
                continue
                
            talla_limpia = talla.strip()
            # stocks_limpios viene del guard (parseo tolerante, negativos a 0).
            # Faltante = 0 (antes inventaba 1 unidad si stocks[] venía corto).
            stock = stocks_limpios[i] if i < len(stocks_limpios) else 0
            sku = skus[i] if i < len(skus) else ''
            guia_talla_manual_id = guias_talla_manual[i] if i < len(guias_talla_manual) else None
            
            # Si la talla ya fue procesada en este loop, sumar el stock
            if talla_limpia in tallas_creadas:
                tallas_creadas[talla_limpia]['stock'] += stock
                logger.warning("Talla duplicada en formulario manual; se suma stock: talla=%s stock=%s", talla_limpia, stock)
                continue
            
            # Verificar si la talla ya existe para este producto
            pt_existente = Producto_Talla.objects.filter(producto=producto, talla=talla_limpia).first()
            
            if pt_existente:
                # ✅ Talla existe - reutilizar
                producto_talla = pt_existente
                tallas_existentes_count += 1
                logger.debug("Talla existente reutilizada en producto manual: talla=%s sku=%s", talla_limpia, pt_existente.sku)
            else:
                if stock <= 0:
                    # ✅ REGLA: una talla NUEVA solo se crea si trae unidades.
                    # Antes esto dependía del flag `omitir_tallas_sin_stock`, que
                    # el frontend solo mandaba desde "Completar desde guía": la
                    # curva completa que arma el selector de guía (o el generador
                    # de rango) creaba SKUs vacíos para tallas que nunca llegaron,
                    # ensuciando el catálogo y las etiquetas. Las tallas que YA
                    # existen se reutilizan igual (arriba) — acá no se borra nada.
                    tallas_omitidas.append(talla_limpia)
                    logger.debug("Talla nueva omitida por stock 0: producto_id=%s talla=%s", producto.id, talla_limpia)
                    continue
                # 🆕 Talla nueva - crear con stock=0 (el movimiento sumará)
                # ✅ VERIFICAR QUE EL SKU NO EXISTA - si existe o está vacío, generar uno nuevo
                sku_final = sku
                if not sku or Producto_Talla.objects.filter(sku=sku).exists():
                    if sku and Producto_Talla.objects.filter(sku=sku).exists():
                        logger.warning("SKU manual ya existia; se generara uno nuevo: sku=%s", sku)
                    sku_final = _next_sku()
                    
                producto_talla = Producto_Talla.objects.create(
                    producto=producto,
                    talla=talla_limpia,
                    stock=0,  # ✅ Iniciar en 0, el movimiento sumará el stock
                    sku=sku_final
                )
                tallas_nuevas += 1
                logger.info("Talla nueva creada en producto manual: producto_id=%s talla=%s sku=%s", producto.id, talla_limpia, sku_final)
            
            tallas_creadas[talla_limpia] = {
                'producto_talla': producto_talla,
                'stock': stock,
                'sku': producto_talla.sku,
                'es_nueva': pt_existente is None
            }
            
        # ========== REGISTRAR MOVIMIENTOS ==========
        for talla_nombre, talla_info in tallas_creadas.items():
            producto_talla = talla_info['producto_talla']
            stock = talla_info['stock']
            
            if stock > 0:
                # Registrar movimiento de ingreso
                ref_externa = f'{dte.tipo_documento} #{dte.numero_documento}' if dte else 'MANUAL'
                registrar_movimiento_producto(
                    producto_talla=producto_talla,
                    concepto='INGRESO_MANUAL',
                    cantidad=stock,
                    responsable=responsable,
                    dte=dte,
                    sucursal_origen=sucursal,
                    sucursal_destino=sucursal,
                    observaciones=f'Ingreso manual - {producto.articulo} Talla {talla_nombre}',
                    referencia_externa=ref_externa,
                    crear_lote_fifo=True
                )
                logger.debug("Movimiento manual registrado: talla=%s stock=%s producto_talla_id=%s", talla_nombre, stock, producto_talla.id)
        
        # ========== REGISTRAR EN COMPRA Y VINCULAR AL DTE ==========
        compra_creada = None
        compra_producto_creado = None
        try:
            with transaction.atomic():
                responsable_nombre = request.user.get_full_name() or responsable
                hoy = timezone.localdate()

                compra_existente = Compras.objects.filter(
                    empresa=proveedor,
                    estado__in=['ACTIVA', 'COMPLETADA'],
                    nombre__startswith='Compra Manual -',
                    fecha=hoy,
                ).first()

                if compra_existente:
                    compra_creada = compra_existente
                    logger.debug("Compra existente reutilizada para producto manual: compra_id=%s nombre=%s", compra_creada.id, compra_creada.nombre)
                else:
                    correlativo_compra = obtener_siguiente_correlativo(sucursal, 'COMPRA')
                    nombre_compra = f"Compra Manual - {proveedor.nombre} - {hoy.strftime('%d/%m/%Y')}"
                    compra_creada = Compras.objects.create(
                        empresa=proveedor,
                        nombre=nombre_compra,
                        correlativo=correlativo_compra,
                        responsable=responsable_nombre,
                        temporada='',
                        fecha=hoy,
                        estado='COMPLETADA',
                        tipo='inicial',
                    )
                    logger.info("Compra creada para producto manual: compra_id=%s nombre=%s", compra_creada.id, nombre_compra)

                marca_nombre = atributo1_obj.valor if atributo1_obj else ''
                color_nombre = atributo2_obj.valor if atributo2_obj else ''
                genero_nombre = atributo3_obj.valor if atributo3_obj else ''

                compra_producto_creado = Compras_Producto.objects.create(
                    compras=compra_creada,
                    # Usar el código canónico del producto (no el texto tipeado):
                    # si se reutilizó un producto existente, mantiene consistente
                    # el join por nombre con Producto.articulo (proveedor, lead-time).
                    nombre=producto.articulo,
                    descripcion=descripcion,
                    atributo1=marca_nombre,
                    atributo2=color_nombre,
                    atributo3=genero_nombre,
                    atributo4='',
                    tipo_talla=tipo_talla or 'CL',
                    costo=int(costo),
                    precioSugerido=int(precioventa),
                    sucursal_destino=sucursal,
                )
                logger.info("Compra_Producto creado para producto manual: compra_producto_id=%s articulo=%s", compra_producto_creado.id, articulo)

                for talla_nombre, talla_info in tallas_creadas.items():
                    producto_talla = talla_info['producto_talla']
                    stock_talla = talla_info['stock']

                    # Sin unidades no hay nada que registrar en la compra/DTE:
                    # antes se creaban Compras_Producto_Talla y Dte_Productos
                    # con stock=0 y monto_item=0 (líneas basura en la compra y
                    # el detalle del DTE) por cada talla del form sin cantidad.
                    if stock_talla <= 0:
                        continue

                    cpt = Compras_Producto_Talla.objects.create(
                        compra_producto=compra_producto_creado,
                        stock=stock_talla,
                        talla=talla_nombre,
                        producto_talla=producto_talla,
                        unidades_recibidas=stock_talla,
                        estado_item='recibido_completo',
                    )
                    logger.debug("Compra_Producto_Talla creada para producto manual: cpt_id=%s talla=%s stock=%s", cpt.id, talla_nombre, stock_talla)

                    dte_prod = Dte_Productos.objects.create(
                        dte=dte,
                        productoTalla=producto_talla,
                        descripcion=f"{articulo} - Talla {talla_nombre}",
                        costo=int(costo),
                        sobreprecio=int(sobreprecio),
                        precio=int(precioventa),
                        precio_unitario=int(costo),
                        monto_item=int(costo) * stock_talla,
                        stock=stock_talla,
                    )
                    logger.debug("Dte_Producto creado para producto manual: dte_producto_id=%s articulo=%s talla=%s", dte_prod.id, articulo, talla_nombre)

                    if stock_talla > 0:
                        Productos_Recepcionados.objects.create(
                            compra_producto_talla=cpt,
                            dte=dte,
                            dte_producto=dte_prod,
                            producto_talla=producto_talla,
                            stockArribado=stock_talla,
                            cantidad_esperada=stock_talla,
                            estado='RECEPCIONADO_OK',
                            sucursal_destino=sucursal,
                            recepcionado_por=responsable_nombre,
                            fecha_recepcion=timezone.now(),
                        )
                        logger.debug("Recepcion registrada para producto manual: talla=%s cantidad=%s", talla_nombre, stock_talla)

        except Exception as e:
            logger.exception("Error vinculando producto manual a compra/DTE")
            compra_creada = None
        
        # ========== SINCRONIZAR PRECIOS Y CREAR ALERTAS EN OTRAS SUCURSALES ==========
        # Sincroniza automáticamente Y crea alertas para que las sucursales revisen el cambio
        productos_sincronizados = 0
        sucursales_afectadas = []
        notificaciones_creadas = 0
        
        try:
            from .models import HistorialCambioPrecio, CambioPrecioPendiente, NotificacionCambioPrecio, EmpresaUser
            from datetime import timedelta
            
            # Buscar el MISMO producto en las otras sucursales. La identidad
            # incluye género y categoría además de código+marca+color: sin ellas
            # este mismo bloque dejó unas ZAPATILLAS de NICK2 a precio de GUANTE
            # el 25-07-2026 (código reutilizado). Ver
            # `qs_fichas_identidad_otras_sucursales`.
            from .utils_producto_match import (
                qs_fichas_identidad_otras_sucursales, qs_fichas_codigo_otra_identidad,
                resumen_casi_coincidencias,
            )
            productos_similares = qs_fichas_identidad_otras_sucursales(
                articulo, atributo1_obj.id, atributo2_obj.id,
                atributo3_obj.id if atributo3_obj else None,
                categoria.id if categoria else None,
                sucursal.id,
            ).annotate(
                stock_total=Sum('producto_talla__stock')
            ).select_related('sucursal')

            logger.debug(
                "Buscando productos similares para sincronizacion manual: articulo=%s total=%s",
                articulo,
                productos_similares.count(),
            )

            # Mismo código+marca+color pero otro género/categoría → otro producto:
            # no se sincroniza y se avisa (código reutilizado o mala categorización).
            _casi = qs_fichas_codigo_otra_identidad(
                articulo, atributo1_obj.id, atributo2_obj.id,
                atributo3_obj.id if atributo3_obj else None,
                categoria.id if categoria else None,
                sucursal.id,
            )
            if _casi.exists():
                logger.warning(
                    "Sync precios (manual): %s ficha(s) con codigo %s NO sincronizadas "
                    "por distinta categoria/genero -> %s",
                    _casi.count(), articulo, resumen_casi_coincidencias(_casi),
                )
            
            if productos_similares.exists():
                for prod_similar in productos_similares:
                    precio_anterior = int(prod_similar.precioventa or 0)
                    stock_sucursal = prod_similar.stock_total or 0
                    
                    logger.debug(
                        "Producto similar manual: sucursal=%s stock=%s precio_actual=%s",
                        prod_similar.sucursal.alias,
                        stock_sucursal,
                        precio_anterior,
                    )
                    
                    # Solo procesar si ALGÚN precio difiere. Antes se comparaba
                    # SOLO la venta: un cambio de costo o sobreprecio con venta
                    # igual quedaba sin sincronizar para siempre.
                    if (precio_anterior == int(precioventa)
                            and int(prod_similar.costo or 0) == int(costo)
                            and int(prod_similar.sobreprecio or 0) == int(sobreprecio)):
                        logger.debug("Producto similar manual sin cambio de precio: sucursal=%s producto_id=%s", prod_similar.sucursal.alias, prod_similar.id)
                        continue

                    # === SINCRONIZAR PRECIO (venta + costo + sobreprecio + sugerido) ===
                    prod_similar.precioventa = precioventa
                    prod_similar.costo = costo
                    prod_similar.sobreprecio = sobreprecio
                    prod_similar.precioSugerido = precioventa
                    prod_similar.save()

                    # Actualizar lotes activos (los 3 valores, igual que en la
                    # ficha local — antes solo se tocaba el precio de venta)
                    LoteProducto.objects.filter(
                        producto_talla__producto=prod_similar,
                        cantidad_disponible__gt=0,
                        activo=True
                    ).update(
                        precio_venta_unitario=int(precioventa),
                        costo_unitario=int(costo),
                        sobreprecio_unitario=int(sobreprecio)
                    )
                    
                    # Calcular diferencia
                    diferencia_sync = int(precioventa) - precio_anterior
                    porcentaje_sync = round((diferencia_sync / precio_anterior * 100), 2) if precio_anterior else 0
                    
                    # Registrar en historial
                    HistorialCambioPrecio.objects.create(
                        producto=prod_similar,
                        precio_anterior=precio_anterior,
                        precio_nuevo=int(precioventa),
                        diferencia=diferencia_sync,
                        porcentaje_cambio=porcentaje_sync,
                        tipo_cambio='SINCRONIZACION',
                        motivo=f'Sincronización automática desde creación de producto en {sucursal.alias}',
                        usuario=request.user if hasattr(request, 'user') and request.user.is_authenticated else None,
                        ip_address=request.META.get('REMOTE_ADDR')
                    )
                    
                    # === CREAR ALERTA Y NOTIFICACIONES (solo si tiene stock) ===
                    try:
                        primera_talla = Producto_Talla.objects.filter(
                            producto=prod_similar,
                            stock__gt=0
                        ).first()
                        
                        if not primera_talla:
                            # No hay stock, precio actualizado pero sin alerta
                            logger.info("Precio manual actualizado sin alerta por stock cero: sucursal=%s producto_id=%s", prod_similar.sucursal.alias, prod_similar.id)
                        
                        if primera_talla:
                            # Determinar prioridad según la diferencia
                            prioridad = 'MEDIA'
                            if abs(porcentaje_sync) > 20:
                                prioridad = 'ALTA'
                            if abs(porcentaje_sync) > 50:
                                prioridad = 'URGENTE'
                            
                            # Crear cambio con estado PENDIENTE para que revisen
                            cambio = CambioPrecioPendiente.objects.create(
                                producto_talla=primera_talla,
                                sucursal=prod_similar.sucursal,
                                precio_anterior=precio_anterior,
                                precio_nuevo=int(precioventa),
                                diferencia=diferencia_sync,
                                porcentaje_cambio=porcentaje_sync,
                                tipo_cambio='SINCRONIZACION',
                                estado='APLICADO',  # APLICADO porque ya se sincronizó
                                motivo=f'Precio sincronizado automáticamente desde {sucursal.alias}',
                                creado_por=request.user if hasattr(request, 'user') and request.user.is_authenticated else None,
                                prioridad=prioridad,
                                fecha_vencimiento=timezone.now() + timedelta(days=7),
                                notificado=True
                            )
                            
                            # Crear notificaciones para usuarios de esa sucursal
                            usuarios_sucursal = EmpresaUser.objects.filter(
                                sucursal=prod_similar.sucursal,
                                status=True
                            ).select_related('user')
                            
                            mensaje_notif = (
                                f"💰 Precio actualizado en {articulo}: "
                                f"${precio_anterior:,} → ${int(precioventa):,} "
                                f"(desde {sucursal.alias})"
                            )
                            
                            for empresa_user in usuarios_sucursal:
                                NotificacionCambioPrecio.objects.create(
                                    cambio_precio=cambio,
                                    usuario=empresa_user.user,
                                    tipo='NUEVA',
                                    mensaje=mensaje_notif
                                )
                                notificaciones_creadas += 1
                            
                            logger.info(
                                "Alerta manual de cambio de precio creada: sucursal=%s usuarios_notificados=%s cambio_id=%s",
                                prod_similar.sucursal.alias,
                                usuarios_sucursal.count(),
                                cambio.id,
                            )
                            
                    except Exception as alert_error:
                        logger.warning("Error creando alerta manual de cambio de precio: producto_id=%s error=%s", prod_similar.id, alert_error)
                    
                    productos_sincronizados += 1
                    if prod_similar.sucursal.alias not in sucursales_afectadas:
                        sucursales_afectadas.append(prod_similar.sucursal.alias)
                
                if productos_sincronizados > 0:
                    logger.info(
                        "Sincronizacion manual de precios completada: productos=%s sucursales=%s notificaciones=%s",
                        productos_sincronizados,
                        len(sucursales_afectadas),
                        notificaciones_creadas,
                    )
        except Exception:
            logger.exception("Error en sincronizacion manual de precios")
        
        # Detalle verificable por talla: registrar_movimiento_producto mutó y
        # guardó las MISMAS instancias referenciadas en tallas_creadas, así que
        # el stock final ya está en memoria (sin queries extra). Permite al
        # frontend confirmar "talla 00: +3 → stock 5" en vez de un genérico.
        tallas_detalle = [
            {
                'talla': _nombre,
                'sku': _info['sku'],
                'stock_ingresado': _info['stock'],
                'stock_final': _info['producto_talla'].stock,
                'es_nueva': _info['es_nueva'],
            }
            for _nombre, _info in tallas_creadas.items()
        ]
        # Contar como "actualizadas" solo las tallas existentes que RECIBIERON
        # unidades (antes se contaban también las enviadas con stock 0).
        tallas_existentes_con_stock = sum(
            1 for _info in tallas_creadas.values()
            if not _info['es_nueva'] and _info['stock'] > 0
        )

        # Construir mensaje descriptivo
        if producto_actualizado:
            mensaje = f'Producto actualizado correctamente'
            if precios_cambiaron:
                mensaje += f' (precio: ${int(precio_anterior):,} → ${int(precioventa):,})'
        else:
            mensaje = 'Producto creado correctamente'

        if tallas_nuevas > 0:
            mensaje += f'. {tallas_nuevas} talla(s) nueva(s) agregada(s)'
        if tallas_existentes_con_stock > 0:
            mensaje += f'. {tallas_existentes_con_stock} talla(s) existente(s) actualizada(s)'
        if tallas_omitidas:
            mensaje += (f'. {len(tallas_omitidas)} talla(s) sin unidades NO se crearon '
                        f'({", ".join(tallas_omitidas[:12])}'
                        f'{"…" if len(tallas_omitidas) > 12 else ""})')
        if especialidades_bodegas > 1:
            mensaje += f'. Especialidades aplicadas en {especialidades_bodegas} bodega(s)'
        if productos_sincronizados > 0:
            mensaje += f'. Precios sincronizados y alertas enviadas a {len(sucursales_afectadas)} sucursal(es)'
        if compra_creada:
            mensaje += f'. Registrado en compra #{compra_creada.correlativo}'

        return JsonResponse({
            'success': True,
            'producto_id': producto.id,
            'mensaje': mensaje,
            'producto_actualizado': producto_actualizado,
            'precios_cambiaron': precios_cambiaron,
            'tallas_nuevas': tallas_nuevas,
            'tallas_existentes': tallas_existentes_count,
            'tallas_detalle': tallas_detalle,
            'tallas_omitidas': tallas_omitidas,
            'especialidades_bodegas': especialidades_bodegas,
            'productos_sincronizados': productos_sincronizados,
            'sucursales_afectadas': sucursales_afectadas,
            'compra_id': compra_creada.id if compra_creada else None,
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)

@require_POST
@login_required
def actualizar_producto_existente(request):
    """
    Actualiza un producto existente con nuevos precios y/o agrega nuevas tallas
    """
    try:
        data = json.loads(request.body) if request.content_type == 'application/json' else request.POST
        
        producto_id = data.get('producto_id')
        actualizar_precios = data.get('actualizar_precios', False)
        agregar_tallas = data.get('agregar_tallas', False)
        
        # Obtener producto existente
        producto = get_object_or_404(Producto, id=producto_id)
        responsable = request.session.get('nombreUsuario', 'Sistema')
        
        cambios_realizados = []
        tallas_agregadas = []
        
        # Actualizar precios si se solicita
        if actualizar_precios:
            nuevo_costo = Decimal(data.get('costo', producto.costo))
            nuevo_sobreprecio = Decimal(data.get('sobreprecio', producto.sobreprecio))
            nuevo_precioventa = Decimal(data.get('precioventa', producto.precioventa))
            
            precio_cambiado = False
            
            # Guardar valores anteriores para mostrar cambios correctamente
            costo_anterior = producto.costo
            sobreprecio_anterior = producto.sobreprecio
            precioventa_anterior = producto.precioventa
            
            if producto.costo != nuevo_costo:
                producto.costo = nuevo_costo
                precio_cambiado = True
                cambios_realizados.append(f'Costo: ${costo_anterior:,.0f} → ${nuevo_costo:,.0f}')
            
            if producto.sobreprecio != nuevo_sobreprecio:
                producto.sobreprecio = nuevo_sobreprecio
                precio_cambiado = True
                cambios_realizados.append(f'Sobreprecio: ${sobreprecio_anterior:,.0f} → ${nuevo_sobreprecio:,.0f}')
            
            if producto.precioventa != nuevo_precioventa:
                producto.precioventa = nuevo_precioventa
                producto.precioSugerido = nuevo_precioventa
                precio_cambiado = True
                cambios_realizados.append(f'Precio Venta: ${precioventa_anterior:,.0f} → ${nuevo_precioventa:,.0f}')
            
            if precio_cambiado:
                producto.save()

                # Registrar historial de cambio (una fila por campo pisado):
                # sin esto el precio original se pierde — el Producto solo
                # guarda el valor vigente.
                from .services.historial_precios import registrar_cambios_precio
                registrar_cambios_precio(
                    producto,
                    {
                        'costo': costo_anterior,
                        'sobreprecio': sobreprecio_anterior,
                        'precioventa': precioventa_anterior,
                    },
                    usuario=getattr(request, 'user', None),
                    motivo='Actualización desde modal de producto existente',
                    tipo_cambio='ACTUALIZACION_MANUAL',
                    ip_address=request.META.get('REMOTE_ADDR'),
                )

                logger.info(
                    "Producto actualizado desde modal existente: producto_id=%s costo=%s sobreprecio=%s precioventa=%s",
                    producto.id,
                    producto.costo,
                    producto.sobreprecio,
                    producto.precioventa,
                )
            else:
                logger.debug("No hubo cambios de precios para producto existente: producto_id=%s", producto.id)
        
        # Agregar nuevas tallas si se solicita
        if agregar_tallas:
            tallas_nuevas = data.get('tallas', [])
            dte_id = data.get('dte_id')
            dte = get_object_or_404(Dte, id=dte_id) if dte_id else None
            
            # ✅ ELIMINAR DUPLICADOS: Agrupar tallas por nombre y sumar stocks
            tallas_agrupadas = {}
            for talla_data in tallas_nuevas:
                talla_nombre = talla_data.get('talla', '').strip()
                if not talla_nombre:
                    continue
                    
                if talla_nombre in tallas_agrupadas:
                    # Talla duplicada: sumar stock
                    tallas_agrupadas[talla_nombre]['stock'] += int(talla_data.get('stock', 0))
                    logger.warning("Talla duplicada detectada al actualizar producto: talla=%s", talla_nombre)
                else:
                    # Primera vez que aparece esta talla
                    tallas_agrupadas[talla_nombre] = {
                        'talla': talla_nombre,
                        'stock': int(talla_data.get('stock', 0)),
                        'sku': talla_data.get('sku', '')
                    }
            
            logger.debug("Tallas recibidas para actualizar producto: recibidas=%s unicas=%s", len(tallas_nuevas), len(tallas_agrupadas))
            
            # Obtener tallas existentes
            tallas_existentes = set(
                Producto_Talla.objects.filter(producto=producto).values_list('talla', flat=True)
            )
            
            for talla_nombre, talla_data in tallas_agrupadas.items():
                talla = talla_data['talla']
                
                # Verificar si la talla ya existe
                if talla in tallas_existentes:
                    # Actualizar stock de talla existente (sumar al existente)
                    producto_talla = Producto_Talla.objects.filter(
                        producto=producto, 
                        talla=talla
                    ).first()
                    
                    if producto_talla:
                        stock_adicional = talla_data['stock']
                        if stock_adicional > 0:
                            # Sumar stock adicional al existente
                            producto_talla.stock += stock_adicional
                            producto_talla.save()
                            
                            # Registrar movimiento de ingreso
                            registrar_movimiento_producto(
                                producto_talla=producto_talla,
                                concepto='INGRESO_MANUAL',
                                cantidad=stock_adicional,
                                responsable=responsable,
                                dte=dte,
                                observaciones=f'Actualización manual - DTE: {dte.numero_documento if dte else "N/A"}',
                                referencia_externa=f'Manual-{dte.numero_documento if dte else "N/A"}'
                            )
                            stock_final = producto_talla.stock
                            logger.info(
                                "Talla existente actualizada: producto_talla_id=%s talla=%s stock_adicional=%s stock_final=%s",
                                producto_talla.id,
                                talla,
                                stock_adicional,
                                stock_final,
                            )
                            cambios_realizados.append(f'Talla {talla}: Stock actualizado (+{stock_adicional}, total: {stock_final})')
                else:
                    # Crear nueva talla
                    stock = talla_data['stock']
                    sku = talla_data.get('sku', '')
                    
                    # Generar SKU si no se proporcionó
                    if not sku:
                        sku = _next_sku()
                    
                    # Verificar que el SKU no esté en uso
                    while Producto_Talla.objects.filter(sku=sku).exists():
                        sku = _next_sku()
                    
                    producto_talla = Producto_Talla.objects.create(
                        producto=producto,
                        talla=talla,
                        stock=stock,
                        sku=sku
                    )
                    
                    # Registrar movimiento de ingreso
                    if dte:
                        registrar_movimiento_producto(
                            producto_talla=producto_talla,
                            concepto='INGRESO_MANUAL',
                            cantidad=stock,
                            responsable=responsable,
                            dte=dte,
                            observaciones=f'Creación manual - DTE: {dte.numero_documento}',
                            referencia_externa=f'Manual-{dte.numero_documento}'
                        )
                    
                    tallas_agregadas.append(talla)
                    cambios_realizados.append(f'Talla {talla}: Agregada (Stock: {stock}, SKU: {sku})')
        
        return JsonResponse({
            'success': True,
            'producto_id': producto.id,
            'mensaje': 'Producto actualizado correctamente',
            'cambios': cambios_realizados,
            'tallas_agregadas': tallas_agregadas
        })
        
    except Exception as e:
        import traceback
        return JsonResponse({
            'success': False, 
            'error': str(e),
            'traceback': traceback.format_exc()
        }, status=500)

# ========== VISTAS PARA BUSCADOR DE PRODUCTOS EXISTENTES ==========

@require_GET
@login_required
def buscar_productos_existentes(request):
    """
    Busca productos existentes por término de búsqueda
    """
    try:
        termino = request.GET.get('q', '').strip()
        logger.debug("Buscando productos existentes: termino=%s", termino)
        
        if not termino:
            logger.debug("Busqueda de productos existentes sin termino")
            return JsonResponse({'success': False, 'error': 'Término de búsqueda requerido'}, status=400)
        
        # Buscar productos que coincidan con el término
        productos = Producto.objects.filter(
            Q(articulo__icontains=termino) |
            Q(descripcion__icontains=termino)
        ).select_related(
            'categoria',
            'atributo1',
            'atributo2',
            'atributo3'
        ).prefetch_related('producto_talla')[:20]

        logger.debug("Productos encontrados en busqueda existente: total=%s", productos.count())

        resultados = []
        for producto in productos:
            tallas_qs = list(producto.producto_talla.values('talla', 'sku', 'stock'))
            try:
                tallas_ordenadas = sorted(tallas_qs, key=lambda x: float(str(x['talla']).replace(',', '.') or 0))
            except (ValueError, TypeError):
                tallas_ordenadas = tallas_qs
            resultado = {
                'id': producto.id,
                'articulo': producto.articulo,
                'descripcion': producto.descripcion,
                'categoria': producto.categoria.nombre if producto.categoria else '',
                'marca': producto.atributo1.valor if producto.atributo1 else '',
                'color': producto.atributo2.valor if producto.atributo2 else '',
                'genero': producto.atributo3.valor if producto.atributo3 else '',
                'costo': float(producto.costo),
                'sobreprecio': float(producto.sobreprecio),
                'precioventa': float(producto.precioventa),
                'tallas': tallas_ordenadas,
            }
            resultados.append(resultado)
            logger.debug("Producto procesado para busqueda existente: producto_id=%s articulo=%s", producto.id, resultado['articulo'])
        
        response_data = {
            'success': True,
            'productos': resultados
        }
        
        logger.debug("Busqueda de productos existentes preparada: total=%s", len(resultados))
        return JsonResponse(response_data)
        
    except Exception as e:
        logger.exception("Error en busqueda de productos existentes")
        return JsonResponse({'success': False, 'error': str(e)}, status=500)

