# ========== VISTAS AJAX PARA DASHBOARD FIFO ==========
@require_GET
@login_required
def obtener_datos_dashboard_fifo(request):
    """
    API para obtener datos del dashboard FIFO con filtros
    Incluye filtros de tiempo para análisis realista
    """
    try:
        sucursal_id = request.session.get('idSucursalActual')
        if not sucursal_id:
            return JsonResponse({'success': False, 'error': 'No hay sucursal activa'})
        
        # Parámetros de filtrado básicos
        filtro_producto = request.GET.get('filtro_producto', '').lower()
        filtro_talla = request.GET.get('filtro_talla', '').lower()
        filtro_diferencia = request.GET.get('filtro_diferencia', '')
        filtro_stock = request.GET.get('filtro_stock', '')
        ordenar_por = request.GET.get('ordenar_por', 'diferencia')
        mostrar_solo_diferencias = request.GET.get('mostrar_solo_diferencias', 'false') == 'true'
        
        # ========== NUEVOS FILTROS DE TIEMPO ==========
        periodo = request.GET.get('periodo', 'todo')  # hoy, semana, mes, trimestre, semestre, anio, todo
        fecha_desde = request.GET.get('fecha_desde', '')
        fecha_hasta = request.GET.get('fecha_hasta', '')
        filtro_antiguedad = request.GET.get('filtro_antiguedad', '')  # fresco, normal, antiguo, critico
        
        # Calcular fechas según período seleccionado
        from datetime import datetime, timedelta
        from django.utils import timezone
        
        hoy = timezone.now()
        fecha_inicio = None
        fecha_fin = hoy
        
        # Si hay rango personalizado, usarlo
        if fecha_desde:
            try:
                fecha_inicio = timezone.make_aware(datetime.strptime(fecha_desde, '%Y-%m-%d'))
            except ValueError:
                pass
        
        if fecha_hasta:
            try:
                fecha_fin = timezone.make_aware(datetime.strptime(fecha_hasta, '%Y-%m-%d').replace(hour=23, minute=59, second=59))
            except ValueError:
                pass
        
        # Si no hay rango personalizado, usar período predefinido
        if not fecha_desde and periodo != 'todo':
            if periodo == 'hoy':
                fecha_inicio = hoy.replace(hour=0, minute=0, second=0, microsecond=0)
            elif periodo == 'semana':
                fecha_inicio = hoy - timedelta(days=7)
            elif periodo == 'mes':
                fecha_inicio = hoy - timedelta(days=30)
            elif periodo == 'trimestre':
                fecha_inicio = hoy - timedelta(days=90)
            elif periodo == 'semestre':
                fecha_inicio = hoy - timedelta(days=180)
            elif periodo == 'anio':
                fecha_inicio = hoy - timedelta(days=365)
        
        # Filtro base de lotes (mismo criterio que los helpers FIFO)
        filtro_lotes = Q(lotes__activo=True, lotes__agotado=False,
                         lotes__cantidad_disponible__gt=0)

        # Aplicar filtro de fechas a los lotes
        if fecha_inicio:
            filtro_lotes &= Q(lotes__fecha_ingreso__gte=fecha_inicio)
        if fecha_fin:
            filtro_lotes &= Q(lotes__fecha_ingreso__lte=fecha_fin)

        # Obtener productos con lotes según filtros de tiempo.
        # Todo el detalle FIFO sale de UNA query anotada — antes eran 4+ queries
        # por SKU-talla (valor, costo promedio, lote más antiguo, count) y el
        # endpoint tardaba minutos contra producción.
        # OJO: se filtra por la anotación (HAVING), no por .filter(filtro_lotes),
        # para no duplicar el join reverso y contaminar los Sum.
        productos_con_lotes = (Producto_Talla.objects
            .filter(producto__sucursal_id=sucursal_id)
            .exclude(producto__excluir_de_analitica=True)
            .select_related('producto')
            .annotate(
                valor_fifo_agg=Sum(F('lotes__cantidad_disponible') * F('lotes__costo_unitario'),
                                   filter=filtro_lotes),
                disp_total_agg=Sum('lotes__cantidad_disponible', filter=filtro_lotes),
                fecha_lote_min=Min('lotes__fecha_ingreso', filter=filtro_lotes),
                n_lotes_agg=Count('lotes', filter=filtro_lotes, distinct=True),
            )
            .filter(n_lotes_agg__gt=0))
        
        # Aplicar filtros de producto y talla
        if filtro_producto:
            productos_con_lotes = productos_con_lotes.filter(
                producto__articulo__icontains=filtro_producto
            )
        
        if filtro_talla:
            productos_con_lotes = productos_con_lotes.filter(
                talla__icontains=filtro_talla
            )
        
        # Obtener datos detallados
        productos_data = []
        valor_total_inventario = 0
        productos_con_diferencia = 0
        diferencia_total = 0
        
        # Contadores para análisis
        diferencias_positivas = 0
        diferencias_negativas = 0
        sin_diferencias = 0
        stock_bajo = 0
        stock_medio = 0
        stock_alto = 0
        sin_stock = 0
        
        # Contadores para métricas de tiempo
        # Umbrales calibrados al negocio real (cobertura media ~641 días):
        # <90 fresco / 90-180 normal / 180-365 antiguo / >365 crítico
        total_antiguedad_dias = 0
        total_lotes_analizados = 0
        lotes_frescos = 0      # < 90 días
        lotes_normales = 0     # 90-180 días
        lotes_antiguos = 0     # 180-365 días
        lotes_criticos = 0     # > 365 días
        
        for producto_talla in productos_con_lotes:
            # Leído de las anotaciones — cero queries extra por fila
            disp_total = int(producto_talla.disp_total_agg or 0)
            valor_inventario = int(producto_talla.valor_fifo_agg or 0)
            costo_promedio = (valor_inventario / disp_total) if disp_total else 0
            valor_sistema = producto_talla.stock * producto_talla.producto.costo
            diferencia = valor_inventario - valor_sistema

            # Calcular porcentaje de diferencia
            porcentaje_diferencia = 0
            if valor_sistema > 0:
                porcentaje_diferencia = (diferencia / valor_sistema) * 100

            # ========== ANTIGÜEDAD DEL LOTE MÁS ANTIGUO (anotado) ==========
            antiguedad_dias = 0
            fecha_lote_antiguo = None

            if producto_talla.fecha_lote_min:
                antiguedad_dias = (hoy - producto_talla.fecha_lote_min).days
                fecha_lote_antiguo = producto_talla.fecha_lote_min.strftime('%Y-%m-%d')
                total_antiguedad_dias += antiguedad_dias
                total_lotes_analizados += 1
                
                # Clasificar por antigüedad (umbrales de negocio: 90/180/365)
                if antiguedad_dias < 90:
                    lotes_frescos += 1
                elif antiguedad_dias < 180:
                    lotes_normales += 1
                elif antiguedad_dias < 365:
                    lotes_antiguos += 1
                else:
                    lotes_criticos += 1

            # ========== APLICAR FILTRO DE ANTIGÜEDAD ==========
            if filtro_antiguedad:
                if filtro_antiguedad == 'fresco' and antiguedad_dias >= 90:
                    continue
                elif filtro_antiguedad == 'normal' and (antiguedad_dias < 90 or antiguedad_dias >= 180):
                    continue
                elif filtro_antiguedad == 'antiguo' and (antiguedad_dias < 180 or antiguedad_dias >= 365):
                    continue
                elif filtro_antiguedad == 'critico' and antiguedad_dias < 365:
                    continue
            
            # Aplicar filtros adicionales
            if filtro_diferencia:
                if filtro_diferencia == 'positiva' and diferencia <= 0:
                    continue
                elif filtro_diferencia == 'negativa' and diferencia >= 0:
                    continue
                elif filtro_diferencia == 'cero' and diferencia != 0:
                    continue
                elif filtro_diferencia == 'alta' and porcentaje_diferencia <= 10:
                    continue
                elif filtro_diferencia == 'baja' and porcentaje_diferencia >= 5:
                    continue
            
            if filtro_stock:
                if filtro_stock == 'bajo' and producto_talla.stock >= 10:
                    continue
                elif filtro_stock == 'medio' and (producto_talla.stock < 10 or producto_talla.stock > 50):
                    continue
                elif filtro_stock == 'alto' and producto_talla.stock <= 50:
                    continue
                elif filtro_stock == 'agotado' and producto_talla.stock > 0:
                    continue
            
            if mostrar_solo_diferencias and diferencia == 0:
                continue
            
            # Contar diferencias
            if diferencia > 0:
                diferencias_positivas += 1
            elif diferencia < 0:
                diferencias_negativas += 1
            else:
                sin_diferencias += 1
            
            # Contar stock
            if producto_talla.stock == 0:
                sin_stock += 1
            elif producto_talla.stock < 10:
                stock_bajo += 1
            elif producto_talla.stock <= 50:
                stock_medio += 1
            else:
                stock_alto += 1
            
            valor_total_inventario += valor_inventario
            diferencia_total += diferencia
            
            if diferencia != 0:
                productos_con_diferencia += 1
            
            productos_data.append({
                'producto_id': producto_talla.producto.id,
                'producto_talla_id': producto_talla.id,
                'articulo': producto_talla.producto.articulo,
                'talla': producto_talla.talla,
                'stock_sistema': producto_talla.stock,
                'valor_inventario_fifo': valor_inventario,
                'costo_promedio_fifo': costo_promedio,
                'diferencia_valor': diferencia,
                'costo_sistema': producto_talla.producto.costo,
                'valor_sistema': valor_sistema,
                'porcentaje_diferencia': porcentaje_diferencia,
                'sku': producto_talla.sku,
                'antiguedad_dias': antiguedad_dias,
                'fecha_lote_antiguo': fecha_lote_antiguo,
                'total_lotes': int(producto_talla.n_lotes_agg or 0)
            })
        
        # Ordenar datos
        if ordenar_por == 'diferencia':
            productos_data.sort(key=lambda x: abs(x['diferencia_valor']), reverse=True)
        elif ordenar_por == 'producto':
            productos_data.sort(key=lambda x: x['articulo'].lower())
        elif ordenar_por == 'valor_fifo':
            productos_data.sort(key=lambda x: x['valor_inventario_fifo'], reverse=True)
        elif ordenar_por == 'stock':
            productos_data.sort(key=lambda x: x['stock_sistema'], reverse=True)
        elif ordenar_por == 'porcentaje':
            productos_data.sort(key=lambda x: abs(x['porcentaje_diferencia']), reverse=True)
        elif ordenar_por == 'antiguedad':
            productos_data.sort(key=lambda x: x['antiguedad_dias'], reverse=True)
        elif ordenar_por == 'reciente':
            productos_data.sort(key=lambda x: x['antiguedad_dias'])
        
        # ========== CALCULAR MÉTRICAS DE TIEMPO ==========
        antiguedad_promedio = round(total_antiguedad_dias / total_lotes_analizados) if total_lotes_analizados > 0 else 0
        
        # Calcular rotación estimada (basada en antigüedad promedio)
        # Rotación = 365 / días promedio de inventario
        rotacion_estimada = round(365 / antiguedad_promedio, 1) if antiguedad_promedio > 0 else 0
        
        # Calcular días de inventario (inverso de rotación)
        dias_inventario = antiguedad_promedio if antiguedad_promedio > 0 else 0
        
        # Eficiencia FIFO (% de lotes frescos + normales vs total)
        eficiencia_fifo = round(((lotes_frescos + lotes_normales) / total_lotes_analizados) * 100, 1) if total_lotes_analizados > 0 else 100
        
        # ========== AGING DEL CAPITAL (agregación en DB, snapshot completo) ==========
        # OJO: a propósito NO respeta el filtro de período — el aging es una foto
        # del inventario completo de la sucursal; filtrar por fecha de ingreso
        # ocultaría justamente el capital viejo.
        lotes_snapshot = LoteProducto.objects.filter(
            activo=True, agotado=False, cantidad_disponible__gt=0,
            producto_talla__producto__sucursal_id=sucursal_id,
        ).exclude(producto_talla__producto__excluir_de_analitica=True)
        _hoy_d = timezone.localdate()
        _cortes = [('0_90', 0, 90), ('90_180', 90, 180), ('180_365', 180, 365), ('mas_365', 365, 36500)]
        aging_capital = {}
        for clave, d1, d2 in _cortes:
            agg = lotes_snapshot.filter(
                fecha_ingreso__date__gt=_hoy_d - timedelta(days=d2),
                fecha_ingreso__date__lte=_hoy_d - timedelta(days=d1),
            ).aggregate(u=Sum('cantidad_disponible'),
                        d=Sum(F('cantidad_disponible') * F('costo_unitario')))
            aging_capital[clave] = {'unidades': int(agg['u'] or 0), 'valor': float(agg['d'] or 0)}
        capital_total_lotes = sum(b['valor'] for b in aging_capital.values())
        capital_viejo = aging_capital['180_365']['valor'] + aging_capital['mas_365']['valor']
        pct_capital_viejo = round(capital_viejo / capital_total_lotes * 100, 1) if capital_total_lotes else 0

        # Capital >180d por categoría v1.2 y por marca (top 10 c/u): la vista
        # que decide liquidaciones. Solo lotes de esta sucursal.
        _viejos = lotes_snapshot.filter(fecha_ingreso__date__lte=_hoy_d - timedelta(days=180))
        aging_categoria = [{
            'categoria': r['producto_talla__producto__categoria__nombre'] or 'Sin categoría',
            'padre': r['producto_talla__producto__categoria__padre__nombre'] or '',
            'unidades': int(r['u'] or 0),
            'valor': float(r['d'] or 0),
        } for r in (_viejos.values('producto_talla__producto__categoria__nombre',
                                   'producto_talla__producto__categoria__padre__nombre')
                    .annotate(u=Sum('cantidad_disponible'),
                              d=Sum(F('cantidad_disponible') * F('costo_unitario')))
                    .order_by('-d')[:10])]
        aging_marca = [{
            'marca': r['producto_talla__producto__atributo1__valor'] or 'Sin marca',
            'unidades': int(r['u'] or 0),
            'valor': float(r['d'] or 0),
        } for r in (_viejos.values('producto_talla__producto__atributo1__valor')
                    .annotate(u=Sum('cantidad_disponible'),
                              d=Sum(F('cantidad_disponible') * F('costo_unitario')))
                    .order_by('-d')[:10])]

        # Generar alertas (con $, accionables — no conteos genéricos)
        alertas = []
        diferencias_altas = sum(1 for p in productos_data if abs(p['porcentaje_diferencia']) > 20)
        if diferencias_altas > 0:
            alertas.append({
                'tipo': 'warning',
                'mensaje': f'{diferencias_altas} SKU-talla con descalce lotes vs stock >20% — correr reconciliar_stock_lotes para diagnóstico'
            })

        if aging_capital['mas_365']['valor'] > 0:
            alertas.append({
                'tipo': 'danger',
                'mensaje': f"Capital crítico: ${aging_capital['mas_365']['valor']/1e6:,.0f}M a costo con más de 1 año en bodega ({aging_capital['mas_365']['unidades']:,} unidades) — candidato a liquidación"
            })

        if pct_capital_viejo > 40:
            alertas.append({
                'tipo': 'warning',
                'mensaje': f'{pct_capital_viejo}% del capital en lotes tiene más de 180 días — priorizar liquidación sobre compra nueva'
            })

        if aging_marca and aging_marca[0]['valor'] > 0:
            top_m = aging_marca[0]
            alertas.append({
                'tipo': 'info',
                'mensaje': f"Marca con más capital viejo (>180d): {top_m['marca']} con ${top_m['valor']/1e6:,.0f}M — revisar antes de recomprar"
            })

        return JsonResponse({
            'success': True,
            'productos': productos_data,
            'total_productos': len(productos_data),
            'valor_total_inventario': valor_total_inventario,
            'productos_con_diferencia': productos_con_diferencia,
            'diferencia_total': diferencia_total,
            'porcentaje_diferencia': (diferencia_total / valor_total_inventario * 100) if valor_total_inventario > 0 else 0,
            'analisis': {
                'diferencias_positivas': diferencias_positivas,
                'diferencias_negativas': diferencias_negativas,
                'sin_diferencias': sin_diferencias,
                'stock_bajo': stock_bajo,
                'stock_medio': stock_medio,
                'stock_alto': stock_alto,
                'sin_stock': sin_stock
            },
            # ========== MÉTRICAS DE TIEMPO ==========
            'metricas_tiempo': {
                'antiguedad_promedio': antiguedad_promedio,
                'rotacion_estimada': rotacion_estimada,
                'dias_inventario': dias_inventario,
                'eficiencia_fifo': eficiencia_fifo,
                'lotes_frescos': lotes_frescos,
                'lotes_normales': lotes_normales,
                'lotes_antiguos': lotes_antiguos,
                'lotes_criticos': lotes_criticos,
                'total_lotes_analizados': total_lotes_analizados
            },
            # ========== AGING DEL CAPITAL (snapshot completo, ignora período) ==========
            'aging_capital': aging_capital,
            'capital_total_lotes': capital_total_lotes,
            'capital_viejo': capital_viejo,
            'pct_capital_viejo': pct_capital_viejo,
            'aging_categoria': aging_categoria,
            'aging_marca': aging_marca,
            'filtros_aplicados': {
                'periodo': periodo,
                'fecha_desde': fecha_inicio.strftime('%Y-%m-%d') if fecha_inicio else None,
                'fecha_hasta': fecha_fin.strftime('%Y-%m-%d') if fecha_fin else None,
                'filtro_antiguedad': filtro_antiguedad
            },
            'alertas': alertas
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)

@require_GET
@login_required
def exportar_dashboard_fifo(request):
    """Exporta el detalle FIFO en CSV respetando TODOS los filtros de la UI
    (antes ignoraba periodo/fechas/antigüedad y el CSV no coincidía con la
    pantalla). Misma query anotada del dashboard: sin N+1."""
    try:
        from datetime import datetime, timedelta

        sucursal_id = request.session.get('idSucursalActual')
        if not sucursal_id:
            return JsonResponse({'success': False, 'error': 'No hay sucursal activa'})

        # Filtros — el mismo set que obtener_datos_dashboard_fifo
        filtro_producto = request.GET.get('filtro_producto', '').lower()
        filtro_talla = request.GET.get('filtro_talla', '').lower()
        filtro_diferencia = request.GET.get('filtro_diferencia', '')
        filtro_stock = request.GET.get('filtro_stock', '')
        periodo = request.GET.get('periodo', 'todo')
        fecha_desde = request.GET.get('fecha_desde', '')
        fecha_hasta = request.GET.get('fecha_hasta', '')
        filtro_antiguedad = request.GET.get('filtro_antiguedad', '')

        hoy = timezone.now()
        fecha_inicio = None
        fecha_fin = hoy
        if fecha_desde:
            try:
                fecha_inicio = timezone.make_aware(datetime.strptime(fecha_desde, '%Y-%m-%d'))
            except ValueError:
                pass
        if fecha_hasta:
            try:
                fecha_fin = timezone.make_aware(datetime.strptime(fecha_hasta, '%Y-%m-%d').replace(hour=23, minute=59, second=59))
            except ValueError:
                pass
        if not fecha_desde and periodo != 'todo':
            dias_periodo = {'hoy': 0, 'semana': 7, 'mes': 30, 'trimestre': 90, 'semestre': 180, 'anio': 365}.get(periodo)
            if dias_periodo == 0:
                fecha_inicio = hoy.replace(hour=0, minute=0, second=0, microsecond=0)
            elif dias_periodo:
                fecha_inicio = hoy - timedelta(days=dias_periodo)

        filtro_lotes = Q(lotes__activo=True, lotes__agotado=False,
                         lotes__cantidad_disponible__gt=0)
        if fecha_inicio:
            filtro_lotes &= Q(lotes__fecha_ingreso__gte=fecha_inicio)
        if fecha_fin:
            filtro_lotes &= Q(lotes__fecha_ingreso__lte=fecha_fin)

        qs = (Producto_Talla.objects
              .filter(producto__sucursal_id=sucursal_id)
              .exclude(producto__excluir_de_analitica=True)
              .select_related('producto', 'producto__categoria',
                              'producto__categoria__padre', 'producto__atributo1')
              .annotate(
                  valor_fifo_agg=Sum(F('lotes__cantidad_disponible') * F('lotes__costo_unitario'),
                                     filter=filtro_lotes),
                  disp_total_agg=Sum('lotes__cantidad_disponible', filter=filtro_lotes),
                  fecha_lote_min=Min('lotes__fecha_ingreso', filter=filtro_lotes),
                  n_lotes_agg=Count('lotes', filter=filtro_lotes, distinct=True),
              )
              .filter(n_lotes_agg__gt=0))
        if filtro_producto:
            qs = qs.filter(producto__articulo__icontains=filtro_producto)
        if filtro_talla:
            qs = qs.filter(talla__icontains=filtro_talla)

        datos_exportacion = []
        for pt in qs:
            disp_total = int(pt.disp_total_agg or 0)
            valor_inventario = int(pt.valor_fifo_agg or 0)
            costo_promedio = round(valor_inventario / disp_total) if disp_total else 0
            valor_sistema = pt.stock * pt.producto.costo
            diferencia = valor_inventario - valor_sistema
            porcentaje_diferencia = (diferencia / valor_sistema * 100) if valor_sistema > 0 else 0
            antiguedad_dias = (hoy - pt.fecha_lote_min).days if pt.fecha_lote_min else 0

            if filtro_antiguedad:
                if filtro_antiguedad == 'fresco' and antiguedad_dias >= 90:
                    continue
                elif filtro_antiguedad == 'normal' and (antiguedad_dias < 90 or antiguedad_dias >= 180):
                    continue
                elif filtro_antiguedad == 'antiguo' and (antiguedad_dias < 180 or antiguedad_dias >= 365):
                    continue
                elif filtro_antiguedad == 'critico' and antiguedad_dias < 365:
                    continue

            if filtro_diferencia:
                if filtro_diferencia == 'positiva' and diferencia <= 0:
                    continue
                elif filtro_diferencia == 'negativa' and diferencia >= 0:
                    continue
                elif filtro_diferencia == 'cero' and diferencia != 0:
                    continue
                elif filtro_diferencia == 'alta' and porcentaje_diferencia <= 10:
                    continue
                elif filtro_diferencia == 'baja' and porcentaje_diferencia >= 5:
                    continue

            if filtro_stock:
                if filtro_stock == 'bajo' and pt.stock >= 10:
                    continue
                elif filtro_stock == 'medio' and (pt.stock < 10 or pt.stock > 50):
                    continue
                elif filtro_stock == 'alto' and pt.stock <= 50:
                    continue
                elif filtro_stock == 'agotado' and pt.stock > 0:
                    continue

            cat = pt.producto.categoria
            datos_exportacion.append({
                'SKU': pt.sku,
                'Artículo': pt.producto.articulo,
                'Talla': pt.talla,
                'Categoría': (f"{cat.padre.nombre} › {cat.nombre}" if cat and cat.padre_id else (cat.nombre if cat else '')),
                'Marca': pt.producto.atributo1.valor if pt.producto.atributo1_id else '',
                'Stock Sistema': pt.stock,
                'Costo Sistema': pt.producto.costo,
                'Valor Sistema': valor_sistema,
                'Valor FIFO': valor_inventario,
                'Costo Promedio FIFO': costo_promedio,
                'Diferencia': diferencia,
                'Porcentaje Diferencia': f"{porcentaje_diferencia:.2f}%",
                'Antigüedad (días)': antiguedad_dias,
                'Fecha Lote Más Antiguo': pt.fecha_lote_min.strftime('%Y-%m-%d') if pt.fecha_lote_min else '',
                'Lotes': int(pt.n_lotes_agg or 0),
            })

        # CSV ordenado por antigüedad desc: lo más viejo (liquidable) primero
        datos_exportacion.sort(key=lambda d: d['Antigüedad (días)'], reverse=True)

        import csv

        response = HttpResponse(content_type='text/csv; charset=utf-8')
        response['Content-Disposition'] = f'attachment; filename="dashboard_fifo_{sucursal_id}_{timezone.localtime().strftime("%Y%m%d_%H%M%S")}.csv"'
        response.write('﻿')  # BOM para que Excel abra el UTF-8 bien

        if datos_exportacion:
            writer = csv.DictWriter(response, fieldnames=datos_exportacion[0].keys())
            writer.writeheader()
            writer.writerows(datos_exportacion)

        return response

    except Exception as e:
        logger.exception('Error exportando dashboard FIFO')
        return JsonResponse({'success': False, 'error': str(e)}, status=500)
