@require_POST
@login_required
def emitir_dte_concepto(request):
    """
    Procesar emisión de DTE por concepto (servicios, sin inventario).
    No genera movimientos de stock ni requiere Producto_Talla.
    """
    try:
        data = json.loads(request.body)

        tipo_documento = data.get('tipo_documento')
        receptor_id = data.get('receptor_id') or None
        fecha_emision = data.get('fecha_emision')
        detalle_conceptos = data.get('detalle_conceptos', [])
        observaciones = data.get('observaciones', '')
        forma_pago_str = data.get('forma_pago', 'Contado')
        dias_credito = int(data.get('dias_credito', 0) or 0)
        referencia = data.get('referencia')

        # La Boleta Electrónica (39) se emite a consumidor final: el receptor es
        # opcional. Si no se indica, el DTE queda sin receptor y el generador de
        # TXT lo emite a "66666666-6 / CONSUMIDOR FINAL". El resto de los DTE sí
        # requieren empresa receptora.
        es_boleta = tipo_documento == 'BOLETA ELECTRONICA'
        obligatorios = (
            [tipo_documento, fecha_emision]
            if es_boleta else
            [tipo_documento, receptor_id, fecha_emision]
        )
        if not all(obligatorios):
            return JsonResponse({
                'success': False,
                'error': 'Faltan datos obligatorios (tipo documento, receptor, fecha)'
            }, status=400)

        tipos_validos = ['FACTURA ELECTRONICA', 'FACTURA EXENTA', 'BOLETA ELECTRONICA', 'NOTA DE CREDITO', 'NOTA DE DEBITO', 'GUIA']
        if tipo_documento not in tipos_validos:
            return JsonResponse({
                'success': False,
                'error': f'Tipo de documento inválido: {tipo_documento}. Válidos: {tipos_validos}'
            }, status=400)

        if not detalle_conceptos:
            return JsonResponse({
                'success': False,
                'error': 'Debe incluir al menos un concepto'
            }, status=400)

        if tipo_documento in ('NOTA DE CREDITO', 'NOTA DE DEBITO') and not referencia:
            return JsonResponse({
                'success': False,
                'error': 'Nota de Crédito/Débito requiere referencia a documento original'
            }, status=400)

        sucursal_id = request.session.get('idSucursalActual')
        empresa_id = request.session.get('idEmpresaActual')

        if not sucursal_id or not empresa_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay sucursal activa en la sesión.'
            }, status=400)

        emisor = get_object_or_404(Empresa, id=empresa_id)
        sucursal = get_object_or_404(Sucursal, id=sucursal_id)
        receptor = get_object_or_404(Empresa, id=receptor_id) if receptor_id else None

        with transaction.atomic():
            subtotal_neto = 0
            for item in detalle_conceptos:
                cantidad = int(item.get('cantidad', 0))
                precio = int(float(item.get('precio_unitario', 0)))
                subtotal_neto += cantidad * precio

            # NC/ND heredan la exención del documento que referencian: si el
            # referenciado es exento (Factura Exenta 34 / Boleta Exenta 41) la
            # nota se emite sin IVA; si es afecto (33/39) lleva IVA 19%.
            es_nc_nd = tipo_documento in ('NOTA DE CREDITO', 'NOTA DE DEBITO')
            if es_nc_nd and referencia:
                es_exenta = int(referencia.get('tipo_documento') or 33) in (34, 41)
            else:
                es_exenta = tipo_documento == 'FACTURA EXENTA'
            subtotal_decimal = Decimal(str(subtotal_neto))

            if es_exenta:
                iva = Decimal('0')
                total_con_iva = subtotal_decimal
            else:
                iva = subtotal_decimal * Decimal('0.19')
                total_con_iva = subtotal_decimal + iva

            numero_documento = obtener_siguiente_correlativo(sucursal, tipo_documento)

            from datetime import timedelta
            fecha_emision_date = parse_date(fecha_emision)
            es_credito = (forma_pago_str == 'Credito' and dias_credito > 0)
            fecha_vencimiento_date = (
                fecha_emision_date + timedelta(days=dias_credito)
                if es_credito else fecha_emision_date
            )
            dias_credito_final = dias_credito if es_credito else 0

            es_nc = tipo_documento == 'NOTA DE CREDITO'

            if es_nc_nd and referencia:
                referencias_json = json.dumps([{
                    'tipo_documento': int(referencia.get('tipo_documento', 33)),
                    'folio': str(referencia.get('folio', '')),
                    'fecha': str(referencia.get('fecha', '')),
                    'razon': str(referencia.get('razon', '1')),
                }])
            else:
                referencias_json = f"DTE por concepto (sin mercadería)"
                if observaciones:
                    referencias_json += f". {observaciones}"

            doc_afectado = None
            if es_nc_nd and referencia:
                folio_ref = str(referencia.get('folio', ''))
                if folio_ref:
                    doc_afectado = Dte.objects.filter(
                        numero_documento=folio_ref,
                        emisor=emisor,
                    ).order_by('-fecha_emision').first()

            dte = Dte.objects.create(
                emisor=emisor,
                receptor=receptor,
                numero_documento=numero_documento,
                tipo_documento=tipo_documento,
                monto_neto=subtotal_decimal,
                monto_con_iva=total_con_iva,
                estado_pago='PENDIENTE',
                estado_dte='EMITIDO',
                responsable=request.user.username,
                fecha_emision=fecha_emision_date,
                fecha_vencimiento=fecha_vencimiento_date,
                diasCredito=dias_credito_final,
                bultos=0,
                unidades_productos=0,
                tipo_transaccion='VENTA',
                referencias=referencias_json,
                sucursal=sucursal,
                es_nota_credito=es_nc,
                documento_afectado=doc_afectado,
            )

            for item in detalle_conceptos:
                desc = item.get('descripcion', 'Concepto')
                cantidad = int(item.get('cantidad', 1))
                unidad = item.get('unidad', 'UN')
                precio = int(float(item.get('precio_unitario', 0)))
                monto_item = cantidad * precio

                Dte_Productos.objects.create(
                    dte=dte,
                    productoTalla=None,
                    descripcion=f"[{unidad}] {desc}",
                    costo=0,
                    sobreprecio=0,
                    precio=precio,
                    precio_unitario=precio,
                    monto_item=monto_item,
                    stock=cantidad,
                    activo=True,
                )

            return JsonResponse({
                'success': True,
                'dte_id': dte.id,
                'numero_documento': numero_documento,
                'total': float(total_con_iva)
            })

    except Exception as e:
        logger.exception("Error al emitir DTE por concepto")
        return JsonResponse({
            'success': False,
            'error': f'Error al emitir DTE por concepto: {str(e)}'
        }, status=500)


@login_required
def debug_session(request):
    """
    Vista temporal para debug de sesión
    """
    session_data = {
        'idSucursalActual': request.session.get('idSucursalActual'),
        'idEmpresaActual': request.session.get('idEmpresaActual'),
        'nombreUsuario': request.session.get('nombreUsuario'),
        'nombreEmpresaActual': request.session.get('nombreEmpresaActual'),
        'rutEmpresaActual': request.session.get('rutEmpresaActual'),
        'alias': request.session.get('alias'),
        'all_session_keys': list(request.session.keys())
    }
    return JsonResponse(session_data)
def debug_user_empresas(request):
    """Vista temporal para debug de empresas del usuario"""
    try:
        debug_data = {
            'usuario_actual': str(request.user),
            'empresas_disponibles': [],
            'sucursales_disponibles': [],
            'relaciones_empresa_user': [],
            'problema_detectado': None
        }
        
        # Obtener todas las empresas del usuario
        empresas_usuario = EmpresaUser.objects.filter(
            user=request.user
        ).select_related('empresa', 'sucursal')
        
        for eu in empresas_usuario:
            debug_data['relaciones_empresa_user'].append({
                'empresa_id': eu.empresa.id,
                'empresa_nombre': eu.empresa.nombre,
                'empresa_rut': eu.empresa.rut,
                'sucursal_id': eu.sucursal.id if eu.sucursal else None,
                'sucursal_alias': eu.sucursal.alias if eu.sucursal else None,
                'status': eu.status,
                'active': eu.active
            })
            
            # Agregar empresa a la lista si no está
            empresa_info = {
                'id': eu.empresa.id,
                'nombre': eu.empresa.nombre,
                'rut': eu.empresa.rut
            }
            if empresa_info not in debug_data['empresas_disponibles']:
                debug_data['empresas_disponibles'].append(empresa_info)
        
        # Obtener todas las sucursales de las empresas del usuario
        empresas_ids = [eu.empresa.id for eu in empresas_usuario if eu.status]
        sucursales = Sucursal.objects.filter(
            empresa_id__in=empresas_ids
        ).select_related('empresa')
        
        # Detectar sucursales mal asignadas
        problemas_sucursales = []
        for sucursal in sucursales:
            debug_data['sucursales_disponibles'].append({
                'id': sucursal.id,
                'alias': sucursal.alias,
                'direccion': sucursal.direccion,
                'empresa_id': sucursal.empresa.id,
                'empresa_nombre': sucursal.empresa.nombre,
                'empresa_rut': sucursal.empresa.rut
            })
            
            # Detectar si hay sucursales NICK en empresa Paola
            if 'NICK' in sucursal.alias and 'Paola' in sucursal.empresa.nombre:
                problemas_sucursales.append(f"Sucursal {sucursal.alias} está en {sucursal.empresa.nombre} pero debería estar en Importadora Nicole Andrea")
        
        if problemas_sucursales:
            debug_data['problema_detectado'] = {
                'tipo': 'sucursales_mal_asignadas',
                'detalles': problemas_sucursales,
                'solucion': 'Corregir las asignaciones de empresa en las sucursales NICK1 y NICK2'
            }
        
        # Información de sesión actual
        debug_data['sesion_actual'] = {
            'idSucursalActual': request.session.get('idSucursalActual'),
            'idEmpresaActual': request.session.get('idEmpresaActual'),
            'alias': request.session.get('alias'),
            'nombreEmpresaActual': request.session.get('nombreEmpresaActual')
        }
        
        # Simular filtro para facturas (otras empresas)
        empresa_actual_id = request.session.get('idEmpresaActual')
        if empresa_actual_id:
            otras_empresas = [emp for emp in debug_data['empresas_disponibles'] if emp['id'] != empresa_actual_id]
            debug_data['simulacion_factura_interna'] = {
                'empresa_actual_id': empresa_actual_id,
                'otras_empresas_disponibles': otras_empresas,
                'sucursales_otras_empresas': [
                    suc for suc in debug_data['sucursales_disponibles'] 
                    if suc['empresa_id'] != empresa_actual_id
                ]
            }
        
        return JsonResponse(debug_data, json_dumps_params={'indent': 2})
        
    except Exception as e:
        return JsonResponse({
            'error': str(e),
            'tipo_error': type(e).__name__
        }, status=500)

