@login_required
def ver_reporte_existencias(request):
    """Vista principal del reporte de existencias de productos"""
    return render(request, 'vistas/reporte_existencias.html')


@login_required
def obtener_existencias_reporte(request):
    """
    API para obtener datos de existencias de productos
    Retorna información completa de productos con stock, costos y precios
    Optimizada para manejar grandes volúmenes de datos con filtros del lado del servidor
    Soporta paginación
    """
    try:
        import logging
        from django.db.models import Sum, F, Value, IntegerField
        from django.db.models.functions import Coalesce
        
        logger = logging.getLogger(__name__)
        logger.info('Iniciando obtención de existencias')
        
        # Obtener filtros del request
        sucursal_id = request.GET.get('sucursal_id')
        categoria_id = request.GET.get('categoria_id')
        busqueda = request.GET.get('busqueda', '').strip()
        estado_stock = request.GET.get('estado_stock', '')  # con-stock, sin-stock, bajo-stock, stock-bajo-medio
        
        # Paginación
        pagina = int(request.GET.get('pagina', 1))
        por_pagina = int(request.GET.get('por_pagina', 100))  # 100 por defecto
        
        logger.info(f'Filtros recibidos - sucursal: {sucursal_id}, categoria: {categoria_id}, busqueda: {busqueda}, estado: {estado_stock}, pagina: {pagina}')
        
        # Filtrar por sucursales del usuario (seguridad multi-tenant)
        empresas_usuario = EmpresaUser.objects.filter(
            user=request.user,
            status=True
        ).values_list('empresa_id', flat=True)
        sucursales_usuario = Sucursal.objects.filter(
            empresa_id__in=empresas_usuario
        ).values_list('id', flat=True)

        # Construir queryset base optimizado
        productos_talla = Producto_Talla.objects.select_related(
            'producto',
            'producto__categoria',
            'producto__sucursal',
            'producto__atributo1',  # Marca
            'producto__atributo2',  # Color
        ).filter(
            producto__isnull=False,
            producto__sucursal__isnull=False,
            producto__sucursal_id__in=sucursales_usuario,
            producto__excluir_de_analitica=False
        )
        
        # ========== APLICAR FILTROS ==========
        
        # Filtro por sucursal
        if sucursal_id:
            productos_talla = productos_talla.filter(producto__sucursal_id=sucursal_id)
            logger.info(f'Filtro sucursal aplicado: {sucursal_id}')
        
        # Filtro por categoría — árbol v1.2: un padre incluye todas sus hijas
        if categoria_id:
            from app.views_modulo_reportes import _expandir_categoria_ids
            productos_talla = productos_talla.filter(
                producto__categoria_id__in=_expandir_categoria_ids(categoria_id)
            )
            logger.info(f'Filtro categoría aplicado (rama v1.2): {categoria_id}')
        
        # Filtro por búsqueda de texto
        if busqueda:
            productos_talla = productos_talla.filter(
                Q(sku__icontains=busqueda) |
                Q(producto__articulo__icontains=busqueda) |
                Q(producto__descripcion__icontains=busqueda) |
                Q(talla__icontains=busqueda)
            )
            logger.info(f'Filtro búsqueda aplicado: {busqueda}')
        
        # Filtro por estado de stock (aplicado en DB para eficiencia)
        if estado_stock == 'con-stock':
            productos_talla = productos_talla.filter(stock__gt=0)
        elif estado_stock == 'sin-stock':
            productos_talla = productos_talla.filter(stock=0)
        elif estado_stock == 'bajo-stock':
            productos_talla = productos_talla.filter(stock__gt=0, stock__lt=10)
        elif estado_stock == 'stock-bajo-medio':
            productos_talla = productos_talla.filter(stock__gte=10, stock__lt=30)
        
        # Ordenar por artículo y sucursal
        productos_talla = productos_talla.order_by('producto__articulo', 'producto__sucursal__alias', 'talla')
        
        total_registros = productos_talla.count()
        total_articulos = productos_talla.values('producto_id').distinct().count()
        total_paginas = (total_registros + por_pagina - 1) // por_pagina  # Redondeo hacia arriba
        
        logger.info(f'Total productos_talla después de filtros: {total_registros}, artículos únicos: {total_articulos}, páginas: {total_paginas}')
        
        # ========== AGREGADOS GLOBALES (todo el dataset filtrado, independiente de paginación) ==========
        from django.db.models import Count as DjCount
        
        # Stock total y conteos por estado a nivel de producto (agrupado por producto_id)
        product_stocks = productos_talla.values('producto_id').annotate(
            stock_producto=Sum('stock')
        )
        total_stock_global = int(productos_talla.aggregate(
            total=Coalesce(Sum('stock'), Value(0, output_field=IntegerField()))
        )['total'])
        sin_stock_global = product_stocks.filter(stock_producto=0).count()
        bajo_stock_global = product_stocks.filter(stock_producto__gt=0, stock_producto__lt=10).count()
        
        # Valor venta total (stock * precioventa)
        valor_venta_global = float(
            productos_talla.aggregate(
                total=Coalesce(
                    Sum(F('stock') * F('producto__precioventa')),
                    Value(0, output_field=IntegerField())
                )
            )['total'] or 0
        )
        
        # Valor FIFO total (lotes activos con cantidad disponible)
        valor_fifo_global = float(
            LoteProducto.objects.filter(
                producto_talla__in=productos_talla,
                cantidad_disponible__gt=0,
                activo=True
            ).aggregate(
                total=Coalesce(
                    Sum(F('cantidad_disponible') * F('costo_unitario')),
                    Value(0, output_field=IntegerField())
                )
            )['total'] or 0
        )
        
        kpis_globales = {
            'total_stock': total_stock_global,
            'sin_stock': sin_stock_global,
            'bajo_stock': bajo_stock_global,
            'valor_inventario_fifo': valor_fifo_global,
            'valor_venta_total': valor_venta_global,
        }
        
        logger.info(f'KPIs globales: stock={total_stock_global}, sin_stock={sin_stock_global}, bajo_stock={bajo_stock_global}, fifo={valor_fifo_global:.0f}, venta={valor_venta_global:.0f}')
        
        # ========== PAGINACIÓN ==========
        inicio = (pagina - 1) * por_pagina
        fin = inicio + por_pagina
        productos_paginados = productos_talla[inicio:fin]
        
        # ========== PREPARAR DATOS ==========
        existencias = []
        
        # Obtener lotes en una sola consulta para optimizar (solo para la página actual)
        lotes_por_talla = {}
        productos_ids = [pt.id for pt in productos_paginados]
        
        lotes_query = LoteProducto.objects.filter(
            producto_talla_id__in=productos_ids,
            cantidad_disponible__gt=0,
            activo=True
        ).values('producto_talla_id').annotate(
            total_cantidad=Sum('cantidad_disponible'),
            valor_total=Sum(F('cantidad_disponible') * F('costo_unitario'))
        )
        
        for lote in lotes_query:
            if lote['total_cantidad'] > 0:
                lotes_por_talla[lote['producto_talla_id']] = {
                    'cantidad': lote['total_cantidad'],
                    'costo_promedio': lote['valor_total'] / lote['total_cantidad']
                }
        
        # Procesar productos de la página actual
        for pt in productos_paginados:
            try:
                # Obtener costo FIFO del cache de lotes
                lote_info = lotes_por_talla.get(pt.id)
                if lote_info:
                    costo_fifo = lote_info['costo_promedio']
                else:
                    costo_fifo = pt.producto.costo or 0
                
                existencias.append({
                    'sku': str(pt.sku),
                    'articulo': pt.producto.articulo,
                    'descripcion': pt.producto.descripcion or '',
                    'talla': pt.talla or '',
                    'sucursal': pt.producto.sucursal.alias if pt.producto.sucursal else 'Sin sucursal',
                    'sucursal_id': pt.producto.sucursal.id if pt.producto.sucursal else None,
                    'categoria': pt.producto.categoria.nombre if pt.producto.categoria else 'Sin categoría',
                    'categoria_id': pt.producto.categoria.id if pt.producto.categoria else None,
                    'marca': pt.producto.atributo1.valor if pt.producto.atributo1 else '',
                    'color': pt.producto.atributo2.valor if pt.producto.atributo2 else '',
                    'stock': pt.stock or 0,
                    'costo': pt.producto.costo or 0,
                    'costo_fifo': int(costo_fifo),
                    'pvp': pt.producto.precioventa or 0,
                })
            except Exception as e:
                logger.error(f'Error procesando producto_talla {pt.id}: {str(e)}')
                continue
        
        logger.info(f'Total existencias procesadas en página {pagina}: {len(existencias)}')
        
        # ========== OBTENER OPCIONES DE FILTROS (solo en página 1 o si se solicita) ==========
        sucursales = []
        categorias = []
        
        if pagina == 1 or request.GET.get('cargar_filtros') == '1':
            # Sucursales del usuario que tienen productos
            sucursales = list(
                Sucursal.objects.filter(
                    id__in=sucursales_usuario,
                    sucursal_producto__isnull=False
                ).distinct().values('id', 'alias').order_by('alias')
            )

            # Categorías árbol v1.2 con productos del usuario: padres primero
            # (filtran su rama completa vía _expandir_categoria_ids) y luego
            # las hijas como "Padre › Hija". Se ocultan las _ZZ_ deprecadas.
            cats_con_prod = list(
                Categoria.objects.filter(
                    categoria_productos__sucursal_id__in=sucursales_usuario
                ).exclude(nombre__startswith='_ZZ_')
                .distinct().values('id', 'nombre', 'padre_id', 'padre__nombre')
                .order_by('nombre')
            )
            padres_vistos = {}
            for c in cats_con_prod:
                if c['padre_id'] and c['padre_id'] not in padres_vistos:
                    padres_vistos[c['padre_id']] = c['padre__nombre'] or ''
            categorias = [
                {'id': pid, 'nombre': f'{nombre} (toda la rama)'}
                for pid, nombre in sorted(padres_vistos.items(), key=lambda x: x[1])
            ]
            categorias += [
                {'id': c['id'],
                 'nombre': (f"{c['padre__nombre']} › {c['nombre']}" if c['padre_id']
                            else f"{c['nombre']} (sin recategorizar)")}
                for c in cats_con_prod
            ]
        
        logger.info(f'Retornando página {pagina} con {len(existencias)} existencias')
        
        return JsonResponse({
            'success': True,
            'existencias': existencias,
            'sucursales': sucursales,
            'categorias': categorias,
            'kpis_globales': kpis_globales,
            'paginacion': {
                'pagina_actual': pagina,
                'por_pagina': por_pagina,
                'total_registros': total_registros,
                'total_articulos': total_articulos,
                'total_paginas': total_paginas,
                'tiene_siguiente': pagina < total_paginas,
                'tiene_anterior': pagina > 1
            }
        })
        
    except Exception as e:
        import traceback
        import logging
        logger = logging.getLogger(__name__)
        logger.error(f'Error en obtener_existencias_reporte: {str(e)}')
        logger.error(traceback.format_exc())
        
        return JsonResponse({
            'success': False,
            'error': f'Error al obtener existencias: {str(e)}'
        }, status=500)


@login_required
@require_GET
def exportar_existencias_excel(request):
    """Exportar reporte de existencias a Excel con filtros aplicados"""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
        from datetime import datetime
        
        # Obtener filtros del request (mismos que la API de datos)
        sucursal_id = request.GET.get('sucursal_id')
        categoria_id = request.GET.get('categoria_id')
        busqueda = request.GET.get('busqueda', '').strip()
        estado_stock = request.GET.get('estado_stock', '')
        
        # Construir queryset base
        productos_talla = Producto_Talla.objects.select_related(
            'producto',
            'producto__categoria',
            'producto__sucursal',
            'producto__atributo1',
            'producto__atributo2'
        ).filter(
            producto__isnull=False,
            producto__sucursal__isnull=False
        )
        
        # Aplicar filtros
        if sucursal_id:
            productos_talla = productos_talla.filter(producto__sucursal_id=sucursal_id)
        
        if categoria_id:
            productos_talla = productos_talla.filter(producto__categoria_id=categoria_id)
        
        if busqueda:
            productos_talla = productos_talla.filter(
                Q(sku__icontains=busqueda) |
                Q(producto__articulo__icontains=busqueda) |
                Q(producto__descripcion__icontains=busqueda) |
                Q(talla__icontains=busqueda)
            )
        
        # Filtro por estado de stock
        if estado_stock == 'con-stock':
            productos_talla = productos_talla.filter(stock__gt=0)
        elif estado_stock == 'sin-stock':
            productos_talla = productos_talla.filter(stock=0)
        elif estado_stock == 'bajo-stock':
            productos_talla = productos_talla.filter(stock__gt=0, stock__lt=10)
        elif estado_stock == 'stock-bajo-medio':
            productos_talla = productos_talla.filter(stock__gte=10, stock__lt=30)
        
        productos_talla = productos_talla.order_by('producto__sucursal__alias', 'producto__articulo', 'talla')
        
        # Crear workbook
        wb = openpyxl.Workbook()
        
        # ===== HOJA 1: VISTA GENERAL =====
        ws_general = wb.active
        ws_general.title = "Existencias General"
        
        # Estilos
        header_fill = PatternFill(start_color='667eea', end_color='667eea', fill_type='solid')
        header_font = Font(bold=True, color='FFFFFF', size=11)
        border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Encabezados
        headers_general = [
            'SKU', 'Artículo', 'Descripción', 'Talla/Alias', 'Sucursal',
            'Categoría', 'Stock', 'Costo', 'Costo FIFO', 'PVP',
            'Valor Total (FIFO)', 'Estado'
        ]
        
        for col_num, header in enumerate(headers_general, 1):
            cell = ws_general.cell(row=1, column=col_num)
            cell.value = header
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal='center', vertical='center')
            cell.border = border
        
        # Datos
        row_num = 2
        for pt in productos_talla:
            # Calcular costo FIFO
            lotes_disponibles = LoteProducto.objects.filter(
                producto_talla=pt,
                cantidad_disponible__gt=0,
                activo=True
            )
            
            costo_fifo = 0
            total_cantidad_lotes = 0
            
            if lotes_disponibles.exists():
                for lote in lotes_disponibles:
                    costo_fifo += lote.costo_unitario * lote.cantidad_disponible
                    total_cantidad_lotes += lote.cantidad_disponible
                
                if total_cantidad_lotes > 0:
                    costo_fifo = costo_fifo / total_cantidad_lotes
            else:
                costo_fifo = pt.producto.costo
            
            valor_total = pt.stock * costo_fifo
            
            # Determinar estado
            if pt.stock == 0:
                estado = 'Sin Stock'
            elif pt.stock < 10:
                estado = 'Bajo Stock'
            else:
                estado = 'Disponible'
            
            # Escribir fila
            ws_general.cell(row=row_num, column=1).value = str(pt.sku)
            ws_general.cell(row=row_num, column=2).value = pt.producto.articulo
            ws_general.cell(row=row_num, column=3).value = pt.producto.descripcion
            ws_general.cell(row=row_num, column=4).value = pt.talla
            ws_general.cell(row=row_num, column=5).value = pt.producto.sucursal.alias
            ws_general.cell(row=row_num, column=6).value = pt.producto.categoria.nombre if pt.producto.categoria else 'Sin categoría'
            ws_general.cell(row=row_num, column=7).value = pt.stock
            ws_general.cell(row=row_num, column=8).value = pt.producto.costo
            ws_general.cell(row=row_num, column=9).value = int(costo_fifo)
            ws_general.cell(row=row_num, column=10).value = pt.producto.precioventa
            ws_general.cell(row=row_num, column=11).value = int(valor_total)
            ws_general.cell(row=row_num, column=12).value = estado
            
            # Aplicar bordes
            for col in range(1, 13):
                ws_general.cell(row=row_num, column=col).border = border
            
            row_num += 1
        
        # Ajustar anchos de columna
        for col in range(1, 13):
            ws_general.column_dimensions[get_column_letter(col)].width = 15
        
        ws_general.column_dimensions['B'].width = 25  # Artículo
        ws_general.column_dimensions['C'].width = 35  # Descripción
        
        # ===== HOJA 2: AGRUPADO POR SUCURSAL =====
        ws_sucursal = wb.create_sheet("Por Sucursal")
        
        # Encabezados
        headers_sucursal = [
            'Sucursal', 'SKU', 'Artículo', 'Talla/Alias',
            'Stock', 'Costo', 'Costo FIFO', 'PVP', 'Valor Total', 'Estado'
        ]
        
        for col_num, header in enumerate(headers_sucursal, 1):
            cell = ws_sucursal.cell(row=1, column=col_num)
            cell.value = header
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal='center', vertical='center')
            cell.border = border
        
        # Datos agrupados por sucursal
        sucursales = Sucursal.objects.all().order_by('alias')
        row_num = 2
        
        for sucursal in sucursales:
            productos_sucursal = productos_talla.filter(producto__sucursal=sucursal)
            
            if not productos_sucursal.exists():
                continue
            
            # Fila de encabezado de sucursal
            cell = ws_sucursal.cell(row=row_num, column=1)
            cell.value = f"🏪 {sucursal.alias}"
            cell.font = Font(bold=True, size=12)
            cell.fill = PatternFill(start_color='E9ECEF', end_color='E9ECEF', fill_type='solid')
            ws_sucursal.merge_cells(f'A{row_num}:J{row_num}')
            row_num += 1
            
            # Productos de la sucursal
            for pt in productos_sucursal:
                # Calcular costo FIFO
                lotes_disponibles = LoteProducto.objects.filter(
                    producto_talla=pt,
                    cantidad_disponible__gt=0,
                    activo=True
                )
                
                costo_fifo = 0
                total_cantidad_lotes = 0
                
                if lotes_disponibles.exists():
                    for lote in lotes_disponibles:
                        costo_fifo += lote.costo_unitario * lote.cantidad_disponible
                        total_cantidad_lotes += lote.cantidad_disponible
                    
                    if total_cantidad_lotes > 0:
                        costo_fifo = costo_fifo / total_cantidad_lotes
                else:
                    costo_fifo = pt.producto.costo
                
                valor_total = pt.stock * costo_fifo
                
                # Determinar estado
                if pt.stock == 0:
                    estado = 'Sin Stock'
                elif pt.stock < 10:
                    estado = 'Bajo Stock'
                else:
                    estado = 'Disponible'
                
                # Escribir fila
                ws_sucursal.cell(row=row_num, column=1).value = sucursal.alias
                ws_sucursal.cell(row=row_num, column=2).value = str(pt.sku)
                ws_sucursal.cell(row=row_num, column=3).value = pt.producto.articulo
                ws_sucursal.cell(row=row_num, column=4).value = pt.talla
                ws_sucursal.cell(row=row_num, column=5).value = pt.stock
                ws_sucursal.cell(row=row_num, column=6).value = pt.producto.costo
                ws_sucursal.cell(row=row_num, column=7).value = int(costo_fifo)
                ws_sucursal.cell(row=row_num, column=8).value = pt.producto.precioventa
                ws_sucursal.cell(row=row_num, column=9).value = int(valor_total)
                ws_sucursal.cell(row=row_num, column=10).value = estado
                
                # Aplicar bordes
                for col in range(1, 11):
                    ws_sucursal.cell(row=row_num, column=col).border = border
                
                row_num += 1
        
        # Ajustar anchos de columna
        for col in range(1, 11):
            ws_sucursal.column_dimensions[get_column_letter(col)].width = 15
        
        ws_sucursal.column_dimensions['C'].width = 25  # Artículo
        
        # ===== HOJA 3: RESUMEN =====
        ws_resumen = wb.create_sheet("Resumen")
        
        # Título
        ws_resumen.cell(row=1, column=1).value = "RESUMEN DE EXISTENCIAS"
        ws_resumen.cell(row=1, column=1).font = Font(bold=True, size=14)
        ws_resumen.cell(row=2, column=1).value = f"Generado el {timezone.localtime().strftime('%d/%m/%Y %H:%M')}"
        
        # Métricas generales
        total_productos = productos_talla.count()
        total_stock = sum(pt.stock for pt in productos_talla)
        sin_stock = productos_talla.filter(stock=0).count()
        bajo_stock = productos_talla.filter(stock__gt=0, stock__lt=10).count()
        
        ws_resumen.cell(row=4, column=1).value = "Total de Productos (SKUs):"
        ws_resumen.cell(row=4, column=2).value = total_productos
        ws_resumen.cell(row=4, column=1).font = Font(bold=True)
        
        ws_resumen.cell(row=5, column=1).value = "Stock Total (Unidades):"
        ws_resumen.cell(row=5, column=2).value = total_stock
        ws_resumen.cell(row=5, column=1).font = Font(bold=True)
        
        ws_resumen.cell(row=6, column=1).value = "Productos Sin Stock:"
        ws_resumen.cell(row=6, column=2).value = sin_stock
        ws_resumen.cell(row=6, column=1).font = Font(bold=True)
        
        ws_resumen.cell(row=7, column=1).value = "Productos Bajo Stock (<10):"
        ws_resumen.cell(row=7, column=2).value = bajo_stock
        ws_resumen.cell(row=7, column=1).font = Font(bold=True)
        
        # Resumen por sucursal
        ws_resumen.cell(row=9, column=1).value = "RESUMEN POR SUCURSAL"
        ws_resumen.cell(row=9, column=1).font = Font(bold=True, size=12)
        
        row_num = 11
        ws_resumen.cell(row=row_num, column=1).value = "Sucursal"
        ws_resumen.cell(row=row_num, column=2).value = "Productos"
        ws_resumen.cell(row=row_num, column=3).value = "Stock Total"
        
        for col in range(1, 4):
            ws_resumen.cell(row=row_num, column=col).font = Font(bold=True)
            ws_resumen.cell(row=row_num, column=col).fill = header_fill
            ws_resumen.cell(row=row_num, column=col).font = header_font
        
        row_num += 1
        
        for sucursal in sucursales:
            productos_sucursal = productos_talla.filter(producto__sucursal=sucursal)
            stock_sucursal = sum(pt.stock for pt in productos_sucursal)
            
            ws_resumen.cell(row=row_num, column=1).value = sucursal.alias
            ws_resumen.cell(row=row_num, column=2).value = productos_sucursal.count()
            ws_resumen.cell(row=row_num, column=3).value = stock_sucursal
            row_num += 1
        
        # Ajustar anchos
        ws_resumen.column_dimensions['A'].width = 30
        ws_resumen.column_dimensions['B'].width = 15
        ws_resumen.column_dimensions['C'].width = 15
        
        # Preparar respuesta
        response = HttpResponse(
            content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        timestamp = timezone.localtime().strftime('%Y%m%d_%H%M%S')
        response['Content-Disposition'] = f'attachment; filename="reporte_existencias_{timestamp}.xlsx"'
        
        wb.save(response)
        return response
        
    except Exception as e:
        return JsonResponse({
            'success': False,
            'error': f'Error al exportar: {str(e)}'
        })


# ========== NOTIFICACIONES DE DTEs RECIBIDOS ==========

@login_required
@require_GET
def obtener_notificaciones_dte(request):
    """
    Obtiene las notificaciones de DTEs recibidos pendientes para la empresa actual.
    Soporta filtro por sucursal y tipo de notificación.
    """
    from .models import NotificacionDTE
    
    try:
        empresa_id = request.session.get('idEmpresaActual')
        sucursal_id = request.session.get('idSucursalActual')
        solo_no_leidas = request.GET.get('solo_no_leidas', 'false').lower() == 'true'
        filtrar_por_sucursal = request.GET.get('filtrar_sucursal', 'false').lower() == 'true'
        tipo_filtro = request.GET.get('tipo', '')  # DTE_RECIBIDO, REGULARIZACION_REQUERIDA, etc.
        limit = int(request.GET.get('limit', 20))
        
        if not empresa_id:
            return JsonResponse({
                'success': False,
                'error': 'No hay empresa seleccionada'
            })
        
        # Query base
        notificaciones_query = NotificacionDTE.objects.select_related(
            'dte', 'dte__emisor', 'dte__receptor', 'sucursal', 'sucursal_reportante'
        ).filter(empresa_receptora_id=empresa_id)
        
        # Filtrar por sucursal si se solicita
        if filtrar_por_sucursal and sucursal_id:
            notificaciones_query = notificaciones_query.filter(
                models.Q(sucursal_id=sucursal_id) | models.Q(sucursal__isnull=True)
            )
        
        # Filtrar por tipo si se especifica
        if tipo_filtro:
            notificaciones_query = notificaciones_query.filter(tipo=tipo_filtro)
        
        if solo_no_leidas:
            notificaciones_query = notificaciones_query.filter(leida=False)
        
        total_no_leidas_query = NotificacionDTE.objects.filter(
            empresa_receptora_id=empresa_id,
            leida=False
        )
        if filtrar_por_sucursal and sucursal_id:
            total_no_leidas_query = total_no_leidas_query.filter(
                models.Q(sucursal_id=sucursal_id) | models.Q(sucursal__isnull=True)
            )
        if tipo_filtro:
            total_no_leidas_query = total_no_leidas_query.filter(tipo=tipo_filtro)
        total_no_leidas = total_no_leidas_query.count()
        
        # Contar notificaciones de regularización pendientes
        regularizaciones_pendientes = NotificacionDTE.objects.filter(
            empresa_receptora_id=empresa_id,
            tipo='REGULARIZACION_REQUERIDA',
            procesada=False
        )
        if filtrar_por_sucursal and sucursal_id:
            regularizaciones_pendientes = regularizaciones_pendientes.filter(
                models.Q(sucursal_id=sucursal_id) | models.Q(sucursal__isnull=True)
            )
        total_regularizaciones = regularizaciones_pendientes.count()
        
        # Obtener notificaciones con límite
        notificaciones = notificaciones_query.order_by('-fecha_creacion')[:limit]
        
        # Formatear respuesta
        lista_notificaciones = []
        for notif in notificaciones:
            item = {
                'id': notif.id,
                'tipo': notif.tipo,
                'tipo_display': notif.get_tipo_display(),
                'titulo': notif.titulo,
                'mensaje': notif.mensaje,
                'leida': notif.leida,
                'procesada': notif.procesada,
                'fecha_creacion': notif.fecha_creacion.strftime('%d/%m/%Y %H:%M'),
                'dte': {
                    'id': notif.dte.id,
                    'numero_documento': notif.dte.numero_documento,
                    'tipo_documento': notif.dte.tipo_documento,
                    'monto_con_iva': float(notif.dte.monto_con_iva),
                    'emisor': notif.dte.emisor.nombre if notif.dte.emisor else 'Desconocido',
                    'fecha_emision': notif.dte.fecha_emision.strftime('%d/%m/%Y') if notif.dte.fecha_emision else '',
                }
            }
            
            # Agregar información adicional para regularizaciones
            if notif.tipo == 'REGULARIZACION_REQUERIDA':
                item['productos_problemas'] = notif.productos_problemas
                item['detalle_problemas'] = notif.detalle_problemas
                item['sucursal_reportante'] = notif.sucursal_reportante.alias if notif.sucursal_reportante else None
            
            lista_notificaciones.append(item)
        
        return JsonResponse({
            'success': True,
            'notificaciones': lista_notificaciones,
            'total_no_leidas': total_no_leidas,
            'total_regularizaciones': total_regularizaciones,
            'total': len(lista_notificaciones)
        })
        
    except Exception as e:
        logger.exception("Error en obtener_notificaciones_dte")
        return JsonResponse({
            'success': False,
            'error': str(e)
        })


