# ================================================================
# QZ TRAY — IMPRESIÓN TÉRMICA SILENCIOSA
# ================================================================

def qz_certificado(request):
    """
    Sirve el certificado digital público para que QZ Tray verifique
    la firma de las peticiones del browser.
    GET /app/qz/certificado/ → retorna digital-certificate.txt
    """
    from pathlib import Path
    from django.conf import settings as django_settings

    cert_path = Path(django_settings.QZ_CERTIFICATE_PATH)
    if cert_path.exists():
        cert_data = cert_path.read_text(encoding='utf-8')
    else:
        import os
        cert_data = os.environ.get('QZ_CERTIFICATE', '')
        if cert_data:
            if '\\n' in cert_data:
                cert_data = cert_data.replace('\\n', '\n')
        else:
            return HttpResponse(
                '# Certificado QZ Tray no configurado.\n'
                '# Configure QZ_CERTIFICATE en variables de entorno.',
                content_type='text/plain',
                status=404
            )
    return HttpResponse(cert_data, content_type='text/plain')


@login_required
def qz_firmar(request):
    """
    Firma el token que QZ Tray envía al browser para autenticar la conexión.
    POST /app/qz/firmar/
    Body: { "request": "<string_a_firmar>" }
    Retorna: { "firma": "<base64>" }
    """
    if request.method != 'POST':
        return JsonResponse({'error': 'Método no permitido'}, status=405)

    try:
        import base64
        from pathlib import Path
        from django.conf import settings as django_settings
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.hazmat.backends import default_backend

        data = json.loads(request.body)
        mensaje = data.get('request', '')

        # Intentar leer la clave privada desde archivo local o variable de entorno
        key_path = Path(django_settings.QZ_PRIVATE_KEY_PATH)
        if key_path.exists():
            key_data = key_path.read_bytes()
        else:
            import os
            key_env = os.environ.get('QZ_PRIVATE_KEY', '')
            if not key_env:
                return JsonResponse(
                    {'error': 'Clave privada no encontrada. Configure QZ_PRIVATE_KEY en variables de entorno.'},
                    status=500
                )
            # Soportar tanto \n literal como saltos reales
            if '\\n' in key_env:
                key_env = key_env.replace('\\n', '\n')
            key_data = key_env.encode('utf-8')

        clave_privada = serialization.load_pem_private_key(
            key_data,
            password=None,
            backend=default_backend()
        )
        firma = clave_privada.sign(
            mensaje.encode('utf-8'),
            padding.PKCS1v15(),
            hashes.SHA512()
        )
        return JsonResponse({'firma': base64.b64encode(firma).decode('utf-8')})

    except ImportError:
        return JsonResponse(
            {'error': 'Librería cryptography no instalada. Ejecute: pip install cryptography'},
            status=500
        )
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)


@login_required
def qz_config_sucursal(request):
    """
    GET /app/qz/config/ → devuelve la configuración QZ de la sucursal activa en sesión.
    """
    sucursal_id = request.session.get('idSucursalActual') or request.session.get('sucursalActual')
    if not sucursal_id:
        return JsonResponse({'habilitado': False, 'impresora': 'EPSON TM-T20II'})

    try:
        sucursal = Sucursal.objects.get(id=sucursal_id)
        return JsonResponse({
            'habilitado': getattr(sucursal, 'usar_qz_tray', False),
            'impresora': getattr(sucursal, 'nombre_impresora_termica', 'EPSON TM-T20II') or 'EPSON TM-T20II',
        })
    except Sucursal.DoesNotExist:
        return JsonResponse({'habilitado': False, 'impresora': 'EPSON TM-T20II'})


# =========================================================================
# VINCULACIÓN RETROACTIVA: PRODUCTOS EXISTENTES → COMPRA
# =========================================================================

@require_GET
@login_required
def buscar_sku_para_vincular(request):
    """
    Busca Producto_Talla por SKU, artículo, marca, color o género.
    Devuelve candidatos con info completa para que el usuario confirme el match.

    GET params:
        q           — texto parcial (busca en SKU, artículo, marca, color, género)
        compra_id   — (opcional) marcar SKUs ya vinculados a esta compra
        talla       — (opcional) filtrar por talla exacta
    """
    q = (request.GET.get('q') or '').strip()
    if len(q) < 1:
        return JsonResponse({'success': True, 'results': []})

    compra_id = request.GET.get('compra_id')
    talla_filtro = (request.GET.get('talla') or '').strip()

    filtro = (
        Q(sku__icontains=q) |
        Q(producto__articulo__icontains=q) |
        Q(producto__atributo1__valor__icontains=q) |
        Q(producto__atributo2__valor__icontains=q) |
        Q(producto__atributo3__valor__icontains=q)
    )

    qs = (
        Producto_Talla.objects
        .filter(filtro)
        .select_related(
            'producto__atributo1',
            'producto__atributo2',
            'producto__atributo3',
            'producto__categoria',
            'producto__sucursal',
        )
    )

    if talla_filtro:
        qs = qs.filter(talla__iexact=talla_filtro)

    qs = qs.order_by(
        Case(
            When(sku__istartswith=q, then=Value(0)),
            When(producto__articulo__iexact=q, then=Value(1)),
            default=Value(2),
            output_field=IntegerField(),
        ),
        'producto__articulo',
        'talla',
    )[:60]

    ya_vinculados = set()
    if compra_id:
        ya_vinculados = set(
            Compras_Producto_Talla.objects
            .filter(compra_producto__compras_id=compra_id, producto_talla__isnull=False)
            .values_list('producto_talla_id', flat=True)
        )

    results = []
    for pt in qs:
        prod = pt.producto
        results.append({
            'producto_talla_id': pt.id,
            'sku': pt.sku,
            'talla': pt.talla,
            'stock': pt.stock if hasattr(pt, 'stock') else 0,
            'articulo': prod.articulo if prod else '',
            'marca': prod.atributo1.valor if prod and prod.atributo1 else '',
            'color': prod.atributo2.valor if prod and prod.atributo2 else '',
            'genero': prod.atributo3.valor if prod and prod.atributo3 else '',
            'categoria': prod.categoria.nombre if prod and prod.categoria else '',
            'sucursal': prod.sucursal.alias if prod and prod.sucursal else '',
            'ya_vinculado_esta_compra': pt.id in ya_vinculados,
        })

    return JsonResponse({'success': True, 'results': results, 'total': len(results)})


@require_GET
@login_required
def buscar_producto_agrupado_para_vincular(request):
    """
    Versión enriquecida del buscador para Vinculación Retroactiva.

    Agrupa Producto_Talla por (artículo · marca · color · género · sucursal
    del catálogo) y devuelve por cada grupo el set de tallas disponibles
    con un resumen de la trazabilidad de cada talla:
      - Movimiento de creación (primer INGRESO_INICIAL/MANUAL,
        RECEPCION_COMPRA, REPOSICION_STOCK o TRASPASO_ENTRADA).
      - Despachos (TRASPASO_SALIDA) agregados por sucursal destino.

    Permite al usuario *ver* si el producto del sistema es realmente
    el mismo que está en la compra antes de vincular.

    GET params:
        q          — texto parcial (busca en SKU, artículo, marca, color, género)
        compra_id  — opcional, marca SKUs ya vinculados a esa compra
    """
    from django.db.models import Prefetch

    q = (request.GET.get('q') or '').strip()
    if len(q) < 1:
        return JsonResponse({'success': True, 'grupos': []})

    compra_id = request.GET.get('compra_id')

    filtro = (
        Q(sku__icontains=q) |
        Q(producto__articulo__icontains=q) |
        Q(producto__atributo1__valor__icontains=q) |
        Q(producto__atributo2__valor__icontains=q) |
        Q(producto__atributo3__valor__icontains=q)
    )

    CONCEPTOS_TRACE = [
        'INGRESO_INICIAL', 'INGRESO_MANUAL', 'RECEPCION_COMPRA',
        'REPOSICION_STOCK', 'TRASPASO_SALIDA', 'TRASPASO_ENTRADA',
    ]

    pts = (
        Producto_Talla.objects
        .filter(filtro)
        .select_related(
            'producto__atributo1', 'producto__atributo2',
            'producto__atributo3', 'producto__categoria',
            'producto__sucursal',
        )
        .prefetch_related(
            Prefetch(
                'movimientos_productos_talla',
                queryset=Movimientos_Producto.objects.filter(
                    concepto__in=CONCEPTOS_TRACE,
                ).select_related('sucursal_origen', 'sucursal_destino')
                 .order_by('fecha', 'hora'),
                to_attr='movs_trace',
            )
        )
        .order_by(
            'producto__articulo',
            'producto__atributo1__valor',
            'producto__atributo2__valor',
            'talla',
        )[:200]
    )

    ya_vinculados = set()
    if compra_id:
        ya_vinculados = set(
            Compras_Producto_Talla.objects
            .filter(compra_producto__compras_id=compra_id, producto_talla__isnull=False)
            .values_list('producto_talla_id', flat=True)
        )

    # Compras asociadas (en CUALQUIER compra) para cada producto_talla:
    # lista con detalle (id, nombre, fecha, stock_compra). Permite al usuario
    # ver exactamente a qué compras ya está enlazada cada talla — fundamental
    # cuando el mismo SKU llegó en varias fechas con compras separadas.
    MESES_ABREV = {1: 'Ene', 2: 'Feb', 3: 'Mar', 4: 'Abr', 5: 'May', 6: 'Jun',
                   7: 'Jul', 8: 'Ago', 9: 'Sep', 10: 'Oct', 11: 'Nov', 12: 'Dic'}

    def _fecha_resumida(f):
        if not f:
            return ''
        return f"{f.day:02d}-{MESES_ABREV.get(f.month, '?')}-{f.year}"

    pt_ids = [pt.id for pt in pts]
    compras_asociadas_map = {}
    if pt_ids:
        rows = (
            Compras_Producto_Talla.objects
            .filter(producto_talla_id__in=pt_ids)
            .select_related('compra_producto__compras')
            .values(
                'producto_talla_id',
                'stock',
                'compra_producto__compras_id',
                'compra_producto__compras__nombre',
                'compra_producto__compras__fecha',
            )
        )
        for row in rows:
            pt_id = row['producto_talla_id']
            compras_asociadas_map.setdefault(pt_id, []).append({
                'compra_id': row['compra_producto__compras_id'],
                'compra_nombre': row['compra_producto__compras__nombre'] or '',
                'compra_fecha': _fecha_resumida(row['compra_producto__compras__fecha']),
                'stock_compra': int(row['stock'] or 0),
            })

    grupos_dict = {}
    for pt in pts:
        prod = pt.producto
        if not prod:
            continue

        marca = prod.atributo1.valor if prod.atributo1 else ''
        color = prod.atributo2.valor if prod.atributo2 else ''
        genero = prod.atributo3.valor if prod.atributo3 else ''
        sucursal_catalogo = prod.sucursal.alias if prod.sucursal else ''

        key = (prod.articulo or '', marca, color, genero, sucursal_catalogo)
        if key not in grupos_dict:
            grupos_dict[key] = {
                'articulo': key[0],
                'marca': marca,
                'color': color,
                'genero': genero,
                'sucursal_catalogo': sucursal_catalogo,
                'categoria': prod.categoria.nombre if prod.categoria else '',
                'tallas': [],
                'total_compras_asociadas_grupo': 0,
            }

        # Procesar movimientos prefetcheados.
        # ingresos = TODOS los movimientos de entrada (no solo el primero),
        # para ver cuántas veces llegó el SKU y cuándo. Necesario cuando el
        # mismo artículo llegó en varias compras con misma SKU.
        CONCEPTO_LEGIBLE = {
            'INGRESO_INICIAL': 'Carga inicial',
            'INGRESO_MANUAL': 'Ingreso manual',
            'RECEPCION_COMPRA': 'Recepción de compra',
            'REPOSICION_STOCK': 'Reposición',
            'TRASPASO_ENTRADA': 'Traspaso entrante',
        }
        movs = getattr(pt, 'movs_trace', [])
        ingresos = []
        total_ingresado = 0
        creado = None
        despachos_resumen = {}
        for m in movs:
            if m.concepto in CONCEPTO_LEGIBLE:
                sucursal_ingreso = (
                    m.sucursal_destino.alias if m.sucursal_destino
                    else (m.sucursal_origen.alias if m.sucursal_origen
                          else sucursal_catalogo)
                )
                ingreso_item = {
                    'fecha': _fecha_resumida(m.fecha) if m.fecha else '',
                    'fecha_iso': m.fecha.strftime('%Y-%m-%d') if m.fecha else '',
                    'cantidad': int(m.cantidad or 0),
                    'sucursal': sucursal_ingreso,
                    'concepto': m.concepto,
                    'concepto_legible': CONCEPTO_LEGIBLE[m.concepto],
                }
                ingresos.append(ingreso_item)
                total_ingresado += abs(int(m.cantidad or 0))
                if creado is None:
                    creado = ingreso_item.copy()
            elif m.concepto == 'TRASPASO_SALIDA':
                dest = m.sucursal_destino.alias if m.sucursal_destino else '-'
                if dest not in despachos_resumen:
                    despachos_resumen[dest] = {
                        'sucursal': dest, 'cantidad': 0,
                        'eventos': 0, 'ultima_fecha': '',
                    }
                despachos_resumen[dest]['cantidad'] += abs(m.cantidad)
                despachos_resumen[dest]['eventos'] += 1
                if m.fecha:
                    despachos_resumen[dest]['ultima_fecha'] = _fecha_resumida(m.fecha)

        compras_asociadas = compras_asociadas_map.get(pt.id, [])
        grupos_dict[key]['tallas'].append({
            'producto_talla_id': pt.id,
            'sku': pt.sku,
            'talla': pt.talla,
            'stock': pt.stock,
            'stock_actual': pt.stock,
            'total_ingresado': total_ingresado,
            'remanente': pt.stock,
            'ya_vinculado_esta_compra': pt.id in ya_vinculados,
            'compras_asociadas': compras_asociadas,
            'compras_asociadas_count': len(compras_asociadas),
            'creado': creado,
            'ingresos': ingresos,
            'despachos_por_sucursal': sorted(
                despachos_resumen.values(),
                key=lambda d: d['cantidad'], reverse=True,
            ),
            'total_despachos_eventos': sum(d['eventos'] for d in despachos_resumen.values()),
        })
        grupos_dict[key]['total_compras_asociadas_grupo'] += len(compras_asociadas)

    grupos = list(grupos_dict.values())[:30]
    return JsonResponse({
        'success': True,
        'grupos': grupos,
        'total': len(grupos),
    })


@require_GET
@login_required
def items_compra_para_vincular(request):
    """
    Devuelve los items de una compra AGRUPADOS por Compras_Producto, indicando
    para cada talla si ya fue rebajada (tiene Productos_Recepcionados) y si
    ya tiene producto_talla vinculado.

    Devuelve productos con tallas que aún no tienen producto_talla asignado
    (incluye compras históricas recién importadas sin Productos_Recepcionados,
    no solo las "rebajadas con factura").

    GET params: compra_id (required)
    """
    compra_id = request.GET.get('compra_id')
    if not compra_id:
        return JsonResponse({'success': False, 'error': 'compra_id requerido'}, status=400)

    compra = get_object_or_404(Compras, id=compra_id)

    cpts = (
        Compras_Producto_Talla.objects
        .filter(compra_producto__compras_id=compra_id)
        .exclude(talla=Compras_Producto_Talla.TALLA_SIN_DESGLOSAR)
        .select_related('compra_producto', 'producto_talla')
        .order_by('compra_producto__nombre', 'talla')
    )

    recepciones_por_cpt = {}
    cpt_ids = [c.id for c in cpts]
    if cpt_ids:
        recs = (
            Productos_Recepcionados.objects
            .filter(compra_producto_talla_id__in=cpt_ids)
            .values('compra_producto_talla_id')
            .annotate(
                total_recibido=Sum('stockArribado'),
                tiene_dte=Count('dte_id'),
                tiene_pt=Count('producto_talla_id'),
            )
        )
        for r in recs:
            recepciones_por_cpt[r['compra_producto_talla_id']] = r

    grupos = {}
    for cpt in cpts:
        cp = cpt.compra_producto
        rec = recepciones_por_cpt.get(cpt.id, {})
        recibido = rec.get('total_recibido', 0)
        tiene_factura = rec.get('tiene_dte', 0) > 0
        tiene_recepcion = recibido > 0
        pt_vinculado = cpt.producto_talla

        talla_info = {
            'cpt_id': cpt.id,
            'talla': cpt.talla,
            'stock': cpt.stock,
            'recibido': recibido,
            'tiene_factura': tiene_factura,
            'tiene_recepcion': tiene_recepcion,
            'vinculado': pt_vinculado is not None,
            'sku_vinculado': pt_vinculado.sku if pt_vinculado else None,
            'producto_talla_id': pt_vinculado.id if pt_vinculado else None,
        }

        if cp.id not in grupos:
            grupos[cp.id] = {
                'compra_producto_id': cp.id,
                'nombre': cp.nombre,
                'descripcion': cp.descripcion or '',
                'atributo1': cp.atributo1 or '',
                'atributo2': cp.atributo2 or '',
                'atributo3': cp.atributo3 or '',
                'costo': int(cp.costo or 0),
                'tallas': [],
                'total_stock': 0,
                'total_recibido': 0,
                'tallas_sin_vincular': 0,        # con recepción previa pero sin pt
                'tallas_pendientes_vinculo': 0,   # sin pt (con o sin recepción)
                'tallas_vinculadas': 0,
            }
        g = grupos[cp.id]
        g['tallas'].append(talla_info)
        g['total_stock'] += cpt.stock
        g['total_recibido'] += recibido
        if not pt_vinculado:
            g['tallas_pendientes_vinculo'] += 1
            if tiene_recepcion:
                g['tallas_sin_vincular'] += 1
        else:
            g['tallas_vinculadas'] += 1

    # Mostramos cualquier producto con tallas sin producto_talla, incluyendo
    # compras históricas frescas que aún no tienen Productos_Recepcionados.
    productos = [
        g for g in grupos.values()
        if g['tallas_pendientes_vinculo'] > 0
    ]

    facturas_proveedor = list(
        Dte.objects.filter(
            tipo_transaccion='COMPRA',
            emisor=compra.empresa,
        ).values('id', 'numero_documento', 'monto_con_iva')
    )

    return JsonResponse({
        'success': True,
        'productos': productos,
        'total_productos': len(productos),
        'compra_nombre': compra.nombre,
        'compra_fecha': compra.fecha.strftime('%Y-%m-%d') if compra.fecha else '',
        'es_historica': compra.es_historica,
        'proveedor': compra.empresa.nombre if compra.empresa else '',
        'facturas': facturas_proveedor,
    })


@require_POST
@login_required
@transaction.atomic
def vincular_productos_retroactivo(request):
    """
    Vincula productos ya existentes a una compra retroactivamente.
    Actualiza Productos_Recepcionados ya rebajados (con factura) para
    asignarles el producto_talla existente, y setea Compras_Producto_Talla.producto_talla.

    Para compras históricas (es_historica=True) NO modifica stock: solo
    crea la asociación para reportes de compra y rendimiento de proveedor.
    Usa compra.fecha como fecha_recepcion para que los reportes filtren
    por la fecha real de la compra, no por la fecha de hoy.

    Payload JSON:
    {
        "compra_id": <int>,
        "vinculaciones": [
            {"cpt_id": <int>, "producto_talla_id": <int>,
             "stock_compra": <int>  # opcional, sobrescribe cpt.stock antes
                                     # de vincular (útil para ajustar la
                                     # cantidad real cuando el mismo SKU
                                     # llegó en varias compras)
            },
            ...
        ],
        "es_historica": <bool>,   # opcional, default = compra.es_historica
        "dte_id": <int>           # opcional. Si viene, se asocia el DTE a
                                   # todas las Productos_Recepcionados
                                   # generadas o actualizadas en esta
                                   # vinculación. Debe ser del mismo
                                   # proveedor (compra.empresa) y
                                   # tipo_transaccion=COMPRA.
    }
    """
    try:
        data = json.loads(request.body or '{}')
    except ValueError:
        return JsonResponse({'success': False, 'error': 'JSON inválido'}, status=400)

    compra_id = data.get('compra_id')
    vinculaciones = data.get('vinculaciones') or []
    dte_id = data.get('dte_id')

    if not compra_id or not vinculaciones:
        return JsonResponse({
            'success': False,
            'error': 'compra_id y vinculaciones son requeridos'
        }, status=400)

    compra = get_object_or_404(Compras, id=compra_id)
    usuario = request.session.get('nombreUsuario', request.user.username)

    # DTE opcional: validar que pertenezca al mismo proveedor de la compra
    # y que sea documento de COMPRA.
    dte_obj = None
    if dte_id:
        try:
            dte_obj = Dte.objects.get(id=int(dte_id))
        except (Dte.DoesNotExist, TypeError, ValueError):
            return JsonResponse({
                'success': False,
                'error': f'DTE #{dte_id} no existe'
            }, status=400)
        if dte_obj.emisor_id != compra.empresa_id:
            return JsonResponse({
                'success': False,
                'error': 'El DTE seleccionado no corresponde al proveedor de la compra'
            }, status=400)

    # Si el payload no trae el flag, hereda del flag de la compra.
    es_historica = bool(data.get('es_historica', compra.es_historica))

    # Fecha efectiva = fecha real de la compra (no hoy). Garantiza que
    # los reportes YoY y de período clasifiquen correctamente.
    fecha_efectiva = datetime.combine(compra.fecha, datetime.min.time())
    if timezone.is_naive(fecha_efectiva):
        fecha_efectiva = timezone.make_aware(fecha_efectiva)

    observ_base = (
        f'Vinculación retroactiva (compra histórica - solo reportes, no toca stock) por {usuario}'
        if es_historica else
        f'Vinculación retroactiva por {usuario}'
    )

    exitosas = 0
    errores = []
    detalle = []

    for v in vinculaciones:
        cpt_id = v.get('cpt_id')
        pt_id = v.get('producto_talla_id')
        stock_compra_in = v.get('stock_compra')

        if not cpt_id or not pt_id:
            errores.append(f'Datos incompletos: cpt_id={cpt_id}, producto_talla_id={pt_id}')
            continue

        try:
            cpt = Compras_Producto_Talla.objects.select_related('compra_producto').get(
                id=cpt_id, compra_producto__compras=compra
            )
        except Compras_Producto_Talla.DoesNotExist:
            errores.append(f'Item de compra #{cpt_id} no encontrado en compra #{compra_id}')
            continue

        try:
            pt = Producto_Talla.objects.select_related('producto').get(id=pt_id)
        except Producto_Talla.DoesNotExist:
            errores.append(f'Producto_Talla #{pt_id} no existe')
            continue

        if cpt.producto_talla_id and cpt.producto_talla_id != pt.id:
            errores.append(
                f'{cpt.compra_producto.nombre} talla {cpt.talla}: ya vinculado a SKU '
                f'{cpt.producto_talla.sku}. Desvincula primero.'
            )
            continue

        # Si llega stock_compra editado, sobrescribir cpt.stock antes de
        # vincular. Permite ajustar la cantidad real cuando el usuario vio
        # el ingreso del sistema y notó que la compra estaba cargada con
        # otra cantidad.
        update_fields = ['producto_talla', 'unidades_recibidas', 'estado_item']
        if stock_compra_in is not None:
            try:
                stock_compra_new = int(stock_compra_in)
                if stock_compra_new < 0:
                    raise ValueError
                if stock_compra_new != cpt.stock:
                    cpt.stock = stock_compra_new
                    update_fields.append('stock')
            except (TypeError, ValueError):
                errores.append(
                    f'{cpt.compra_producto.nombre} talla {cpt.talla}: cantidad inválida ({stock_compra_in})'
                )
                continue

        cpt.producto_talla = pt
        cpt.unidades_recibidas = cpt.stock
        cpt.estado_item = 'recibido_completo'
        cpt.save(update_fields=update_fields)

        update_kwargs = {
            'producto_talla': pt,
            'fecha_recepcion': fecha_efectiva,
            'recepcionado_por': usuario,
            'observaciones': observ_base,
            'es_historica': es_historica,
        }
        if dte_obj is not None:
            update_kwargs['dte'] = dte_obj

        recs_actualizadas = Productos_Recepcionados.objects.filter(
            compra_producto_talla=cpt,
            producto_talla__isnull=True,
        ).update(**update_kwargs)

        if recs_actualizadas == 0:
            ya_vinculada = Productos_Recepcionados.objects.filter(
                compra_producto_talla=cpt, producto_talla=pt
            ).exists()
            if not ya_vinculada:
                create_kwargs = dict(
                    compra_producto_talla=cpt,
                    producto_talla=pt,
                    stockArribado=cpt.stock,
                    cantidad_esperada=cpt.stock,
                    estado='RECEPCIONADO_OK',
                    observaciones=f'{observ_base} (sin recepción previa)',
                    fecha_recepcion=fecha_efectiva,
                    recepcionado_por=usuario,
                    es_historica=es_historica,
                    sucursal_destino=cpt.compra_producto.sucursal_destino,
                    es_reposicion=cpt.compra_producto.es_reposicion,
                    precio_anterior=cpt.compra_producto.precio_anterior,
                    precio_nuevo=cpt.compra_producto.precio_nuevo,
                )
                if dte_obj is not None:
                    create_kwargs['dte'] = dte_obj
                Productos_Recepcionados.objects.create(**create_kwargs)
            elif dte_obj is not None:
                # Backfill DTE en recepciones ya existentes que no lo tenían
                Productos_Recepcionados.objects.filter(
                    compra_producto_talla=cpt,
                    producto_talla=pt,
                    dte__isnull=True,
                ).update(dte=dte_obj)

        exitosas += 1
        detalle.append({
            'cpt_id': cpt.id,
            'nombre': cpt.compra_producto.nombre,
            'talla': cpt.talla,
            'sku': pt.sku,
            'recepciones_actualizadas': recs_actualizadas,
        })

    # Si todas las tallas reales (sin contar la fantasma "__TOTAL__") quedaron
    # vinculadas, cerrar la compra como COMPLETADA.
    pendientes = (
        Compras_Producto_Talla.objects
        .filter(compra_producto__compras=compra, producto_talla__isnull=True)
        .exclude(talla=Compras_Producto_Talla.TALLA_SIN_DESGLOSAR)
        .exists()
    )
    compra_completada = False
    if not pendientes and compra.estado == 'ACTIVA':
        compra.estado = 'COMPLETADA'
        compra.save(update_fields=['estado'])
        compra_completada = True

    return JsonResponse({
        'success': True,
        'exitosas': exitosas,
        'errores': errores,
        'detalle': detalle,
        'es_historica': es_historica,
        'compra_completada': compra_completada,
        'message': f'{exitosas} producto(s) vinculado(s) retroactivamente a compra "{compra.nombre}".'
    })


@require_POST
@login_required
@transaction.atomic
def desvincular_cpt_retroactivo(request):
    """
    Deshace UNA vinculación retroactiva específica para una compra histórica.
    Limpia Compras_Producto_Talla.producto_talla y desenlaza los
    Productos_Recepcionados asociados (que son sólo de tipo histórica:
    es_historica=True, sin movimiento_ingreso).

    NO toca stock, NO toca movimientos, NO toca lotes — pensado para
    corregir errores de vinculación en compras históricas sin secuelas.

    Para no-históricas con stock real, usar revertir_producto_a_pendiente.

    Payload JSON:
    {
        "cpt_id": <int>
    }
    """
    try:
        data = json.loads(request.body or '{}')
    except ValueError:
        return JsonResponse({'success': False, 'error': 'JSON inválido'}, status=400)

    cpt_id = data.get('cpt_id')
    if not cpt_id:
        return JsonResponse({'success': False, 'error': 'cpt_id es requerido'}, status=400)

    try:
        cpt = (Compras_Producto_Talla.objects
               .select_related('compra_producto__compras', 'producto_talla')
               .get(id=cpt_id))
    except Compras_Producto_Talla.DoesNotExist:
        return JsonResponse({'success': False, 'error': f'CPT #{cpt_id} no existe'}, status=404)

    if not cpt.producto_talla_id:
        return JsonResponse({'success': False, 'error': 'Esta talla no está vinculada'}, status=400)

    compra = cpt.compra_producto.compras

    # Guardia: si las recepciones asociadas tienen movimientos de stock
    # reales (no es histórica), bloquear — debe usar revertir_producto_a_pendiente.
    tiene_movimientos = Productos_Recepcionados.objects.filter(
        compra_producto_talla=cpt,
        movimiento_ingreso__isnull=False,
    ).exists()
    if tiene_movimientos:
        return JsonResponse({
            'success': False,
            'error': 'Esta vinculación generó movimientos de stock reales. Usa "Revertir a pendiente" desde Editar Recepciones.',
        }, status=400)

    sku_anterior = cpt.producto_talla.sku if cpt.producto_talla else None

    recepciones_borradas = Productos_Recepcionados.objects.filter(
        compra_producto_talla=cpt,
        es_historica=True,
        movimiento_ingreso__isnull=True,
    ).delete()[0]

    cpt.producto_talla = None
    cpt.unidades_recibidas = 0
    cpt.estado_item = 'pendiente'
    cpt.save(update_fields=['producto_talla', 'unidades_recibidas', 'estado_item'])

    # Si la compra estaba COMPLETADA, volver a ACTIVA porque ya no lo está.
    if compra.estado == 'COMPLETADA':
        compra.estado = 'ACTIVA'
        compra.save(update_fields=['estado'])

    return JsonResponse({
        'success': True,
        'message': f'Talla {cpt.talla} de {cpt.compra_producto.nombre} desvinculada (SKU anterior: {sku_anterior}).',
        'cpt_id': cpt.id,
        'recepciones_borradas': recepciones_borradas,
        'sku_anterior': sku_anterior,
    })


# =========================================================================
# REVERTIR PRODUCTO A PENDIENTE (para recrear corregido)
# =========================================================================

@require_POST
@login_required
@transaction.atomic
def revertir_producto_a_pendiente(request):
    """
    Revierte un producto ya creado a estado "pendiente de crear".
    Soporta reversión total o parcial por cantidad.

    Desenlaza Productos_Recepcionados (vuelven a pendiente), ajusta
    movimientos, lotes y stock, conservando toda la trazabilidad de
    compra/factura/DTE.

    Payload JSON:
    {
        "producto_talla_id": <int>,
        "cantidad": <int|null>,      # null/0 = revertir todo; >0 = parcial
        "motivo": "texto libre"
    }
    """
    from .models import PendienteDespacho

    try:
        data = json.loads(request.body or '{}')
    except ValueError:
        return JsonResponse({'success': False, 'error': 'JSON inválido'}, status=400)

    pt_id = data.get('producto_talla_id')
    cantidad_revertir = data.get('cantidad')
    motivo = (data.get('motivo') or '').strip() or 'Sin motivo especificado'
    usuario = request.session.get('nombreUsuario', request.user.username)

    if not pt_id:
        return JsonResponse({
            'success': False,
            'error': 'producto_talla_id es requerido'
        }, status=400)

    try:
        pt = Producto_Talla.objects.select_related('producto').get(id=pt_id)
    except Producto_Talla.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Producto_Talla no encontrado'}, status=404)

    producto = pt.producto
    stock_actual = pt.stock or 0

    if cantidad_revertir and int(cantidad_revertir) > 0:
        cantidad_revertir = int(cantidad_revertir)
    else:
        cantidad_revertir = 0  # 0 = revertir todo

    es_parcial = cantidad_revertir > 0 and cantidad_revertir < stock_actual

    resumen = {
        'tipo': 'parcial' if es_parcial else 'total',
        'cantidad_revertida': 0,
        'recepciones_desenlazadas': 0,
        'recepciones_divididas': 0,
        'movimientos_ajustados': 0,
        'lotes_ajustados': 0,
        'talla_eliminada': False,
        'producto_eliminado': False,
    }

    if es_parcial:
        # --- REVERSIÓN PARCIAL ---
        cant_por_desenlazar = cantidad_revertir

        recepciones = list(
            Productos_Recepcionados.objects.filter(producto_talla=pt)
            .order_by('-id')
        )

        for rec in recepciones:
            if cant_por_desenlazar <= 0:
                break
            arr = rec.stockArribado or 0
            if arr <= cant_por_desenlazar:
                rec.producto_talla = None
                rec.observaciones = (rec.observaciones or '') + f' | Revertido parcial ({arr}u) por {usuario}: {motivo}'
                rec.save(update_fields=['producto_talla', 'observaciones'])
                cant_por_desenlazar -= arr
                resumen['recepciones_desenlazadas'] += 1
            else:
                nueva_rec = Productos_Recepcionados.objects.create(
                    compra_producto_talla=rec.compra_producto_talla,
                    dte=rec.dte,
                    dte_producto=rec.dte_producto,
                    producto_talla=None,
                    stockArribado=cant_por_desenlazar,
                    cantidad_esperada=cant_por_desenlazar,
                    estado=rec.estado,
                    observaciones=f'Split de recepción #{rec.id} - Revertido parcial ({cant_por_desenlazar}u) por {usuario}: {motivo}',
                    fecha_recepcion=rec.fecha_recepcion,
                    recepcionado_por=rec.recepcionado_por,
                    es_reposicion=rec.es_reposicion,
                    precio_anterior=rec.precio_anterior,
                    precio_nuevo=rec.precio_nuevo,
                    sucursal_destino=rec.sucursal_destino,
                )
                rec.stockArribado = arr - cant_por_desenlazar
                rec.save(update_fields=['stockArribado'])
                cant_por_desenlazar = 0
                resumen['recepciones_divididas'] += 1
                resumen['recepciones_desenlazadas'] += 1

        cantidad_efectiva = cantidad_revertir - cant_por_desenlazar
        resumen['cantidad_revertida'] = cantidad_efectiva

        pt.stock = max(0, stock_actual - cantidad_efectiva)
        pt.save(update_fields=['stock'])

        if cantidad_efectiva > 0:
            Movimientos_Producto.objects.create(
                ProductoTalla=pt,
                tipo='EGRESO',
                cantidad=cantidad_efectiva,
                concepto='REVERSION_PARCIAL',
                observaciones=f'Reversión parcial de {cantidad_efectiva}u por {usuario}: {motivo}',
                referencia_externa=f'REVERSION_PARCIAL_{pt.id}',
                usuario=usuario,
            )
            resumen['movimientos_ajustados'] = 1

        lotes = list(
            LoteProducto.objects.filter(producto_talla=pt, activo=True)
            .order_by('-id')
        )
        cant_lote_ajustar = cantidad_efectiva
        for lote in lotes:
            if cant_lote_ajustar <= 0:
                break
            disp = lote.cantidad_disponible or 0
            if disp <= cant_lote_ajustar:
                lote.cantidad_disponible = 0
                lote.activo = False
                lote.save(update_fields=['cantidad_disponible', 'activo'])
                cant_lote_ajustar -= disp
            else:
                lote.cantidad_disponible = disp - cant_lote_ajustar
                lote.save(update_fields=['cantidad_disponible'])
                cant_lote_ajustar = 0
            resumen['lotes_ajustados'] += 1

        cpts = Compras_Producto_Talla.objects.filter(producto_talla=pt)
        for cpt in cpts:
            nuevo = max(0, (cpt.unidades_recibidas or 0) - cantidad_efectiva)
            cpt.unidades_recibidas = nuevo
            cpt.estado_item = 'recibido_parcial' if nuevo > 0 else 'pendiente'
            cpt.save(update_fields=['unidades_recibidas', 'estado_item'])

    else:
        # --- REVERSIÓN TOTAL ---
        resumen['cantidad_revertida'] = stock_actual

        resumen['recepciones_desenlazadas'] = Productos_Recepcionados.objects.filter(
            producto_talla=pt
        ).update(producto_talla=None)

        PendienteDespacho.objects.filter(producto_talla=pt).delete()

        resumen['movimientos_ajustados'] = Movimientos_Producto.objects.filter(
            ProductoTalla=pt
        ).count()
        Movimientos_Producto.objects.filter(ProductoTalla=pt).delete()

        resumen['lotes_ajustados'] = LoteProducto.objects.filter(
            producto_talla=pt
        ).count()
        LoteProducto.objects.filter(producto_talla=pt).delete()

        Compras_Producto_Talla.objects.filter(producto_talla=pt).update(
            producto_talla=None,
            estado_item='pendiente',
        )

        resumen['talla_eliminada'] = True
        pt.delete()

        restantes = Producto_Talla.objects.filter(producto=producto).count()
        if restantes == 0:
            producto.delete()
            resumen['producto_eliminado'] = True

    logger.info(
        'REVERTIR_PRODUCTO: usuario=%s producto="%s" talla=%s sku=%s tipo=%s '
        'cantidad=%s motivo="%s" resumen=%s',
        usuario, producto.articulo, pt.talla, pt.sku,
        resumen['tipo'], resumen['cantidad_revertida'], motivo, resumen,
    )

    if es_parcial:
        msg = (
            f'Reversión parcial: {resumen["cantidad_revertida"]}u de talla {pt.talla} '
            f'(SKU {pt.sku}) revertidas a pendiente. Stock restante: {pt.stock}u.'
        )
    else:
        msg = (
            f'Talla {pt.talla} (SKU {pt.sku}) de "{producto.articulo}" '
            f'revertida completamente. {resumen["recepciones_desenlazadas"]} recepción(es) '
            f'volvieron a pendiente.'
        )

    return JsonResponse({
        'success': True,
        'resumen': resumen,
        'message': msg,
    })


@require_POST
@login_required
@transaction.atomic
def editar_producto_talla_creado(request):
    """
    Corrige talla y/o SKU de un Producto_Talla ya creado sin destruir
    movimientos ni lotes.

    Payload JSON:
    {
        "producto_talla_id": <int>,
        "nueva_talla": "string",    # opcional
        "nuevo_sku": "string"       # opcional
    }
    """
    try:
        data = json.loads(request.body or '{}')
    except ValueError:
        return JsonResponse({'success': False, 'error': 'JSON inválido'}, status=400)

    pt_id = data.get('producto_talla_id')
    nueva_talla = (data.get('nueva_talla') or '').strip()
    nuevo_sku = (data.get('nuevo_sku') or '').strip()
    usuario = request.session.get('nombreUsuario', request.user.username)

    if not pt_id:
        return JsonResponse({'success': False, 'error': 'producto_talla_id requerido'}, status=400)

    if not nueva_talla and not nuevo_sku:
        return JsonResponse({'success': False, 'error': 'Nada que actualizar'}, status=400)

    try:
        pt = Producto_Talla.objects.select_related('producto').get(id=pt_id)
    except Producto_Talla.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Producto_Talla no encontrado'}, status=404)

    cambios = []
    talla_anterior = pt.talla
    sku_anterior = pt.sku

    if nueva_talla and nueva_talla != pt.talla:
        pt.talla = nueva_talla
        cambios.append(f'talla: {talla_anterior} → {nueva_talla}')

        Compras_Producto_Talla.objects.filter(
            producto_talla=pt
        ).update(talla=nueva_talla)

    if nuevo_sku and nuevo_sku != pt.sku:
        existe = Producto_Talla.objects.filter(sku=nuevo_sku).exclude(id=pt.id).exists()
        if existe:
            return JsonResponse({
                'success': False,
                'error': f'El SKU "{nuevo_sku}" ya existe en otro producto'
            }, status=409)
        pt.sku = nuevo_sku
        cambios.append(f'sku: {sku_anterior} → {nuevo_sku}')

    if not cambios:
        return JsonResponse({'success': True, 'message': 'Sin cambios', 'cambios': []})

    pt.save()

    logger.info(
        'EDITAR_PRODUCTO_TALLA: usuario=%s pt_id=%s producto="%s" cambios=[%s]',
        usuario, pt.id, pt.producto.articulo if pt.producto else '?', '; '.join(cambios),
    )

    return JsonResponse({
        'success': True,
        'cambios': cambios,
        'message': f'Producto actualizado: {", ".join(cambios)}',
    })


# ============================================================
# LIMBO INBOX — Gestión unificada de DTEs en estado intermedio
# ============================================================
# Centraliza las decisiones del emisor cuando un DTE de TRASPASO queda
# atascado entre EMITIDO y RECEPCIONADO_COMPLETO. Reusa endpoints
# existentes (rehabilitar_dte_rechazado_api, corregir_recepcion_emisor_api,
# ajustar_dte_emisor_api) y agrega dos piezas faltantes:
#   1) Vista de inbox con resumen por DTE
#   2) Confirmación del receptor cuando hay devolución física pendiente

@login_required
@requiere_permiso('recepcion_dte', 'puede_ver')
def dtes_en_limbo(request):
    """Renderiza el Limbo Inbox del emisor."""
    sucursal_id = request.session.get('idSucursalActual')
    puede_aprobar = _permiso_recepcion_dte(request.user, 'puede_aprobar', sucursal_id)
    return render(request, 'vistas/modulo_documentos/dtes_en_limbo.html', {
        'puede_aprobar': puede_aprobar,
    })


@login_required
@requiere_permiso('recepcion_dte', 'puede_ver')
@require_GET
def obtener_dtes_limbo_emisor_api(request):
    """Lista todos los DTEs de TRASPASO emitidos por la sucursal actual
    que requieren decisión del emisor:
      - RECHAZADO
      - RECEPCIONADO_PARCIAL
      - RECEPCIONADO_SOBRANTE
      - EN_REGULARIZACION
      - EMITIDO con > N días sin recepcionar (configurable; default 7)
    Excluye DTEs hijos (NCs / AJUSTE TRASPASO POST) y estados terminales.
    """
    from datetime import timedelta
    from django.db.models import Q, Sum, Count

    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa.'}, status=400)

    try:
        dias_emision = int(request.GET.get('dias_emision', 7))
    except (TypeError, ValueError):
        dias_emision = 7

    ESTADOS_LIMBO = ['RECHAZADO', 'RECEPCIONADO_PARCIAL',
                     'RECEPCIONADO_SOBRANTE', 'EN_REGULARIZACION']
    hace_n_dias = timezone.now() - timedelta(days=dias_emision)

    qs = (
        Dte.objects
        .filter(sucursal_id=sucursal_id,
                tipo_transaccion='TRASPASO',
                es_nota_credito=False,
                documento_afectado__isnull=True)
        .filter(
            Q(estado_dte__in=ESTADOS_LIMBO) |
            Q(estado_dte='EMITIDO', fecha_emision__lt=hace_n_dias.date())
        )
        .exclude(estado_dte__in=['CANCELADO', 'ANULADO',
                                  'RECEPCIONADO_COMPLETO'])
        .exclude(tipo_documento__in=['NOTA DE CREDITO',
                                       'AJUSTE TRASPASO',
                                       'AJUSTE TRASPASO POST'])
        .exclude(descartado=True)
        .select_related('emisor', 'receptor', 'sucursal')
        .order_by('-fecha_emision', '-id')
    )

    estado_filtro = (request.GET.get('estado') or '').strip().upper()
    if estado_filtro:
        qs = qs.filter(estado_dte=estado_filtro)

    items = []
    for dte in qs[:300]:
        mov_salida = dte.dte_movimientos.filter(
            concepto='TRASPASO_SALIDA',
            sucursal_destino__isnull=False,
        ).select_related('sucursal_destino').first()
        destino = mov_salida.sucursal_destino if mov_salida else None

        recepciones = Productos_Recepcionados.objects.filter(dte=dte)
        resumen_faltantes = recepciones.aggregate(s=Sum('cantidad_faltante'))['s'] or 0
        resumen_danados = recepciones.aggregate(s=Sum('cantidad_danada'))['s'] or 0
        resumen_sobrantes = recepciones.aggregate(s=Sum('cantidad_sobrante'))['s'] or 0

        fecha_ref = dte.fecha_recepcion or dte.fecha_emision
        dias_en_limbo = (timezone.now().date() - fecha_ref).days if fecha_ref else None

        acciones = []
        if dte.estado_dte == 'RECHAZADO':
            acciones.append('rehabilitar')
            acciones.append('nc_con_devolucion')
        elif dte.estado_dte in ('RECEPCIONADO_PARCIAL', 'EN_REGULARIZACION'):
            if resumen_faltantes > 0:
                acciones.append('corregir')
            acciones.append('nc_con_devolucion')
            acciones.append('nc_sin_devolucion')
        elif dte.estado_dte == 'RECEPCIONADO_SOBRANTE':
            acciones.append('nc_con_devolucion')
            acciones.append('nc_sin_devolucion')
        elif dte.estado_dte == 'EMITIDO':
            acciones.append('nc_con_devolucion')

        ncs_hijas_pendientes = Dte.objects.filter(
            documento_afectado=dte,
            requiere_devolucion_fisica=True,
            fecha_confirmacion_devolucion__isnull=True,
        ).count()

        items.append({
            'id': dte.id,
            'numero_documento': dte.numero_documento,
            'tipo_documento': dte.tipo_documento,
            'estado_dte': dte.estado_dte,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d') if dte.fecha_emision else None,
            'fecha_recepcion': dte.fecha_recepcion.strftime('%Y-%m-%d') if dte.fecha_recepcion else None,
            'motivo_rechazo': dte.motivo_rechazo,
            'destino_alias': destino.alias if destino else None,
            'destino_id': destino.id if destino else None,
            'dias_en_limbo': dias_en_limbo,
            'resumen_problemas': {
                'faltantes': int(resumen_faltantes),
                'danados': int(resumen_danados),
                'sobrantes': int(resumen_sobrantes),
            },
            'acciones_permitidas': acciones,
            'ncs_hijas_pendientes_devolucion': ncs_hijas_pendientes,
            'monto_con_iva': float(dte.monto_con_iva or 0),
            'unidades_productos': int(dte.unidades_productos or 0),
        })

    return JsonResponse({
        'success': True,
        'total': len(items),
        'items': items,
    })


@login_required
@requiere_permiso('recepcion_dte', 'puede_ver')
@require_GET
def obtener_resumen_limbo_dte_api(request, dte_id):
    """Detalle completo de un DTE en limbo para alimentar el wizard."""
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa.'}, status=400)

    try:
        dte = Dte.objects.select_related(
            'emisor', 'receptor', 'sucursal'
        ).get(id=dte_id)
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if dte.sucursal_id != int(sucursal_id):
        return JsonResponse({'success': False,
                              'error': 'Solo la sucursal emisora puede ver este detalle.'},
                             status=403)

    mov_salida = dte.dte_movimientos.filter(
        concepto='TRASPASO_SALIDA',
        sucursal_destino__isnull=False,
    ).select_related('sucursal_destino').first()
    destino = mov_salida.sucursal_destino if mov_salida else None

    productos_problema = []
    recepciones = Productos_Recepcionados.objects.filter(dte=dte).select_related(
        'producto_talla', 'producto_talla__producto', 'dte_producto'
    )
    for rec in recepciones:
        prod = rec.producto_talla.producto if rec.producto_talla else None
        productos_problema.append({
            'recepcion_id': rec.id,
            'dte_producto_id': rec.dte_producto_id,
            'sku': rec.producto_talla.sku if rec.producto_talla else '-',
            'talla': rec.producto_talla.talla if rec.producto_talla else '-',
            'descripcion': (prod.descripcion if prod else
                            (rec.dte_producto.descripcion if rec.dte_producto else '-')),
            'articulo': prod.articulo if prod else '-',
            'cantidad_esperada': rec.cantidad_esperada,
            'cantidad_recepcionada': rec.stockArribado,
            'cantidad_faltante': rec.cantidad_faltante or 0,
            'cantidad_danada': rec.cantidad_danada or 0,
            'cantidad_sobrante': rec.cantidad_sobrante or 0,
            'estado': rec.estado,
            'observaciones': rec.observaciones or '',
        })

    # Si no hay Productos_Recepcionados (caso RECHAZADO/EMITIDO),
    # fallback a Dte_Productos del DTE original para alimentar el wizard NC.
    if not productos_problema:
        dte_productos = Dte_Productos.objects.filter(
            dte=dte, activo=True
        ).select_related('productoTalla', 'productoTalla__producto')
        for dp in dte_productos:
            prod = dp.productoTalla.producto if dp.productoTalla else None
            productos_problema.append({
                'recepcion_id': None,
                'dte_producto_id': dp.id,
                'sku': dp.productoTalla.sku if dp.productoTalla else '-',
                'talla': dp.productoTalla.talla if dp.productoTalla else '-',
                'descripcion': dp.descripcion or (prod.descripcion if prod else '-'),
                'articulo': prod.articulo if prod else '-',
                'cantidad_esperada': dp.stock or 0,
                'cantidad_recepcionada': 0,
                'cantidad_faltante': dp.stock or 0,
                'cantidad_danada': 0,
                'cantidad_sobrante': 0,
                'estado': 'PENDIENTE',
                'observaciones': '',
            })

    acciones = []
    if dte.estado_dte == 'RECHAZADO':
        acciones = ['rehabilitar', 'nc_con_devolucion']
    elif dte.estado_dte in ('RECEPCIONADO_PARCIAL', 'EN_REGULARIZACION'):
        if any(p['cantidad_faltante'] > 0 for p in productos_problema):
            acciones.append('corregir')
        acciones.append('nc_con_devolucion')
        acciones.append('nc_sin_devolucion')
    elif dte.estado_dte == 'RECEPCIONADO_SOBRANTE':
        acciones = ['nc_con_devolucion', 'nc_sin_devolucion']
    elif dte.estado_dte == 'EMITIDO':
        acciones = ['nc_con_devolucion']

    return JsonResponse({
        'success': True,
        'dte': {
            'id': dte.id,
            'numero_documento': dte.numero_documento,
            'tipo_documento': dte.tipo_documento,
            'estado_dte': dte.estado_dte,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d') if dte.fecha_emision else None,
            'fecha_recepcion': dte.fecha_recepcion.strftime('%Y-%m-%d') if dte.fecha_recepcion else None,
            'destino_alias': destino.alias if destino else None,
            'destino_id': destino.id if destino else None,
            'motivo_rechazo': dte.motivo_rechazo,
            'monto_con_iva': float(dte.monto_con_iva or 0),
            'unidades_productos': int(dte.unidades_productos or 0),
            'referencias': dte.referencias or '',
        },
        'productos': productos_problema,
        'acciones_permitidas': acciones,
    })


@login_required
@requiere_permiso('recepcion_dte', 'puede_crear')
@require_POST
@transaction.atomic
def confirmar_devolucion_fisica_api(request):
    """El RECEPTOR confirma que despachó físicamente la mercadería de
    vuelta al origen. Toma los Movimientos_Producto en estado PENDIENTE
    del DTE hijo (NC/AJUSTE POST con requiere_devolucion_fisica=True) y
    los completa, moviendo stock destino → origen.

    Soporta confirmaciones parciales (si el receptor pudo despachar
    menos que lo pedido). Lo no despachado queda PENDIENTE para que el
    emisor decida si emite NC complementaria sin devolución.

    Payload:
        {
            "dte_hijo_id": int,
            "lineas": [{"sku": str, "cantidad_efectiva": int}, ...]
        }
    Si `lineas` no se envía, se asume que se despachó todo lo pedido.
    """
    from .services.limbo_dte import completar_movimientos_pendientes

    try:
        data = json.loads(request.body or '{}')
    except json.JSONDecodeError:
        return JsonResponse({'success': False, 'error': 'JSON inválido.'}, status=400)

    dte_hijo_id = data.get('dte_hijo_id')
    lineas = data.get('lineas') or []

    if not dte_hijo_id:
        return JsonResponse({'success': False, 'error': 'Falta dte_hijo_id.'}, status=400)

    sucursal_actual_id = request.session.get('idSucursalActual')
    if not sucursal_actual_id:
        return JsonResponse({'success': False,
                              'error': 'No hay sucursal activa.'}, status=400)
    sucursal_actual_id = int(sucursal_actual_id)

    try:
        dte_hijo = (
            Dte.objects
            .select_for_update(of=('self',))
            .select_related('documento_afectado', 'sucursal')
            .get(id=dte_hijo_id)
        )
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if not dte_hijo.documento_afectado_id:
        return JsonResponse({'success': False,
                              'error': 'Este DTE no es una NC/AJUSTE hijo.'}, status=400)

    if not dte_hijo.requiere_devolucion_fisica:
        return JsonResponse({'success': False,
                              'error': 'Este DTE no tiene devolución física pendiente.'},
                             status=400)

    if dte_hijo.fecha_confirmacion_devolucion is not None:
        return JsonResponse({'success': False,
                              'error': 'La devolución ya fue confirmada anteriormente.'},
                             status=400)

    # Validar que el usuario sea de la sucursal destino del traspaso original.
    dte_original = dte_hijo.documento_afectado
    mov_salida_original = dte_original.dte_movimientos.filter(
        concepto='TRASPASO_SALIDA',
        sucursal_destino__isnull=False,
    ).select_related('sucursal_destino').first()

    if not mov_salida_original or not mov_salida_original.sucursal_destino:
        return JsonResponse({'success': False,
                              'error': 'No se pudo identificar la sucursal destino.'},
                             status=400)

    sucursal_destino_id = mov_salida_original.sucursal_destino_id
    if sucursal_destino_id != sucursal_actual_id:
        return JsonResponse({
            'success': False,
            'error': 'Solo la sucursal destino del traspaso original puede confirmar la devolución.',
        }, status=403)

    mapping_cantidades = {}
    for ln in lineas:
        sku = (ln.get('sku') or '').strip()
        try:
            cant = int(ln.get('cantidad_efectiva') or 0)
        except (TypeError, ValueError):
            cant = 0
        if sku and cant > 0:
            mapping_cantidades[sku] = cant

    # Si el usuario no pasó `lineas`, leer las cantidades pedidas y usar todo
    if not mapping_cantidades:
        for mov in Movimientos_Producto.objects.filter(
            dte=dte_hijo,
            concepto='DEVOLUCION_NC_PENDIENTE_DESPACHO',
            estado='PENDIENTE',
            tipo_movimiento='EGRESO',
        ).select_related('ProductoTalla'):
            if mov.ProductoTalla and mov.ProductoTalla.sku:
                mapping_cantidades[mov.ProductoTalla.sku] = abs(int(mov.cantidad or 0))

    resultado = completar_movimientos_pendientes(
        dte_hijo=dte_hijo,
        mapping_cantidades=mapping_cantidades,
        usuario=request.user.username,
    )

    quedan_pendientes = Movimientos_Producto.objects.filter(
        dte=dte_hijo,
        concepto='DEVOLUCION_NC_PENDIENTE_DESPACHO',
        estado='PENDIENTE',
    ).exists()

    if not quedan_pendientes:
        dte_hijo.requiere_devolucion_fisica = False
        dte_hijo.fecha_confirmacion_devolucion = timezone.now()
        dte_hijo.save(update_fields=['requiere_devolucion_fisica',
                                       'fecha_confirmacion_devolucion'])

    # Notificar al emisor
    try:
        from .models.dte import NotificacionDTE
        total_aplicado = sum(a['cantidad'] for a in resultado['aplicados'])
        NotificacionDTE.objects.create(
            dte=dte_original,
            empresa_receptora=dte_original.emisor,
            sucursal=dte_original.sucursal,
            sucursal_reportante=mov_salida_original.sucursal_destino,
            tipo='CORRECCION_RECEPCION',
            titulo=(f"Devolución confirmada — DTE #{dte_original.numero_documento} "
                    f"(NC #{dte_hijo.numero_documento})"),
            mensaje=(
                f"La sucursal destino confirmó el despacho físico de "
                f"{total_aplicado} unidad(es) hacia {dte_original.sucursal.alias}. "
                f"{'Quedan unidades pendientes — revisa el Limbo Inbox.' if quedan_pendientes else 'Devolución completada.'}"
            ),
            usuario_que_proceso=request.user,
        )
    except Exception:
        pass

    return JsonResponse({
        'success': True,
        'message': (
            f"Despacho confirmado. {len(resultado['aplicados'])} producto(s) "
            f"procesados; {len(resultado['no_aplicados'])} con observaciones."
        ),
        'aplicados': resultado['aplicados'],
        'no_aplicados': resultado['no_aplicados'],
        'cerrado': not quedan_pendientes,
    })


@login_required
@requiere_permiso('recepcion_dte', 'puede_ver')
@require_GET
def obtener_dtes_regularizacion_receptor_api(request):
    """Lista los DTEs que la sucursal actual (receptora) tiene en proceso
    de regularización por parte del emisor. Para cada uno se incluye un
    label legible con la decisión del emisor y, si hay un DTE hijo con
    devolución física pendiente, la información para confirmar el despacho.
    """
    sucursal_id = request.session.get('idSucursalActual')
    puede_ver_todas = (
        request.user.is_superuser
        or PermisoUsuario.usuario_ve_todas_sucursales(request.user)
    )
    ver_todas = puede_ver_todas and request.GET.get('alcance') == 'todas'
    if not sucursal_id and not ver_todas:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa.'}, status=400)
    sucursal_id = int(sucursal_id) if sucursal_id else None

    # DTEs cuyo destino es la sucursal actual (o cualquiera si ver_todas).
    movs_qs = Movimientos_Producto.objects.filter(
        concepto='TRASPASO_SALIDA',
        dte__isnull=False,
    )
    if not ver_todas:
        movs_qs = movs_qs.filter(sucursal_destino_id=sucursal_id)
    movs = movs_qs.values_list('dte_id', flat=True).distinct()

    dtes = (
        Dte.objects
        .filter(id__in=list(movs),
                tipo_transaccion='TRASPASO',
                es_nota_credito=False,
                documento_afectado__isnull=True)
        .exclude(estado_dte__in=['RECEPCIONADO_COMPLETO', 'CANCELADO', 'ANULADO'])
        .exclude(descartado=True)
        .select_related('emisor', 'sucursal')
        .order_by('-fecha_emision', '-id')[:300]
    )

    items = []
    for dte in dtes:
        # Buscar DTE hijo (NC / AJUSTE POST) más reciente con devolución pendiente.
        hijo_pendiente = (
            Dte.objects.filter(documento_afectado=dte,
                                requiere_devolucion_fisica=True,
                                fecha_confirmacion_devolucion__isnull=True)
            .order_by('-id').first()
        )

        # Label legible del estado.
        if hijo_pendiente:
            label = (f"NC #{hijo_pendiente.numero_documento} emitida — "
                     f"debes despachar mercadería a {dte.sucursal.alias}")
        elif dte.estado_dte == 'RECHAZADO':
            label = "Rechazado — espera decisión del emisor"
        elif dte.estado_dte == 'EN_REGULARIZACION':
            label = "En regularización — emisor está revisando"
        elif dte.estado_dte in ('RECEPCIONADO_PARCIAL',
                                 'RECEPCIONADO_SOBRANTE'):
            label = f"{dte.estado_dte.replace('_', ' ').title()} — pendiente decisión del emisor"
        else:
            label = dte.estado_dte

        items.append({
            'id': dte.id,
            'numero_documento': dte.numero_documento,
            'tipo_documento': dte.tipo_documento,
            'estado_dte': dte.estado_dte,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d') if dte.fecha_emision else None,
            'origen_alias': dte.sucursal.alias if dte.sucursal else None,
            'label': label,
            'hijo_devolucion_pendiente': (
                {
                    'id': hijo_pendiente.id,
                    'numero_documento': hijo_pendiente.numero_documento,
                    'tipo_documento': hijo_pendiente.tipo_documento,
                } if hijo_pendiente else None
            ),
        })

    return JsonResponse({'success': True, 'items': items})


@login_required
@requiere_permiso('recepcion_dte', 'puede_ver')
@require_GET
def obtener_devolucion_pendiente_detalle_api(request, dte_hijo_id):
    """Devuelve el detalle de los Movimientos_Producto PENDIENTE de un DTE
    hijo (NC con devolución física pendiente), para que el receptor pueda
    confirmar el despacho línea por línea.
    """
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa.'}, status=400)
    sucursal_id = int(sucursal_id)

    try:
        dte_hijo = Dte.objects.select_related('documento_afectado',
                                                'documento_afectado__sucursal').get(id=dte_hijo_id)
    except Dte.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'DTE no encontrado.'}, status=404)

    if not dte_hijo.documento_afectado_id or not dte_hijo.requiere_devolucion_fisica:
        return JsonResponse({'success': False,
                              'error': 'Este DTE no requiere devolución pendiente.'},
                             status=400)

    dte_original = dte_hijo.documento_afectado
    mov_salida = dte_original.dte_movimientos.filter(
        concepto='TRASPASO_SALIDA',
        sucursal_destino__isnull=False,
    ).first()
    if not mov_salida or mov_salida.sucursal_destino_id != sucursal_id:
        return JsonResponse({'success': False,
                              'error': 'Solo la sucursal destino puede ver este detalle.'},
                             status=403)

    lineas = []
    for mov in Movimientos_Producto.objects.filter(
        dte=dte_hijo,
        concepto='DEVOLUCION_NC_PENDIENTE_DESPACHO',
        estado='PENDIENTE',
        tipo_movimiento='EGRESO',
    ).select_related('ProductoTalla', 'ProductoTalla__producto'):
        talla = mov.ProductoTalla
        if not talla:
            continue
        stock_actual = int(Producto_Talla.objects.only('stock').get(id=talla.id).stock or 0)
        lineas.append({
            'sku': talla.sku,
            'talla': talla.talla,
            'descripcion': talla.producto.descripcion if talla.producto else '-',
            'articulo': talla.producto.articulo if talla.producto else '-',
            'cantidad_pedida': abs(int(mov.cantidad or 0)),
            'stock_actual_destino': stock_actual,
        })

    return JsonResponse({
        'success': True,
        'dte_hijo': {
            'id': dte_hijo.id,
            'numero_documento': dte_hijo.numero_documento,
            'tipo_documento': dte_hijo.tipo_documento,
        },
        'dte_original': {
            'id': dte_original.id,
            'numero_documento': dte_original.numero_documento,
            'origen_alias': dte_original.sucursal.alias if dte_original.sucursal else None,
        },
        'lineas': lineas,
    })
